#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MeshTrafficDirection {
    Inbound,
    Outbound,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MeshListenerKind {
    PlaintextCapture,
    MtlsTermination,
    HboneTermination,
    /// UDP TPROXY capture listener (F3 §3.3 Stage 3). Plaintext; bound to the
    /// Stage-2 `FERRUM_MESH_CAPTURE_UDP_PORT`. Receives TPROXY-diverted UDP
    /// datagrams, recovers per-datagram orig-dst from the `IP_RECVORIGDSTADDR`
    /// cmsg, and (Stage 3) drops them — the egress relay is Stage 4. Only
    /// emitted when `FERRUM_MESH_CAPTURE_UDP_ENABLED` is set (default-off).
    PlaintextUdpCapture,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MeshListener {
    pub direction: MeshTrafficDirection,
    pub kind: MeshListenerKind,
    pub addr: SocketAddr,
}

/// Mesh data-plane topology. Sidecar and ambient share the same runtime path;
/// ambient selects HBONE termination instead of sidecar inbound mTLS,
/// node-waypoint uses one HBONE listener for multiple node-local pods,
/// east-west gateway delegates SNI passthrough to the stream listener manager,
/// and egress gateway materializes HTTP-family proxies from external
/// `ServiceEntry` resources for controlled mesh-to-external routing.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MeshTopology {
    Sidecar,
    Ambient,
    NodeWaypoint,
    /// Istio Ambient GAMMA service-scoped waypoint. One process serves L7
    /// policy for a specific set of services bound to a named waypoint via
    /// `istio.io/use-waypoint` Service label/annotation (or the equivalent
    /// Gateway-API `parentRefs` flow). HBONE inbound on the same port as
    /// `NodeWaypoint`/`Ambient`; the slice filter narrows services to those
    /// bound to this waypoint instead of admitting every service on this node.
    ServiceWaypoint,
    EastWestGateway,
    EgressGateway,
}

impl MeshTopology {
    fn parse(raw: &str) -> Result<Self, String> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "sidecar" => Ok(Self::Sidecar),
            "ambient" => Ok(Self::Ambient),
            "node_waypoint" | "node-waypoint" => Ok(Self::NodeWaypoint),
            "service_waypoint" | "service-waypoint" => Ok(Self::ServiceWaypoint),
            "east_west_gateway" | "east-west-gateway" => Ok(Self::EastWestGateway),
            "egress_gateway" | "egress-gateway" => Ok(Self::EgressGateway),
            other => Err(format!(
                "Invalid FERRUM_MESH_TOPOLOGY {}. Expected: sidecar, ambient, node_waypoint, service_waypoint, east_west_gateway, or egress_gateway",
                crate::secrets::quoted_env_value("FERRUM_MESH_TOPOLOGY", other)
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Sidecar => "sidecar",
            Self::Ambient => "ambient",
            Self::NodeWaypoint => "node_waypoint",
            Self::ServiceWaypoint => "service_waypoint",
            Self::EastWestGateway => "east_west_gateway",
            Self::EgressGateway => "egress_gateway",
        }
    }

    /// Whether this topology terminates HBONE inbound on the shared waypoint
    /// listener (port 15008 by default). True for `Ambient`, `NodeWaypoint`,
    /// and `ServiceWaypoint`. Used by listener spawning and by validation
    /// paths that require HBONE-specific config.
    #[inline]
    #[allow(dead_code)]
    pub fn terminates_hbone(self) -> bool {
        matches!(
            self,
            Self::Ambient | Self::NodeWaypoint | Self::ServiceWaypoint
        )
    }

    /// Whether this topology is a waypoint flavor (node or service scope).
    /// Used by slice-filter and admin-endpoint dispatch to identify the
    /// shared-listener topologies that need extra scoping beyond Ambient's
    /// single-workload identity.
    #[inline]
    #[allow(dead_code)]
    pub fn is_waypoint(self) -> bool {
        matches!(self, Self::NodeWaypoint | Self::ServiceWaypoint)
    }

    /// Whether this topology terminates Ambient HBONE datagrams and can apply
    /// trusted per-pod UDP source evidence at the destination.
    #[inline]
    fn uses_ambient_udp_source_scoping(self) -> bool {
        matches!(self, Self::Ambient | Self::ServiceWaypoint)
    }
}

/// Control-protocol source for mesh runtime config.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MeshConfigProtocol {
    Native,
    Xds,
    /// Localized file source: the mesh slice is built DP-side from a local
    /// YAML/JSON document (`FERRUM_MESH_FILE_CONFIG_PATH`), no control plane.
    File,
}

impl MeshConfigProtocol {
    fn parse(raw: &str) -> Result<Self, String> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "native" => Ok(Self::Native),
            "xds" => Ok(Self::Xds),
            "file" => Ok(Self::File),
            other => Err(format!(
                "Invalid FERRUM_MESH_CONFIG_PROTOCOL {}. Expected: native, xds, or file",
                crate::secrets::quoted_env_value("FERRUM_MESH_CONFIG_PROTOCOL", other)
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Native => "native",
            Self::Xds => "xds",
            Self::File => "file",
        }
    }

    /// Whether this protocol consumes config from a control plane over gRPC
    /// (and therefore needs CP URLs, the CP/DP JWT secret, and gRPC TLS).
    fn requires_control_plane(self) -> bool {
        matches!(self, Self::Native | Self::Xds)
    }
}

/// Parsed mesh runtime settings kept separate from `EnvConfig` so mesh mode
/// stays strictly additive and non-mesh deployments do not carry new fields.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MeshRuntimeConfig {
    pub node_id: String,
    pub namespace: String,
    pub cp_urls: Vec<String>,
    pub config_protocol: MeshConfigProtocol,
    /// Localized mesh config document consumed when `config_protocol` is
    /// [`MeshConfigProtocol::File`]. Required for that protocol, `None`
    /// otherwise. Sourced from `FERRUM_MESH_FILE_CONFIG_PATH`.
    pub file_config_path: Option<String>,
    pub topology: MeshTopology,
    pub inbound_listen_addr: SocketAddr,
    pub outbound_listen_addr: SocketAddr,
    pub hbone_listen_addr: SocketAddr,
    pub east_west_listen_port: u16,
    /// Port dialed on DESTINATION workloads for Ambient egress HBONE
    /// (`FERRUM_MESH_EGRESS_HBONE_PORT`, default Istio's 15008). Stamped as the
    /// `mesh.hbone_port` target tag when non-default so heterogeneous meshes —
    /// and the two-gateways-on-one-host functional harness — can address peers
    /// off the convention port.
    pub egress_hbone_port: u16,
    /// Port dialed on DESTINATION sidecars for Sidecar egress SVID-mTLS
    /// (`FERRUM_MESH_EGRESS_MTLS_PORT`, default Istio's 15006). Stamped as the
    /// `mesh.mtls_port` target tag when non-default.
    pub egress_mtls_port: u16,
    /// Address the egress gateway listens on for mesh-internal mTLS traffic
    /// from sidecars. Only used when `topology == EgressGateway`. Parsed from
    /// `FERRUM_MESH_EGRESS_LISTEN_ADDR`, default `0.0.0.0:15090`.
    pub egress_listen_addr: SocketAddr,
    pub workload_spiffe_id: Option<String>,
    /// Name of the GAMMA Waypoint this process serves. Required when
    /// `topology == ServiceWaypoint`; ignored for every other topology.
    /// Sourced from `FERRUM_MESH_WAYPOINT_NAME`. The K8s translator records
    /// service→waypoint bindings (via `istio.io/use-waypoint` Service
    /// label/annotation or `gatewayClassName: istio-waypoint` Gateway resources),
    /// and the slice builder narrows admitted services to those bound to
    /// this name at slice-projection time.
    pub waypoint_name: Option<String>,
    /// xDS node cluster identity sent in DiscoveryRequest.node.cluster.
    /// Defaults to the Ferrum namespace when `FERRUM_MESH_XDS_NODE_CLUSTER`
    /// is unset.
    pub xds_node_cluster: String,
    /// Client-side ADS request channel capacity.
    pub xds_stream_channel_capacity: usize,
    /// How often a mesh xDS client retries the primary CP while connected to a
    /// fallback CP. `0` disables the timer.
    pub xds_primary_retry_secs: u64,
    /// Mesh xDS client connect timeout in seconds. `0` disables tonic's
    /// explicit connect timeout.
    pub xds_connect_timeout_seconds: u64,
    /// Operator-configured trust-domain aliases — additional SPIFFE trust
    /// domains accepted as equivalent to the peer cert's trust domain when
    /// validating HBONE baggage `source.principal`. Default empty: strict
    /// same-trust-domain match. Mirror of Istio
    /// `MeshConfig.trustDomainAliases`.
    pub trust_domain_aliases: Vec<crate::identity::TrustDomain>,
    /// Identity-asserting infrastructure SVIDs trusted to rewrite the authz
    /// principal via HBONE baggage `source.principal`. Empty means
    /// `mesh_authz`'s built-in defaults of `["ztunnel", "waypoint"]` apply.
    /// Operator-configured entries replace the defaults. Sourced from
    /// `FERRUM_MESH_TRUSTED_HBONE_ASSERTORS`. Each entry is either a bare
    /// Kubernetes service-account name or a full SPIFFE id.
    pub trusted_hbone_assertors: Vec<String>,
    /// Workload labels for this mesh data plane. Used by `mesh_authz`'s
    /// PolicyScope filter (and by `MeshSlice::from_gateway_config`'s
    /// WorkloadSelector matching) to decide which policies apply to this
    /// proxy's workload. Sourced from `FERRUM_MESH_WORKLOAD_LABELS`
    /// (`key1=val1,key2=val2`); empty when unset. The Kubernetes injector
    /// (Phase D) can populate this from pod labels via the downward API.
    pub workload_labels: std::collections::HashMap<String, String>,
    /// Workload X.509-SVID certificate chain used for mesh-originated backend
    /// mTLS when DestinationRule `ISTIO_MUTUAL` is projected onto an upstream.
    /// Sourced from `FERRUM_GATEWAY_SVID_CERT_PATH`.
    pub workload_svid_cert_path: Option<String>,
    /// Workload X.509-SVID private key used with `workload_svid_cert_path`.
    /// Sourced from `FERRUM_GATEWAY_SVID_KEY_PATH`.
    pub workload_svid_key_path: Option<String>,
    /// Trust bundle for backend server SVID verification when DestinationRule
    /// `ISTIO_MUTUAL` is projected onto an upstream.
    /// Sourced from `FERRUM_GATEWAY_SVID_TRUST_BUNDLE_PATH`.
    pub workload_svid_trust_bundle_path: Option<String>,
    /// Automatic mesh CA backend used to populate the runtime SVID slot when
    /// file-based `FERRUM_GATEWAY_SVID_*` material is absent.
    pub ca_backend: CaBackend,
    /// Whether the transparent DNS proxy is enabled. Opt-in because it
    /// requires iptables/eBPF redirect to be useful.
    /// Sourced from `FERRUM_MESH_DNS_PROXY_ENABLED` (default false).
    pub dns_enabled: bool,
    /// Listen address for the mesh DNS proxy.
    /// Sourced from `FERRUM_MESH_DNS_LISTEN_ADDR` (default `127.0.0.1:15053`).
    pub dns_listen_addr: SocketAddr,
    /// Upstream DNS resolver for non-mesh queries.
    /// Sourced from `FERRUM_MESH_DNS_UPSTREAM_ADDR` (default `127.0.0.53:53`).
    pub dns_upstream_addr: SocketAddr,
    /// TTL (seconds) for DNS responses served from the mesh resolution table.
    /// Sourced from `FERRUM_MESH_DNS_TTL_SECONDS` (default 60).
    pub dns_ttl_seconds: u32,
    /// Maximum concurrent mesh DNS queries / upstream forwards.
    /// Sourced from `FERRUM_MESH_DNS_MAX_CONCURRENT_QUERIES` (default 1024).
    pub dns_max_concurrent_queries: usize,
    /// Maximum per-slice cached mesh DNS response templates.
    /// Sourced from `FERRUM_MESH_DNS_RESPONSE_CACHE_MAX_ENTRIES` (default 4096).
    pub dns_response_cache_max_entries: usize,
    /// Kubernetes cluster DNS domain used for synthetic mesh service names.
    /// Sourced from `FERRUM_MESH_CLUSTER_DOMAIN` (default `cluster.local`).
    pub cluster_domain: String,
    /// Traffic capture mode for observability/logging. Does not change proxy
    /// behavior — listeners are topology-driven. Sourced from
    /// `FERRUM_MESH_CAPTURE_MODE` (default `explicit`).
    pub capture_mode: crate::capture::CaptureMode,
    /// Operator-set outbound traffic policy. Sourced from
    /// `FERRUM_MESH_OUTBOUND_TRAFFIC_POLICY`. When `RegistryOnly`, the
    /// slice-apply path injects the `mesh_outbound_registry` plugin with a
    /// registry built from the slice's known destinations.
    pub outbound_traffic_policy: crate::modes::mesh::config::OutboundTrafficPolicy,
    /// HTTP status returned by the auto-injected outbound registry plugin for
    /// unknown destinations. Sourced from
    /// `FERRUM_MESH_OUTBOUND_REGISTRY_REJECT_STATUS` (default 502).
    pub outbound_registry_reject_status: u16,
    /// When `true`, the slice builder applies Istio `Sidecar` egress scope
    /// narrowing. Sourced from `FERRUM_MESH_SIDECAR_ENFORCED` (default
    /// `false`). When disabled, `Sidecar` resources are parsed and persisted
    /// in `MeshConfig` but the slice projection ignores them — behavior is
    /// identical to today, preserving safe-rollout semantics.
    pub sidecar_enforced: bool,
    /// When `true`, compute Sidecar egress diagnostics while keeping the
    /// unenforced slice output. Sourced from
    /// `FERRUM_MESH_SIDECAR_ENFORCED_DRY_RUN` (default `false`).
    pub sidecar_enforced_dry_run: bool,
    /// When `true`, and only when `sidecar_enforced` is also true, per-workload
    /// slices filter `workloads` down to identities referenced by admitted
    /// services. Sourced from `FERRUM_MESH_SIDECAR_IDENTITY_NARROWING`
    /// (default `false`).
    pub sidecar_identity_narrowing: bool,
    /// Opt-in for stream-family (TCP/UDP) egress proxy materialization.
    /// Default `false`. When enabled, the materialized per-port stream egress
    /// proxies terminate SVID-mTLS (reusing the mesh-inbound `ServerConfig`)
    /// and run `mesh_authz` at accept — the same authn/z as HTTP egress —
    /// unless [`Self::egress_stream_allow_plaintext`] flips them back to the
    /// legacy plaintext posture. Sourced from `FERRUM_MESH_EGRESS_STREAM_ENABLED`.
    pub egress_stream_enabled: bool,
    /// Explicit opt-out that makes stream-family egress listeners plaintext +
    /// unauthenticated (the legacy posture). Default `false`: stream egress
    /// listeners terminate SVID-mTLS and run `mesh_authz`. Sourced from
    /// `FERRUM_MESH_EGRESS_STREAM_ALLOW_PLAINTEXT`. Only meaningful when
    /// [`Self::egress_stream_enabled`] is `true`; a loud warning is emitted at
    /// startup when it is enabled.
    pub egress_stream_allow_plaintext: bool,
    /// Whether the auto-injected mesh `RequestAuthentication` (`jwks_auth`)
    /// plugin requires the JWT `exp` claim. Defaults to `true` (secure):
    /// `exp`-less tokens are rejected so they cannot live forever. Sourced
    /// from `FERRUM_MESH_REQUEST_AUTH_REQUIRE_EXP`. Present-but-expired tokens
    /// are always rejected regardless of this flag.
    pub request_auth_require_exp: bool,
    /// Strict local-first locality load balancing. Default `false` preserves the
    /// historical fail-open behavior: when an upstream's source locality is
    /// absent/unresolved, the locality-aware LB returns mixed local + remote
    /// endpoints. When `true`, an absent source locality fails closed to LOCAL
    /// endpoints only (targets not tagged with the synthetic `remote-<cluster>`
    /// locality); if there are no local endpoints the LB falls back to the full
    /// healthy pool with a one-time warning. Stamped onto materialized upstreams
    /// at slice apply so the load balancer reads it at cache-build time without a
    /// per-request env lookup. Sourced from `FERRUM_MESH_LOCALITY_LB_STRICT`.
    pub locality_lb_strict: bool,
}

impl MeshRuntimeConfig {
    fn node_waypoint_secured_transport_required(&self) -> bool {
        if self.topology != MeshTopology::NodeWaypoint {
            return false;
        }
        if self.ca_backend != CaBackend::None {
            return true;
        }
        self.workload_svid_cert_path.is_some()
            && self.workload_svid_key_path.is_some()
            && self.workload_svid_trust_bundle_path.is_some()
    }

    pub fn from_env_config(env_config: &EnvConfig) -> Result<Self, String> {
        let config_protocol = MeshConfigProtocol::parse(&env_config.mesh_config_protocol)?;
        let cp_urls = env_config.resolved_dp_cp_grpc_urls();
        if config_protocol.requires_control_plane() && cp_urls.is_empty() {
            return Err("FERRUM_DP_CP_GRPC_URLS is required in mesh mode".into());
        }
        let file_config_path = env_config
            .mesh_file_config_path
            .clone()
            .filter(|value| !value.trim().is_empty());
        if config_protocol == MeshConfigProtocol::File && file_config_path.is_none() {
            return Err(
                "FERRUM_MESH_FILE_CONFIG_PATH is required when FERRUM_MESH_CONFIG_PROTOCOL=file"
                    .into(),
            );
        }

        let node_id = resolve_ferrum_var("FERRUM_MESH_NODE_ID")
            .filter(|value| !value.trim().is_empty())
            .or_else(|| std::env::var("HOSTNAME").ok())
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| "ferrum-mesh-node".to_string());
        let topology = MeshTopology::parse(
            &resolve_ferrum_var("FERRUM_MESH_TOPOLOGY").unwrap_or_else(|| "sidecar".to_string()),
        )?;
        let inbound_listen_addr = parse_socket_addr(
            "FERRUM_MESH_INBOUND_LISTEN_ADDR",
            resolve_ferrum_var("FERRUM_MESH_INBOUND_LISTEN_ADDR")
                .as_deref()
                .unwrap_or(DEFAULT_INBOUND_LISTEN_ADDR),
        )?;
        let outbound_listen_addr = parse_socket_addr(
            "FERRUM_MESH_OUTBOUND_LISTEN_ADDR",
            resolve_ferrum_var("FERRUM_MESH_OUTBOUND_LISTEN_ADDR")
                .as_deref()
                .unwrap_or(DEFAULT_OUTBOUND_LISTEN_ADDR),
        )?;
        let hbone_listen_addr = parse_socket_addr(
            "FERRUM_MESH_HBONE_LISTEN_ADDR",
            resolve_ferrum_var("FERRUM_MESH_HBONE_LISTEN_ADDR")
                .as_deref()
                .unwrap_or(DEFAULT_HBONE_LISTEN_ADDR),
        )?;
        let east_west_port_raw = resolve_ferrum_var("FERRUM_MESH_EAST_WEST_LISTEN_PORT")
            .unwrap_or_else(|| DEFAULT_EAST_WEST_LISTEN_PORT.to_string());
        let east_west_listen_port =
            parse_port("FERRUM_MESH_EAST_WEST_LISTEN_PORT", &east_west_port_raw)?;
        let egress_hbone_port_raw = resolve_ferrum_var("FERRUM_MESH_EGRESS_HBONE_PORT")
            .unwrap_or_else(|| hbone::ISTIO_HBONE_PORT.to_string());
        let egress_hbone_port =
            parse_port("FERRUM_MESH_EGRESS_HBONE_PORT", &egress_hbone_port_raw)?;
        let egress_mtls_port_raw = resolve_ferrum_var("FERRUM_MESH_EGRESS_MTLS_PORT")
            .unwrap_or_else(|| {
                crate::proxy::mesh_mtls_pool::ISTIO_SIDECAR_INBOUND_PORT.to_string()
            });
        let egress_mtls_port = parse_port("FERRUM_MESH_EGRESS_MTLS_PORT", &egress_mtls_port_raw)?;
        let egress_listen_addr = parse_socket_addr(
            "FERRUM_MESH_EGRESS_LISTEN_ADDR",
            resolve_ferrum_var("FERRUM_MESH_EGRESS_LISTEN_ADDR")
                .as_deref()
                .unwrap_or(DEFAULT_EGRESS_LISTEN_ADDR),
        )?;
        let workload_spiffe_id = resolve_ferrum_var("FERRUM_MESH_WORKLOAD_SPIFFE_ID")
            .filter(|value| !value.trim().is_empty());
        let waypoint_name = resolve_ferrum_var("FERRUM_MESH_WAYPOINT_NAME")
            .filter(|value| !value.trim().is_empty());
        if matches!(topology, MeshTopology::ServiceWaypoint) && waypoint_name.is_none() {
            return Err(
                "FERRUM_MESH_WAYPOINT_NAME is required when FERRUM_MESH_TOPOLOGY=service_waypoint \
                 (names the GAMMA Waypoint this process serves; bound services match via the \
                 istio.io/use-waypoint Service label/annotation or a Gateway resource with \
                 gatewayClassName=istio-waypoint)"
                    .into(),
            );
        }
        let workload_svid_cert_path = env_config.gateway_svid_cert_path.clone();
        let workload_svid_key_path = env_config.gateway_svid_key_path.clone();
        let workload_svid_trust_bundle_path = env_config.gateway_svid_trust_bundle_path.clone();
        let ca_backend = CaBackend::from_str_lossy(&env_config.mesh_ca_backend)
            .map_err(|error| format!("Invalid FERRUM_MESH_CA_BACKEND: {error}"))?;
        let xds_node_cluster = resolve_ferrum_var("FERRUM_MESH_XDS_NODE_CLUSTER")
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| env_config.namespace.clone());
        let xds_connect_timeout_raw = resolve_ferrum_var("FERRUM_MESH_XDS_CONNECT_TIMEOUT_SECONDS")
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| "10".to_string());
        let xds_connect_timeout_seconds = parse_duration_seconds(
            "FERRUM_MESH_XDS_CONNECT_TIMEOUT_SECONDS",
            &xds_connect_timeout_raw,
        )?;
        let workload_labels =
            parse_workload_labels(resolve_ferrum_var("FERRUM_MESH_WORKLOAD_LABELS").as_deref())?;

        let trust_domain_aliases = env_config
            .mesh_trust_domain_aliases
            .iter()
            .map(|raw| crate::identity::TrustDomain::new(raw.as_str()))
            .collect::<Result<Vec<_>, _>>()
            .map_err(|e| format!("FERRUM_MESH_TRUST_DOMAIN_ALIASES: {e}"))?;

        // Validate each entry early so a typo in the env var fails startup
        // with a clear message instead of failing later inside the plugin
        // constructor. We keep the raw strings here and let mesh_authz do the
        // real parsing — this is just an admission gate.
        for raw in &env_config.mesh_trusted_hbone_assertors {
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                return Err(
                    "FERRUM_MESH_TRUSTED_HBONE_ASSERTORS: entries must not be empty".to_string(),
                );
            }
            if let Some(rest) = trimmed.strip_prefix("spiffe://") {
                let _ = rest;
                crate::identity::SpiffeId::new(trimmed).map_err(|e| {
                    format!(
                        "FERRUM_MESH_TRUSTED_HBONE_ASSERTORS: invalid SPIFFE id {}: {e}",
                        crate::secrets::quoted_env_value(
                            "FERRUM_MESH_TRUSTED_HBONE_ASSERTORS",
                            trimmed
                        )
                    )
                })?;
            } else if trimmed.contains("://") {
                return Err(format!(
                    "FERRUM_MESH_TRUSTED_HBONE_ASSERTORS: entry {} looks like a URI \
                     but is not a 'spiffe://' SPIFFE id",
                    crate::secrets::quoted_env_value(
                        "FERRUM_MESH_TRUSTED_HBONE_ASSERTORS",
                        trimmed
                    )
                ));
            }
        }
        let trusted_hbone_assertors = env_config.mesh_trusted_hbone_assertors.clone();

        let dns_enabled = resolve_ferrum_var("FERRUM_MESH_DNS_PROXY_ENABLED")
            .map(|v| v.eq_ignore_ascii_case("true") || v == "1")
            .unwrap_or(DEFAULT_DNS_ENABLED);
        let dns_listen_addr = parse_socket_addr(
            "FERRUM_MESH_DNS_LISTEN_ADDR",
            resolve_ferrum_var("FERRUM_MESH_DNS_LISTEN_ADDR")
                .as_deref()
                .unwrap_or(DEFAULT_DNS_LISTEN_ADDR),
        )?;
        let dns_upstream_addr = parse_socket_addr(
            "FERRUM_MESH_DNS_UPSTREAM_ADDR",
            resolve_ferrum_var("FERRUM_MESH_DNS_UPSTREAM_ADDR")
                .as_deref()
                .unwrap_or(DEFAULT_DNS_UPSTREAM_ADDR),
        )?;
        let dns_ttl_seconds = resolve_ferrum_var("FERRUM_MESH_DNS_TTL_SECONDS")
            .and_then(|v| v.parse::<u32>().ok())
            .unwrap_or(DEFAULT_DNS_TTL_SECONDS);
        let dns_max_concurrent_queries =
            resolve_ferrum_var("FERRUM_MESH_DNS_MAX_CONCURRENT_QUERIES")
                .and_then(|v| v.parse::<usize>().ok())
                .filter(|value| *value > 0)
                .unwrap_or(DEFAULT_DNS_MAX_CONCURRENT_QUERIES);
        let dns_response_cache_max_entries =
            resolve_ferrum_var("FERRUM_MESH_DNS_RESPONSE_CACHE_MAX_ENTRIES")
                .and_then(|v| v.parse::<usize>().ok())
                .filter(|value| *value > 0)
                .unwrap_or(dns_proxy::DEFAULT_DNS_RESPONSE_CACHE_MAX_ENTRIES);
        let cluster_domain = resolve_ferrum_var("FERRUM_MESH_CLUSTER_DOMAIN")
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| dns_proxy::DEFAULT_CLUSTER_DOMAIN.to_string());
        let capture_mode = crate::capture::CaptureMode::parse(
            &resolve_ferrum_var("FERRUM_MESH_CAPTURE_MODE")
                .unwrap_or_else(|| "explicit".to_string()),
        )?;
        let outbound_traffic_policy = match env_config
            .mesh_outbound_traffic_policy
            .trim()
            .to_ascii_lowercase()
            .as_str()
        {
            "" | "allow_any" => crate::modes::mesh::config::OutboundTrafficPolicy::AllowAny,
            "registry_only" => crate::modes::mesh::config::OutboundTrafficPolicy::RegistryOnly,
            other => {
                return Err(format!(
                    "Invalid FERRUM_MESH_OUTBOUND_TRAFFIC_POLICY {}. Expected: \
                     allow_any or registry_only",
                    crate::secrets::quoted_env_value("FERRUM_MESH_OUTBOUND_TRAFFIC_POLICY", other)
                ));
            }
        };
        let outbound_registry_reject_status = env_config.mesh_outbound_registry_reject_status;
        if !(400..=599).contains(&outbound_registry_reject_status) {
            return Err(format!(
                "Invalid FERRUM_MESH_OUTBOUND_REGISTRY_REJECT_STATUS \
                 '{outbound_registry_reject_status}'. Expected: 400..=599"
            ));
        }

        Ok(Self {
            node_id,
            namespace: env_config.namespace.clone(),
            cp_urls,
            config_protocol,
            file_config_path,
            topology,
            inbound_listen_addr,
            outbound_listen_addr,
            hbone_listen_addr,
            east_west_listen_port,
            egress_hbone_port,
            egress_mtls_port,
            egress_listen_addr,
            workload_spiffe_id,
            waypoint_name,
            xds_node_cluster,
            xds_stream_channel_capacity: env_config.xds_stream_channel_capacity,
            xds_primary_retry_secs: env_config.dp_cp_failover_primary_retry_secs,
            xds_connect_timeout_seconds,
            trust_domain_aliases,
            trusted_hbone_assertors,
            workload_labels,
            workload_svid_cert_path,
            workload_svid_key_path,
            workload_svid_trust_bundle_path,
            ca_backend,
            dns_enabled,
            dns_listen_addr,
            dns_upstream_addr,
            dns_ttl_seconds,
            dns_max_concurrent_queries,
            dns_response_cache_max_entries,
            cluster_domain,
            capture_mode,
            outbound_traffic_policy,
            outbound_registry_reject_status,
            sidecar_enforced: env_config.mesh_sidecar_enforced,
            sidecar_enforced_dry_run: env_config.mesh_sidecar_enforced_dry_run,
            sidecar_identity_narrowing: env_config.mesh_sidecar_identity_narrowing,
            egress_stream_enabled: env_config.mesh_egress_stream_enabled,
            egress_stream_allow_plaintext: env_config.mesh_egress_stream_allow_plaintext,
            request_auth_require_exp: env_config.mesh_request_auth_require_exp,
            locality_lb_strict: env_config.mesh_locality_lb_strict,
        })
    }

    fn native_client_config(&self) -> NativeMeshClientConfig {
        NativeMeshClientConfig {
            node_id: self.node_id.clone(),
            namespace: self.namespace.clone(),
            workload_spiffe_id: self.workload_spiffe_id.clone(),
            waypoint_name: self.service_waypoint_name(),
            ambient_udp_source_scoping: self.topology.uses_ambient_udp_source_scoping(),
            labels: self.workload_labels.clone(),
            // Same `FERRUM_DP_CP_FAILOVER_PRIMARY_RETRY_SECS` interval the xDS
            // client uses — the knob is protocol-agnostic failover/failback.
            primary_retry_secs: self.xds_primary_retry_secs,
        }
    }

    fn xds_client_config(&self) -> XdsClientConfig {
        XdsClientConfig {
            cp_urls: self.cp_urls.clone(),
            node_id: self.node_id.clone(),
            cluster: self.xds_node_cluster.clone(),
            namespace: self.namespace.clone(),
            workload_spiffe_id: self.workload_spiffe_id.clone(),
            waypoint_name: self.service_waypoint_name(),
            ambient_udp_source_scoping: self.topology.uses_ambient_udp_source_scoping(),
            stream_channel_capacity: self.xds_stream_channel_capacity,
            primary_retry_secs: self.xds_primary_retry_secs,
            connect_timeout_seconds: self.xds_connect_timeout_seconds,
            labels: self
                .workload_labels
                .iter()
                .map(|(key, value)| (key.clone(), value.clone()))
                .collect(),
        }
    }

    pub fn listener_plan(&self) -> Vec<MeshListener> {
        match self.topology {
            MeshTopology::Sidecar => {
                let mut listeners = vec![
                    MeshListener {
                        direction: MeshTrafficDirection::Outbound,
                        kind: MeshListenerKind::PlaintextCapture,
                        addr: self.outbound_listen_addr,
                    },
                    MeshListener {
                        direction: MeshTrafficDirection::Inbound,
                        kind: MeshListenerKind::MtlsTermination,
                        addr: self.inbound_listen_addr,
                    },
                ];
                // Sidecar relays captured UDP over a mesh-mTLS datagram tunnel
                // (#1808), so the helper emits the `PlaintextUdpCapture` listener
                // here when the capture flag is set (gated to Ambient | Sidecar).
                listeners.extend(self.udp_capture_listener());
                listeners
            }
            MeshTopology::Ambient => {
                let mut listeners = vec![
                    MeshListener {
                        direction: MeshTrafficDirection::Outbound,
                        kind: MeshListenerKind::PlaintextCapture,
                        addr: self.outbound_listen_addr,
                    },
                    MeshListener {
                        direction: MeshTrafficDirection::Inbound,
                        kind: MeshListenerKind::HboneTermination,
                        addr: self.hbone_listen_addr,
                    },
                ];
                listeners.extend(self.udp_capture_listener());
                listeners
            }
            MeshTopology::NodeWaypoint | MeshTopology::ServiceWaypoint => {
                vec![MeshListener {
                    direction: MeshTrafficDirection::Inbound,
                    kind: MeshListenerKind::HboneTermination,
                    addr: self.hbone_listen_addr,
                }]
            }
            MeshTopology::EastWestGateway => Vec::new(),
            MeshTopology::EgressGateway => vec![MeshListener {
                direction: MeshTrafficDirection::Inbound,
                kind: MeshListenerKind::MtlsTermination,
                addr: self.egress_listen_addr,
            }],
        }
    }

    /// The optional UDP TPROXY capture listener (F3 §3.3), emitted on the two
    /// topologies that actually **relay** captured UDP — **Ambient** (datagram
    /// over HBONE `:15008`) and **Sidecar** (datagram over mesh-mTLS `:15006`).
    /// UDP egress materialization is dual-transport
    /// (`materialize_mesh_outbound_udp_upstreams` gates `Ambient => HBONE,
    /// Sidecar => SidecarMtls, _ => return`), so this listener is gated to the
    /// SAME two topologies. Emitting it for a topology with NO UDP relay
    /// (EastWestGateway / EgressGateway / waypoints) would divert the pod's UDP
    /// into a listener with no relay and **black-hole every captured datagram**
    /// (codex r1 P2); leaving those un-captured (UDP passes through) is the
    /// fail-open-by-passthrough posture. NodeWaypoint / ServiceWaypoint also have
    /// no outbound capture listener (and UDP stays mesh-wide-only there per the
    /// per-pod-scope notes).
    ///
    /// **End-to-end status (tracked in #1808): the FIRST working end-to-end UDP
    /// path is SIDECAR** — the injector's pod-netns TPROXY producer (re-enabled
    /// via `injector::sidecar_udp_capture_supported()`) feeds this listener, the
    /// egress datapath relays the datagram over a mesh-mTLS CONNECT, and the
    /// destination unframes it into a local `UdpSocket`. **Ambient still has NO
    /// UDP capture *producer*** feeding this listener — the node-agent host-netns
    /// path emits no UDP TPROXY rules (the same per-pod-scope blocker that defers
    /// F4.3 / #1803) and eBPF capture is `connect()`-hooked / TCP-only — so
    /// Ambient end-to-end UDP capture→relay is **not yet active in production**
    /// (its relay/transport is implemented and unit-tested, awaiting a producer).
    ///
    /// NOTE: the injector/init TPROXY-rule emission for a Sidecar pod is gated to
    /// MATCH this runtime listener gate: `injector::sidecar_udp_capture_supported()`
    /// (a central switch) now ENABLES the init container's UDP TPROXY rules, the
    /// sidecar's runtime-enable env, AND the transparent-bind capability TOGETHER,
    /// so an injected Sidecar with the flag set both binds a UDP listener (here)
    /// AND diverts UDP into it (init container). (The low-level
    /// `crate::capture::udp_tproxy_commands_for_family` still gates only on
    /// `host_netns`; the topology decision lives in the injector, which is the only
    /// pod-netns emitter.)
    ///
    /// Returns at most one listener, gated on `FERRUM_MESH_CAPTURE_UDP_ENABLED`
    /// (default-off via [`crate::capture::udp_capture_settings_from_env`]), bound
    /// on the **dual-stack IPv6 wildcard** (`[::]`, independent of
    /// `FERRUM_MESH_OUTBOUND_LISTEN_ADDR`'s family) on the Stage-2 UDP capture
    /// port (`FERRUM_MESH_CAPTURE_UDP_PORT`): TPROXY leaves each datagram's
    /// original (non-local) destination intact, so a specific-IP bind would miss
    /// them — only a wildcard `IP_TRANSPARENT` socket receives the captured
    /// non-local dests. A dual-stack `[::]` socket captures **both** v4-mapped
    /// and v6 datagrams from one listener (codex r3 P2 — a v4-only bind
    /// black-holes the v6 half when IPv6 capture rules are present); the bind
    /// falls back to the v4 wildcard on hosts without IPv6. A disabled flag yields no
    /// listener — the capture path stays inert. A *parse error* warn-skips here
    /// (this helper is infallible because read-only predicates call it too), but
    /// `serve_mesh_runtime` validates the same env with `?` before binding, so on
    /// the serving path a malformed setting fails startup rather than reaching
    /// this branch (codex r2 P2).
    fn udp_capture_listener(&self) -> Option<MeshListener> {
        let settings = match crate::capture::udp_capture_settings_from_env() {
            Ok(s) => s,
            Err(e) => {
                warn!("Skipping mesh UDP capture listener: {e}");
                return None;
            }
        };
        if !settings.udp_capture_enabled {
            return None;
        }
        // This helper emits ONLY the CURRENT-netns UDP capture listener, which is
        // correct for SIDECAR: the injected sidecar shares the pod netns where the
        // injector installed the TPROXY rules, so a listener bound here receives
        // the captured datagrams.
        //
        // AMBIENT relays captured UDP too, but its proxy runs OUTSIDE the pod
        // netns, so a host-netns listener would receive nothing (the host-netns
        // iptables fallback emits no UDP TPROXY rules). Ambient UDP source-capture
        // instead rides the per-pod-netns producer (`NetnsUdpCaptureManager`,
        // #2013), started separately at mesh startup — it binds the capture socket
        // and installs the TPROXY rules INSIDE each enrolled pod's netns. So Ambient
        // emits NO listener here (a second, inert host-netns listener on the same
        // port would be misleading and receive no pod traffic).
        //
        // Any OTHER topology has no UDP relay at all: warn ONCE and capture
        // nothing — UDP passes through un-captured rather than being black-holed.
        // `listener_plan()` is called many times (serving, predicates, tests), so
        // the warn is gated behind a `Once` to avoid log spam.
        match self.topology {
            MeshTopology::Sidecar => {}
            MeshTopology::Ambient => return None,
            _ => {
                static UDP_RELAY_UNSUPPORTED_WARN: std::sync::Once = std::sync::Once::new();
                UDP_RELAY_UNSUPPORTED_WARN.call_once(|| {
                    warn!(
                        topology = ?self.topology,
                        "FERRUM_MESH_CAPTURE_UDP_ENABLED is set but UDP egress is only supported on \
                         the Ambient (per-pod-netns producer, datagram-over-HBONE over :15008) and \
                         Sidecar (current-netns listener, datagram-over-mesh-mTLS over :15006) \
                         topologies. This topology has no UDP relay, so no UDP capture is emitted — \
                         UDP egress passes through un-captured rather than being captured and \
                         dropped. Disable the flag to silence this warning."
                    );
                });
                return None;
            }
        }
        // Bind the capture port on the DUAL-STACK IPv6 WILDCARD (`[::]`), not the
        // configured outbound IP (codex r1 P2) and not a family-following v4/v6
        // choice (codex r3 P2). TPROXY (`--on-port` only, no `--on-ip`) diverts
        // the datagram to this socket WITHOUT rewriting its destination, so each
        // captured datagram still carries the pod's real service/cluster-IP
        // destination, never the listener's IP; only a wildcard `IP_TRANSPARENT`
        // socket receives those non-local dests. A single dual-stack `[::]`
        // socket (V6ONLY disabled at bind time) claims BOTH v4-mapped and v6
        // captured datagrams — a v4-only `0.0.0.0` bind would black-hole the v6
        // half whenever IPv6 capture rules (`ip6tables` TPROXY) are present. The
        // listener bind falls back to the v4 wildcard on IPv6-less hosts.
        let addr = std::net::SocketAddr::new(
            std::net::IpAddr::V6(std::net::Ipv6Addr::UNSPECIFIED),
            settings.udp_outbound_port,
        );
        Some(MeshListener {
            direction: MeshTrafficDirection::Outbound,
            kind: MeshListenerKind::PlaintextUdpCapture,
            addr,
        })
    }

    /// Whether this topology runs an inbound **TLS-terminating** listener (mTLS
    /// or HBONE). EastWestGateway does SNI passthrough — it forwards encrypted
    /// bytes without terminating — so it has no plaintext-inbound posture and is
    /// the single topology this returns `false` for. This is the one source of
    /// truth for the runtime inbound fail-closed exemption (issue #1523): both
    /// the startup gate (`enforce_mesh_inbound_fail_closed`) and the live-reload
    /// apply task key their "is there anything to fail closed on?" check off it,
    /// so the exempt set can never drift between the two.
    fn has_inbound_tls_termination_listener(&self) -> bool {
        self.listener_plan().iter().any(|listener| {
            matches!(
                listener.kind,
                MeshListenerKind::MtlsTermination | MeshListenerKind::HboneTermination
            )
        })
    }

    pub fn mesh_slice_request(&self) -> MeshSliceRequest {
        MeshSliceRequest {
            node_id: self.node_id.clone(),
            namespace: self.namespace.clone(),
            workload_spiffe_id: self.workload_spiffe_id.clone(),
            waypoint_name: self.service_waypoint_name(),
            labels: self
                .workload_labels
                .iter()
                .map(|(k, v)| (k.clone(), v.clone()))
                .collect(),
            cluster_domain: self.cluster_domain.clone(),
            enforce_sidecar_egress: self.sidecar_enforced,
            sidecar_egress_dry_run: self.sidecar_enforced_dry_run,
            enforce_sidecar_identity_narrowing: self.sidecar_identity_narrowing,
            ambient_udp_source_scoping: self.topology.uses_ambient_udp_source_scoping(),
        }
    }

    fn service_waypoint_name(&self) -> Option<String> {
        if self.topology == MeshTopology::ServiceWaypoint {
            self.waypoint_name.clone()
        } else {
            None
        }
    }
}

/// Prepare a gateway snapshot for mesh-mode serving.
///
/// Mesh mode is the only caller. The mutation is cold-path: it runs before
/// `ProxyState` builds router/plugin caches, so non-mesh modes and ordinary
/// requests never pay for mesh plugin injection.
#[allow(dead_code)] // Used by tests and future xDS bootstrap wiring.
pub fn prepare_gateway_config_for_mesh(
    mut config: GatewayConfig,
    runtime: &MeshRuntimeConfig,
) -> Result<GatewayConfig, anyhow::Error> {
    config.normalize_fields();
    config.normalize_mesh_fields();
    let mesh_slice = MeshSlice::from_gateway_config(&config, runtime.mesh_slice_request());
    // Back-project the slice's narrowed `services` view BEFORE preparation so
    // every consumer of the prepared config sees exactly what materialization
    // consumes — CP parity: on the CP-driven paths `gateway_config_from_mesh_slice`
    // builds `config.mesh` FROM the slice, so a DP never carries un-narrowed
    // services. Without this, a Sidecar egress scope that narrows a
    // multi-port service's ports would leave the raw declaration in
    // `config.mesh.services`, and the router's outbound sibling grouping
    // (declared-HTTP-port fail-closed) would demand orig-dst for a service
    // the slice narrowed to a single port.
    if let Some(mesh) = config.mesh.as_deref_mut() {
        mesh.services = mesh_slice.services.clone();
    }
    prepare_normalized_gateway_config_for_mesh(config, runtime, &mesh_slice)
}

fn prepare_gateway_config_for_native_slice(
    mut config: GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) -> Result<GatewayConfig, anyhow::Error> {
    config.normalize_fields();
    config.normalize_mesh_fields();
    prepare_normalized_gateway_config_for_mesh(config, runtime, mesh_slice)
}

fn prepare_normalized_gateway_config_for_mesh(
    mut config: GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) -> Result<GatewayConfig, anyhow::Error> {
    let mesh_errors = config.validate_mesh_fields();
    if !mesh_errors.is_empty() {
        return Err(anyhow::anyhow!(
            "Mesh configuration validation failed: {}",
            mesh_errors.join("; ")
        ));
    }

    inject_mesh_global_plugins(&mut config, runtime, mesh_slice);
    materialize_east_west_gateway_proxies(&mut config, runtime, mesh_slice);
    materialize_egress_gateway_proxies(&mut config, runtime, mesh_slice);
    materialize_sidecar_inbound_proxies(&mut config, runtime, mesh_slice);
    // Outbound (egress) runs after inbound and before `apply_destination_rules`
    // so the materialized outbound upstreams pick up port-level DR policy
    // under the service-port key or dial-port key their dispatch path uses.
    // Topology-aware: Ambient emits HBONE routes; Sidecar emits SVID-mTLS routes.
    materialize_mesh_outbound_proxies(&mut config, runtime, mesh_slice);
    // VirtualService-derived CORS attaches to the just-materialized outbound
    // routes (issue #1973) — after materialization so the proxy ids exist,
    // before DR application like every other route-policy overlay.
    synthesize_mesh_outbound_cors_plugins(&mut config, runtime, mesh_slice);
    materialize_mesh_outbound_tcp_upstreams(&mut config, runtime, mesh_slice);
    materialize_mesh_outbound_udp_upstreams(&mut config, runtime, mesh_slice);
    fail_closed_node_waypoint_udp_dtls_scoped_policies(&mut config, runtime);
    apply_destination_rules(&mut config, runtime, mesh_slice)?;
    project_mesh_source_locality(&mut config, runtime, mesh_slice);
    // Project slice-filtered ServiceEntries back into the prepared mesh
    // block so introspection consumers (admin diagnostics, projected-config
    // snapshots, future helpers) see the same `export_to` / sidecar-narrowed
    // view the runtime serves. The slice has already applied namespace
    // visibility (`service_entry_exported_to_namespace`), sidecar egress
    // port narrowing, and ServiceWaypoint binding scoping; without this
    // back-projection, `config.mesh.service_entries` still carries the
    // unfiltered set even though DNS rebuild and egress materialization
    // consume the filtered slice directly. Closes Gap #2.
    if let Some(mesh) = config.mesh.as_deref_mut() {
        mesh.service_entries = mesh_slice.service_entries.clone();
        // Back-project the slice's narrowed LOCAL-INBOUND service view (kept
        // SEPARATE from the egress-narrowed `services` — never folded in, per
        // the egress-scope security rule) so the router's inbound per-port
        // sibling grouping and the listen-path uniqueness exemption derive
        // sibling identity from the same view
        // `materialize_sidecar_inbound_proxies` consumed. `Some` exactly when
        // Sidecar narrowing resolved the local view, mirroring the
        // materializer's `local_inbound_workloads` gate.
        mesh.local_inbound_services = mesh_slice
            .local_inbound_workloads
            .is_some()
            .then(|| mesh_slice.local_inbound_services.clone());
        // Back-project the resolved Sidecar ingress[] listeners so the router's
        // ingress sibling grouping and the listen-path uniqueness exemption
        // derive the same listener set `materialize_sidecar_inbound_proxies`
        // emitted (F6 §6.2). Forward-derived from the slice, never parsed from
        // ids.
        //
        // Re-validate each carried listener at this single chokepoint (consumed by
        // BOTH the router grouping and the materializer) before it is trusted. A
        // `ResolvedIngressListener` can arrive already resolved over the xDS/native
        // slice carrier, where every field — backend `endpoint_host`/`endpoint_port`
        // AND the stamped `owner_namespace`/`owner_service` — is decoded straight
        // from untrusted wire JSON. Drop a listener that fails EITHER guard:
        //   - an invalid backend (off-box host / `:0` port) the raw Sidecar
        //     resolution path would have deferred fail-closed, and
        //   - an owner-less entry that has no host identity of its own (in a mixed
        //     malformed carrier it would otherwise be grouped/materialized under
        //     another listener's service host).
        // Applying the IDENTICAL pair of guards the materializer applies keeps the
        // router's `declared_http_ports` count and the materialized routes in
        // lock-step and fails closed instead of routing somewhere resolution would
        // refuse.
        mesh.local_ingress_listeners = mesh_slice
            .local_ingress_listeners
            .iter()
            .filter(|listener| {
                if !listener.endpoint_is_valid() {
                    warn!(
                        listener_port = listener.port,
                        endpoint_host = %listener.endpoint_host,
                        endpoint_port = listener.endpoint_port,
                        "Dropping carried Sidecar ingress[] listener with an invalid backend endpoint \
                         (not a loopback host:port); failing closed rather than routing it"
                    );
                    return false;
                }
                if listener.owner_namespace.is_empty() || listener.owner_service.is_empty() {
                    warn!(
                        listener_port = listener.port,
                        "Dropping carried Sidecar ingress[] listener with no stamped owner identity \
                         (no local service anchor); failing closed rather than grouping it under \
                         another listener's service host"
                    );
                    return false;
                }
                true
            })
            .cloned()
            .collect();
        // Back-project the DECLARED HTTP-family ingress port count untouched by
        // the re-validation drops above (F6 §6.2). The drops reduce the
        // materialized `local_ingress_listeners` (siblings), but the declared
        // count must reflect what the operator declared so a partially
        // materialized group stays ambiguous: `mesh_ingress_listener_groups`
        // floors it at the surviving sibling count, so a hostile carrier can
        // never push it BELOW what materialized.
        mesh.declared_ingress_http_ports = mesh_slice.declared_ingress_http_ports;
    }
    materialize_fault_runtime_overlay(&mut config, &mesh_slice.runtime_overlay);
    config.normalize_fields();
    config.resolve_upstream_tls();

    Ok(config)
}

fn fail_closed_node_waypoint_udp_dtls_scoped_policies(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
) {
    if runtime.topology != MeshTopology::NodeWaypoint {
        return;
    }

    let scoped_policies = effective_node_waypoint_scoped_authz_policy_labels(config);
    if scoped_policies.is_empty() {
        return;
    }

    let udp_proxy_ids: HashSet<String> = config
        .proxies
        .iter()
        .filter(|proxy| proxy.dispatch_kind.is_udp())
        .map(|proxy| proxy.id.clone())
        .collect();
    let udp_proxies: Vec<String> = config
        .proxies
        .iter()
        .filter(|proxy| udp_proxy_ids.contains(&proxy.id))
        .map(|proxy| format!("{}/{}", proxy.namespace, proxy.id))
        .collect();
    let udp_services = strip_node_waypoint_udp_dtls_mesh_service_ports(config.mesh.as_deref_mut());

    let udp_upstreams: Vec<String> = config
        .upstreams
        .iter()
        .filter(|upstream| {
            upstream
                .id
                .starts_with(MESH_OUTBOUND_UDP_UPSTREAM_ID_PREFIX)
        })
        .map(|upstream| upstream.id.clone())
        .collect();

    if udp_proxy_ids.is_empty() && udp_services.is_empty() && udp_upstreams.is_empty() {
        return;
    }

    if !udp_proxy_ids.is_empty() {
        config
            .proxies
            .retain(|proxy| !udp_proxy_ids.contains(&proxy.id));
        config.plugin_configs.retain(|plugin| {
            plugin
                .proxy_id
                .as_deref()
                .is_none_or(|proxy_id| !udp_proxy_ids.contains(proxy_id))
        });
    }
    if !udp_upstreams.is_empty() {
        config.upstreams.retain(|upstream| {
            !upstream
                .id
                .starts_with(MESH_OUTBOUND_UDP_UPSTREAM_ID_PREFIX)
        });
    }

    warn!(
        topology = "node_waypoint",
        udp_services = %capped_join(&udp_services, 8),
        udp_proxies = %capped_join(&udp_proxies, 8),
        udp_upstreams = %capped_join(&udp_upstreams, 8),
        scoped_policies = %capped_join(&scoped_policies, 8),
        "Disabling NodeWaypoint UDP/DTLS paths because enforcing namespace/selector-scoped \
         AuthorizationPolicies require per-source-pod identity, but the NodeWaypoint UDP/DTLS \
         path has no trustworthy per-datagram/session pod identity. The slice is still applied \
         so scoped policy updates take effect for supported TCP/HTTP traffic; UDP/DTLS fails \
         closed in this topology. Use Sidecar for workload-scoped UDP/DTLS authorization or \
         keep NodeWaypoint UDP/DTLS policy MeshWide."
    );
}

fn effective_node_waypoint_scoped_authz_policy_labels(config: &GatewayConfig) -> Vec<String> {
    let mut labels = Vec::new();
    for plugin in config.plugin_configs.iter().filter(|plugin| {
        plugin.enabled
            && plugin.scope == PluginScope::Global
            && plugin.plugin_name == "mesh_authz"
            && plugin
                .config
                .get("per_pod_policy_scoping")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false)
    }) {
        labels.extend(
            mesh_authz_config_policies(&plugin.config)
                .into_iter()
                .filter(|policy| {
                    !matches!(policy.scope, PolicyScope::MeshWide)
                        && mesh_policy_has_enforcing_rule(policy)
                })
                .map(|policy| scoped_policy_label(&policy)),
        );
    }
    labels.sort();
    labels.dedup();
    labels
}

fn mesh_authz_config_policies(config: &serde_json::Value) -> Vec<MeshPolicy> {
    if let Some(value) = config.get("mesh_slice") {
        return serde_json::from_value::<MeshSlice>(value.clone())
            .map(|slice| slice.mesh_policies)
            .unwrap_or_default();
    }
    if let Some(value) = config.get("mesh_policies") {
        return serde_json::from_value::<Vec<MeshPolicy>>(value.clone()).unwrap_or_default();
    }
    Vec::new()
}

fn strip_node_waypoint_udp_dtls_mesh_service_ports(mesh: Option<&mut MeshConfig>) -> Vec<String> {
    let Some(mesh) = mesh else {
        return Vec::new();
    };

    let mut udp_services = Vec::new();
    for service in &mut mesh.services {
        let udp_port_numbers: HashSet<u16> = service_udp_stream_ports(service)
            .iter()
            .map(|port| port.port)
            .collect();
        if udp_port_numbers.is_empty() {
            continue;
        }
        let mut rendered_ports = udp_port_numbers
            .iter()
            .map(|port| port.to_string())
            .collect::<Vec<_>>();
        rendered_ports.sort();
        udp_services.push(format!(
            "{}/{}:{}",
            service.namespace,
            service.name,
            rendered_ports.join(",")
        ));
        let protocol_overrides = service.protocol_overrides.clone();
        service.ports.retain(|port| {
            let protocol = protocol_overrides
                .get(&port.port)
                .copied()
                .unwrap_or(port.protocol);
            !is_udp_mesh_protocol(protocol)
        });
        let remaining_port_numbers: HashSet<u16> =
            service.ports.iter().map(|port| port.port).collect();
        service
            .protocol_overrides
            .retain(|port, _| remaining_port_numbers.contains(port));
    }

    udp_services
}

fn node_waypoint_dns_slice_for_prepared_config(
    runtime: &MeshRuntimeConfig,
    base_slice: &MeshSlice,
    config: &GatewayConfig,
) -> Option<MeshSlice> {
    if runtime.topology != MeshTopology::NodeWaypoint
        || effective_node_waypoint_scoped_authz_policy_labels(config).is_empty()
    {
        return None;
    }
    let mesh = config.mesh.as_deref()?;
    let dns_suppressed_services = base_slice
        .services
        .iter()
        .filter(|service| !service_udp_stream_ports(service).is_empty())
        .map(|service| (service.namespace.as_str(), service.name.as_str()))
        .collect::<HashSet<_>>();
    // DNS is rebuilt from a MeshSlice, while UDP fail-closed suppression mutates
    // the prepared GatewayConfig. Hide every service that declared a UDP port:
    // mesh DNS is service-name scoped, not port scoped, so a mixed TCP+UDP
    // service would otherwise keep resolving for UDP clients after UDP routing
    // was stripped.
    let services = mesh
        .services
        .iter()
        .filter(|service| {
            !dns_suppressed_services.contains(&(service.namespace.as_str(), service.name.as_str()))
        })
        .cloned()
        .collect::<Vec<_>>();
    let service_entries = mesh
        .service_entries
        .iter()
        .filter(|entry| !service_entry_has_udp_port(entry))
        .cloned()
        .collect::<Vec<_>>();
    if services == base_slice.services && service_entries == base_slice.service_entries {
        return None;
    }

    let mut dns_slice = base_slice.clone();
    dns_slice.services = services;
    dns_slice.service_entries = service_entries;
    Some(dns_slice)
}

fn service_entry_has_udp_port(entry: &ServiceEntry) -> bool {
    entry
        .ports
        .iter()
        .any(|port| is_udp_mesh_protocol(port.protocol))
}

fn mesh_policy_has_enforcing_rule(policy: &MeshPolicy) -> bool {
    policy
        .rules
        .iter()
        .any(|rule| matches!(rule.action, PolicyAction::Allow | PolicyAction::Deny))
}

fn scoped_policy_label(policy: &MeshPolicy) -> String {
    let scope = match &policy.scope {
        PolicyScope::MeshWide => "mesh-wide",
        PolicyScope::Namespace { .. } => "namespace",
        PolicyScope::WorkloadSelector { .. } => "selector",
    };
    format!("{}/{} ({scope})", policy.namespace, policy.name)
}

fn capped_join(values: &[String], max_items: usize) -> String {
    let mut rendered = values
        .iter()
        .take(max_items)
        .map(String::as_str)
        .collect::<Vec<_>>()
        .join(", ");
    if values.len() > max_items {
        rendered.push_str(&format!(", ... +{} more", values.len() - max_items));
    }
    rendered
}

fn project_mesh_source_locality(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) {
    // When a projection actually changes an upstream's locality content we
    // advance its `updated_at` so `ConfigDelta` (which detects upstream changes
    // by `id` + `updated_at`) rebuilds the LB cache. We bump to a FRESH
    // wall-clock timestamp (the same convention the mesh materializers use,
    // `now`), NOT to `config.loaded_at`: `loaded_at` is derived from
    // `slice.version` and is therefore STABLE across re-applies of the same
    // slice version, so clobbering `updated_at` to it could collide with the
    // previously-applied upstream's `updated_at` and hide a real same-version
    // change. A fresh timestamp can never collide.
    //
    // NOTE on per-apply churn: this projection runs DURING preparation, where
    // every upstream was just freshly materialized and therefore ALWAYS enters
    // with `source_locality = None` — so on a re-apply with a resolved source
    // locality this branch re-stamps `updated_at` on EVERY upstream, not only
    // genuinely changed ones. Preventing that churn is NOT this function's job:
    // the slice-apply boundary runs `reconcile_mesh_upstream_timestamps` against
    // the previously-accepted config AFTER preparation, which restores the prior
    // timestamp for any upstream whose FINAL (post-projection) content is
    // unchanged. So a fresh bump here is safe: it is the correct timestamp for a
    // genuinely changed upstream and is reconciled away for an unchanged one.
    let bump = chrono::Utc::now();

    // Stamp the operator's strict local-first locality preference onto every
    // mesh upstream regardless of whether a source locality resolves: strict
    // mode's whole point is to govern the *absent-source-locality* case, so the
    // flag must reach upstreams that have no `source_locality` too. The load
    // balancer reads this at cache-build time (no per-request env lookup).
    let strict = runtime.locality_lb_strict;
    for upstream in &mut config.upstreams {
        if upstream.locality_lb_strict != strict {
            upstream.locality_lb_strict = strict;
            upstream.updated_at = bump;
        }
    }

    let Some(locality) = mesh_source_workload_locality(mesh_slice) else {
        return;
    };
    for upstream in &mut config.upstreams {
        if upstream.source_locality.as_deref() != Some(locality) {
            upstream.source_locality = Some(locality.to_string());
            upstream.updated_at = bump;
        }
    }
}

fn mesh_source_workload_locality(mesh_slice: &MeshSlice) -> Option<&str> {
    // The source workload is ALWAYS the LOCAL sidecar — never a remote-cluster
    // endpoint merged in by multi-cluster discovery (codex r6 [R6-3]). When remote
    // endpoint polling is active the slice now carries remote workloads, and a
    // remote replica that shares the local service-account SPIFFE (same-domain
    // multi-network) or matches the local labels could otherwise stamp a REMOTE
    // locality — or, on the label path, conflict and clear `source_locality`,
    // disabling the local-first priority tiers for every upstream. Skip remote
    // workloads in BOTH resolution paths.
    let multi_cluster = mesh_slice.multi_cluster.as_ref();

    // SPIFFE-matched workload is authoritative: if the configured workload
    // identity matches a known LOCAL workload, that workload's locality is the
    // answer — even when it is `None`. Falling through to the label-based
    // heuristic here would pick up a different pod's metadata and silently
    // disagree with the SPIFFE source of truth.
    if let Some(spiffe_id) = mesh_slice.workload_spiffe_id.as_deref()
        && let Some(workload) = mesh_slice.workloads.iter().find(|workload| {
            workload.spiffe_id.as_str() == spiffe_id
                && !crate::modes::mesh::multicluster::workload_is_remote(workload, multi_cluster)
        })
    {
        return workload.locality.as_deref();
    }

    // Label-based fallback for native-discovery / non-SPIFFE deployments.
    // Multi-replica Deployments commonly produce N workloads with identical
    // labels and identical locality — accept those as a single answer.
    // Bail out only when two label-matched workloads disagree on locality.
    let mut matched_locality: Option<&str> = None;
    for workload in &mesh_slice.workloads {
        if crate::modes::mesh::multicluster::workload_is_remote(workload, multi_cluster) {
            continue;
        }
        if workload.namespace != mesh_slice.namespace {
            continue;
        }
        let labels_match = mesh_slice.labels.iter().all(|(key, value)| {
            workload
                .selector
                .labels
                .get(key)
                .is_some_and(|candidate| candidate == value)
        });
        if !labels_match {
            continue;
        }
        let Some(locality) = workload.locality.as_deref() else {
            continue;
        };
        match matched_locality {
            None => matched_locality = Some(locality),
            Some(prev) if prev == locality => {}
            Some(_) => return None,
        }
    }
    matched_locality
}

/// Preserve materialized-mesh upstream timestamps across re-applies of the same
/// content.
///
/// Mesh upstreams are FRESHLY MATERIALIZED on every slice apply: the
/// materializers (`materialize_mesh_outbound_proxies`, the east-west / egress /
/// inbound builders) each stamp `created_at`/`updated_at` with a per-apply
/// `chrono::Utc::now()`, and `project_mesh_source_locality` then bumps
/// `updated_at` again whenever it stamps `source_locality`/`locality_lb_strict`
/// onto an upstream that entered the projection with `source_locality = None`
/// (which a freshly materialized upstream ALWAYS does). `ConfigDelta` keys
/// upstream identity on `id` and detects modification by `updated_at != old`
/// (`src/config_delta.rs`), so without reconciliation EVERY mesh upstream would
/// look "modified" on EVERY apply — and a "modified" upstream rebuilds a fresh
/// `LoadBalancer` (`LoadBalancerCache::build_delta_inner`), discarding its
/// round-robin counters, latency EWMAs, hash rings, and passive-health state.
/// That means an unrelated mesh-only update (a federation/trust-bundle overlay
/// refresh, or a remote-cluster scale event for a DIFFERENT service) would reset
/// LB + health for every materialized upstream.
///
/// This step runs at the slice-apply boundary — the only place that has the
/// PREVIOUSLY-ACCEPTED config — and copies the previous upstream's
/// `created_at`/`updated_at` onto a candidate upstream whose CONTENT is identical
/// (every field except the two timestamps; see [`upstream_content_eq`]). A
/// candidate whose content genuinely changed (target set, locality, strict flag,
/// DR-projected overrides, …) keeps its fresh timestamp, so a real change still
/// rebuilds exactly that one LB. New upstream ids (not present in the previous
/// config) are left untouched — `ConfigDelta` classifies them as ADDED, which
/// builds a fresh LB regardless of timestamp. This makes a no-op re-apply produce
/// an EMPTY upstream delta and preserves per-upstream LB/health state.
fn reconcile_mesh_upstream_timestamps(candidate: &mut GatewayConfig, previous: &GatewayConfig) {
    if candidate.upstreams.is_empty() || previous.upstreams.is_empty() {
        return;
    }
    let previous_by_id: HashMap<&str, &Upstream> = previous
        .upstreams
        .iter()
        .map(|upstream| (upstream.id.as_str(), upstream))
        .collect();
    for upstream in &mut candidate.upstreams {
        if let Some(old) = previous_by_id.get(upstream.id.as_str())
            && upstream_content_eq(upstream, old)
        {
            // Content-identical to the last accepted projection: preserve the
            // prior timestamps so `ConfigDelta` sees no change and the LB +
            // passive-health state for this upstream is reused as-is.
            upstream.created_at = old.created_at;
            upstream.updated_at = old.updated_at;
        }
    }
}

/// Materialize RTDS percentages into candidate fault configs on the cold path.
///
/// A zero override removes that fault side. When both sides are removed, the
/// candidate plugin is disabled for the generation; a later slice built from
/// the operator's static config re-enables it when the zero override disappears.
fn materialize_fault_runtime_overlay(
    config: &mut GatewayConfig,
    overlay: &crate::modes::mesh::config::MeshRuntimeOverlay,
) {
    use crate::plugins::fault_injection::runtime_overlay::{
        FaultOverlayMaterialization, materialize_config,
    };

    for plugin in config
        .plugin_configs
        .iter_mut()
        .filter(|plugin| plugin.enabled && plugin.plugin_name == "fault_injection")
    {
        if materialize_config(&mut plugin.config, overlay) == FaultOverlayMaterialization::Disabled
        {
            plugin.enabled = false;
        }
    }
}

/// Advance fault-plugin generations whose reconciled non-persistence content changed.
///
/// RTDS is not one of the mesh slice's version-coherence resource types, so an
/// RTDS-only response can legitimately keep `GatewayConfig.loaded_at` stable.
/// `ConfigDelta` detects plugin changes through `PluginConfig.updated_at`; this
/// cold-path stamp makes the affected instances rebuild from their materialized
/// effective config before `RequestEpoch` publishes the candidate. Unchanged
/// and unrelated scopes retain their stateful plugin instances.
pub(crate) fn reconcile_fault_plugin_generations(
    candidate: &mut GatewayConfig,
    previous: &GatewayConfig,
) {
    let previous_plugins = previous
        .plugin_configs
        .iter()
        .filter(|plugin| plugin.plugin_name == "fault_injection")
        .map(|plugin| ((plugin.namespace.as_str(), plugin.id.as_str()), plugin))
        .collect::<HashMap<_, _>>();

    for plugin in candidate
        .plugin_configs
        .iter_mut()
        .filter(|plugin| plugin.plugin_name == "fault_injection")
    {
        let Some(previous) = previous_plugins.get(&(plugin.namespace.as_str(), plugin.id.as_str()))
        else {
            continue;
        };
        if plugin_config_content_eq_ignoring_persistence(plugin, previous) {
            // The candidate may have been reconstructed from the static mesh
            // source timestamp while `previous` carries the synthetic stamp
            // assigned to an earlier RTDS materialization. Preserve that
            // accepted stamp when every non-persistence field is identical so
            // ConfigDelta does not rebuild the plugin or reset its sampler.
            plugin.updated_at = previous.updated_at;
            continue;
        }

        if plugin.updated_at != previous.updated_at {
            continue;
        }
        let now = chrono::Utc::now();
        plugin.updated_at = if now <= previous.updated_at {
            previous.updated_at + chrono::Duration::nanoseconds(1)
        } else {
            now
        };
    }
}

/// Whether two plugin configs are identical after neutralizing persistence-only
/// timestamps.
///
/// Serializing the normalized configs makes this comparison automatically
/// complete over the `PluginConfig` schema: a future runtime-relevant field is
/// included without another hand-maintained equality update. `api_spec_id` is
/// intentionally still compared; an extra cold-path rebuild for an admin-only
/// metadata edit is safer than retaining a stale runtime instance. A
/// serialization failure is treated as changed so reconciliation fails toward
/// rebuilding rather than stale reuse.
fn plugin_config_content_eq_ignoring_persistence(
    candidate: &PluginConfig,
    previous: &PluginConfig,
) -> bool {
    let mut normalized_candidate = candidate.clone();
    normalized_candidate.created_at = previous.created_at;
    normalized_candidate.updated_at = previous.updated_at;

    match (
        serde_json::to_value(&normalized_candidate),
        serde_json::to_value(previous),
    ) {
        (Ok(candidate), Ok(previous)) => candidate == previous,
        _ => false,
    }
}

/// Whether two upstreams are identical in everything EXCEPT their
/// `created_at`/`updated_at` timestamps.
///
/// Compares by serializing both sides with the timestamps normalized to a single
/// value, so the comparison is automatically complete over the whole `Upstream`
/// schema (it picks up future fields with no code change) and ignores the
/// `#[serde(skip)]` `resolved_subset_tls` derived overlay — which is safe because
/// that overlay is a pure function of `subsets[].traffic_policy.tls`, so two
/// upstreams with equal serialized content always resolve it identically. This is
/// a cold-path comparison (slice apply only), so correctness/robustness wins over
/// avoiding the clone.
///
/// `dispatch_port_override_fallback` is a `#[serde(skip)]` field that is NOT a
/// pure function of the serialized content (#1806): it is derived from the
/// matching *DestinationRule*, so a DR-only edit to an SD upstream's top-level
/// `connectionPool.http` changes it while the serialized `Upstream` content is
/// byte-identical. Comparing it here bumps the upstream's `updated_at` so the LB
/// cache (and `ConfigDelta`) reflect the change.
///
/// NOTE (#1816): immediate route-TABLE rebuild on a DR-only edit is DEFERRED.
/// `ProxyState::delta_routes_changed` keys on PROXY add/modify/remove, and the
/// route table holds the `Arc<Proxy>` carrying the projected fallback — a
/// shared characteristic of ALL `#[serde(skip)]` DR-derived proxy fields (incl.
/// the established per-port `dispatch_port_overrides`), not unique to the
/// fallback. Until #1816 wires a proxy-side route-rebuild signal for these
/// derived fields, an SD `connectionPool.http` edit applies on the next route
/// rebuild (proxy change / full reload).
fn upstream_content_eq(a: &Upstream, b: &Upstream) -> bool {
    fn content_value(upstream: &Upstream) -> serde_json::Value {
        let mut normalized = upstream.clone();
        // Neutralize both timestamps so only the remaining fields drive equality.
        let epoch =
            chrono::DateTime::<chrono::Utc>::from_timestamp(0, 0).unwrap_or_else(chrono::Utc::now);
        normalized.created_at = epoch;
        normalized.updated_at = epoch;
        serde_json::to_value(&normalized).unwrap_or(serde_json::Value::Null)
    }
    // The DR-derived `#[serde(skip)]` fallback overlay is invisible to the
    // serialized comparison, so compare it explicitly first.
    if a.dispatch_port_override_fallback != b.dispatch_port_override_fallback {
        return false;
    }
    let a_value = content_value(a);
    // A serialization failure yields `Null`; never treat two failed (`Null`)
    // serializations as "equal" (that would silently preserve a stale timestamp
    // and hide a real change), so bail to "changed" when either side is `Null`.
    if a_value.is_null() {
        return false;
    }
    a_value == content_value(b)
}

#[cfg(test)]
#[allow(dead_code)]
fn gateway_config_from_mesh_slice(
    slice: &MeshSlice,
    runtime: &MeshRuntimeConfig,
    federation: Option<&federation::FederationSnapshot>,
    remote_endpoints: Option<&multicluster::RemoteEndpointSnapshot>,
) -> Result<GatewayConfig, anyhow::Error> {
    gateway_config_from_mesh_slice_with_federation(
        slice,
        runtime,
        federation,
        remote_endpoints,
        FederationActivation::disabled(),
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct FederationActivation {
    fail_open: bool,
    poll_enabled: bool,
}

impl FederationActivation {
    #[cfg(test)]
    fn disabled() -> Self {
        Self {
            fail_open: false,
            poll_enabled: false,
        }
    }

    fn from_env_config(env_config: &EnvConfig) -> Self {
        Self {
            fail_open: env_config.mesh_federation_fail_open,
            poll_enabled: env_config.mesh_federation_poll_interval_seconds > 0,
        }
    }
}

fn effective_trust_bundles_for_slice(
    slice: &MeshSlice,
    federation: Option<&federation::FederationSnapshot>,
    activation: FederationActivation,
) -> Option<config::TrustBundleSet> {
    match federation {
        Some(snapshot) => federation::merge_federation_into_trust_bundles(
            slice.trust_bundles.clone(),
            snapshot,
            slice.multi_cluster.as_ref(),
            activation.fail_open,
            activation.poll_enabled,
        ),
        None => slice.trust_bundles.clone(),
    }
}

fn validation_trust_bundles_for_slice(
    slice: &MeshSlice,
    federation: Option<&federation::FederationSnapshot>,
) -> Option<config::TrustBundleSet> {
    match federation {
        Some(snapshot) => {
            federation::merge_federation_for_validation(slice.trust_bundles.clone(), snapshot)
        }
        None => slice.trust_bundles.clone(),
    }
}

fn gateway_config_from_mesh_slice_with_federation(
    slice: &MeshSlice,
    runtime: &MeshRuntimeConfig,
    federation: Option<&federation::FederationSnapshot>,
    remote_endpoints: Option<&multicluster::RemoteEndpointSnapshot>,
    _activation: FederationActivation,
) -> Result<GatewayConfig, anyhow::Error> {
    let loaded_at = chrono::DateTime::parse_from_rfc3339(&slice.version)
        .map(|ts| ts.with_timezone(&chrono::Utc))
        .unwrap_or_else(|_| chrono::Utc::now());
    // Keep CP-provided federation bootstrap bundles visible to structural mesh
    // validation even in fail-closed mode. Traffic-facing verifier slots are
    // published separately from `effective_trust_bundles_for_slice` only after
    // this candidate config is accepted, so inactive bootstrap roots do not
    // become live trust.
    let trust_bundles = validation_trust_bundles_for_slice(slice, federation);
    // Aggregate cross-cluster endpoints (Tier 3b): merge remote-cluster
    // workloads / services discovered from `RemoteCluster.control_plane_url`
    // into the local registry. Remote workloads carry a distinct (remote)
    // locality so the locality-aware priority-tier load balancer fails over
    // local → remote at the endpoint level. Empty snapshots are a no-op.
    //
    // The merge is filtered against THIS slice's `multi_cluster` (the candidate
    // about to be applied): a remote cluster absent from — or with a divergent
    // identity vs — the candidate contributes no endpoints, so cluster removal /
    // control-plane identity changes fail closed within the same generation
    // instead of leaking one generation until the discovery reconciler (sourced
    // from the accepted slice) evicts the store entry. Fail-closed: a slice with
    // no `multi_cluster` admits no remote endpoints (codex F7.2 round-4).
    let merged_remote = matches!(remote_endpoints, Some(snapshot) if !snapshot.is_empty());
    // A Sidecar-enforced slice has already narrowed `slice.services` to the
    // authorized egress registry. Poller-discovered workloads may be unioned
    // into those admitted services, but remote-only services must not be
    // appended after narrowing or the merge would widen the outbound policy
    // boundary.
    let allow_remote_service_append = !slice
        .sidecar_egress_scope
        .as_ref()
        .is_some_and(|scope| scope.sidecar_applied);
    let (workloads, services) = match remote_endpoints {
        Some(snapshot) if !snapshot.is_empty() => multicluster::merge_remote_endpoints_into_mesh(
            &slice.workloads,
            &slice.services,
            snapshot,
            slice.multi_cluster.as_ref(),
            allow_remote_service_append,
        ),
        _ => (slice.workloads.clone(), slice.services.clone()),
    };

    // Materialization (`materialize_mesh_outbound_proxies` → `build_outbound_mesh_targets`,
    // and the inbound / TCP / UDP materializers) reads workloads and services
    // from the SLICE it is handed, NOT from `config.mesh`. So when remote
    // endpoints were merged in — the `remote_clusters` DISCOVERY path, where the
    // multi-cluster poller learns remote workloads instead of them being embedded
    // in the slice — the merged set must ALSO reach materialization through the
    // slice, or cross-cluster east-west targets are built only from endpoints
    // already in the slice and miss every poller-discovered remote workload
    // (codex r5 [R5-4]). Mirror the merged workloads/services onto a synthetic
    // slice; the LOCAL materializers still filter remote workloads out
    // (`matched_local_service_workloads`), so only the cross-cluster materializer
    // picks the extra endpoints up. Built only when a merge happened, so the
    // common no-remote-endpoint apply clones nothing.
    let merged_slice = merged_remote.then(|| MeshSlice {
        workloads: workloads.clone(),
        services: services.clone(),
        ..slice.clone()
    });
    let materialization_slice = merged_slice.as_ref().unwrap_or(slice);

    let config = GatewayConfig {
        mesh: Some(Box::new(MeshConfig {
            workloads,
            services,
            mesh_policies: slice.mesh_policies.clone(),
            peer_authentications: slice.peer_authentications.clone(),
            service_entries: slice.service_entries.clone(),
            request_authentications: slice.request_authentications.clone(),
            telemetry_resources: slice.telemetry_resources.clone(),
            destination_rules: slice.destination_rules.clone(),
            virtual_service_cors_policies: slice.virtual_service_cors_policies.clone(),
            proxy_configs: slice.proxy_configs.clone(),
            // Slice-narrowing is applied CP-side at `MeshSlice::from_gateway_config`.
            // DPs receive the already-narrowed set of services / service-entries /
            // destination-rules; `MeshSidecar` resources are not echoed back.
            sidecars: Vec::new(),
            trust_bundles,
            multi_cluster: slice.multi_cluster.clone(),
            outbound_traffic_policy: slice.outbound_traffic_policy,
            ..MeshConfig::default()
        })),
        loaded_at,
        ..GatewayConfig::default()
    };
    prepare_gateway_config_for_native_slice(config, runtime, materialization_slice)
}

async fn wait_for_initial_mesh_config(
    mesh_state: &MeshRuntimeState,
    runtime: &MeshRuntimeConfig,
    activation: FederationActivation,
    mut shutdown_rx: tokio::sync::watch::Receiver<bool>,
) -> Result<(GatewayConfig, Arc<MeshSlice>), anyhow::Error> {
    let mut updates = mesh_state.subscribe();
    loop {
        let snapshot = mesh_state.snapshot();
        if let Some(slice) = snapshot.as_ref().as_ref() {
            let federation_snapshot = mesh_state.federation_store().snapshot();
            let remote_snapshot = mesh_state.remote_endpoint_store().snapshot();
            match gateway_config_from_mesh_slice_with_federation(
                slice,
                runtime,
                Some(&federation_snapshot),
                Some(&remote_snapshot),
                activation,
            ) {
                Ok(config) => return Ok((config, Arc::new(slice.clone()))),
                Err(e) => {
                    warn!(
                        mesh_slice_version = %slice.version,
                        error = %e,
                        "Ignoring invalid initial mesh slice"
                    );
                }
            }
        }

        tokio::select! {
            changed = updates.changed() => {
                if changed.is_err() {
                    return Err(anyhow::anyhow!(
                        "mesh slice update channel closed before a valid initial slice arrived"
                    ));
                }
            }
            _ = wait_for_mesh_shutdown(&mut shutdown_rx) => {
                return Err(anyhow::anyhow!("shutdown requested"));
            }
        }
    }
}

async fn wait_for_mesh_shutdown(shutdown_rx: &mut tokio::sync::watch::Receiver<bool>) {
    while !*shutdown_rx.borrow() {
        if shutdown_rx.changed().await.is_err() {
            return;
        }
    }
}

fn materialize_east_west_gateway_proxies(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) {
    if runtime.topology != MeshTopology::EastWestGateway {
        return;
    }

    // Materialize proxies from explicit EastWestGateway config entries (remote
    // gateway backends).
    if let Some(mesh) = config.mesh.as_ref()
        && let Some(multi_cluster) = mesh.multi_cluster.as_ref()
    {
        for gateway in &multi_cluster.east_west_gateways {
            if gateway.namespace != runtime.namespace {
                continue;
            }

            let proxy = east_west_gateway_proxy(gateway, runtime.east_west_listen_port);

            if let Some(existing) = config
                .proxies
                .iter_mut()
                .find(|candidate| candidate.id == proxy.id)
            {
                *existing = proxy;
            } else {
                config.proxies.push(proxy);
            }
        }
    }

    // SNI hosts already claimed by explicit EastWestGateway entries (same
    // namespace as the materialized explicit proxies above). The auto-materializer
    // yields to these so an operator's explicit route is never rejected as an
    // overlapping host on the shared listen port. Hosts are lowercased during
    // materialization and compared case-insensitively + wildcard-aware by
    // `validate_stream_proxies` (`hosts_overlap`), so the override set is
    // lowercased and the skip below uses the SAME overlap semantics — an exact
    // membership test would miss a wildcard explicit entry like
    // `*.ns.svc.cluster.local` that still owns the concrete auto host.
    //
    // The set must reflect only the gateways that ACTUALLY materialized a proxy.
    // The loop above collapses entries by generated proxy id (`find().map() ->
    // overwrite`), so two same-namespace gateways sharing a `name` leave only the
    // last one's proxy bound. Collecting SNI hosts from the raw list would also
    // keep the overwritten entry's hosts, suppressing an auto local-service proxy
    // that no surviving explicit proxy actually owns — silently dropping that
    // service from east-west routing. Dedup by the same generated id (last wins)
    // so an overwritten entry's hosts never suppress autos.
    let explicit_sni_hosts: Vec<String> = config
        .mesh
        .as_ref()
        .and_then(|mesh| mesh.multi_cluster.as_ref())
        .map(|multi_cluster| {
            let mut hosts_by_proxy_id: HashMap<String, Vec<String>> = HashMap::new();
            for gateway in multi_cluster
                .east_west_gateways
                .iter()
                .filter(|gateway| gateway.namespace == runtime.namespace)
            {
                // Last write wins, mirroring the materialization loop's
                // overwrite-by-id behavior above.
                hosts_by_proxy_id.insert(
                    mesh_east_west_proxy_id(&gateway.namespace, &gateway.name),
                    gateway
                        .sni_hosts
                        .iter()
                        .map(|host| host.to_ascii_lowercase())
                        .collect(),
                );
            }
            hosts_by_proxy_id.into_values().flatten().collect()
        })
        .unwrap_or_default();

    // Materialize SNI-routed TCP passthrough proxies for each local mesh
    // service so that inbound cross-cluster traffic on the east-west listen
    // port reaches the correct workload. Each service gets one proxy (SNI host
    // = service FQDN) and one upstream (targets = workload addresses).
    let (proxies, upstreams) = build_east_west_service_proxies_and_upstreams(
        mesh_slice,
        runtime.east_west_listen_port,
        &runtime.namespace,
        &runtime.cluster_domain,
        &explicit_sni_hosts,
    );

    if !proxies.is_empty() {
        info!(
            east_west_service_proxies = proxies.len(),
            east_west_service_upstreams = upstreams.len(),
            "Materializing east-west gateway proxies for local mesh services"
        );
    }

    for upstream in upstreams {
        if let Some(existing) = config
            .upstreams
            .iter_mut()
            .find(|candidate| candidate.id == upstream.id)
        {
            *existing = upstream;
        } else {
            config.upstreams.push(upstream);
        }
    }

    for proxy in proxies {
        if let Some(existing) = config
            .proxies
            .iter_mut()
            .find(|candidate| candidate.id == proxy.id)
        {
            *existing = proxy;
        } else {
            config.proxies.push(proxy);
        }
    }
}

fn east_west_gateway_proxy(gateway: &EastWestGateway, listen_port: u16) -> Proxy {
    let now = chrono::Utc::now();
    Proxy {
        id: mesh_east_west_proxy_id(&gateway.namespace, &gateway.name),
        name: Some(format!("mesh east-west {}", gateway.name)),
        namespace: gateway.namespace.clone(),
        hosts: gateway.sni_hosts.clone(),
        listen_path: None,
        backend_scheme: Some(BackendScheme::Tcp),
        dispatch_kind: Default::default(),
        backend_host: gateway.host.clone(),
        backend_port: gateway.port,
        backend_path: None,
        strip_listen_path: false,
        preserve_host_header: false,
        backend_connect_timeout_ms: 30_000,
        backend_read_timeout_ms: 30_000,
        backend_write_timeout_ms: 30_000,
        backend_tls_client_cert_path: None,
        backend_tls_client_key_path: None,
        backend_tls_verify_server_cert: true,
        backend_tls_server_ca_cert_path: None,
        resolved_tls: BackendTlsConfig::default(),
        dispatch_port_overrides: None,
        dispatch_port_override_fallback: None,
        dns_override: None,
        dns_cache_ttl_seconds: None,
        auth_mode: Default::default(),
        plugins: Vec::<PluginAssociation>::new(),
        pool_idle_timeout_seconds: None,
        pool_enable_http_keep_alive: None,
        pool_enable_http2: None,
        pool_tcp_keepalive_seconds: None,
        pool_http2_keep_alive_interval_seconds: None,
        pool_http2_keep_alive_timeout_seconds: None,
        pool_http2_initial_stream_window_size: None,
        pool_http2_initial_connection_window_size: None,
        pool_http2_adaptive_window: None,
        pool_http2_max_frame_size: None,
        pool_http2_max_concurrent_streams: None,
        pool_http3_connections_per_backend: None,
        h2_upgrade_policy: None,
        pool_max_requests_per_connection: None,
        // Derived-only: projected from DestinationRule port overrides at
        // dispatch time via `resolve_effective_proxy_for_target`; a
        // freshly-materialized mesh proxy starts at `None`.
        pool_http1_max_pending_requests: None,
        upstream_id: None,
        upstream_subset: None,
        api_spec_id: None,
        circuit_breaker: None,
        retry: None,
        response_body_mode: ResponseBodyMode::Stream,
        listen_port: Some(listen_port),
        frontend_tls: false,
        passthrough: true,
        udp_idle_timeout_seconds: 60,
        udp_max_response_amplification_factor: None,
        stream_proxy_protocol: None,
        tcp_idle_timeout_seconds: None,
        websocket_idle_timeout_seconds: None,
        allowed_methods: None,
        allowed_ws_origins: Vec::new(),
        created_at: now,
        updated_at: now,
    }
}

fn mesh_east_west_proxy_id(namespace: &str, name: &str) -> String {
    format!("__mesh-east-west-{namespace}-{name}").replace(['/', '.'], "-")
}

// ── East-west service proxy materialization ──────────────────────────────

/// Build TCP passthrough proxies and upstreams for local mesh services so that
/// inbound cross-cluster traffic on the east-west listen port is SNI-routed to
/// the correct local workload.
///
/// For each service in the mesh slice:
///   - SNI hostname = `{name}.{namespace}.svc.{cluster_domain}`
///   - One upstream with targets from workload addresses
///   - One TCP passthrough proxy on the east-west listen port
fn build_east_west_service_proxies_and_upstreams(
    mesh_slice: &MeshSlice,
    listen_port: u16,
    namespace: &str,
    cluster_domain: &str,
    explicit_sni_hosts: &[String],
) -> (Vec<Proxy>, Vec<Upstream>) {
    let mut proxies = Vec::new();
    let mut upstreams = Vec::new();
    let now = chrono::Utc::now();

    for service in &mesh_slice.services {
        // MULTI-PORT east-west (issue #2010 phase 3): materialize ONE
        // SNI-passthrough proxy per cross-cluster service port. A SINGLE-HTTP-port
        // service materializes exactly one proxy on the bare base service FQDN
        // with the port-less legacy id, byte-identical to the pre-multi-port
        // behavior. A MULTI-HTTP-port service materializes a proxy per port on an
        // explicit `p<port>.<fqdn>` SNI alias — the lowest port INCLUDED — so
        // client + destination agree per EXPLICIT numeric port and cannot
        // cross-wire under cross-cluster port skew (codex #2040 Finding A);
        // `cross_cluster_service_sni` is the shared source of that SNI. L4 ports
        // are inherently per-port and use `p<port>.<fqdn>` (or the
        // protocol-suffixed form when TCP and UDP share a number).
        for service_port in &service.ports {
            // `None` (⇒ port-less legacy id) ONLY for a single-port service's sole
            // port (`cross_cluster_service_base_port` returns `None` for a
            // multi-port service); every port of a multi-port service carries its
            // own `.p<port>` id so the per-port proxies never collide (codex #2040
            // Finding B).
            let id_suffix = cross_cluster_service_sni_label(service, service_port);
            // Build upstream targets for THIS service port.
            let targets = build_east_west_service_targets(
                service,
                service_port,
                &mesh_slice.workloads,
                mesh_slice.multi_cluster.as_ref(),
            );
            if targets.is_empty() {
                debug!(
                    service = %service.name,
                    namespace = %service.namespace,
                    service_port = service_port.port,
                    "Skipping east-west service port with no reachable workload targets"
                );
                continue;
            }

            let sni_hostname = cross_cluster_service_sni(service, service_port, cluster_domain);

            // An explicit `EastWestGateway.sni_hosts` entry takes precedence over
            // the auto-materialized local-service proxy: materializing both yields
            // two TCP passthrough proxies claiming the same SNI on the shared
            // east-west listen port, which `validate_stream_proxies` rejects as
            // overlapping hosts — silently dropping the operator's explicit route.
            // Skip the auto proxy (and its upstream) so the override survives. Use
            // the SAME wildcard-aware `hosts_overlap` semantics validation uses (an
            // exact match would miss a wildcard explicit entry); guard on non-empty
            // so an absent explicit list (a catch-all under `hosts_overlap`) never
            // suppresses every auto proxy.
            //
            // Suppress PER PORT SNI ONLY (codex #2040): suppress an auto proxy only
            // when the explicit list overlaps THIS port's SNI. An explicit entry
            // that lists only the base FQDN suppresses the base auto proxy but
            // leaves the per-port ALIAS auto proxies materialized, so the alias
            // ports stay routable to the local workload. Suppressing the aliases
            // WITHOUT the explicit route also owning them (its `hosts` are not
            // expanded with the aliases) would make every non-base port fail closed
            // — no SNI match at the destination gateway. A partial explicit
            // override therefore SPLITS the service (base ⇒ explicit backend,
            // aliases ⇒ local auto route); an operator who wants all ports on the
            // explicit backend lists the aliases (or a wildcard) in `sni_hosts`.
            let auto_sni_lower = sni_hostname.to_ascii_lowercase();
            if !explicit_sni_hosts.is_empty()
                && crate::config::types::hosts_overlap(
                    std::slice::from_ref(&auto_sni_lower),
                    explicit_sni_hosts,
                )
            {
                debug!(
                    service = %service.name,
                    namespace = %service.namespace,
                    sni = %sni_hostname,
                    "Skipping east-west auto-materialization; an explicit EastWestGateway already owns this SNI host (or the base service FQDN)"
                );
                continue;
            }

            let upstream_id = mesh_east_west_service_upstream_id(
                &service.namespace,
                &service.name,
                id_suffix.as_deref(),
            );

            let upstream = Upstream {
                id: upstream_id.clone(),
                name: Some(upstream_id.clone()),
                namespace: namespace.to_string(),
                targets,
                algorithm: LoadBalancerAlgorithm::RoundRobin,
                hash_on: None,
                hash_on_cookie_config: None,
                health_checks: Some(HealthCheckConfig {
                    active: None,
                    passive: Some(PassiveHealthCheck::default()),
                }),
                service_discovery: None,
                subsets: None,
                port_overrides: HashMap::new(),
                source_locality: None,
                locality_lb_strict: false,
                locality_lb_setting: None,
                backend_tls_client_cert_path: None,
                backend_tls_client_key_path: None,
                backend_tls_verify_server_cert: true,
                backend_tls_server_ca_cert_path: None,
                backend_tls_sni: None,
                backend_tls_san_allow_list: Vec::new(),
                resolved_subset_tls: HashMap::new(),
                dispatch_port_override_fallback: None,
                api_spec_id: None,
                created_at: now,
                updated_at: now,
            };
            upstreams.push(upstream);

            let proxy_id = mesh_east_west_service_proxy_id(
                &service.namespace,
                &service.name,
                id_suffix.as_deref(),
            );
            let proxy = east_west_service_proxy(
                &proxy_id,
                &sni_hostname,
                namespace,
                &upstream_id,
                listen_port,
                now,
            );
            proxies.push(proxy);
        }
    }

    (proxies, upstreams)
}

/// Match a service's `WorkloadRef`s to slice `Workload`s one-to-one by index (so
/// replicas sharing a SPIFFE id yield distinct workloads), while filtering
/// remote-cluster endpoints before consuming a ref slot. Shared scaffold for
/// the east-west and Ambient outbound target builders, which differ only in
/// per-target port/tag policy.
pub(crate) fn matched_local_service_workloads<'a>(
    service: &crate::modes::mesh::config::MeshService,
    workloads: &'a [crate::modes::mesh::config::Workload],
    multi_cluster: Option<&crate::modes::mesh::config::MultiClusterConfig>,
) -> Vec<&'a crate::modes::mesh::config::Workload> {
    let mut matched = Vec::new();
    let mut used_workload_indices = std::collections::HashSet::new();

    for workload_ref in &service.workloads {
        let has_matching_service_metadata = workloads.iter().any(|workload| {
            workload.spiffe_id == workload_ref.spiffe_id
                && workload.namespace == service.namespace
                && workload.service_name == service.name
        });
        let Some((workload_index, workload)) =
            workloads.iter().enumerate().find(|(idx, workload)| {
                !used_workload_indices.contains(idx)
                    && workload.spiffe_id == workload_ref.spiffe_id
                    && workload.namespace == service.namespace
                    && (workload.service_name == service.name || !has_matching_service_metadata)
                    && !crate::modes::mesh::multicluster::workload_is_remote(
                        workload,
                        multi_cluster,
                    )
            })
        else {
            continue;
        };
        used_workload_indices.insert(workload_index);
        matched.push(workload);
    }

    matched
}

/// The REMOTE-cluster counterpart of [`matched_local_service_workloads`]: the
/// service's workloads that ARE remote (`workload_is_remote == true`). Used by
/// cross-cluster east-west materialization to learn (per remote network) the
/// remote trust domain a service is reachable in, so a SIDECAR client can route
/// the service to the remote network's east-west gateway. The local materializer
/// filters these OUT (their pod IPs are unreachable); this helper deliberately
/// keeps ONLY them — it never produces targets that dial a remote pod IP (the
/// caller addresses the east-west gateway instead).
///
/// Mirrors the local helper's SPIFFE-ref + namespace matching and the
/// `service_name`-vs-stale-metadata fallback, with the remoteness predicate
/// flipped — but, UNLIKE the local helper, it collects ALL remote workloads a
/// ref matches, not one-per-ref (codex r3): `merge_remote_endpoints_into_mesh`
/// UNIONS remote service workload refs by SPIFFE id, so in the common
/// same-trust-domain multi-cluster case where replicas of a service in different
/// remote NETWORKS share one service-account SPIFFE id, the service carries a
/// SINGLE ref for that id even though both networks' `Workload`s survive the
/// merge (keyed by endpoint, incl. network+address). A one-per-ref `.find` would
/// return only the first network and the second network's east-west gateway
/// would never be reached by `(network, trust_domain)` grouping. The
/// `used_workload_indices` guard still prevents double-counting a single
/// workload across refs that share a SPIFFE id.
fn matched_remote_service_workloads<'a>(
    service: &crate::modes::mesh::config::MeshService,
    workloads: &'a [crate::modes::mesh::config::Workload],
    multi_cluster: Option<&crate::modes::mesh::config::MultiClusterConfig>,
) -> Vec<&'a crate::modes::mesh::config::Workload> {
    let mut matched = Vec::new();
    let mut used_workload_indices = std::collections::HashSet::new();

    for workload_ref in &service.workloads {
        let has_matching_service_metadata = workloads.iter().any(|workload| {
            workload.spiffe_id == workload_ref.spiffe_id
                && workload.namespace == service.namespace
                && workload.service_name == service.name
        });
        // Collect EVERY not-yet-used remote workload this ref matches (one ref
        // can stand for replicas across multiple remote networks).
        for (workload_index, workload) in workloads.iter().enumerate() {
            if !used_workload_indices.contains(&workload_index)
                && workload.spiffe_id == workload_ref.spiffe_id
                && workload.namespace == service.namespace
                && (workload.service_name == service.name || !has_matching_service_metadata)
                && crate::modes::mesh::multicluster::workload_is_remote(workload, multi_cluster)
            {
                used_workload_indices.insert(workload_index);
                matched.push(workload);
            }
        }
    }

    matched
}

/// The base cross-cluster east-west SNI for a service — the destination service
/// FQDN `<name>.<namespace>.svc.<cluster-domain>`. A SINGLE-HTTP-port service's
/// sole port routes on this; a MULTI-HTTP-port service routes NO port on it
/// (every port takes a `p<port>.<fqdn>` alias). It is also the host a client
/// uses to SELECT an `EastWestGateway` (whose `sni_hosts` claiming the base
/// FQDN auto-extends to the per-port aliases; see
/// [`east_west_acceptable_snis`]). See [`cross_cluster_service_sni`].
pub(crate) fn cross_cluster_service_base_fqdn(
    service: &crate::modes::mesh::config::MeshService,
    cluster_domain: &str,
) -> String {
    let cluster_domain = cluster_domain.trim_matches('.');
    format!(
        "{}.{}.svc.{cluster_domain}",
        service.name, service.namespace
    )
}

/// The service port that owns the port-LESS internal east-west id for a
/// SINGLE-HTTP-port service — its sole HTTP-family port. Returns `None` for a
/// service with no HTTP-family port (no cross-cluster east-west target is
/// materialized for it) OR for a MULTI-HTTP-port service (every port of which
/// takes an explicit per-port id/SNI — no port owns a bare base). This drives
/// only the internal id/SNI base-vs-alias decision; it is NOT a routing
/// authority. It is intentionally `None` for multi-port so no port is silently
/// mapped onto the bare base FQDN across clusters (codex #2040 Finding A).
pub(crate) fn cross_cluster_service_base_port(
    service: &crate::modes::mesh::config::MeshService,
) -> Option<u16> {
    let http_ports = service_http_family_ports(service);
    match http_ports.as_slice() {
        [only] => Some(only.port),
        _ => None,
    }
}

/// DNS label (and internal id suffix) for a service port's east-west alias.
/// `None` is the HTTP-only bare-base compatibility case. L4 normally uses
/// `p<port>`; when TCP-family and UDP share the same numeric service port, the
/// transport discriminator is required because their targetPorts may differ.
fn cross_cluster_service_sni_label(
    service: &crate::modes::mesh::config::MeshService,
    service_port: &crate::modes::mesh::config::ServicePort,
) -> Option<String> {
    let effective_protocol = service
        .protocol_overrides
        .get(&service_port.port)
        .copied()
        .unwrap_or(service_port.protocol);
    if is_http_family_mesh_protocol(effective_protocol)
        && cross_cluster_service_base_port(service) == Some(service_port.port)
    {
        return None;
    }

    let l4_same_number = service
        .ports
        .iter()
        .filter(|candidate| {
            candidate.port == service_port.port
                && !is_http_family_mesh_protocol(
                    service
                        .protocol_overrides
                        .get(&candidate.port)
                        .copied()
                        .unwrap_or(candidate.protocol),
                )
        })
        .count();
    if l4_same_number > 1 {
        let transport = if is_udp_mesh_protocol(effective_protocol) {
            "udp"
        } else {
            "tcp"
        };
        Some(format!("p{}-{transport}", service_port.port))
    } else {
        Some(format!("p{}", service_port.port))
    }
}

/// The cross-cluster east-west SNI a `(service, service_port)` routes on
/// (multi-port scheme, issue #2010 phase 3; codex #2040 Finding A).
///
/// - A **single-HTTP-port** service routes its sole port on the bare base
///   service FQDN ([`cross_cluster_service_base_fqdn`], e.g.
///   `reviews.default.svc.cluster.local`) — backward-compatible and unambiguous
///   (only one port is possible, so there is nothing to disambiguate).
/// - A **multi-HTTP-port** service routes EVERY port — including the numerically
///   lowest — on an explicit per-port alias `p<service_port>.<base_fqdn>` (e.g.
///   `p8080.reviews...`, `p9090.reviews...`). The bare base FQDN routes to NO
///   port for a multi-port service.
/// - A **raw-TCP or UDP** port routes on `p<service_port>.<base_fqdn>`; when
///   TCP and UDP share the number, `-tcp` / `-udp` disambiguates their aliases.
///   L4 capture never consumes the HTTP-only bare-base compatibility case.
///
/// Aliasing every port of a multi-port service (rather than routing the lowest
/// port on the bare base) is what makes the scheme fail CLOSED under
/// cross-cluster port skew: because the port channel is the EXPLICIT numeric
/// port in the alias, a client cluster and the destination cluster agree per
/// numeric port regardless of which HTTP ports EITHER cluster happens to declare.
/// The previous "lowest port owns the base FQDN" rule could silently misroute
/// when the two clusters had different port sets (a client that only knows :9090
/// would treat it as the base while the destination materialized the base for
/// :8080). There is no bare-base-to-port mapping to mis-hit here, so the skew
/// cannot cross-wire.
///
/// The NUMERIC service port is authoritative in the alias — a port NAME is never
/// used. SNI carries no port, so a per-port DNS-safe alias is the port channel.
/// Both the client materializers (as the `mesh.eastwest_sni` dial override) and
/// the destination gateway's per-port passthrough proxies derive their SNI from
/// this one function, so the two sides cannot drift.
pub(crate) fn cross_cluster_service_sni(
    service: &crate::modes::mesh::config::MeshService,
    service_port: &crate::modes::mesh::config::ServicePort,
    cluster_domain: &str,
) -> String {
    let base = cross_cluster_service_base_fqdn(service, cluster_domain);
    // Bare base FQDN ONLY for a single-HTTP-port service (its sole port). Every
    // port of a multi-port service — lowest included — gets an explicit alias.
    cross_cluster_service_sni_label(service, service_port)
        .map_or(base.clone(), |label| format!("{label}.{base}"))
}

/// Build upstream targets from workloads that belong to the given service, for
/// ONE `service_port`.
///
/// Matches workloads by SPIFFE ID against the service's `WorkloadRef` list. Each
/// workload address + the resolved container port for `service_port` produces one
/// `UpstreamTarget`. When a workload has no addresses, it is skipped (pod IP not
/// yet assigned). One passthrough proxy is materialized per HTTP-family service
/// port (multi-port east-west, issue #2010 phase 3), each keyed by the port's SNI
/// alias ([`cross_cluster_service_sni`]).
fn build_east_west_service_targets(
    service: &crate::modes::mesh::config::MeshService,
    service_port: &crate::modes::mesh::config::ServicePort,
    workloads: &[crate::modes::mesh::config::Workload],
    multi_cluster: Option<&crate::modes::mesh::config::MultiClusterConfig>,
) -> Vec<UpstreamTarget> {
    let mut targets = Vec::new();
    for workload in matched_local_service_workloads(service, workloads, multi_cluster) {
        // Backend (container) port for this workload address: honor
        // `service_port`'s `targetPort` (Kubernetes' authoritative
        // service-port→container-port binding). A DECLARED targetPort is
        // authoritative — resolve it, or SKIP this target (fail closed) rather
        // than fall back to the Service port, so an unresolved named targetPort
        // (rollout skew / typo like `targetPort: "http"` with no matching
        // container port) doesn't silently publish a target on the wrong port.
        // Only an ABSENT targetPort falls back to the service port.
        let target_port = match service_port.target_port.as_ref() {
            Some(_) => {
                match resolve_target_port(service_port.target_port.as_ref(), &workload.ports) {
                    Some(p) if p != 0 => p,
                    _ => continue,
                }
            }
            None => service_port.port,
        };

        for address in &workload.addresses {
            // Copy the workload's operator-authored labels as target tags, but
            // STRIP the reserved `mesh.*` namespace first: those keys are mesh
            // provenance/transport markers the data plane owns (e.g. the
            // `mesh.remote=true` strict-locality signal). Without this, a workload
            // labelled `mesh.remote: "true"` would make a LOCAL east-west target
            // masquerade as remote and be excluded by strict locality LB.
            let mut tags = workload.selector.labels.clone();
            crate::modes::mesh::multicluster::strip_reserved_mesh_tags(&mut tags);
            targets.push(UpstreamTarget {
                host: address.clone(),
                port: target_port,
                service_port_policy_key: Some(service_port.port),
                weight: 1,
                tags,
                locality: workload.locality.clone(),
                path: None,
            });
        }
    }

    targets
}

/// Construct a TCP passthrough proxy for east-west service routing.
fn east_west_service_proxy(
    id: &str,
    sni_hostname: &str,
    namespace: &str,
    upstream_id: &str,
    listen_port: u16,
    now: chrono::DateTime<chrono::Utc>,
) -> Proxy {
    Proxy {
        id: id.to_string(),
        name: Some(format!("mesh east-west svc {sni_hostname}")),
        namespace: namespace.to_string(),
        hosts: vec![sni_hostname.to_string()],
        listen_path: None,
        backend_scheme: Some(BackendScheme::Tcp),
        dispatch_kind: Default::default(),
        backend_host: String::new(),
        backend_port: 0,
        backend_path: None,
        strip_listen_path: false,
        preserve_host_header: false,
        backend_connect_timeout_ms: 30_000,
        backend_read_timeout_ms: 30_000,
        backend_write_timeout_ms: 30_000,
        backend_tls_client_cert_path: None,
        backend_tls_client_key_path: None,
        backend_tls_verify_server_cert: false,
        backend_tls_server_ca_cert_path: None,
        resolved_tls: BackendTlsConfig::default(),
        dispatch_port_overrides: None,
        dispatch_port_override_fallback: None,
        dns_override: None,
        dns_cache_ttl_seconds: None,
        auth_mode: Default::default(),
        plugins: Vec::<PluginAssociation>::new(),
        pool_idle_timeout_seconds: None,
        pool_enable_http_keep_alive: None,
        pool_enable_http2: None,
        pool_tcp_keepalive_seconds: None,
        pool_http2_keep_alive_interval_seconds: None,
        pool_http2_keep_alive_timeout_seconds: None,
        pool_http2_initial_stream_window_size: None,
        pool_http2_initial_connection_window_size: None,
        pool_http2_adaptive_window: None,
        pool_http2_max_frame_size: None,
        pool_http2_max_concurrent_streams: None,
        pool_http3_connections_per_backend: None,
        h2_upgrade_policy: None,
        pool_max_requests_per_connection: None,
        // Derived-only: projected from DestinationRule port overrides at
        // dispatch time via `resolve_effective_proxy_for_target`; a
        // freshly-materialized mesh proxy starts at `None`.
        pool_http1_max_pending_requests: None,
        upstream_id: Some(upstream_id.to_string()),
        upstream_subset: None,
        api_spec_id: None,
        circuit_breaker: None,
        retry: None,
        response_body_mode: ResponseBodyMode::Stream,
        listen_port: Some(listen_port),
        frontend_tls: false,
        passthrough: true,
        udp_idle_timeout_seconds: 60,
        udp_max_response_amplification_factor: None,
        stream_proxy_protocol: None,
        tcp_idle_timeout_seconds: None,
        websocket_idle_timeout_seconds: None,
        allowed_methods: None,
        allowed_ws_origins: Vec::new(),
        created_at: now,
        updated_at: now,
    }
}

/// Sanitize one namespace/name component of an internal east-west id. These ids
/// are purely internal registry keys (a `Proxy.id`/`Upstream.id`, never emitted
/// to Kubernetes, DNS, SNI/TLS, or any wire protocol — the SNI is built
/// independently by [`cross_cluster_service_sni`]), so the only requirement is
/// intra-component uniqueness. `/` and `.` are folded to `-` so a hostile or
/// malformed component cannot smuggle the reserved `.` port-marker separator
/// (see [`mesh_east_west_service_proxy_id`]) into the middle of an id. A
/// well-formed Kubernetes namespace/service name (DNS-1035/1123 label) contains
/// neither character, so this is a no-op for real inputs.
fn sanitize_mesh_id_component(component: &str) -> String {
    component.replace(['/', '.'], "-")
}

/// East-west per-service proxy id. `sni_label` is `None` for a SINGLE-HTTP-port
/// service — which keeps the historic port-LESS `__mesh-ew-svc-<ns>-<name>` id so
/// that service is byte-identical to the pre-multi-port shape — and `Some(port)`
/// for EVERY port of a MULTI-port service (multi-port east-west, issue #2010
/// phase 3; L4 labels may additionally carry a `-tcp` / `-udp` discriminator
/// when both transports share one number. No bare base id is emitted for a multi-port service, matching the
/// SNI scheme where every port of a multi-port service takes an explicit
/// `p<port>.<fqdn>` alias).
///
/// The port marker is joined with `.` — a character DNS-1035/1123 labels forbid,
/// so it CANNOT appear in a Kubernetes namespace or service name (codex #2040
/// Finding B). This makes the per-port id `__mesh-ew-svc-<ns>-<name>.p<port>`
/// unambiguous: a distinct service literally named `<name>-p<port>` yields
/// `__mesh-ew-svc-<ns>-<name>-p<port>` (no dot) and a service named `<name>.p<port>`
/// is not a valid k8s name (impossible), so neither can collide in the
/// materializer's id-keyed upsert map. The ns/name components are individually
/// sanitized (`/`,`.` → `-`) BEFORE the `.p<port>` marker is appended so a
/// malformed component can never forge the structural separator, while the
/// intentional marker dot is preserved (never collapsed).
fn mesh_east_west_service_proxy_id(namespace: &str, name: &str, sni_label: Option<&str>) -> String {
    let namespace = sanitize_mesh_id_component(namespace);
    let name = sanitize_mesh_id_component(name);
    match sni_label {
        None => format!("__mesh-ew-svc-{namespace}-{name}"),
        Some(label) => format!("__mesh-ew-svc-{namespace}-{name}.{label}"),
    }
}

/// East-west per-service upstream id; `sni_label` semantics and the
/// collision-free `.p<port>` marker mirror [`mesh_east_west_service_proxy_id`]
/// (single-port ⇒ port-less legacy id; multi-port ⇒ explicit per-port id).
fn mesh_east_west_service_upstream_id(
    namespace: &str,
    name: &str,
    sni_label: Option<&str>,
) -> String {
    let namespace = sanitize_mesh_id_component(namespace);
    let name = sanitize_mesh_id_component(name);
    match sni_label {
        None => format!("__mesh-ew-upstream-{namespace}-{name}"),
        Some(label) => format!("__mesh-ew-upstream-{namespace}-{name}.{label}"),
    }
}

// ── Sidecar inbound route materialization ─────────────────────────────────

/// True for application protocols routed through the HTTP-family proxy chain.
/// Stream protocols (raw TCP/TLS and the DB protocols) need an L4 stream proxy;
/// `Udp` is a distinct L4 transport whose capture/egress arrives in a later
/// stage. Neither is HTTP-family — only `Udp` is also excluded from the
/// raw-TCP stream lane (see [`service_udp_stream_ports`]).
fn is_http_family_mesh_protocol(protocol: AppProtocol) -> bool {
    matches!(
        protocol,
        AppProtocol::Http | AppProtocol::Http2 | AppProtocol::Grpc | AppProtocol::Unknown
    )
}

/// Host header variants a peer may use to reach a mesh service, in the form the
/// router matches (the listener strips the port before routing): the bare
/// service name (local-namespace short form) plus the `.ns`, `.ns.svc`, and
/// `.ns.svc.<cluster_domain>` Kubernetes forms.
fn mesh_service_host_variants(name: &str, namespace: &str, cluster_domain: &str) -> Vec<String> {
    let domain = cluster_domain.trim_matches('.');
    vec![
        name.to_string(),
        format!("{name}.{namespace}"),
        format!("{name}.{namespace}.svc"),
        format!("{name}.{namespace}.svc.{domain}"),
    ]
}

/// Reserved id prefix for materialized sidecar inbound routes. These routes are
/// **direction-scoped**: only the inbound listener may serve them. The inbound
/// and outbound capture listeners share one route table, so the request path
/// uses [`is_mesh_inbound_route_id`] to keep these loopback routes off the
/// outbound listener (where they would shortcut an app's own-service traffic to
/// loopback instead of the mesh).
pub(crate) const MESH_INBOUND_PROXY_ID_PREFIX: &str = "__mesh-inbound-";

/// Reserved id prefix for materialized Sidecar `ingress[]` custom inbound
/// listener routes (F6 §6.2). Also inbound-direction (served only on the
/// inbound listener), but a DISTINCT prefix from the service-port default
/// inbound routes so the two are never conflated: ingress routes are keyed by
/// the operator-declared listener port and forward to the entry's
/// `defaultEndpoint`, and (per Istio) REPLACE the default service-port inbound
/// materialization when present. Treated as `Inbound` by
/// [`is_mesh_inbound_route_id`] / [`mesh_route_direction`].
pub(crate) const MESH_INGRESS_PROXY_ID_PREFIX: &str = "__mesh-ingress-";

/// Whether a proxy id names a materialized sidecar inbound route — either a
/// service-port default inbound route or a Sidecar `ingress[]` custom listener
/// route. Both are inbound-direction (served only on the inbound listener) and
/// share the request-path inbound port-selection arm.
pub(crate) fn is_mesh_inbound_route_id(id: &str) -> bool {
    id.starts_with(MESH_INBOUND_PROXY_ID_PREFIX) || id.starts_with(MESH_INGRESS_PROXY_ID_PREFIX)
}

/// Whether a proxy id names a Sidecar `ingress[]` custom inbound listener route
/// specifically (a subset of [`is_mesh_inbound_route_id`]).
pub(crate) fn is_mesh_ingress_route_id(id: &str) -> bool {
    id.starts_with(MESH_INGRESS_PROXY_ID_PREFIX)
}

/// LATENT-COLLISION HAZARD (shared by this whole `mesh_*_id` family —
/// `mesh_ingress_proxy_id`, `mesh_outbound_proxy_id`,
/// `mesh_outbound_upstream_id`, `mesh_outbound_tcp_upstream_id`,
/// `mesh_east_west_*_id`, etc.): the `{namespace}-{name}-{port}` join uses `-`
/// as the field separator, but `replace(['/', '.'], "-")` ALSO emits `-`, so
/// `(ns="a-b", name="c")` and `(ns="a", name="b-c")` would map to the same id.
/// SAFE TODAY because every in-scope materializer consumes a SINGLE-namespace
/// service set (the slice is scoped to one namespace), so the `namespace`
/// segment is constant and only `name`+`port` vary — and a `name` cannot
/// borrow a `-` from a fixed `namespace`. Before any MULTI-namespace caller is
/// added, switch this family to the reversible token scheme used by the egress
/// ids (`sanitize_egress_host_id_part`) so the id space stays injective. See
/// #1727.
fn mesh_inbound_proxy_id(namespace: &str, name: &str, port: u16) -> String {
    format!("{MESH_INBOUND_PROXY_ID_PREFIX}{namespace}-{name}-{port}").replace(['/', '.'], "-")
}

/// Id for a materialized Sidecar `ingress[]` listener route, one per declared
/// listener port. The local workload's namespace + service name scope the id so
/// it never collides with another local service's ingress siblings; the port
/// disambiguates listeners. Like the inbound id, sanitized of `/`/`.`.
fn mesh_ingress_proxy_id(namespace: &str, name: &str, port: u16) -> String {
    format!("{MESH_INGRESS_PROXY_ID_PREFIX}{namespace}-{name}-{port}").replace(['/', '.'], "-")
}

/// Reserved id prefix for materialized mesh OUTBOUND (egress) routes. Like the
/// inbound prefix, these are **direction-scoped**: only the outbound capture
/// listener (`:15001`) may serve them. The inbound and outbound capture
/// listeners share one route table, so the request path uses
/// [`mesh_route_direction`] to keep an outbound route off the inbound listener
/// (where a peer's request for the local service would otherwise be re-tunnelled
/// back out to the mesh instead of delivered locally).
pub(crate) const MESH_OUTBOUND_PROXY_ID_PREFIX: &str = "__mesh-outbound-";

/// Whether a proxy id names a materialized mesh outbound route.
pub(crate) fn is_mesh_outbound_route_id(id: &str) -> bool {
    id.starts_with(MESH_OUTBOUND_PROXY_ID_PREFIX)
}

/// The mesh traffic direction a materialized route serves, or `None` when the id
/// does not name a direction-scoped mesh route. The request path uses this to
/// keep inbound routes off the outbound listener and outbound routes off the
/// inbound listener (the two capture listeners share one route table).
///
/// Only ever called on **proxy (route) ids** — request path, operator-yield,
/// authz — never on upstream ids. `mesh_outbound_upstream_id` deliberately uses a
/// non-overlapping `__mesh-out-upstream-` prefix (not `__mesh-outbound-`) so an
/// upstream id can never be misclassified as an Outbound route here.
///
/// Sidecar `ingress[]` custom-listener routes (`__mesh-ingress-*`) classify as
/// `Inbound` too (via [`is_mesh_inbound_route_id`]).
pub(crate) fn mesh_route_direction(id: &str) -> Option<MeshTrafficDirection> {
    if is_mesh_inbound_route_id(id) {
        Some(MeshTrafficDirection::Inbound)
    } else if is_mesh_outbound_route_id(id) {
        Some(MeshTrafficDirection::Outbound)
    } else {
        None
    }
}

fn mesh_outbound_proxy_id(namespace: &str, name: &str, port: u16) -> String {
    format!("{MESH_OUTBOUND_PROXY_ID_PREFIX}{namespace}-{name}-{port}").replace(['/', '.'], "-")
}

/// HTTP-family service ports of an in-mesh service, with `protocol_overrides`
/// applied — the canonical "which ports does outbound materialization route"
/// predicate, shared by the materializer, the router's sibling grouping, and
/// the listen-path uniqueness exemption so the three can never drift.
pub(crate) fn service_http_family_ports(
    service: &crate::modes::mesh::config::MeshService,
) -> Vec<&crate::modes::mesh::config::ServicePort> {
    service
        .ports
        .iter()
        .filter(|sp| {
            is_http_family_mesh_protocol(
                service
                    .protocol_overrides
                    .get(&sp.port)
                    .copied()
                    .unwrap_or(sp.protocol),
            )
        })
        .collect()
}

/// Expected per-port outbound sibling routes of one in-mesh service.
///
/// **Single source of truth for per-port sibling identity.** Derived
/// *forward* from the mesh service (the exact ids [`mesh_outbound_proxy_id`]
/// emits), never by parsing ids backwards — `{namespace}-{name}` joining is
/// lossy (`ns "a" / svc "b-c"` and `ns "a-b" / svc "c"` collide), so id
/// parsing could conflate distinct services. Consumers:
/// `RouterCache::build_route_table` groups a service's materialized siblings
/// under one lowest-port tier representative, and
/// `validate_unique_listen_paths` exempts same-service sibling pairs from the
/// host+path uniqueness conflict (they intentionally share hosts + `/` and
/// are disambiguated post-match by the captured original-destination port).
/// Operator configs cannot reach either consumer's special-casing:
/// resource-id validation rejects ids starting with `_`, so
/// `__mesh-outbound-*` ids exist only via mesh materialization, and both
/// consumers key strictly off the `mesh` block the slice carried.
///
/// Despite the name, the struct shape is direction-agnostic:
/// [`mesh_inbound_service_groups`] reuses it for the sidecar INBOUND per-port
/// siblings (disambiguated by inbound orig-dst / the request authority port
/// instead of the outbound capture's orig-dst).
pub(crate) struct MeshOutboundServiceGroup {
    /// How many HTTP-family ports the service DECLARES — which can exceed the
    /// materialized sibling count (e.g. an unresolved named `targetPort`
    /// produced no targets for one port). Orig-dst-less requests must fail
    /// closed whenever this is > 1, even if only one sibling materialized:
    /// without the captured port, traffic meant for a skipped port is
    /// indistinguishable from the surviving one.
    pub declared_http_ports: usize,
    /// `(service_port, expected proxy id)` for every declared HTTP-family
    /// port, whether or not it materialized.
    pub siblings: Vec<(u16, String)>,
}

/// Compute [`MeshOutboundServiceGroup`]s for every in-mesh service carried by
/// the prepared config's `mesh` block. Empty outside mesh mode.
pub(crate) fn mesh_outbound_service_groups(
    mesh: &crate::modes::mesh::config::MeshConfig,
) -> Vec<MeshOutboundServiceGroup> {
    mesh.services
        .iter()
        .filter_map(|service| {
            let http_ports = service_http_family_ports(service);
            if http_ports.is_empty() {
                return None;
            }
            Some(MeshOutboundServiceGroup {
                declared_http_ports: http_ports.len(),
                siblings: http_ports
                    .iter()
                    .map(|sp| {
                        (
                            sp.port,
                            mesh_outbound_proxy_id(&service.namespace, &service.name, sp.port),
                        )
                    })
                    .collect(),
            })
        })
        .collect()
}

/// True when a (override-resolved) protocol is the distinct UDP L4 transport.
/// `Udp` is NEITHER HTTP-family NOR raw-TCP-stream — it forms the third leg of
/// the port partition. Capture/egress for UDP arrives in a later F3 §3.3 stage;
/// today this only keeps UDP ports out of the other two lanes (they were
/// previously mis-classified as HTTP via `Unknown`).
fn is_udp_mesh_protocol(protocol: AppProtocol) -> bool {
    matches!(protocol, AppProtocol::Udp)
}

/// Stream-family service ports of an in-mesh service — raw TCP, opaque TLS,
/// and the DB protocols — with `protocol_overrides` applied: the raw-TCP
/// egress mirror of [`service_http_family_ports`]. HTTP-family,
/// raw-TCP-stream, and UDP form a STRICT THREE-WAY PARTITION of `AppProtocol`
/// (a unit test pins this): `Unknown` deliberately stays HTTP-family (the
/// long-standing default), `Tls` is opaque-byte passthrough here (the captured
/// original destination selects the destination service, no SNI parsing), and
/// `Udp` is EXCLUDED here (it is neither HTTP-family nor a REDIRECT-captured
/// raw-TCP stream — see [`service_udp_stream_ports`]).
pub(crate) fn service_tcp_stream_ports(
    service: &crate::modes::mesh::config::MeshService,
) -> Vec<&crate::modes::mesh::config::ServicePort> {
    service
        .ports
        .iter()
        .filter(|sp| {
            let protocol = service
                .protocol_overrides
                .get(&sp.port)
                .copied()
                .unwrap_or(sp.protocol);
            !is_http_family_mesh_protocol(protocol) && !is_udp_mesh_protocol(protocol)
        })
        .collect()
}

/// UDP service ports of an in-mesh service, with `protocol_overrides` applied:
/// the third leg of the HTTP-family / raw-TCP-stream / UDP port partition.
/// Consumed by the Ambient UDP egress materializer
/// (`materialize_mesh_outbound_udp_upstreams`, F3 §3.3 Stage 4) and the route
/// table's `mesh_udp_egress` index — a captured UDP datagram whose orig-dst
/// matches `(service VIP, UDP service port)` is tunnelled over a `udp`-marked
/// HBONE CONNECT. Mirrors [`service_http_family_ports`] and
/// [`service_tcp_stream_ports`]; the SINGLE forward-derivation source the
/// materializer, the route table, and the capability enrollment share.
pub(crate) fn service_udp_stream_ports(
    service: &crate::modes::mesh::config::MeshService,
) -> Vec<&crate::modes::mesh::config::ServicePort> {
    service
        .ports
        .iter()
        .filter(|sp| {
            is_udp_mesh_protocol(
                service
                    .protocol_overrides
                    .get(&sp.port)
                    .copied()
                    .unwrap_or(sp.protocol),
            )
        })
        .collect()
}

/// Expected per-port INBOUND sibling routes of each local service, mirroring
/// [`mesh_outbound_service_groups`] for the sidecar inbound direction (same
/// forward-derivation doctrine — see that helper's doc). Reads the
/// local-inbound service view (`local_inbound_services` when Sidecar narrowing
/// resolved it, else `services`) so it matches what
/// `materialize_sidecar_inbound_proxies` consumed; the egress-narrowed
/// `services` can lack the local service entirely. Over-approximates — it does
/// not re-run local-workload resolution — which is harmless: the router only
/// groups ids that exist as materialized proxies, the uniqueness exemption
/// only matters for ids that exist, and operators cannot author
/// `__mesh-inbound-*` ids (resource-id validation rejects a leading `_`).
/// Empty outside mesh mode.
pub(crate) fn mesh_inbound_service_groups(
    mesh: &crate::modes::mesh::config::MeshConfig,
) -> Vec<MeshOutboundServiceGroup> {
    let services = mesh
        .local_inbound_services
        .as_deref()
        .unwrap_or(&mesh.services);
    services
        .iter()
        .filter_map(|service| {
            let http_ports = service_http_family_ports(service);
            if http_ports.is_empty() {
                return None;
            }
            Some(MeshOutboundServiceGroup {
                declared_http_ports: http_ports.len(),
                siblings: http_ports
                    .iter()
                    .map(|sp| {
                        (
                            sp.port,
                            mesh_inbound_proxy_id(&service.namespace, &service.name, sp.port),
                        )
                    })
                    .collect(),
            })
        })
        .collect()
}

/// Expected per-port sibling routes for the local workload's Sidecar
/// `ingress[]` custom listeners (F6 §6.2). Mirrors [`mesh_inbound_service_groups`]
/// for ingress: forward-derived from the resolved listeners
/// (`mesh.local_ingress_listeners`, back-projected by mesh preparation), never
/// by parsing ids. All of a workload's ingress listeners form ONE group
/// (they share the local service's host identity + `/` and disambiguate by the
/// declared LISTENER port), so `declared_http_ports` is the listener count and
/// `siblings` carries `(listener_port, ingress_proxy_id)` for every listener.
/// The router groups them into `mesh_inbound_ports` and the listen-path
/// uniqueness exemption treats them as one (service, ingress-direction) owner.
/// Empty when no ingress was modeled.
pub(crate) fn mesh_ingress_listener_groups(
    mesh: &crate::modes::mesh::config::MeshConfig,
) -> Vec<MeshOutboundServiceGroup> {
    if mesh.local_ingress_listeners.is_empty() {
        return Vec::new();
    }
    let siblings: Vec<(u16, String)> = mesh
        .local_ingress_listeners
        .iter()
        .map(|listener| {
            (
                listener.port,
                mesh_ingress_proxy_id(
                    &listener.owner_namespace,
                    &listener.owner_service,
                    listener.port,
                ),
            )
        })
        .collect();
    // `declared_http_ports` is the count of DISTINCT HTTP-family listener ports
    // the operator DECLARED (`MeshConfig.declared_ingress_http_ports`), NOT the
    // materialized sibling count — so an HTTP-family entry whose `defaultEndpoint`
    // was unroutable (or a listener dropped at carrier re-validation) still keeps
    // the group ambiguous: an orig-dst-less request fails closed in the router
    // (`PortSignalUnavailable`) instead of the surviving sibling absorbing the
    // skipped port's traffic. Floored at the materialized sibling count so a
    // hostile/stale carrier count below what materialized can never collapse a
    // multi-listener group back to the single-listener no-signal pass-through.
    let declared_http_ports = mesh.declared_ingress_http_ports.max(siblings.len());
    vec![MeshOutboundServiceGroup {
        declared_http_ports,
        siblings,
    }]
}

/// Upstream id for a materialized mesh outbound route, one per HTTP-family
/// service port (per-port upstreams keep LB counters, hash rings, passive
/// health, and pool keys isolated per app port). Deliberately
/// does NOT start with [`MESH_OUTBOUND_PROXY_ID_PREFIX`] (`__mesh-outbound-`) so
/// it is never misclassified as a direction-scoped *route* by
/// [`mesh_route_direction`] / [`is_mesh_outbound_route_id`] — those predicates
/// run on proxy ids, and a shared prefix would be a latent footgun if one were
/// ever handed an upstream id. Parallels the east-west `__mesh-ew-upstream-` id.
pub(crate) fn mesh_outbound_upstream_id(namespace: &str, name: &str, port: u16) -> String {
    format!("__mesh-out-upstream-{namespace}-{name}-{port}").replace(['/', '.'], "-")
}

/// Upstream id for a materialized raw-TCP egress port, one per stream-family
/// service port. A DISTINCT id space from [`mesh_outbound_upstream_id`] so a
/// service exposing the same port number as both (via `protocol_overrides`
/// skew across slices) can never conflate LB counters / passive health / DR
/// fan-out between its HTTP and TCP lanes. Same non-route prefix rationale.
pub(crate) fn mesh_outbound_tcp_upstream_id(namespace: &str, name: &str, port: u16) -> String {
    format!("__mesh-out-tcp-upstream-{namespace}-{name}-{port}").replace(['/', '.'], "-")
}

/// Upstream id for a materialized UDP egress port, one per UDP service port
/// (F3 §3.3 Stage 4). A DISTINCT id space from both
/// [`mesh_outbound_upstream_id`] (HTTP per-port) and
/// [`mesh_outbound_tcp_upstream_id`] (raw-TCP per-port) so a service exposing
/// the same port number across the three lanes (via `protocol_overrides` skew)
/// can never conflate LB counters / passive health / DR fan-out. Same non-route
/// prefix rationale (never enters the route table or `config.proxies`).
pub(crate) const MESH_OUTBOUND_UDP_UPSTREAM_ID_PREFIX: &str = "__mesh-out-udp-upstream-";

pub(crate) fn mesh_outbound_udp_upstream_id(namespace: &str, name: &str, port: u16) -> String {
    format!("{MESH_OUTBOUND_UDP_UPSTREAM_ID_PREFIX}{namespace}-{name}-{port}")
        .replace(['/', '.'], "-")
}

/// Upstream id for a raw-TCP egress upstream addressed by a DIRECT pod IP
/// (headless / direct-dial path; F3 §3.4), one per
/// (stream-family service port × backing workload IP). A captured raw-TCP dial
/// whose `SO_ORIGINAL_DST` IP+port matches a declared workload address+port —
/// NOT a service VIP — routes here to a SINGLE-TARGET upstream pinned to that
/// workload's identity. Distinct id space from both
/// [`mesh_outbound_upstream_id`] (HTTP per-port) and
/// [`mesh_outbound_tcp_upstream_id`] (VIP per-port) so LB counters / passive
/// health / DR fan-out never conflate the three lanes. The canonical IP is
/// folded into the id (replacing `.`/`:` like the rest) so each backing
/// workload IP of a service port gets its own deterministic, single-target
/// upstream; same non-route prefix rationale so it is never misclassified as a
/// direction-scoped route id. The id is always derived FORWARD from
/// config — never parsed back.
pub(crate) fn mesh_outbound_tcp_bywl_upstream_id(
    namespace: &str,
    name: &str,
    port: u16,
    canonical_ip: std::net::IpAddr,
) -> String {
    format!("__mesh-out-tcp-bywl-upstream-{namespace}-{name}-{port}-{canonical_ip}")
        .replace(['/', '.', ':'], "-")
}

/// Upstream id for an HTTP-family egress upstream addressed by a DIRECT pod IP,
/// one per (HTTP-family service port × backing workload IP). A captured
/// HTTP/1.1+ request whose `SO_ORIGINAL_DST` matches a backing workload
/// address+targetPort routes through this single-target upstream instead of the
/// service-host route. Kept out of the route-id prefix space (like the VIP
/// outbound upstream ids); the paired proxy below carries the direction-scoped
/// route prefix.
pub(crate) fn mesh_outbound_http_bywl_upstream_id(
    namespace: &str,
    name: &str,
    port: u16,
    canonical_ip: std::net::IpAddr,
) -> String {
    format!("__mesh-out-http-bywl-upstream-{namespace}-{name}-{port}-{canonical_ip}")
        .replace(['/', '.', ':'], "-")
}

/// Reserved proxy-id prefix for hidden direct-pod-IP HTTP egress routes.
///
/// This deliberately starts with `__mesh-outbound-`, so if a hidden proxy ever
/// escaped into normal host routing it would still be direction-scoped to the
/// outbound capture listener. The route table skips these ids from host/path
/// tiers and indexes them only by captured original destination.
pub(crate) const MESH_OUTBOUND_HTTP_BYWL_PROXY_ID_PREFIX: &str = "__mesh-outbound-http-bywl-";

pub(crate) fn is_mesh_outbound_http_bywl_route_id(id: &str) -> bool {
    id.starts_with(MESH_OUTBOUND_HTTP_BYWL_PROXY_ID_PREFIX)
}

pub(crate) fn mesh_outbound_http_bywl_proxy_id(
    namespace: &str,
    name: &str,
    port: u16,
    canonical_ip: std::net::IpAddr,
) -> String {
    format!("{MESH_OUTBOUND_HTTP_BYWL_PROXY_ID_PREFIX}{namespace}-{name}-{port}-{canonical_ip}")
        .replace(['/', '.', ':'], "-")
}

fn mesh_outbound_http_bywl_hidden_host(
    namespace: &str,
    name: &str,
    port: u16,
    canonical_ip: std::net::IpAddr,
) -> String {
    let token = format!("{namespace}-{name}-{port}-{canonical_ip}").replace(['/', '.', ':'], "-");
    format!("bywl-{token}.mesh.internal")
}

/// One direct-pod-IP raw-TCP egress upstream candidate (F3 §3.4): a single
/// backing workload IP of a service's stream-family port, resolved to its
/// container/target port and pinned to the workload's SPIFFE identity. The
/// SINGLE forward-derivation source shared by every consumer — materialization
/// (`materialize_mesh_outbound_tcp_upstreams`), the route-table
/// `mesh_tcp_egress_by_workload` index (`router_cache::build_route_table`), the
/// HBONE capability enrollment (`collect_mesh_tcp_egress_capability_targets`),
/// and DestinationRule per-port fan-out (`apply_destination_rules`) — so the
/// deterministic upstream id, the `(IP, port)` index key, the capability key,
/// and the DR owner-port map can never drift. Borrows from the prepared
/// `MeshConfig` (the slice's `workloads`/`services`).
pub(crate) struct MeshTcpBywlUpstreamSpec<'a> {
    /// Deterministic per-(service-port, workload-IP) upstream id.
    pub(crate) upstream_id: String,
    /// The backing workload address canonicalized to an `IpAddr` (mapped-IPv6
    /// folded the SAME way the VIP path keys `mesh_tcp_egress`) — the IP half of
    /// the strict `(IP, target_port)` index key.
    pub(crate) canonical_ip: std::net::IpAddr,
    /// Resolved container/target port the dial uses — the port half of the
    /// index key and the `UpstreamTarget.port`.
    pub(crate) target_port: u16,
    /// The service this workload backs (for tag building + the relay proxy /
    /// FQDN identity, all forward-derived).
    pub(crate) service: &'a crate::modes::mesh::config::MeshService,
    /// The owning Service stream-family port (for the relay proxy id, the DR
    /// owner-port map, and protocol classification).
    pub(crate) service_port: &'a crate::modes::mesh::config::ServicePort,
    /// The backing workload (carries the pinned `spiffe_id` + tags + locality).
    pub(crate) workload: &'a crate::modes::mesh::config::Workload,
    /// The service's effective protocol on this port (override-aware) — passed
    /// to the transport tag builders so the materialized target's `mesh.protocol`
    /// matches the VIP path.
    pub(crate) protocol: crate::modes::mesh::config::AppProtocol,
}

impl MeshTcpBywlUpstreamSpec<'_> {
    /// FQDN the relay upstream is named after (DR-matchable), built forward from
    /// the service + cluster domain exactly like the VIP per-port path.
    pub(crate) fn service_fqdn(&self, cluster_domain: &str) -> String {
        format!(
            "{}.{}.svc.{}",
            self.service.name,
            self.service.namespace,
            cluster_domain.trim_matches('.')
        )
    }
}

/// One direct-pod-IP HTTP-family egress candidate: a single backing workload IP
/// of a service's HTTP-family port, resolved to its container/target port and
/// pinned to the workload identity. This is the HTTP counterpart of
/// [`MeshTcpBywlUpstreamSpec`], but it also forward-derives a hidden proxy id
/// because HTTP dispatch still uses a `Proxy` + `Upstream` pair once the route
/// table has selected the captured `(IP, target_port)` entry.
pub(crate) struct MeshHttpBywlUpstreamSpec<'a> {
    pub(crate) upstream_id: String,
    pub(crate) proxy_id: String,
    pub(crate) canonical_ip: std::net::IpAddr,
    pub(crate) target_port: u16,
    pub(crate) service: &'a crate::modes::mesh::config::MeshService,
    pub(crate) service_port: &'a crate::modes::mesh::config::ServicePort,
    pub(crate) workload: &'a crate::modes::mesh::config::Workload,
    pub(crate) protocol: crate::modes::mesh::config::AppProtocol,
}

impl MeshHttpBywlUpstreamSpec<'_> {
    pub(crate) fn service_fqdn(&self, cluster_domain: &str) -> String {
        format!(
            "{}.{}.svc.{}",
            self.service.name,
            self.service.namespace,
            cluster_domain.trim_matches('.')
        )
    }
}

/// Forward-derive direct-pod-IP HTTP-family egress candidates. The index key is
/// exactly `(workload IP, resolved targetPort)`: the request Host header is not
/// trusted to select a service for direct Pod-IP traffic because the client may
/// send an arbitrary Host while dialing a pod IP. The route table treats
/// duplicate keys across services as unroutable, preserving identity correctness
/// over convenience.
pub(crate) fn mesh_outbound_http_bywl_upstreams<'a>(
    services: &'a [crate::modes::mesh::config::MeshService],
    workloads: &'a [crate::modes::mesh::config::Workload],
    multi_cluster: Option<&crate::modes::mesh::config::MultiClusterConfig>,
) -> Vec<MeshHttpBywlUpstreamSpec<'a>> {
    let mut specs = Vec::new();
    for service in services {
        let http_ports = service_http_family_ports(service);
        if http_ports.is_empty() {
            continue;
        }
        for service_port in http_ports {
            let protocol = service
                .protocol_overrides
                .get(&service_port.port)
                .copied()
                .unwrap_or(service_port.protocol);
            let mut seen: std::collections::HashSet<(std::net::IpAddr, u16)> =
                std::collections::HashSet::new();
            for workload in matched_local_service_workloads(service, workloads, multi_cluster) {
                let app_port = match service_port.target_port.as_ref() {
                    Some(_) => match crate::modes::mesh::config::resolve_target_port(
                        service_port.target_port.as_ref(),
                        &workload.ports,
                    ) {
                        Some(p) if p != 0 => p,
                        _ => continue,
                    },
                    None => service_port.port,
                };
                if app_port == 0 {
                    continue;
                }
                for address in &workload.addresses {
                    if address.is_empty() {
                        continue;
                    }
                    let Ok(parsed) = address.parse::<std::net::IpAddr>() else {
                        continue;
                    };
                    let canonical_ip = parsed.to_canonical();
                    if !seen.insert((canonical_ip, app_port)) {
                        continue;
                    }
                    specs.push(MeshHttpBywlUpstreamSpec {
                        upstream_id: mesh_outbound_http_bywl_upstream_id(
                            &service.namespace,
                            &service.name,
                            service_port.port,
                            canonical_ip,
                        ),
                        proxy_id: mesh_outbound_http_bywl_proxy_id(
                            &service.namespace,
                            &service.name,
                            service_port.port,
                            canonical_ip,
                        ),
                        canonical_ip,
                        target_port: app_port,
                        service,
                        service_port,
                        workload,
                        protocol,
                    });
                }
            }
        }
    }
    specs
}

/// Forward-derive the direct-pod-IP raw-TCP egress upstream candidates (F3
/// §3.4): for every in-mesh service's stream-family port, every backing
/// local-cluster workload, every workload address that parses as an IP. DNS-name
/// workload addresses are skipped (the index is keyed by `IpAddr` and a raw
/// `SO_ORIGINAL_DST` is always an IP). The container/target port is resolved
/// with the SAME fail-closed rule the VIP path uses
/// (`build_outbound_mesh_targets`): a DECLARED `targetPort` must resolve (numeric
/// non-zero, or named matching a workload port) or the candidate is dropped — an
/// unresolved named targetPort never falls back to the service port; only an
/// ABSENT targetPort falls back. Duplicate `(canonical_ip, target_port)` pairs
/// (e.g. two replicas whose distinct address strings canonicalize to one IP, or
/// a `targetPort` that collapses two ports) collapse to the FIRST candidate —
/// the strict index can route a given `(IP, port)` to exactly one workload, and
/// the first-wins choice is deterministic given a stable slice order. Empty when
/// `workloads` is empty or no service declares a routable stream port.
///
/// Takes the three slices directly (rather than a `MeshConfig`/`MeshSlice`) so
/// both the materializer (`MeshSlice`) and the route-table / capability /
/// DR consumers (`MeshConfig` via `config.mesh`) share ONE derivation — the
/// upstream id, the `(IP, port)` index key, the capability key, and the DR
/// owner-port map can never drift.
pub(crate) fn mesh_outbound_tcp_bywl_upstreams<'a>(
    services: &'a [crate::modes::mesh::config::MeshService],
    workloads: &'a [crate::modes::mesh::config::Workload],
    multi_cluster: Option<&crate::modes::mesh::config::MultiClusterConfig>,
) -> Vec<MeshTcpBywlUpstreamSpec<'a>> {
    let mut specs = Vec::new();
    for service in services {
        let tcp_ports = service_tcp_stream_ports(service);
        if tcp_ports.is_empty() {
            continue;
        }
        for service_port in tcp_ports {
            let protocol = service
                .protocol_overrides
                .get(&service_port.port)
                .copied()
                .unwrap_or(service_port.protocol);
            // De-dupe within ONE service port so a workload listed twice (or two
            // replicas collapsing to one canonical IP) yields one routable
            // upstream per `(IP, port)`.
            let mut seen: std::collections::HashSet<(std::net::IpAddr, u16)> =
                std::collections::HashSet::new();
            for workload in matched_local_service_workloads(service, workloads, multi_cluster) {
                // Same app-port resolution as `build_outbound_mesh_targets`:
                // a DECLARED targetPort is authoritative (resolve or SKIP);
                // only an ABSENT one falls back to the service port.
                let app_port = match service_port.target_port.as_ref() {
                    Some(_) => match crate::modes::mesh::config::resolve_target_port(
                        service_port.target_port.as_ref(),
                        &workload.ports,
                    ) {
                        Some(p) if p != 0 => p,
                        _ => continue,
                    },
                    None => service_port.port,
                };
                if app_port == 0 {
                    continue;
                }
                for address in &workload.addresses {
                    if address.is_empty() {
                        continue;
                    }
                    // The index is keyed by IpAddr — a raw captured original
                    // destination is always an IP. Skip DNS-name workload
                    // addresses (they can never match an orig-dst IP, and
                    // HTTP-family headless already routes by Host).
                    let Ok(parsed) = address.parse::<std::net::IpAddr>() else {
                        continue;
                    };
                    let canonical_ip = parsed.to_canonical();
                    if !seen.insert((canonical_ip, app_port)) {
                        continue;
                    }
                    specs.push(MeshTcpBywlUpstreamSpec {
                        upstream_id: mesh_outbound_tcp_bywl_upstream_id(
                            &service.namespace,
                            &service.name,
                            service_port.port,
                            canonical_ip,
                        ),
                        canonical_ip,
                        target_port: app_port,
                        service,
                        service_port,
                        workload,
                        protocol,
                    });
                }
            }
        }
    }
    specs
}

/// Materialize inbound routes for the sidecar's **local** workload so that
/// mTLS-terminated traffic on the inbound listener (`:15006`) reaches the
/// co-located application on loopback. `docs/mesh.md` documents this ("the
/// inbound listener … forwards plaintext to the local application"), but nothing
/// implemented it: the slice's services/workloads were never turned into
/// routable inbound proxies, so an inbound request found no proxy and returned
/// 404. (The existing integration tests passed only because they hand-supplied a
/// `Proxy`.) This closes that gap for the sidecar inbound direction.
///
/// Driven by the **local workload(s)** — this sidecar's own pods, matched by the
/// SPIFFE identity in `runtime.workload_spiffe_id`. Each route is keyed by the
/// workload's own service FQDN (`service_name`/`namespace`) — never another
/// service that merely shares the SPIFFE id — and targets the workload's own
/// listening port (the app/target port, which may differ from the K8s service
/// port). One loopback proxy is emitted PER HTTP-family service port; the
/// route table groups a multi-port service's siblings under one lowest-port
/// representative and the request path swaps in the sibling matching the
/// inbound connection's captured original destination (REDIRECT-captured
/// plain inbound) or the pre-strip `Host`/`:authority` port (peer-sidecar
/// dials), failing closed when a multi-port request carries neither signal —
/// see `HostRouteTable::select_mesh_inbound_port_route`. Stream-family raw TCP
/// inbound is prepared as a runtime-only port map consumed by the accept loop
/// before Hyper parses the connection. The emitted HTTP proxies carry the
/// [`MESH_INBOUND_PROXY_ID_PREFIX`] so the request path keeps them off the
/// outbound listener.
fn resolve_sidecar_inbound_backend_port(
    service_port: &crate::modes::mesh::config::ServicePort,
    workload: &crate::modes::mesh::config::Workload,
) -> Option<u16> {
    match service_port.target_port.as_ref() {
        Some(ServiceTargetPort::Number(n)) => Some(*n),
        Some(ServiceTargetPort::Name(name)) => workload
            .ports
            .iter()
            .find(|wp| wp.name.as_deref() == Some(name.as_str()))
            .map(|wp| wp.port),
        None if workload.ports.is_empty() => Some(service_port.port),
        None => workload
            .ports
            .iter()
            .find(|wp| wp.name.is_some() && wp.name == service_port.name)
            .or_else(|| {
                workload
                    .ports
                    .iter()
                    .find(|wp| wp.port == service_port.port)
            })
            .or(match workload.ports.as_slice() {
                [only] => Some(only),
                _ => None,
            })
            .map(|wp| wp.port),
    }
}

fn materialize_sidecar_inbound_proxies(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) {
    if runtime.topology != MeshTopology::Sidecar {
        return;
    }
    let Some(local_spiffe) = runtime.workload_spiffe_id.as_deref() else {
        debug!("Sidecar inbound route materialization skipped: no workload SPIFFE identity");
        return;
    };

    let now = chrono::Utc::now();
    // The local workload(s) are this sidecar's own pods. A SPIFFE id alone is not
    // a unique key — multiple workloads can share a service account / SPIFFE id —
    // so when the sidecar's own labels are known (the slice carries them), also
    // require the workload's selector labels to **non-vacuously** match this pod
    // (an empty selector matches "any" and would reintroduce the shared-SPIFFE
    // leak). Without labels at all, fall back to SPIFFE-only.
    let sidecar_labels = &mesh_slice.labels;
    // Name of this sidecar's own cluster, when the slice declares one. Used to
    // tell a remote endpoint apart from a legitimately cluster-tagged local
    // workload (see the cluster check below).
    let local_cluster = mesh_slice
        .multi_cluster
        .as_ref()
        .and_then(|mc| mc.local_cluster.as_deref());
    // `local_inbound_workloads` is `Some` exactly when the slice builder resolved
    // the local-inbound view under Sidecar narrowing — it is then AUTHORITATIVE
    // for BOTH the workload and service sources: an empty `Some` means the local
    // identity was ambiguous, so materialize nothing and do NOT fall back to the
    // narrowed `workloads`/`services` (that could collapse the ambiguity to one
    // wrong service). `None` means no narrowing applied, so fall back to the full
    // sets. Reading the separate views keeps the egress/outbound-registry
    // `services`/`workloads` untouched. `resolve_local_workloads` re-applies the
    // precise match + shared-SPIFFE ambiguity guard so CP and DP cannot drift.
    let (inbound_services, local_workload_src) = match mesh_slice.local_inbound_workloads.as_deref()
    {
        Some(local) => (mesh_slice.local_inbound_services.as_slice(), local),
        None => (
            mesh_slice.services.as_slice(),
            mesh_slice.workloads.as_slice(),
        ),
    };

    // F6 §6.2: when the local workload's applicable Sidecar declares
    // `ingress[]` listeners, Istio configures the workload's inbound listeners
    // explicitly and they REPLACE the default per-service-port inbound
    // materialization. Mirror that, FAIL CLOSED on the "declared" signal — NOT
    // on whether any listener resolved:
    //   * `sidecar_ingress_declared` is the authoritative marker that the
    //     operator declared a non-empty `ingress[]` (the slice builder sets it
    //     independent of how many entries resolved; it rides its own ECDS
    //     carrier so it survives an empty resolved list on the xDS path).
    //   * `local_ingress_listeners` is the subset that resolved into routable
    //     loopback HTTP routes.
    // When ingress is DECLARED we materialize the resolved listeners (possibly
    // none) and RETURN, skipping the service-port defaults. An all-unsupported
    // `ingress[]` (declared, but empty resolved list) therefore yields NO
    // inbound routes rather than silently exposing the default `:15006`
    // loopback routes the operator explicitly replaced — exposing those would
    // be a fail-open regression. (`local_ingress_listeners` non-empty implies
    // declared, so the OR also covers a pre-marker slice that somehow carries
    // listeners without the flag.)
    if mesh_slice.sidecar_ingress_declared || !mesh_slice.local_ingress_listeners.is_empty() {
        if let Some(mesh) = config.mesh.as_deref_mut() {
            mesh.local_inbound_tcp_routes.clear();
        }
        if mesh_slice.local_ingress_listeners.is_empty() {
            warn!(
                local_spiffe,
                "Sidecar ingress[] declared but no listener resolved into a routable inbound \
                 route (all entries unsupported, or no local service anchored them); failing \
                 closed — emitting NO default service-port inbound routes for this workload"
            );
        }
        materialize_sidecar_ingress_listener_proxies(
            config,
            runtime,
            mesh_slice,
            local_spiffe,
            now,
        );
        return;
    }

    let mut materialized = 0usize;
    let mut tcp_routes = Vec::new();
    // Container (app) ports claimed by a materialized HTTP-family inbound route.
    // The raw-TCP inbound accept-loop branch matches ONLY `orig_dst.port()` and
    // runs BEFORE Hyper routing + the mesh plugin chain, so a stream-family
    // route sharing a container port with an HTTP-family route would splice a
    // REDIRECTed HTTP request straight to loopback as raw TCP — bypassing the
    // HTTP inbound route, `mesh_authz`, and the access log. When both families
    // resolve to the same container port the HTTP route WINS: the raw-TCP entry
    // is dropped so the request is parsed + authorized on the materialized HTTP
    // route. Collected across ALL local services/workloads because the collision
    // can straddle two distinct Services backing one workload.
    let mut http_inbound_backend_ports: std::collections::HashSet<u16> =
        std::collections::HashSet::new();
    for workload in crate::modes::mesh::slice::resolve_local_workloads(
        local_workload_src,
        local_spiffe,
        sidecar_labels,
        local_cluster,
    ) {
        // Route inbound traffic for the service(s) this workload backs — its own
        // service (matched by name + namespace), never a service that merely
        // shares its SPIFFE id. HTTP-family routability is read from the SERVICE
        // port: Kubernetes container ports carry only the transport protocol
        // (e.g. TCP), while the application protocol (HTTP/gRPC) is declared on
        // the Service. The backend targets the workload's own app port.
        for service in inbound_services.iter().filter(|s| {
            s.name == workload.service_name
                && s.namespace == workload.namespace
                // Require the Service to actually back the local workload. Other
                // mesh resolution paths treat `MeshService.workloads[]` as the
                // authoritative backing set, so a service whose refs omit this
                // SPIFFE id (config typo, EndpointSlice lag) must not be routed
                // to the local app merely because the names line up.
                && s.workloads.iter().any(|w| w.spiffe_id.as_str() == local_spiffe)
        }) {
            let http_ports: Vec<_> = service
                .ports
                .iter()
                .filter(|sp| {
                    is_http_family_mesh_protocol(
                        service
                            .protocol_overrides
                            .get(&sp.port)
                            .copied()
                            .unwrap_or(sp.protocol),
                    )
                })
                .collect();
            // Multi-port services materialize one loopback route PER
            // HTTP-family service port. Host-only routing alone can't tell the
            // ports apart (the router strips the request port from
            // `Host`/`:authority`), so the route table groups a service's
            // per-port siblings under one lowest-port representative and the
            // request path swaps in the sibling matching, in priority order,
            // (1) the connection's captured original destination — present
            // when a sidecar-less client's dial to the app port was
            // iptables-REDIRECTed to `:15006`, its port is the CONTAINER
            // (target) port — or (2) the pre-strip `Host`/`:authority` port —
            // the SERVICE port, which a peer sidecar's multi-port egress
            // rewrites into the authority (its `:15006` dials are direct,
            // never NATed, so orig-dst is None for them). Multi-port requests
            // carrying neither signal fail closed (502) — see
            // `HostRouteTable::select_mesh_inbound_port_route`. Single-port
            // services keep their signal-free behavior. The expected sibling
            // id set also scopes the operator-overlap scan below: a sibling
            // must not yield to its OWN service's other siblings (they
            // intentionally share hosts + `/`), but must keep yielding to
            // everything else — including ANOTHER local service's inbound
            // route on an overlapping bare-name host variant.
            let sibling_ids: std::collections::HashSet<String> = http_ports
                .iter()
                .map(|sp| mesh_inbound_proxy_id(&service.namespace, &service.name, sp.port))
                .collect();
            for service_port in &http_ports {
                // Backend = the workload's app (container) port this service port
                // forwards to. A declared `targetPort` is Kubernetes' AUTHORITATIVE
                // service-port→container-port binding, so honor it exclusively — no
                // heuristic fallback: a numeric targetPort IS the container port; a
                // named one resolves against the workload's container-port names, and
                // an unresolved name (typo / rollout skew) SKIPS rather than guessing
                // a different port. Only when NO targetPort is declared do we fall
                // back to the heuristic over the signals we have, in declining order
                // of confidence:
                //   1. a shared port NAME — the canonical Service↔container linkage,
                //   2. an equal port NUMBER — `targetPort` defaulting to the port,
                //   3. the workload's sole container port — single-port pod.
                // A workload that declares no ports defaults to the service port
                // (Kubernetes' `targetPort`-defaults-to-`port` rule). Otherwise the
                // target is genuinely ambiguous: skip and warn rather than misroute.
                let backend_port = resolve_sidecar_inbound_backend_port(service_port, workload);
                // Reject a 0 backend (invalid targetPort/port; config validation also
                // rejects it for non-xDS slices) defensively rather than route to :0.
                let Some(backend_port) = backend_port.filter(|&p| p != 0) else {
                    warn!(
                        service = %service.name,
                        namespace = %service.namespace,
                        service_port = service_port.port,
                        target_port = ?service_port.target_port,
                        "Cannot resolve a usable local backend port for an inbound mesh route \
                         (no resolvable Service targetPort, and no port name/number match among \
                         multiple container ports). Set targetPort, name the ports consistently, \
                         or define an explicit proxy. Skipping this route."
                    );
                    continue;
                };
                // Claim this container port for the HTTP family so the raw-TCP
                // inbound branch never preempts it (recorded even when the
                // operator-overlap scan below skips materializing our route —
                // an operator proxy still serves HTTP on this port, not raw
                // TCP).
                http_inbound_backend_ports.insert(backend_port);
                let proxy = mesh_inbound_loopback_proxy(
                    &mesh_inbound_proxy_id(&service.namespace, &service.name, service_port.port),
                    mesh_service_host_variants(
                        &service.name,
                        &service.namespace,
                        &runtime.cluster_domain,
                    ),
                    &service.namespace,
                    backend_port,
                    now,
                );
                // Don't collide with or shadow an explicit operator proxy (e.g. the
                // documented file-mode pre-materialization workaround) already
                // routing this host. Our route is the greediest HTTP match for the
                // host — a `/` prefix — and the router searches exact → prefix →
                // regex → host-only, so it shadows any same-host regex (`~...`) or
                // host-only (`listen_path: None`) route and collides with an equal
                // `/` prefix. (Exact and longer-prefix operator routes still win for
                // their own paths, so they coexist.) Only HTTP-family proxies share
                // this routing space: stream proxies route by `listen_port` and carry
                // empty hosts + null `listen_path` that would otherwise read as a
                // host-only catch-all here, so skip them exactly as
                // `validate_unique_listen_paths` does. Either way the operator wins.
                // This service's OWN per-port siblings are excluded (they
                // intentionally share hosts + `/` and are grouped by the router) —
                // but ONLY its own: another local service's inbound route on an
                // overlapping bare-name host variant still wins first-materialized,
                // exactly as before per-port siblings existed.
                if config.proxies.iter().any(|p| {
                    if sibling_ids.contains(p.id.as_str()) || p.dispatch_kind.is_stream() {
                        return false;
                    }
                    let shadows_or_collides = p.listen_path == proxy.listen_path
                        || p.listen_path.is_none()
                        || p.listen_path
                            .as_deref()
                            .is_some_and(|lp| lp.starts_with('~'));
                    shadows_or_collides
                        && crate::config::types::hosts_overlap(&p.hosts, &proxy.hosts)
                }) {
                    debug!(
                        proxy_id = %proxy.id,
                        "Skipping inbound route materialization; an existing proxy already routes this host/path"
                    );
                    continue;
                }
                if let Some(existing) = config.proxies.iter_mut().find(|p| p.id == proxy.id) {
                    *existing = proxy;
                } else {
                    config.proxies.push(proxy);
                }
                materialized += 1;
            }

            for service_port in service_tcp_stream_ports(service) {
                let backend_port = resolve_sidecar_inbound_backend_port(service_port, workload);
                let Some(backend_port) = backend_port.filter(|&p| p != 0) else {
                    warn!(
                        service = %service.name,
                        namespace = %service.namespace,
                        service_port = service_port.port,
                        target_port = ?service_port.target_port,
                        "Cannot resolve a usable local backend port for an inbound raw-TCP mesh \
                         route (no resolvable Service targetPort, and no port name/number match \
                         among multiple container ports). Set targetPort or name ports \
                         consistently. Skipping this route."
                    );
                    continue;
                };
                // Effective protocol with `protocol_overrides` applied (same
                // resolution `service_tcp_stream_ports` filtered on). Only an
                // opaque-TLS port carries a real ClientHello, so only it is
                // safely pre-dial peeked by the inbound relay. Ambiguous raw
                // TCP and known server-first ports (Redis/MySQL/Postgres/Mongo)
                // must not peek or the relay stalls on the handshake clock
                // waiting for bytes the client never sends before the backend
                // greeting.
                let effective_protocol = service
                    .protocol_overrides
                    .get(&service_port.port)
                    .copied()
                    .unwrap_or(service_port.protocol);
                tcp_routes.push(MeshInboundTcpRoute {
                    match_port: backend_port,
                    backend_addr: std::net::SocketAddr::new(
                        std::net::IpAddr::V4(std::net::Ipv4Addr::LOCALHOST),
                        backend_port,
                    ),
                    namespace: service.namespace.clone(),
                    service_name: service.name.clone(),
                    service_fqdn: format!(
                        "{}.{}.svc.{}",
                        service.name,
                        service.namespace,
                        runtime.cluster_domain.trim_matches('.')
                    ),
                    tls_inspect: matches!(effective_protocol, AppProtocol::Tls),
                    first_bytes_inspect: matches!(effective_protocol, AppProtocol::Tls),
                });
            }
        }
    }

    // HTTP-family inbound routes WIN a shared container port. Drop any raw-TCP
    // route whose app port also backs an HTTP-family inbound route so the
    // accept-loop branch never preempts HTTP parsing + `mesh_authz` + access
    // logging for that port. Filtered AFTER the full workload/service sweep so
    // the decision is independent of the order distinct Services are visited.
    if !http_inbound_backend_ports.is_empty() {
        tcp_routes.retain(|route| {
            if http_inbound_backend_ports.contains(&route.match_port) {
                warn!(
                    service = %route.service_name,
                    namespace = %route.namespace,
                    app_port = route.match_port,
                    "A stream-family inbound port collides with an HTTP-family inbound route on \
                     the same container port; the HTTP route wins. Not installing a raw-TCP \
                     inbound entry for this port (it would bypass HTTP routing, mesh authz, and \
                     access logging)."
                );
                false
            } else {
                true
            }
        });
    }

    let tcp_route_count = tcp_routes.len();
    if let Some(mesh) = config.mesh.as_deref_mut() {
        mesh.local_inbound_tcp_routes = tcp_routes;
    }

    if materialized > 0 {
        info!(
            inbound_proxies = materialized,
            local_spiffe, "Materialized sidecar inbound routes to the local application"
        );
    }
    if tcp_route_count > 0 {
        info!(
            inbound_tcp_routes = tcp_route_count,
            local_spiffe, "Prepared sidecar raw-TCP inbound routes to the local application"
        );
    }
}

/// Materialize the workload's Sidecar `ingress[]` custom inbound listeners as
/// loopback routes (F6 §6.2). Called only when the slice resolved at least one
/// listener; per Istio these REPLACE the default per-service-port inbound
/// routes, so the caller returns without running the service-port path.
///
/// Each listener becomes one route: hosts = the union of its owning local
/// service's FQDN variants (the owner identity the slice builder stamped from
/// the resolved local-inbound view — Istio only configures ingress "if and only
/// if the workload is associated with a service"); backend = the entry's
/// resolved loopback `defaultEndpoint`; listen path `/`. The listener port
/// disambiguates per-port siblings exactly like the default inbound path, but
/// the captured original destination matches the LISTENER port (the dialed
/// port) rather than the backend port — see
/// `HostRouteTable::select_mesh_inbound_port_route` and the router's ingress
/// grouping. Operator-proxy yield mirrors the default inbound path.
fn materialize_sidecar_ingress_listener_proxies(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
    local_spiffe: &str,
    now: chrono::DateTime<chrono::Utc>,
) {
    // Re-validate every carried listener before using it. A
    // `ResolvedIngressListener` can arrive already resolved over the xDS/native
    // slice carrier, where every field — `endpoint_host`/`endpoint_port` AND the
    // stamped `owner_namespace`/`owner_service` — is decoded straight from
    // untrusted wire JSON. Drop a listener that fails EITHER guard, fail-closed:
    //
    //   1. Backend endpoint: must pass the same loopback/instance-IP +
    //      nonzero-port allowlist `MeshSidecarIngress::resolve` enforces, so the
    //      carrier path can never dial somewhere resolution would have refused.
    //   2. Owner anchor: must carry a non-empty `owner_namespace`/`owner_service`
    //      (the slice builder stamps these from the resolved local service; it
    //      clears ALL listeners when no local service anchors them). An owner-less
    //      entry has NO host identity of its own. In a MIXED malformed carrier
    //      (one stamped listener + one owner-less one) the `hosts` set below would
    //      be non-empty from the stamped entry, so without this guard the
    //      owner-less listener would be materialized with another service's hosts
    //      and an `__mesh-ingress--PORT` id — routing the service host to a
    //      listener that failed the local-service anchor check. Drop it instead.
    //
    // Filtering at this single point keeps `hosts`, the sibling-id set, and the
    // materialization loop all operating on the same stamped-and-valid set (the
    // back-projection that feeds the router's `mesh_ingress_listener_groups`
    // applies the identical pair of guards, so router grouping and materialized
    // routes stay in lock-step).
    let listeners: Vec<&crate::modes::mesh::config::ResolvedIngressListener> = mesh_slice
        .local_ingress_listeners
        .iter()
        .filter(|listener| {
            if !listener.endpoint_is_valid() {
                warn!(
                    local_spiffe,
                    listener_port = listener.port,
                    endpoint_host = %listener.endpoint_host,
                    endpoint_port = listener.endpoint_port,
                    "Dropping carried Sidecar ingress[] listener with an invalid backend endpoint \
                     (not a loopback host:port); failing closed rather than dialing it"
                );
                return false;
            }
            if listener.owner_namespace.is_empty() || listener.owner_service.is_empty() {
                warn!(
                    local_spiffe,
                    listener_port = listener.port,
                    "Dropping carried Sidecar ingress[] listener with no stamped owner identity \
                     (no local service anchor); failing closed rather than routing it under \
                     another listener's service host"
                );
                return false;
            }
            true
        })
        .collect();

    // Host identity for the ingress routes: the union of each listener's owning
    // local service FQDN variants (the owner the slice builder stamped from the
    // resolved local-inbound view). Every surviving listener carries a non-empty
    // owner (owner-less entries were dropped fail-closed above), so this is the
    // union of all stamped owners. A peer-sidecar dial addressed to the service
    // host matches here; an orig-dst-captured plain inbound dial is disambiguated
    // by the listener port post-match.
    let mut hosts: Vec<String> = Vec::new();
    for listener in &listeners {
        for host in mesh_service_host_variants(
            &listener.owner_service,
            &listener.owner_namespace,
            &runtime.cluster_domain,
        ) {
            if !hosts.contains(&host) {
                hosts.push(host);
            }
        }
    }
    if hosts.is_empty() {
        // Every listener was dropped (no valid, owner-stamped entry survived the
        // filter above) so there is no local service to anchor a host identity.
        // Fail closed: a host-less `/` route would read as a catch-all and could
        // shadow unrelated traffic. Istio also only configures ingress when the
        // workload is associated with a service. (The slice builder normally
        // drops listeners in this case; this is a defensive backstop.)
        warn!(
            local_spiffe,
            "Sidecar ingress[] declared but no local service resolved to anchor the listener host \
             identity; skipping ingress materialization (no routes emitted)"
        );
        return;
    }

    // Expected sibling id set for this workload's ingress listeners — used to
    // exclude a listener's OWN siblings from the operator-overlap scan (they
    // intentionally share hosts + `/` and are grouped by the router), exactly
    // as the default inbound path scopes its `sibling_ids`. Ids are derived
    // forward from each listener's stamped owner identity, identical to the
    // router/validator (`mesh_ingress_listener_groups`).
    let sibling_ids: std::collections::HashSet<String> = listeners
        .iter()
        .map(|listener| {
            mesh_ingress_proxy_id(
                &listener.owner_namespace,
                &listener.owner_service,
                listener.port,
            )
        })
        .collect();

    let mut materialized = 0usize;
    for listener in listeners.iter().copied() {
        let proxy = mesh_inbound_loopback_proxy_to(
            &mesh_ingress_proxy_id(
                &listener.owner_namespace,
                &listener.owner_service,
                listener.port,
            ),
            hosts.clone(),
            &listener.owner_namespace,
            &listener.endpoint_host,
            listener.endpoint_port,
            now,
        );
        // Yield to an explicit operator proxy already routing this host/path,
        // exactly like the default inbound path. Exclude this workload's OWN
        // ingress siblings (grouped by the router); another proxy still wins
        // first-materialized.
        if config.proxies.iter().any(|p| {
            if sibling_ids.contains(p.id.as_str()) || p.dispatch_kind.is_stream() {
                return false;
            }
            let shadows_or_collides = p.listen_path == proxy.listen_path
                || p.listen_path.is_none()
                || p.listen_path
                    .as_deref()
                    .is_some_and(|lp| lp.starts_with('~'));
            shadows_or_collides && crate::config::types::hosts_overlap(&p.hosts, &proxy.hosts)
        }) {
            debug!(
                proxy_id = %proxy.id,
                "Skipping ingress listener materialization; an existing proxy already routes this host/path"
            );
            continue;
        }
        if let Some(existing) = config.proxies.iter_mut().find(|p| p.id == proxy.id) {
            *existing = proxy;
        } else {
            config.proxies.push(proxy);
        }
        materialized += 1;
    }

    if materialized > 0 {
        info!(
            ingress_listeners = materialized,
            local_spiffe,
            "Materialized Sidecar ingress[] custom inbound listeners to the local application"
        );
    }
}

/// A loopback-backend HTTP proxy: inbound mesh traffic matching `hosts` is
/// forwarded in plaintext to the co-located application at `127.0.0.1:<port>`.
fn mesh_inbound_loopback_proxy(
    id: &str,
    hosts: Vec<String>,
    namespace: &str,
    port: u16,
    now: chrono::DateTime<chrono::Utc>,
) -> Proxy {
    mesh_inbound_loopback_proxy_to(id, hosts, namespace, "127.0.0.1", port, now)
}

/// Like [`mesh_inbound_loopback_proxy`] but with an explicit loopback backend
/// host (`127.0.0.1` or `::1`). Used by Sidecar `ingress[]` materialization,
/// where the resolved `defaultEndpoint` selects the address family.
fn mesh_inbound_loopback_proxy_to(
    id: &str,
    hosts: Vec<String>,
    namespace: &str,
    backend_host: &str,
    port: u16,
    now: chrono::DateTime<chrono::Utc>,
) -> Proxy {
    Proxy {
        id: id.to_string(),
        name: Some(format!("mesh inbound {id}")),
        namespace: namespace.to_string(),
        hosts,
        listen_path: Some("/".to_string()),
        backend_scheme: Some(BackendScheme::Http),
        dispatch_kind: Default::default(),
        backend_host: backend_host.to_string(),
        backend_port: port,
        backend_path: None,
        strip_listen_path: false,
        // The local app expects its own service Host, not 127.0.0.1.
        preserve_host_header: true,
        backend_connect_timeout_ms: 5_000,
        backend_read_timeout_ms: 30_000,
        backend_write_timeout_ms: 30_000,
        backend_tls_client_cert_path: None,
        backend_tls_client_key_path: None,
        backend_tls_verify_server_cert: false,
        backend_tls_server_ca_cert_path: None,
        resolved_tls: BackendTlsConfig::default(),
        dispatch_port_overrides: None,
        dispatch_port_override_fallback: None,
        dns_override: None,
        dns_cache_ttl_seconds: None,
        auth_mode: Default::default(),
        plugins: Vec::<PluginAssociation>::new(),
        pool_idle_timeout_seconds: None,
        pool_enable_http_keep_alive: None,
        pool_enable_http2: None,
        pool_tcp_keepalive_seconds: None,
        pool_http2_keep_alive_interval_seconds: None,
        pool_http2_keep_alive_timeout_seconds: None,
        pool_http2_initial_stream_window_size: None,
        pool_http2_initial_connection_window_size: None,
        pool_http2_adaptive_window: None,
        pool_http2_max_frame_size: None,
        pool_http2_max_concurrent_streams: None,
        pool_http3_connections_per_backend: None,
        h2_upgrade_policy: None,
        pool_max_requests_per_connection: None,
        // Derived-only: projected from DestinationRule port overrides at
        // dispatch time via `resolve_effective_proxy_for_target`; a
        // freshly-materialized mesh proxy starts at `None`.
        pool_http1_max_pending_requests: None,
        upstream_id: None,
        upstream_subset: None,
        api_spec_id: None,
        circuit_breaker: None,
        retry: None,
        response_body_mode: ResponseBodyMode::Stream,
        listen_port: None,
        frontend_tls: false,
        passthrough: false,
        udp_idle_timeout_seconds: 60,
        udp_max_response_amplification_factor: None,
        stream_proxy_protocol: None,
        tcp_idle_timeout_seconds: Some(300),
        websocket_idle_timeout_seconds: None,
        allowed_methods: None,
        allowed_ws_origins: Vec::new(),
        created_at: now,
        updated_at: now,
    }
}

/// Reserved id prefix for synthesized local raw-TCP inbound relay proxies.
/// These proxies never enter `config.proxies`; they provide a stable proxy
/// identity and timeout config for the accept-loop relay from captured
/// plaintext inbound TCP to the co-located loopback app.
pub(crate) const MESH_INBOUND_TCP_RELAY_PROXY_ID_PREFIX: &str = "__mesh-in-tcp-relay-";

pub(crate) fn mesh_inbound_tcp_relay_proxy(route: &MeshInboundTcpRoute) -> Proxy {
    let id = format!(
        "{MESH_INBOUND_TCP_RELAY_PROXY_ID_PREFIX}{}-{}-{}",
        route.namespace, route.service_name, route.match_port
    )
    .replace(['/', '.'], "-");
    let now = chrono::Utc::now();
    Proxy {
        id: id.clone(),
        name: Some(format!("mesh raw-tcp inbound {id}")),
        namespace: route.namespace.clone(),
        hosts: Vec::new(),
        listen_path: None,
        backend_scheme: Some(BackendScheme::Tcp),
        dispatch_kind: Default::default(),
        backend_host: route.backend_addr.ip().to_string(),
        backend_port: route.backend_addr.port(),
        backend_path: None,
        strip_listen_path: false,
        preserve_host_header: false,
        backend_connect_timeout_ms: 5_000,
        backend_read_timeout_ms: 30_000,
        backend_write_timeout_ms: 30_000,
        backend_tls_client_cert_path: None,
        backend_tls_client_key_path: None,
        backend_tls_verify_server_cert: false,
        backend_tls_server_ca_cert_path: None,
        resolved_tls: BackendTlsConfig::default(),
        dispatch_port_overrides: None,
        dispatch_port_override_fallback: None,
        dns_override: None,
        dns_cache_ttl_seconds: None,
        auth_mode: Default::default(),
        plugins: Vec::<PluginAssociation>::new(),
        pool_idle_timeout_seconds: None,
        pool_enable_http_keep_alive: None,
        pool_enable_http2: None,
        pool_tcp_keepalive_seconds: None,
        pool_http2_keep_alive_interval_seconds: None,
        pool_http2_keep_alive_timeout_seconds: None,
        pool_http2_initial_stream_window_size: None,
        pool_http2_initial_connection_window_size: None,
        pool_http2_adaptive_window: None,
        pool_http2_max_frame_size: None,
        pool_http2_max_concurrent_streams: None,
        pool_http3_connections_per_backend: None,
        h2_upgrade_policy: None,
        pool_max_requests_per_connection: None,
        // Derived-only: projected from DestinationRule port overrides at
        // dispatch time via `resolve_effective_proxy_for_target`; a
        // freshly-materialized mesh proxy starts at `None`.
        pool_http1_max_pending_requests: None,
        upstream_id: None,
        upstream_subset: None,
        api_spec_id: None,
        circuit_breaker: None,
        retry: None,
        response_body_mode: ResponseBodyMode::Stream,
        listen_port: None,
        frontend_tls: false,
        passthrough: false,
        udp_idle_timeout_seconds: 60,
        udp_max_response_amplification_factor: None,
        stream_proxy_protocol: None,
        tcp_idle_timeout_seconds: Some(300),
        websocket_idle_timeout_seconds: None,
        allowed_methods: None,
        allowed_ws_origins: Vec::new(),
        created_at: now,
        updated_at: now,
    }
}

/// Reserved id for a synthesized transparent INBOUND HBONE relay proxy.
/// Ambient / Waypoint terminators materialize NO inbound routes (the relay is
/// transparent — it dials the CONNECT `:authority`, the original destination
/// the mesh peer asked for), so an authenticated HBONE CONNECT that matches no
/// route is relayed through a proxy built on the fly with this id. Carries the
/// `MESH_INBOUND_PROXY_ID_PREFIX` so `mesh_authz`'s `mesh_inbound_app_port`
/// reads the relay's `backend_port` (the destination app port) when evaluating
/// port-scoped policy, exactly as for a materialized sidecar inbound route.
pub(crate) const MESH_INBOUND_HBONE_RELAY_PROXY_ID: &str = "__mesh-inbound-hbone-relay";

/// Build the transparent inbound HBONE relay proxy that dials `host:port` — the
/// CONNECT `:authority` of an authenticated mesh peer. The caller
/// (`proxy::mod`) gates this on the destination being a safe local target
/// (loopback or a slice-known in-mesh workload address), so the terminator can
/// never be used as an open proxy to arbitrary hosts. No upstreams / circuit
/// breaker / retry: it is a transparent TCP tunnel, and the mesh global plugin
/// chain (incl. `mesh_authz`) still runs on the outer CONNECT before the relay.
pub(crate) fn mesh_inbound_hbone_relay_proxy(host: &str, port: u16) -> Proxy {
    let now = chrono::Utc::now();
    Proxy {
        id: MESH_INBOUND_HBONE_RELAY_PROXY_ID.to_string(),
        name: Some("mesh inbound hbone relay".to_string()),
        namespace: String::new(),
        hosts: Vec::new(),
        listen_path: Some("/".to_string()),
        backend_scheme: Some(BackendScheme::Http),
        dispatch_kind: Default::default(),
        backend_host: host.to_string(),
        backend_port: port,
        backend_path: None,
        strip_listen_path: false,
        preserve_host_header: true,
        backend_connect_timeout_ms: 5_000,
        backend_read_timeout_ms: 30_000,
        backend_write_timeout_ms: 30_000,
        backend_tls_client_cert_path: None,
        backend_tls_client_key_path: None,
        backend_tls_verify_server_cert: false,
        backend_tls_server_ca_cert_path: None,
        resolved_tls: BackendTlsConfig::default(),
        dispatch_port_overrides: None,
        dispatch_port_override_fallback: None,
        dns_override: None,
        dns_cache_ttl_seconds: None,
        auth_mode: Default::default(),
        plugins: Vec::<PluginAssociation>::new(),
        pool_idle_timeout_seconds: None,
        pool_enable_http_keep_alive: None,
        pool_enable_http2: None,
        pool_tcp_keepalive_seconds: None,
        pool_http2_keep_alive_interval_seconds: None,
        pool_http2_keep_alive_timeout_seconds: None,
        pool_http2_initial_stream_window_size: None,
        pool_http2_initial_connection_window_size: None,
        pool_http2_adaptive_window: None,
        pool_http2_max_frame_size: None,
        pool_http2_max_concurrent_streams: None,
        pool_http3_connections_per_backend: None,
        h2_upgrade_policy: None,
        pool_max_requests_per_connection: None,
        // Derived-only: projected from DestinationRule port overrides at
        // dispatch time via `resolve_effective_proxy_for_target`; a
        // freshly-materialized mesh proxy starts at `None`.
        pool_http1_max_pending_requests: None,
        upstream_id: None,
        upstream_subset: None,
        api_spec_id: None,
        circuit_breaker: None,
        retry: None,
        response_body_mode: ResponseBodyMode::Stream,
        listen_port: None,
        frontend_tls: false,
        passthrough: false,
        udp_idle_timeout_seconds: 60,
        udp_max_response_amplification_factor: None,
        stream_proxy_protocol: None,
        tcp_idle_timeout_seconds: Some(300),
        websocket_idle_timeout_seconds: None,
        allowed_methods: None,
        allowed_ws_origins: Vec::new(),
        created_at: now,
        updated_at: now,
    }
}

/// Which egress dispatch posture an outbound-materialized target uses.
/// Mesh transports are PER-TOPOLOGY (see `.claude/rules/mesh.md` "Datapath
/// Layering"): Ambient speaks HBONE on `:15008`; Sidecar speaks plain
/// SVID-mTLS HTTP on `:15006`. NodeWaypoint captured-Service HTTP dispatch has
/// no pod-local backing-pod mesh transport. In an identity-backed posture it
/// requires `Workload.node_waypoint` metadata and emits a secured HBONE target
/// to the destination NodeWaypoint; in explicit no-CA/dev posture it preserves
/// the temporary plaintext compatibility target while H2 production live gates
/// are still being built.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum MeshEgressTransport {
    /// HBONE: HTTP/2 CONNECT over mTLS to the destination's `:15008`
    /// (`mesh.hbone`-tagged targets → `HboneConnectionPool`).
    Hbone,
    /// NodeWaypoint captured HTTP Service traffic: run the normal route/plugin
    /// chain from the pod-netns capture listener, then dispatch according to
    /// the selected workload's NodeWaypoint metadata and the runtime identity
    /// posture. This is not used for direct Pod-IP routes or raw stream
    /// materialization.
    NodeWaypointCapturedService,
    /// Plain SVID-mTLS HTTP/2 to the destination sidecar's inbound `:15006`
    /// (`mesh.mtls`-tagged targets → `MeshMtlsConnectionPool`).
    SidecarMtls,
}

/// Materialize OUTBOUND (egress) routes for the in-mesh services this proxy may
/// reach, so captured outbound traffic on the outbound listener (`:15001`) is
/// routed to the destination workload over the topology's transport. Before this
/// native outbound had no materialized routes and 404'd.
///
/// **Topology-aware transport** (see `.claude/rules/mesh.md` "Datapath
/// Layering"): mesh transports differ by topology, so egress materialization
/// does too —
/// - **Ambient** egress uses **HBONE** (HTTP/2 CONNECT over mTLS to the
///   destination's `:15008`): `mesh.hbone`-tagged targets light up
///   `current_dispatch_hbone` → `HboneConnectionPool`.
/// - **NodeWaypoint** captured HTTP Service traffic materializes host-routed
///   service routes with no mesh transport tag: the in-pod-netns listener has
///   already attributed the source pod, `mesh_authz` runs on the normal plugin
///   chain, and dispatch dials the selected backing pod app port directly.
///   Direct Pod-IP/headless HTTP routes remain fail-closed because the current
///   eBPF path must not synthesize unreachable pod-IP HBONE targets.
/// - **Sidecar** egress uses plain **SVID-mTLS HTTP/2** to the peer sidecar's
///   inbound `:15006` (HBONE is NOT Sidecar's transport): `mesh.mtls`-tagged
///   targets light up `current_dispatch_mesh_mtls` → `MeshMtlsConnectionPool`.
///   Sidecar egress yields to the local workload's own materialized INBOUND
///   route (the route table holds one proxy per host+path), so a service's
///   own-sidecar traffic stays on the loopback route.
///
/// Driven by `MeshSlice.services` (the egress-narrowed view). For each in-mesh
/// service: host = the service FQDN variants (the router strips the request
/// port), upstream targets = the service's local-cluster workload addresses
/// tagged for the topology's dispatch posture (Ambient HBONE, Sidecar
/// mesh-mTLS, or NodeWaypoint captured-Service plaintext metadata), one
/// HTTP-family `/` proxy **per
/// HTTP-family service port** with a matching per-port upstream. The route
/// table groups a service's per-port siblings under one lowest-port
/// representative (they share hosts + `/`) and the request path swaps in the
/// sibling matching the connection's captured original-destination port
/// (`SO_ORIGINAL_DST`), failing closed when the dialed port cannot be
/// determined for a multi-port service — see
/// `HostRouteTable::select_mesh_outbound_port_route`. Proxies carry
/// [`MESH_OUTBOUND_PROXY_ID_PREFIX`] so the request path keeps them off the
/// inbound listener (direction scoping); they yield to explicit operator proxies
/// on overlapping hosts. `targetPort` is honored, mirroring the inbound
/// materializer.
fn materialize_mesh_outbound_proxies(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) {
    let transport = match runtime.topology {
        MeshTopology::Ambient => MeshEgressTransport::Hbone,
        MeshTopology::NodeWaypoint => MeshEgressTransport::NodeWaypointCapturedService,
        MeshTopology::Sidecar => MeshEgressTransport::SidecarMtls,
        // Gateway and ServiceWaypoint topologies have their own materializers
        // and no plaintext outbound capture listener.
        _ => return,
    };
    let now = chrono::Utc::now();
    // Exclude remote-cluster endpoints: direct outbound HBONE targets a
    // destination service's LOCAL-cluster pods (remote clusters are reached via
    // the east-west gateway, not a per-pod HBONE tunnel). Classification is by
    // discovery provenance (`workload_is_remote`): a local workload is `None`,
    // `Some(local_cluster)`, or a cluster the config does not list as remote;
    // a remote one carries a configured remote cluster's name.
    let multi_cluster = mesh_slice.multi_cluster.as_ref();
    let mut materialized = 0usize;
    for service in &mesh_slice.services {
        // HTTP-family routability is read from the SERVICE port protocol
        // (Kubernetes container ports carry only the transport protocol).
        // Multi-port services materialize one route + upstream PER HTTP-family
        // port: the route table holds one lowest-port representative per
        // service (host tiers are (host, path)-keyed) and the request path
        // swaps in the sibling matching the connection's captured
        // original-destination port (`SO_ORIGINAL_DST`), failing closed when
        // the dialed port cannot be determined. Per-port upstreams keep LB
        // counters, hash rings, passive health, and pool keys isolated per
        // app port. Shared predicate with the router grouping / uniqueness
        // exemption (`mesh_outbound_service_groups`) so they cannot drift.
        let http_ports = service_http_family_ports(service);
        // Sidecar multi-port egress is end-to-end complete: the destination
        // sidecar's inbound materializer now emits per-port loopback
        // siblings disambiguated by the request authority port, and
        // `build_outbound_mesh_targets` stamps the owning service port on
        // each multi-port target so dispatch rewrites the `:authority` to
        // carry it (Ambient needs neither — its inbound is the transparent
        // HBONE relay dialing the CONNECT authority's app port). An OLD
        // destination sidecar (pre-disambiguation) materialized nothing for
        // multi-port services, so new-egress traffic 404s there — fail
        // closed, never misrouted.
        let multi_port_service = http_ports.len() > 1;
        for service_port in &http_ports {
            let protocol = service
                .protocol_overrides
                .get(&service_port.port)
                .copied()
                .unwrap_or(service_port.protocol);
            let targets = build_outbound_mesh_targets(
                transport,
                runtime,
                service,
                service_port,
                protocol,
                &mesh_slice.workloads,
                multi_cluster,
                multi_port_service,
            );
            if targets.is_empty() {
                debug!(
                    service = %service.name,
                    namespace = %service.namespace,
                    service_port = service_port.port,
                    "Skipping outbound mesh service port with no reachable local-cluster workload targets"
                );
                continue;
            }
            let upstream_id =
                mesh_outbound_upstream_id(&service.namespace, &service.name, service_port.port);
            let proxy = mesh_outbound_route_proxy(
                &mesh_outbound_proxy_id(&service.namespace, &service.name, service_port.port),
                mesh_service_host_variants(
                    &service.name,
                    &service.namespace,
                    &runtime.cluster_domain,
                ),
                &service.namespace,
                &upstream_id,
                now,
            );
            // Yield to any existing proxy already routing this host at an
            // overlapping path. That covers explicit operator proxies (the
            // operator's routing wins) AND — for Sidecar — the local workload's own
            // materialized INBOUND loopback route (materialized before this pass):
            // the route table holds one proxy per host+path, so the local service's
            // host must keep its inbound route rather than be re-tunnelled out to
            // the mesh. Sibling OUTBOUND routes carry distinct service hosts (or are
            // this service's own per-port siblings, grouped by the router) and
            // are skipped only for re-materialization idempotency. Stream proxies
            // route by `listen_port` and are skipped.
            if config.proxies.iter().any(|p| {
                if p.id == proxy.id
                    || p.dispatch_kind.is_stream()
                    || is_mesh_outbound_route_id(&p.id)
                {
                    return false;
                }
                let shadows_or_collides = p.listen_path == proxy.listen_path
                    || p.listen_path.is_none()
                    || p.listen_path
                        .as_deref()
                        .is_some_and(|lp| lp.starts_with('~'));
                shadows_or_collides && crate::config::types::hosts_overlap(&p.hosts, &proxy.hosts)
            }) {
                debug!(
                    proxy_id = %proxy.id,
                    "Skipping outbound route materialization; an existing operator proxy already routes this host/path"
                );
                continue;
            }
            // Name the upstream with the service FQDN (not the internal id) so a
            // DestinationRule keyed on the service host matches it
            // (`destination_rule_matches_upstream` matches by target host / upstream
            // NAME / id, and the targets are pod IPs) — otherwise no DR traffic policy
            // would apply to outbound HBONE routes (top-level connectTimeout / LB /
            // outlier, plus per-port `portLevelSettings`, which `apply_destination_rules`
            // fans out from the owning Service port onto the targets' dial ports).
            let service_fqdn = format!(
                "{}.{}.svc.{}",
                service.name,
                service.namespace,
                runtime.cluster_domain.trim_matches('.')
            );
            let upstream = mesh_outbound_route_upstream(
                &upstream_id,
                &service.namespace,
                &service_fqdn,
                targets,
                now,
            );
            if let Some(existing) = config.upstreams.iter_mut().find(|u| u.id == upstream.id) {
                *existing = upstream;
            } else {
                config.upstreams.push(upstream);
            }
            if let Some(existing) = config.proxies.iter_mut().find(|p| p.id == proxy.id) {
                *existing = proxy;
            } else {
                config.proxies.push(proxy);
            }
            materialized += 1;
        }
    }

    let mut http_bywl_materialized = 0usize;
    if runtime.topology == MeshTopology::Ambient {
        for spec in mesh_outbound_http_bywl_upstreams(
            &mesh_slice.services,
            &mesh_slice.workloads,
            multi_cluster,
        ) {
            let mut tags = crate::service_discovery::mesh::mesh_hbone_target_tags(
                spec.service,
                spec.workload,
                spec.protocol,
                spec.service_port.name.as_deref(),
            );
            if runtime.egress_hbone_port != hbone::ISTIO_HBONE_PORT {
                tags.insert(
                    crate::proxy::hbone_pool::HBONE_PORT_TAG.to_string(),
                    runtime.egress_hbone_port.to_string(),
                );
            }
            let target = UpstreamTarget {
                host: spec.canonical_ip.to_string(),
                port: spec.target_port,
                service_port_policy_key: Some(spec.service_port.port),
                weight: 1,
                tags,
                locality: spec.workload.locality.clone(),
                path: None,
            };
            let service_fqdn = spec.service_fqdn(&runtime.cluster_domain);
            let upstream = mesh_outbound_route_upstream(
                &spec.upstream_id,
                &spec.service.namespace,
                &service_fqdn,
                vec![target],
                now,
            );
            let proxy = mesh_outbound_http_bywl_route_proxy(&spec, now);
            if let Some(existing) = config.upstreams.iter_mut().find(|u| u.id == upstream.id) {
                *existing = upstream;
            } else {
                config.upstreams.push(upstream);
            }
            if let Some(existing) = config.proxies.iter_mut().find(|p| p.id == proxy.id) {
                *existing = proxy;
            } else {
                config.proxies.push(proxy);
            }
            http_bywl_materialized += 1;
        }
    }

    if materialized > 0 || http_bywl_materialized > 0 {
        info!(
            outbound_proxies = materialized,
            outbound_http_bywl_proxies = http_bywl_materialized,
            transport = match transport {
                MeshEgressTransport::Hbone => "hbone",
                MeshEgressTransport::NodeWaypointCapturedService =>
                    "node_waypoint_captured_service",
                MeshEgressTransport::SidecarMtls => "mtls",
            },
            "Materialized mesh outbound egress routes to in-mesh services"
        );
    }
}

/// Materialize raw-TCP egress UPSTREAMS for the stream-family
/// (TCP/TLS/DB-protocol) service ports of in-mesh services — both captured
/// topologies.
///
/// Unlike HTTP-family egress, NO route proxy enters the config: a raw stream
/// has no Host header to route by, so the request path can't use the host
/// tiers at all. Instead the captured connection's pre-NAT original
/// destination (`SO_ORIGINAL_DST`) is matched STRICTLY against
/// `(cluster_ip, service_port)` by the route table's
/// `mesh_tcp_egress_decision` (built forward from the prepared `mesh` block,
/// same doctrine as the per-port sibling groups) and relayed through an HBONE
/// CONNECT tunnel to the LB-selected workload's app port — HBONE is already a
/// byte-stream tunnel, and the destination's transparent inbound relay dials
/// the CONNECT authority, so raw TCP rides the existing transport end to end.
/// A VIP/port pair that matches nothing falls through to the HTTP path
/// (unchanged behavior); a declared-but-unroutable match is CLOSED — never
/// guessed (the #1601 fail-closed rule). Port-number-only matching is
/// deliberately NOT supported: two services may share a port number, and a
/// captured dial to a non-mesh destination must never be tunnelled into the
/// mesh on a port coincidence.
///
/// Per-topology scope: **Ambient and Sidecar.** The transport differs — Ambient
/// emits `mesh.hbone` targets (relay over HBONE `:15008`), Sidecar emits
/// `mesh.mtls` targets (relay over a fresh mesh-mTLS H2
/// CONNECT tunnel to the peer's `:15006`; the destination sidecar's inbound
/// listener recognizes a bare H2 CONNECT and relays it like HBONE does) — but
/// the materialization is identical: per-port upstreams keyed to the service
/// VIP. Headless / VIP-less services materialize nothing routable and warn (raw
/// streams carry no Host, so captured dials are matched strictly by `(VIP,
/// port)`). NodeWaypoint skips this materialization until the eBPF datapath can
/// deliver HBONE to a reachable peer address.
fn materialize_mesh_outbound_tcp_upstreams(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) {
    // Raw-TCP egress rides captured outbound topologies that can deliver the
    // selected transport to a reachable peer address. Gateways, ServiceWaypoint,
    // and NodeWaypoint materialize no raw-TCP outbound capture routes here.
    let transport = match runtime.topology {
        MeshTopology::Ambient => MeshEgressTransport::Hbone,
        MeshTopology::NodeWaypoint => {
            debug!(
                "Skipping NodeWaypoint raw-TCP egress materialization; current eBPF datapath cannot deliver pod-IP HBONE targets"
            );
            return;
        }
        MeshTopology::Sidecar => MeshEgressTransport::SidecarMtls,
        _ => return,
    };
    let multi_cluster = mesh_slice.multi_cluster.as_ref();
    let now = chrono::Utc::now();
    let mut materialized = 0usize;
    for service in &mesh_slice.services {
        let tcp_ports = service_tcp_stream_ports(service);
        if tcp_ports.is_empty() {
            continue;
        }
        if service.cluster_ips.is_empty() {
            warn!(
                service = %service.name,
                namespace = %service.namespace,
                tcp_ports = tcp_ports.len(),
                "In-mesh service declares stream-family (TCP) ports but carries no cluster_ips; \
                 raw-TCP egress maps captured original destinations to services strictly by \
                 service VIP (a raw stream has no Host header and a bare port number is \
                 ambiguous), so these ports cannot be egress-routed. Headless services are \
                 expected here; otherwise populate cluster_ips."
            );
            continue;
        }
        for service_port in &tcp_ports {
            let protocol = service
                .protocol_overrides
                .get(&service_port.port)
                .copied()
                .unwrap_or(service_port.protocol);
            let targets = build_outbound_mesh_targets(
                transport,
                runtime,
                service,
                service_port,
                protocol,
                &mesh_slice.workloads,
                multi_cluster,
                false,
            );
            if targets.is_empty() {
                debug!(
                    service = %service.name,
                    namespace = %service.namespace,
                    service_port = service_port.port,
                    "Skipping raw-TCP mesh service port with no reachable local-cluster workload targets"
                );
                continue;
            }
            let upstream_id =
                mesh_outbound_tcp_upstream_id(&service.namespace, &service.name, service_port.port);
            // FQDN-named for DestinationRule matching, exactly like the HTTP
            // per-port upstreams (top-level connectTimeout / LB / outlier and
            // per-port portLevelSettings fan-out all apply).
            let service_fqdn = format!(
                "{}.{}.svc.{}",
                service.name,
                service.namespace,
                runtime.cluster_domain.trim_matches('.')
            );
            let upstream = mesh_outbound_route_upstream(
                &upstream_id,
                &service.namespace,
                &service_fqdn,
                targets,
                now,
            );
            if let Some(existing) = config.upstreams.iter_mut().find(|u| u.id == upstream.id) {
                *existing = upstream;
            } else {
                config.upstreams.push(upstream);
            }
            materialized += 1;
        }
    }

    // ── Direct-pod-IP / headless raw-TCP egress (F3 §3.4) ──────────────────
    // The VIP loop above routes ONLY `(cluster_ip VIP, service port)` dials. A
    // client that resolved a HEADLESS service itself and dials a POD IP
    // directly bypasses the VIP table; a VIP-less service warns+skips above.
    // For each backing workload IP of a stream-family service port, materialize
    // a SINGLE-TARGET upstream pinned to THAT workload's identity over the
    // topology's transport, so a captured `(pod IP, target port)` dial routes
    // to exactly that workload. Strict exact match; the route-table index
    // (`mesh_tcp_egress_by_workload`) and the accept-loop fallback enforce it.
    let mut bywl_materialized = 0usize;
    for spec in
        mesh_outbound_tcp_bywl_upstreams(&mesh_slice.services, &mesh_slice.workloads, multi_cluster)
    {
        // One tagged target dialing the resolved container port, identity-pinned
        // to this workload — built with the SAME transport tag builders the VIP
        // path uses, so `mesh.spiffe_id` / `mesh.protocol` / the transport tag
        // match (the VIP path stamps a `mesh.mtls_authority_port` only for
        // MULTI-port destinations; a direct pod-IP dial already carries the app
        // port in its orig-dst, so no `:authority` rewrite is needed and the tag
        // is intentionally absent — the destination's inbound relay dials the
        // CONNECT authority `host:target_port` directly).
        let mut tags = match transport {
            MeshEgressTransport::Hbone => crate::service_discovery::mesh::mesh_hbone_target_tags(
                spec.service,
                spec.workload,
                spec.protocol,
                spec.service_port.name.as_deref(),
            ),
            MeshEgressTransport::NodeWaypointCapturedService => {
                crate::service_discovery::mesh::mesh_node_waypoint_target_tags(
                    spec.service,
                    spec.workload,
                    spec.protocol,
                    spec.service_port.name.as_deref(),
                )
            }
            MeshEgressTransport::SidecarMtls => {
                crate::service_discovery::mesh::mesh_sidecar_mtls_target_tags(
                    spec.service,
                    spec.workload,
                    spec.protocol,
                    spec.service_port.name.as_deref(),
                )
            }
        };
        // Non-default egress dial port (heterogeneous meshes / functional
        // harness), exactly like the VIP path.
        match transport {
            MeshEgressTransport::Hbone => {
                if runtime.egress_hbone_port != hbone::ISTIO_HBONE_PORT {
                    tags.insert(
                        crate::proxy::hbone_pool::HBONE_PORT_TAG.to_string(),
                        runtime.egress_hbone_port.to_string(),
                    );
                }
            }
            MeshEgressTransport::NodeWaypointCapturedService => {}
            MeshEgressTransport::SidecarMtls => {
                if runtime.egress_mtls_port
                    != crate::proxy::mesh_mtls_pool::ISTIO_SIDECAR_INBOUND_PORT
                {
                    tags.insert(
                        crate::proxy::mesh_mtls_pool::MESH_MTLS_PORT_TAG.to_string(),
                        runtime.egress_mtls_port.to_string(),
                    );
                }
            }
        }
        let target = UpstreamTarget {
            // Dial the workload's own (canonicalized) IP, not the VIP.
            host: spec.canonical_ip.to_string(),
            port: spec.target_port,
            service_port_policy_key: Some(spec.service_port.port),
            weight: 1,
            tags,
            locality: spec.workload.locality.clone(),
            path: None,
        };
        let service_fqdn = spec.service_fqdn(&runtime.cluster_domain);
        let upstream = mesh_outbound_route_upstream(
            &spec.upstream_id,
            &spec.service.namespace,
            &service_fqdn,
            vec![target],
            now,
        );
        if let Some(existing) = config.upstreams.iter_mut().find(|u| u.id == upstream.id) {
            *existing = upstream;
        } else {
            config.upstreams.push(upstream);
        }
        bywl_materialized += 1;
    }

    if materialized > 0 || bywl_materialized > 0 {
        info!(
            tcp_upstreams = materialized,
            tcp_bywl_upstreams = bywl_materialized,
            topology = ?runtime.topology,
            "Materialized mesh raw-TCP egress upstreams for in-mesh services (relayed over the \
             topology's CONNECT transport, selected by captured original destination against \
             service VIPs and — for direct pod-IP / headless dials — against backing workload \
             addresses)"
        );
    }
}

/// Materialize per-port UDP egress upstreams for the UDP service ports of
/// in-mesh services (F3 §3.3 Stage 4). **Ambient-only.**
///
/// Like raw-TCP egress, NO route proxy enters the config: a UDP datagram has no
/// Host header to route by. Instead the captured datagram's original
/// destination (recovered from the TPROXY `IP_RECVORIGDSTADDR` cmsg, NOT
/// `SO_ORIGINAL_DST` which is TCP-only) is matched STRICTLY against
/// `(cluster_ip, UDP service port)` by the route table's `mesh_udp_egress`
/// index and tunnelled over a `udp`-marked HBONE CONNECT to the LB-selected
/// workload's app port (length-delimited datagrams — see
/// `crate::proxy::mesh_udp_frame`). The destination's inbound relay unframes the
/// tunnel into a local `UdpSocket` to the CONNECT authority.
///
/// **Dual-transport, mirroring raw-TCP egress**: Ambient relays the datagram
/// tunnel over an HBONE CONNECT (`:15008`, `mesh.hbone`-tagged targets →
/// `HboneConnectionPool::get_datagram_tunnel`); Sidecar relays it over a
/// mesh-mTLS CONNECT (`:15006`, `mesh.mtls`-tagged targets →
/// `MeshMtlsConnectionPool::open_datagram_tunnel`) — Sidecar peers expose no
/// `:15008` HBONE listener (they speak plain SVID-mTLS HTTP on `:15006`). The
/// materializer therefore gates `Ambient => Hbone, Sidecar => SidecarMtls, _ =>
/// return`; other topologies (EastWestGateway / EgressGateway) materialize
/// nothing and UDP stays outside the mesh. `build_outbound_mesh_targets` stamps
/// the per-transport tag (`mesh.mtls` + pinned `mesh.spiffe_id` for Sidecar), so
/// the egress datapath picks the right tunnel from the tag. Headless / VIP-less
/// UDP services also materialize nothing (a UDP datagram carries no Host, so
/// captured dials are matched strictly by VIP).
fn materialize_mesh_outbound_udp_upstreams(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) {
    // Dual-transport: Ambient → HBONE datagram tunnel (`:15008`); Sidecar →
    // mesh-mTLS datagram tunnel (`:15006`). Other topologies materialize nothing.
    let transport = match runtime.topology {
        MeshTopology::Ambient => MeshEgressTransport::Hbone,
        MeshTopology::Sidecar => MeshEgressTransport::SidecarMtls,
        _ => return,
    };
    let multi_cluster = mesh_slice.multi_cluster.as_ref();
    let now = chrono::Utc::now();
    let mut materialized = 0usize;
    for service in &mesh_slice.services {
        let udp_ports = service_udp_stream_ports(service);
        if udp_ports.is_empty() {
            continue;
        }
        if service.cluster_ips.is_empty() {
            warn!(
                service = %service.name,
                namespace = %service.namespace,
                udp_ports = udp_ports.len(),
                "In-mesh service declares UDP ports but carries no cluster_ips; UDP egress maps \
                 captured original destinations to services strictly by service VIP (a datagram \
                 has no Host header and a bare port number is ambiguous), so these ports cannot \
                 be egress-routed. Headless services are expected here; otherwise populate \
                 cluster_ips."
            );
            continue;
        }
        for service_port in &udp_ports {
            let protocol = service
                .protocol_overrides
                .get(&service_port.port)
                .copied()
                .unwrap_or(service_port.protocol);
            let targets = build_outbound_mesh_targets(
                transport,
                runtime,
                service,
                service_port,
                protocol,
                &mesh_slice.workloads,
                multi_cluster,
                false,
            );
            if targets.is_empty() {
                debug!(
                    service = %service.name,
                    namespace = %service.namespace,
                    service_port = service_port.port,
                    "Skipping UDP mesh service port with no reachable local-cluster workload targets"
                );
                continue;
            }
            let upstream_id =
                mesh_outbound_udp_upstream_id(&service.namespace, &service.name, service_port.port);
            let service_fqdn = format!(
                "{}.{}.svc.{}",
                service.name,
                service.namespace,
                runtime.cluster_domain.trim_matches('.')
            );
            let upstream = mesh_outbound_route_upstream(
                &upstream_id,
                &service.namespace,
                &service_fqdn,
                targets,
                now,
            );
            if let Some(existing) = config.upstreams.iter_mut().find(|u| u.id == upstream.id) {
                *existing = upstream;
            } else {
                config.upstreams.push(upstream);
            }
            materialized += 1;
        }
    }

    if materialized > 0 {
        info!(
            udp_upstreams = materialized,
            topology = ?runtime.topology,
            "Materialized mesh UDP egress upstreams for in-mesh services (datagrams tunnelled over \
             a udp-marked mesh CONNECT — HBONE :15008 for Ambient, mesh-mTLS :15006 for Sidecar — \
             selected by captured original destination against service VIPs)"
        );
    }
}

/// Reserved id prefix for the synthesized raw-TCP egress relay proxies. Like
/// the upstream id, deliberately NOT under `__mesh-outbound-` so it can never
/// be misclassified as a direction-scoped route id — these proxies never
/// enter the route table or `config.proxies`; they exist so the HBONE pool's
/// per-proxy pool-config / connect-budget resolution and the capability-probe
/// key have a stable proxy identity shared between probing and dispatch.
pub(crate) const MESH_OUTBOUND_TCP_RELAY_PROXY_ID_PREFIX: &str = "__mesh-out-tcp-relay-";

/// Reserved id prefix for the synthesized DIRECT-pod-IP raw-TCP egress relay
/// proxies (F3 §3.4) — the by-workload-addr counterpart of
/// [`MESH_OUTBOUND_TCP_RELAY_PROXY_ID_PREFIX`]. Same non-route-prefix rationale;
/// a distinct prefix so a VIP relay proxy and a by-workload relay proxy for the
/// same service port never collide.
pub(crate) const MESH_OUTBOUND_TCP_BYWL_RELAY_PROXY_ID_PREFIX: &str = "__mesh-out-tcp-bywl-relay-";

/// Build the synthesized relay proxy backing one raw-TCP egress entry.
/// DETERMINISTIC apart from timestamps: the capability registry keys off the
/// proxy's scheme/dns/TLS fields plus the target, so the table's dispatch
/// copy and the probe-enrollment copy (built independently) must agree —
/// keep any field that feeds `capability_key_for_proxy_target` or
/// `PoolConfig::for_proxy` in sync between the two call sites by sharing
/// this builder. `BackendScheme::Tcp` keeps the plain-HTTP/h2c probes away
/// from a raw-TCP app port (only the HBONE probe runs for it).
pub(crate) fn mesh_outbound_tcp_relay_proxy(
    namespace: &str,
    name: &str,
    port: u16,
    upstream_id: &str,
) -> Proxy {
    let id = format!("{MESH_OUTBOUND_TCP_RELAY_PROXY_ID_PREFIX}{namespace}-{name}-{port}")
        .replace(['/', '.'], "-");
    mesh_outbound_tcp_relay_proxy_with_id(id, namespace, upstream_id, BackendScheme::Tcp)
}

/// Build the synthesized relay proxy backing one DIRECT-pod-IP raw-TCP egress
/// entry (F3 §3.4). Same shape and capability/pool-config contract as
/// [`mesh_outbound_tcp_relay_proxy`] (it shares the builder), but its id folds
/// in the canonical workload IP and points at the per-workload upstream, so the
/// capability key + LB-selection upstream agree between the index, dispatch, and
/// probe enrollment. The id is forward-derived, never parsed.
pub(crate) fn mesh_outbound_tcp_bywl_relay_proxy(
    namespace: &str,
    name: &str,
    port: u16,
    canonical_ip: std::net::IpAddr,
    upstream_id: &str,
) -> Proxy {
    let id = format!(
        "{MESH_OUTBOUND_TCP_BYWL_RELAY_PROXY_ID_PREFIX}{namespace}-{name}-{port}-{canonical_ip}"
    )
    .replace(['/', '.', ':'], "-");
    mesh_outbound_tcp_relay_proxy_with_id(id, namespace, upstream_id, BackendScheme::Tcp)
}

/// Reserved id prefix for the synthesized UDP egress relay proxies (F3 §3.3
/// Stage 4). Same non-route-prefix rationale as the raw-TCP relay proxies; a
/// DISTINCT prefix so a TCP relay proxy and a UDP relay proxy for the same
/// service port never collide in the capability registry / pool-config keys.
pub(crate) const MESH_OUTBOUND_UDP_RELAY_PROXY_ID_PREFIX: &str = "__mesh-out-udp-relay-";

/// Build the synthesized relay proxy backing one UDP egress entry (F3 §3.3
/// Stage 4). Same deterministic shape and capability/pool-config contract as
/// [`mesh_outbound_tcp_relay_proxy`] (shares the builder body), but uses
/// `BackendScheme::Udp` — which the capability probe gate recognizes for HBONE
/// probing (a UDP egress target still rides an HBONE CONNECT, so its HBONE
/// support must be proven) while keeping the plain-HTTP/h2c probes off it. The
/// id is forward-derived, never parsed.
pub(crate) fn mesh_outbound_udp_relay_proxy(
    namespace: &str,
    name: &str,
    port: u16,
    upstream_id: &str,
) -> Proxy {
    let id = format!("{MESH_OUTBOUND_UDP_RELAY_PROXY_ID_PREFIX}{namespace}-{name}-{port}")
        .replace(['/', '.'], "-");
    mesh_outbound_tcp_relay_proxy_with_id(id, namespace, upstream_id, BackendScheme::Udp)
}

/// Shared body for the mesh egress relay proxies (raw-TCP VIP/by-workload and
/// UDP). The fields that vary between flavors are the `id`, the `upstream_id` it
/// dispatches through, and the `scheme` (`Tcp` for raw-TCP, `Udp` for UDP — both
/// keep the plain-HTTP/h2c probes away from the app port while still letting the
/// HBONE probe run); everything else (the connect/read/write budgets, the stream
/// idle default) is identical, so the flavors stay byte-for-byte consistent in
/// the capability key / pool-config dimensions.
fn mesh_outbound_tcp_relay_proxy_with_id(
    id: String,
    namespace: &str,
    upstream_id: &str,
    scheme: BackendScheme,
) -> Proxy {
    let now = chrono::Utc::now();
    Proxy {
        name: Some(format!("mesh egress {id}")),
        id,
        namespace: namespace.to_string(),
        hosts: Vec::new(),
        listen_path: None,
        backend_scheme: Some(scheme),
        dispatch_kind: Default::default(),
        backend_host: String::new(),
        backend_port: 0,
        backend_path: None,
        strip_listen_path: false,
        preserve_host_header: false,
        backend_connect_timeout_ms: 5_000,
        backend_read_timeout_ms: 30_000,
        backend_write_timeout_ms: 30_000,
        backend_tls_client_cert_path: None,
        backend_tls_client_key_path: None,
        backend_tls_verify_server_cert: false,
        backend_tls_server_ca_cert_path: None,
        resolved_tls: BackendTlsConfig::default(),
        dispatch_port_overrides: None,
        dispatch_port_override_fallback: None,
        dns_override: None,
        dns_cache_ttl_seconds: None,
        auth_mode: Default::default(),
        plugins: Vec::<PluginAssociation>::new(),
        pool_idle_timeout_seconds: None,
        pool_enable_http_keep_alive: None,
        pool_enable_http2: None,
        pool_tcp_keepalive_seconds: None,
        pool_http2_keep_alive_interval_seconds: None,
        pool_http2_keep_alive_timeout_seconds: None,
        pool_http2_initial_stream_window_size: None,
        pool_http2_initial_connection_window_size: None,
        pool_http2_adaptive_window: None,
        pool_http2_max_frame_size: None,
        pool_http2_max_concurrent_streams: None,
        pool_http3_connections_per_backend: None,
        h2_upgrade_policy: None,
        pool_max_requests_per_connection: None,
        // Derived-only: projected from DestinationRule port overrides at
        // dispatch time via `resolve_effective_proxy_for_target`; a
        // freshly-materialized mesh proxy starts at `None`.
        pool_http1_max_pending_requests: None,
        upstream_id: Some(upstream_id.to_string()),
        upstream_subset: None,
        api_spec_id: None,
        circuit_breaker: None,
        retry: None,
        response_body_mode: ResponseBodyMode::Stream,
        listen_port: None,
        frontend_tls: false,
        passthrough: false,
        udp_idle_timeout_seconds: 60,
        udp_max_response_amplification_factor: None,
        stream_proxy_protocol: None,
        // Matches the repo's stream-proxy idle default; long-lived idle DB
        // connections past this are closed by the relay's idle watchdog.
        tcp_idle_timeout_seconds: Some(300),
        websocket_idle_timeout_seconds: None,
        allowed_methods: None,
        allowed_ws_origins: Vec::new(),
        created_at: now,
        updated_at: now,
    }
}

/// Build upstream targets for an in-mesh service's workloads,
/// for outbound (`:15001`-capture) egress materialization. Matches workloads
/// by `WorkloadRef` SPIFFE (one-to-one by index so replicas sharing a SPIFFE id
/// still produce distinct targets, with remote-cluster endpoints filtered out),
/// tags each target for the topology's dispatch posture via the shared
/// `service_discovery::mesh` tag builders (HBONE for Ambient, SVID-mTLS for
/// Sidecar, and NodeWaypoint metadata-backed HBONE or dev-only plaintext
/// captured-Service dispatch for NodeWaypoint), and
/// sets `UpstreamTarget.port` to the app (container) port the service port
/// forwards to (the HBONE CONNECT authority port / DR `port_overrides` key),
/// not the service port. The transport's own DIAL port (15008 / 15006, or the
/// operator's `FERRUM_MESH_EGRESS_*_PORT` override stamped as a tag) is
/// resolved by the pools at dispatch time. When the service declares MULTIPLE
/// HTTP-family ports (`multi_port_service`), Sidecar targets additionally
/// carry [`crate::proxy::mesh_mtls_pool::MESH_MTLS_AUTHORITY_PORT_TAG`] — the
/// owning SERVICE port — so dispatch rewrites the request `:authority` to
/// `<host>:<service_port>` and the destination sidecar's per-port inbound
/// siblings can tell the ports apart (its `:15006` dials are direct, never
/// NATed, so the authority is the only port channel the source controls).
#[allow(clippy::too_many_arguments)]
fn build_outbound_mesh_targets(
    transport: MeshEgressTransport,
    runtime: &MeshRuntimeConfig,
    service: &crate::modes::mesh::config::MeshService,
    service_port: &crate::modes::mesh::config::ServicePort,
    protocol: AppProtocol,
    workloads: &[crate::modes::mesh::config::Workload],
    multi_cluster: Option<&crate::modes::mesh::config::MultiClusterConfig>,
    multi_port_service: bool,
) -> Vec<UpstreamTarget> {
    let mut targets = Vec::new();
    let require_node_waypoint_metadata = transport
        == MeshEgressTransport::NodeWaypointCapturedService
        && runtime.node_waypoint_secured_transport_required();
    for workload in matched_local_service_workloads(service, workloads, multi_cluster) {
        if require_node_waypoint_metadata && workload.node_waypoint.is_none() {
            warn!(
                service = %service.name,
                namespace = %service.namespace,
                workload_spiffe = %workload.spiffe_id,
                "Skipping NodeWaypoint service target without destination node_waypoint metadata; \
                 secured NodeWaypoint transport is required in this identity posture"
            );
            continue;
        }
        // App (container) port the request is for. A DECLARED `targetPort` is
        // authoritative: resolve it, or SKIP this target (fail closed) rather
        // than fall back to the service port — an unresolved named targetPort
        // (rollout skew / typo) must not dial the wrong port. Only an ABSENT
        // targetPort falls back to the service port.
        let app_port = match service_port.target_port.as_ref() {
            Some(_) => {
                match resolve_target_port(service_port.target_port.as_ref(), &workload.ports) {
                    Some(p) if p != 0 => p,
                    _ => continue,
                }
            }
            None => service_port.port,
        };
        if app_port == 0 {
            continue;
        }

        let mut tags = match transport {
            MeshEgressTransport::Hbone => crate::service_discovery::mesh::mesh_hbone_target_tags(
                service,
                workload,
                protocol,
                service_port.name.as_deref(),
            ),
            MeshEgressTransport::NodeWaypointCapturedService => {
                crate::service_discovery::mesh::mesh_node_waypoint_target_tags(
                    service,
                    workload,
                    protocol,
                    service_port.name.as_deref(),
                )
            }
            MeshEgressTransport::SidecarMtls => {
                crate::service_discovery::mesh::mesh_sidecar_mtls_target_tags(
                    service,
                    workload,
                    protocol,
                    service_port.name.as_deref(),
                )
            }
        };
        // Stamp a non-default egress dial port so heterogeneous meshes (and the
        // two-gateways-on-one-host functional harness) can address peers whose
        // transport listener is not on the Istio-convention port.
        match transport {
            MeshEgressTransport::Hbone => {
                if runtime.egress_hbone_port != hbone::ISTIO_HBONE_PORT {
                    tags.insert(
                        crate::proxy::hbone_pool::HBONE_PORT_TAG.to_string(),
                        runtime.egress_hbone_port.to_string(),
                    );
                }
            }
            MeshEgressTransport::NodeWaypointCapturedService => {}
            MeshEgressTransport::SidecarMtls => {
                if runtime.egress_mtls_port
                    != crate::proxy::mesh_mtls_pool::ISTIO_SIDECAR_INBOUND_PORT
                {
                    tags.insert(
                        crate::proxy::mesh_mtls_pool::MESH_MTLS_PORT_TAG.to_string(),
                        runtime.egress_mtls_port.to_string(),
                    );
                }
                // Multi-port destination: stamp the owning service port so
                // dispatch rewrites the `:authority` the peer's inbound
                // per-port siblings disambiguate by. Never stamped for
                // single-port services (their authority stays untouched).
                if multi_port_service {
                    tags.insert(
                        crate::proxy::mesh_mtls_pool::MESH_MTLS_AUTHORITY_PORT_TAG.to_string(),
                        service_port.port.to_string(),
                    );
                }
            }
        }
        for address in &workload.addresses {
            targets.push(UpstreamTarget {
                host: address.clone(),
                port: app_port,
                service_port_policy_key: Some(service_port.port),
                weight: 1,
                tags: tags.clone(),
                locality: workload.locality.clone(),
                path: None,
            });
        }
    }

    // CROSS-CLUSTER east-west targets. For a service with REMOTE workloads,
    // materialize targets that route to the destination cluster via its REMOTE
    // east-west gateway (SNI passthrough), using trust-domain-only peer
    // verification (the gateway LB-picks the destination, so no pod pinning) +
    // the destination-FQDN SNI override (`mesh.eastwest_sni`). Local targets
    // above stay first-tier; these remote-tier targets only receive traffic once
    // locals are exhausted (`mesh.remote=true`).
    //
    // The SHAPE differs per transport (the inner protocol does):
    // - SIDECAR mesh-mTLS: the dest sidecar routes the inner mesh-mTLS-HTTP
    //   request by its `Host:<service-fqdn>` to loopback, so ONE target per
    //   `(network, trust_domain)` group at the GATEWAY endpoint suffices
    //   (`append_cross_cluster_mesh_targets`).
    // - AMBIENT HBONE: the inner is an HBONE CONNECT whose `:authority` the dest
    //   relay dials under the OPEN-RELAY GUARD (loopback or a slice-declared
    //   workload addr+port — a service FQDN is REJECTED), so targets are
    //   PER-REMOTE-POD (`host:port` = pod addr:app-port = the CONNECT authority)
    //   with the east-west gateway carried as a DIAL OVERRIDE
    //   (`mesh.hbone_dial_host` / `mesh.hbone_port`)
    //   (`append_cross_cluster_ambient_hbone_targets`).
    //
    // Cross-cluster transport is available to all three protocol lanes. HTTP
    // keeps its gateway-endpoint target shape because the destination routes
    // the inner request by Host. Raw TCP and UDP instead require a per-pod
    // CONNECT authority, so Sidecar uses the L4-specific target shape below;
    // Ambient already uses a per-pod authority for every protocol.
    match transport {
        MeshEgressTransport::SidecarMtls => {
            if is_http_family_mesh_protocol(protocol) {
                append_cross_cluster_mesh_targets(
                    &mut targets,
                    &runtime.cluster_domain,
                    service,
                    service_port,
                    protocol,
                    workloads,
                    multi_cluster,
                )
            } else {
                append_cross_cluster_sidecar_l4_targets(
                    &mut targets,
                    &runtime.cluster_domain,
                    service,
                    service_port,
                    protocol,
                    workloads,
                    multi_cluster,
                )
            }
        }
        MeshEgressTransport::Hbone => append_cross_cluster_ambient_hbone_targets(
            &mut targets,
            runtime,
            service,
            service_port,
            protocol,
            workloads,
            multi_cluster,
        ),
        // NodeWaypoint captured-Service egress is dispatched per the selected
        // workload's NodeWaypoint metadata, not an east-west gateway.
        MeshEgressTransport::NodeWaypointCapturedService => {}
    }

    targets
}

/// Append SIDECAR cross-cluster east-west targets for `service` on
/// `service_port` (see the call site in [`build_outbound_mesh_targets`]).
///
/// The service's remote workloads are first REACHABILITY-FILTERED (codex r2
/// [R2-2]): a remote workload is kept only if it has ≥1 address AND its
/// first-service-port target port resolves — MIRRORING
/// [`build_east_west_service_targets`]'s skip conditions on the GATEWAY side, so
/// a workload the destination cluster's east-west materializer would itself drop
/// (no pod IP / unresolved named targetPort) never produces a dead gateway path
/// here. Unreachable remote workloads are dropped; if none remain, nothing is
/// emitted.
///
/// The surviving reachable remote workloads are grouped by
/// `(network, trust_domain)`, and exactly ONE target is emitted per group,
/// addressed at the group's selected east-west gateway DIAL ENDPOINT
/// (`gateway.host:gateway.port`) with:
/// - `mesh.mtls = "true"` (Sidecar transport) and NO `mesh.spiffe_id` (the
///   gateway LB-picks the destination workload, so no pod pinning — verification
///   is trust-domain-only against the remote trust domain);
/// - `mesh.trust_domain` = the group's trust domain;
/// - `mesh.mtls_port` = `gateway.port` (the DIAL port, e.g. `:15443`);
/// - `mesh.eastwest_sni` = the destination service FQDN (the SNI the remote
///   gateway's passthrough routes on);
/// - `mesh.cross_cluster = "true"`;
/// - `mesh.remote = "true"` (strict local-first LB provenance);
/// - **identity = the gateway DIAL ENDPOINT** (codex r2 [R2-4]): `host =
///   gateway.host`, `port = gateway.port` (NOT the service port), so the
///   LB/health/CB `(host, port)` key is the actual reachable gateway endpoint
///   and two gateways on the same host (different ports) — or two services
///   fronted by distinct gateways — never collapse onto one identity. The DR
///   policy stays keyed by the SERVICE port via `service_port_policy_key =
///   Some(service_port.port)`. The inner request authority/Host is the service
///   FQDN (the route host), unaffected by `port`.
/// - `locality` = the group representative's (already remote-tiered) locality so
///   locality-LB ranks it AFTER local targets (local-first failover).
///
/// Gateway selection ([`select_east_west_gateway_for_network`]) requires the
/// gateway to front the group's network, claim the destination service FQDN in
/// its `sni_hosts`, AND match the group's trust domain (codex r2 [R2-3]). A
/// `network: None` catch-all gateway is considered ONLY when the requested
/// network has NO EastWestGateway entry at all (codex r2 [R2-1]) — a network
/// that HAS gateways but whose gateways fail SNI/trust-domain fails CLOSED (no
/// fall-through to a different-network catch-all). A group with no matching
/// gateway is SKIPPED with a warning — fail closed, never dial an unresolved
/// address.
///
/// SHARED CORE: this is the single implementation of Sidecar cross-cluster
/// grouping/reachability/gateway-selection, used by BOTH the mesh-mode
/// outbound materializer ([`build_outbound_mesh_targets`], which passes
/// `&runtime.cluster_domain`) and the gateway-to-mesh SD bridge
/// ([`crate::service_discovery::mesh::MeshServiceDiscoverer`], which runs in
/// database/file/dp modes with no `MeshRuntimeConfig` and passes its own
/// resolved cluster domain). `cluster_domain` is the only runtime field the
/// logic needs — do NOT re-widen the parameter to the mesh runtime, and do NOT
/// fork this logic into the SD path.
///
/// TWO ENTRY POINTS, ONE CORE: workload→service MATCHING is the one step the
/// two callers legitimately do differently. This function is the mesh-mode
/// materializer entry point — it matches via the ref-based
/// [`matched_remote_service_workloads`] (mirroring the local materializer's
/// matcher) and delegates everything else to
/// [`append_cross_cluster_mesh_targets_prematched`]. The SD bridge calls the
/// prematched entry point DIRECTLY with the remote workloads its `discover()`
/// loop already matched (`workload_matches_service` semantics, which include
/// the service-name fallback for a `MeshService` with no `workloads` refs) —
/// so the two matchers never fork the grouping/reachability/gateway-selection
/// logic, and neither caller's matching semantics leak into the other's.
pub(crate) fn append_cross_cluster_mesh_targets(
    targets: &mut Vec<UpstreamTarget>,
    cluster_domain: &str,
    service: &crate::modes::mesh::config::MeshService,
    service_port: &crate::modes::mesh::config::ServicePort,
    protocol: AppProtocol,
    workloads: &[crate::modes::mesh::config::Workload],
    multi_cluster: Option<&crate::modes::mesh::config::MultiClusterConfig>,
) {
    let Some(multi_cluster) = multi_cluster else {
        return;
    };

    let all_remote_workloads =
        matched_remote_service_workloads(service, workloads, Some(multi_cluster));
    append_cross_cluster_mesh_targets_prematched(
        targets,
        cluster_domain,
        service,
        service_port,
        protocol,
        &all_remote_workloads,
        multi_cluster,
    );
}

/// The pre-matched entry point of the Sidecar cross-cluster SHARED CORE (see
/// [`append_cross_cluster_mesh_targets`], which documents the emitted target
/// shape and the two-entry-point contract). `remote_workloads` MUST already be
/// (a) matched to `service` under the CALLER's workload-matching semantics and
/// (b) classified remote via
/// [`crate::modes::mesh::multicluster::workload_is_remote`] against the SAME
/// `multi_cluster`. Everything downstream of matching lives here — the
/// per-port SNI scheme, the [R2-2] reachability filter, `(network, trust_domain)`
/// grouping, fail-closed gateway selection, and the [R3-3]/[R5-3] duplicate
/// dial-endpoint resolution — so it can never diverge between the mesh-mode
/// materializer and the SD bridge.
pub(crate) fn append_cross_cluster_mesh_targets_prematched(
    targets: &mut Vec<UpstreamTarget>,
    cluster_domain: &str,
    service: &crate::modes::mesh::config::MeshService,
    service_port: &crate::modes::mesh::config::ServicePort,
    protocol: AppProtocol,
    remote_workloads: &[&crate::modes::mesh::config::Workload],
    multi_cluster: &crate::modes::mesh::config::MultiClusterConfig,
) {
    // MULTI-PORT (issue #2010 phase 3): every HTTP-family `service_port` gets a
    // cross-cluster target. The destination gateway auto-materializes one
    // passthrough proxy per service port (`build_east_west_service_proxies_and_
    // upstreams`), keyed by the port's SNI: a single-HTTP-port service's sole
    // port on the bare base service FQDN, every port of a multi-port service on
    // its `p<port>.<fqdn>` alias (`cross_cluster_service_sni`). The client
    // SELECTS the gateway by the base FQDN or the exact dialed alias
    // (`east_west_acceptable_snis`) but DIALS the per-port SNI, so a gateway
    // owning the base FQDN auto-owns its port aliases with no extra operator
    // config. Non-HTTP-family ports never reach here (the caller gates the
    // append on `is_http_family_mesh_protocol`).
    if remote_workloads.is_empty() {
        return;
    }

    // [R2-2] REACHABILITY FILTER: keep only remote workloads the destination
    // cluster's east-west gateway could actually materialize a backend for —
    // MIRRORING `build_east_west_service_targets`'s per-workload skip conditions
    // for THIS service port (the gateway-side materializer drops a workload with
    // no pod IP or an unresolved targetPort). A workload that fails those would be
    // a DEAD gateway path (the SNI would reach the gateway, which would have no
    // backend to forward to), so it must not produce a cross-cluster target here.
    let remote_workloads: Vec<_> = remote_workloads
        .iter()
        .copied()
        .filter(|workload| east_west_workload_is_reachable(service_port, workload))
        .collect();
    if remote_workloads.is_empty() {
        warn!(
            service = %service.name,
            namespace = %service.namespace,
            service_port = service_port.port,
            "Skipping cross-cluster egress: no reachable remote workload (every remote endpoint \
             lacks an address or has an unresolved targetPort for this port; the east-west gateway \
             would have no backend to forward the SNI to)"
        );
        return;
    }

    // The client stamps the PER-PORT SNI as the dial override
    // (`mesh.eastwest_sni`) so the gateway's per-port passthrough proxy routes it
    // to the right backend port. It SELECTS the east-west gateway by accepting one
    // that claims EITHER the base service FQDN (whose ownership auto-extends to the
    // service's per-port aliases) OR the exact per-port alias being dialed (codex
    // #2040 Finding C). Both SNIs derive from `cross_cluster_service_{base_fqdn,
    // sni}` so client + gateway cannot drift. `dial_sni == base_fqdn` for a
    // single-port service, so the accept set collapses to the base FQDN there.
    let base_fqdn = cross_cluster_service_base_fqdn(service, cluster_domain);
    let dial_sni = cross_cluster_service_sni(service, service_port, cluster_domain);
    let acceptable_snis = east_west_acceptable_snis(&base_fqdn, &dial_sni);

    // Group the reachable remote workloads by `(network, trust_domain)`. Each
    // group needs a gateway that fronts its network, claims the service FQDN,
    // AND matches its trust domain (codex r2 [R2-3]); a target's identity is the
    // gateway DIAL endpoint ([R2-4]), so two networks fronted by gateways on the
    // same host but different ports produce DISTINCT targets. Iteration is
    // deterministic (sorted by network then trust-domain string) so the
    // materialized target order is stable across runs. Group VALUE is the index
    // of the first reachable workload in the group (its representative).
    let mut groups: std::collections::BTreeMap<(Option<&str>, &str), usize> =
        std::collections::BTreeMap::new();
    for (idx, workload) in remote_workloads.iter().enumerate() {
        groups
            .entry((workload.network.as_deref(), workload.trust_domain.as_str()))
            .or_insert(idx);
    }

    // Build each group's target into a local list first so duplicate gateway
    // DIAL ENDPOINTS can be rejected (codex r3 [R3-3]) before any reach the LB.
    let mut built: Vec<UpstreamTarget> = Vec::new();
    for ((network, _trust_domain_str), representative_idx) in groups {
        // Representative reachable remote workload for this group — its trust
        // domain is the cross-cluster verification target and its locality keeps
        // the target in the remote tier.
        let representative = remote_workloads[representative_idx];
        let Some(gateway) = select_east_west_gateway_for_network(
            multi_cluster,
            network,
            &acceptable_snis,
            &representative.trust_domain,
        ) else {
            warn!(
                service = %service.name,
                namespace = %service.namespace,
                network = network.unwrap_or("<none>"),
                trust_domain = %representative.trust_domain.as_str(),
                service_fqdn = %base_fqdn,
                "Skipping cross-cluster egress: no EastWestGateway on the remote network whose \
                 sni_hosts claim the destination service FQDN AND whose trust domain matches the \
                 remote workloads' (fail closed; never broaden to a different-network catch-all or \
                 a mismatched-trust-domain gateway)"
            );
            continue;
        };
        if gateway.host.is_empty() || gateway.port == 0 {
            warn!(
                service = %service.name,
                namespace = %service.namespace,
                gateway = %gateway.name,
                "Skipping cross-cluster egress: EastWestGateway has no usable host:port"
            );
            continue;
        }

        // Start from the standard Sidecar mesh-mTLS tag core, then override for
        // the cross-cluster posture: drop the pinned pod identity, set the
        // remote trust domain, the dial port, the SNI override, and the marker.
        let mut tags = crate::service_discovery::mesh::mesh_sidecar_mtls_target_tags(
            service,
            representative,
            protocol,
            service_port.name.as_deref(),
        );
        // No pod pinning across the SNI-passthrough gateway: remove the pinned
        // SPIFFE id so dispatch uses trust-domain-SCOPED verification. The
        // trust_domain tag is set to the REMOTE workloads' trust domain (the
        // domain dispatch scopes verification to — fail-closed if absent).
        tags.remove(crate::proxy::hbone_pool::MESH_SPIFFE_ID_TAG);
        tags.insert(
            crate::proxy::mesh_mtls_pool::MESH_TRUST_DOMAIN_TAG.to_string(),
            representative.trust_domain.as_str().to_string(),
        );
        // Remote provenance: the target is built from REMOTE workloads (it dials
        // the remote east-west gateway), so stamp the reserved `mesh.remote=true`
        // marker that strict local-first locality LB (`Upstream.locality_lb_strict`
        // / `FERRUM_MESH_LOCALITY_LB_STRICT=true`) keys remote-vs-local on. Without
        // it the gateway target would be ranked LOCAL and could be picked over
        // healthy local endpoints. (The remote-tier `locality` below is a fallback
        // for non-strict locality LB; the explicit tag is authoritative.)
        tags.insert(
            crate::modes::mesh::multicluster::MESH_REMOTE_TAG.to_string(),
            crate::modes::mesh::multicluster::MESH_REMOTE_TAG_VALUE.to_string(),
        );
        // Dial port = the east-west gateway port (e.g. :15443), NOT :15006.
        tags.insert(
            crate::proxy::mesh_mtls_pool::MESH_MTLS_PORT_TAG.to_string(),
            gateway.port.to_string(),
        );
        tags.insert(
            crate::proxy::mesh_mtls_pool::MESH_EASTWEST_SNI_TAG.to_string(),
            dial_sni.clone(),
        );
        tags.insert(
            crate::proxy::mesh_mtls_pool::MESH_CROSS_CLUSTER_TAG.to_string(),
            "true".to_string(),
        );
        // Multi-port east-west (issue #2010 phase 3) rides the per-port SNI alias
        // (`dial_sni`), NOT a `mesh.mtls_authority_port` rewrite: the destination
        // gateway routes the alias SNI to the correct per-port passthrough proxy,
        // whose backend already carries the right container port. The inner
        // mesh-mTLS request authority stays the service FQDN (the route host).
        //
        // KNOWN LIMITATION — SHARED targetPort (codex #2040): when two HTTP-family
        // service ports resolve to the SAME container port (e.g. `80 -> 8080` and
        // `90 -> 8080`), the SNI alias is consumed at the SNI-passthrough gateway,
        // which forwards BOTH to the same workload app port; the destination's
        // inbound selector then sees the same captured orig-dst (8080) for both and
        // — since cross-cluster carries no `mesh.mtls_authority_port` — applies the
        // lower port's inbound route/policy to both. This is NOT a misroute: both
        // service ports reach the SAME backend container (same app), so the
        // destination treatment is consistent; only DESTINATION-side per-SERVICE-
        // port policy differentiation for shared-container ports is lost (the
        // client-side DR policy stays per service port via `service_port_policy_key`
        // below). It is inherent to the single-SNI-per-port passthrough model —
        // distinct container ports are fully disambiguated. Documented rather than
        // papered over with an authority-port rewrite whose cross-cluster dest
        // interaction is not yet live-verified.

        built.push(UpstreamTarget {
            // [R2-4] IDENTITY = the gateway DIAL ENDPOINT (`host:port`). The
            // LB/health/CB key is `(host, port)`, so this MUST be the actual
            // reachable gateway endpoint — using the service port would collapse
            // two gateways on the same host (different ports), and two distinct
            // services fronted by different gateways, onto one identity. The
            // transport dials `target.host:mesh.mtls_port`, and `mesh.mtls_port`
            // is ALSO `gateway.port`, so dial and identity agree.
            host: gateway.host.clone(),
            port: gateway.port,
            // DR policy stays keyed by the declared SERVICE port (the authority
            // the operator's portLevelSettings target), even though the dial
            // identity is the gateway port. The inner request authority/Host is
            // the service FQDN (route host), unaffected by `port`.
            service_port_policy_key: Some(service_port.port),
            weight: 1,
            tags,
            // Remote-tier locality so locality-LB ranks this AFTER local targets.
            locality: representative.locality.clone(),
            path: None,
        });
    }

    // [R3-3]/[R5-3] Resolve targets that share a gateway DIAL ENDPOINT
    // (`host:port` — the LB / passive-health / circuit-breaker / retry key).
    // Group the built targets by endpoint and inspect the DISTINCT trust domains
    // landing on each:
    //   - ONE trust domain (e.g. two remote networks fronted by a single shared
    //     east-west gateway): NOT ambiguous — same SNI, same trust-domain
    //     verification — so COLLAPSE the duplicates to a single target (codex r5
    //     [R5-3]); dropping them would leave a remote-only service unreachable.
    //   - MULTIPLE trust domains on one endpoint (e.g. a TD-less wildcard gateway
    //     fronting a network whose workloads span two trust domains): genuinely
    //     ambiguous — the SNI-passthrough gateway LB-picks the backend, so the
    //     client cannot steer the shared endpoint to its expected trust domain,
    //     and the targets would collapse under one `host:port` LB/health key. FAIL
    //     CLOSED — drop EVERY target on that endpoint ([R3-3]); the operator must
    //     declare a distinct gateway endpoint per trust domain.
    let mut tds_by_endpoint: std::collections::HashMap<
        (String, u16),
        std::collections::HashSet<String>,
    > = std::collections::HashMap::new();
    for target in &built {
        let trust_domain = target
            .tags
            .get(crate::proxy::mesh_mtls_pool::MESH_TRUST_DOMAIN_TAG)
            .cloned()
            .unwrap_or_default();
        tds_by_endpoint
            .entry((target.host.clone(), target.port))
            .or_default()
            .insert(trust_domain);
    }
    let mut emitted_endpoints: std::collections::HashSet<(String, u16)> =
        std::collections::HashSet::new();
    for target in built {
        let endpoint = (target.host.clone(), target.port);
        if tds_by_endpoint
            .get(&endpoint)
            .map(std::collections::HashSet::len)
            .unwrap_or(0)
            > 1
        {
            warn!(
                service = %service.name,
                namespace = %service.namespace,
                gateway_host = %target.host,
                gateway_port = target.port,
                "Skipping cross-cluster egress target: multiple trust domains resolve to the same \
                 east-west gateway endpoint (fail closed; an SNI-passthrough gateway LB-picks the \
                 backend, so a shared endpoint cannot pin a trust domain — declare a distinct \
                 gateway endpoint per trust domain)"
            );
            continue;
        }
        // Sole trust domain on this endpoint: emit ONE target per endpoint,
        // collapsing duplicate same-domain groups (e.g. two networks behind one
        // shared gateway) onto a single LB identity.
        if emitted_endpoints.insert(endpoint) {
            targets.push(target);
        }
    }
}

/// Append Sidecar cross-cluster raw-TCP / UDP targets. Unlike HTTP-family
/// Sidecar egress, an L4 CONNECT has no inner Host route. Each remote workload
/// address therefore gets a target whose network dial is the east-west gateway
/// while `mesh.mtls_authority_host` carries the real pod address the selected
/// destination relay is allowed to dial. `target.host` is a scoped synthetic
/// identity including gateway, trust domain, SNI, and pod address so distinct
/// connection identities cannot collide in LB/health/circuit-breaker maps.
#[allow(clippy::too_many_arguments)]
fn append_cross_cluster_sidecar_l4_targets(
    targets: &mut Vec<UpstreamTarget>,
    cluster_domain: &str,
    service: &crate::modes::mesh::config::MeshService,
    service_port: &crate::modes::mesh::config::ServicePort,
    protocol: AppProtocol,
    workloads: &[crate::modes::mesh::config::Workload],
    multi_cluster: Option<&crate::modes::mesh::config::MultiClusterConfig>,
) {
    let Some(multi_cluster) = multi_cluster else {
        return;
    };
    let remote_workloads =
        matched_remote_service_workloads(service, workloads, Some(multi_cluster));
    let remote_workloads: Vec<_> = remote_workloads
        .into_iter()
        .filter(|workload| east_west_workload_is_reachable(service_port, workload))
        .collect();
    if remote_workloads.is_empty() {
        return;
    }

    let base_fqdn = cross_cluster_service_base_fqdn(service, cluster_domain);
    let dial_sni = cross_cluster_service_sni(service, service_port, cluster_domain);
    let acceptable_snis = east_west_acceptable_snis(&base_fqdn, &dial_sni);
    struct BuiltTarget {
        target: UpstreamTarget,
        dial_endpoint: (String, u16),
        trust_domain: String,
    }
    let mut built = Vec::new();

    for workload in remote_workloads {
        let Some(gateway) = select_east_west_gateway_for_network(
            multi_cluster,
            workload.network.as_deref(),
            &acceptable_snis,
            &workload.trust_domain,
        ) else {
            warn!(
                service = %service.name,
                namespace = %service.namespace,
                network = workload.network.as_deref().unwrap_or("<none>"),
                "Skipping cross-cluster Sidecar L4 workload without a matching east-west gateway"
            );
            continue;
        };
        if gateway.host.trim().is_empty() || gateway.port == 0 {
            warn!(service = %service.name, gateway = %gateway.name,
                "Skipping cross-cluster Sidecar L4 workload with an unusable gateway endpoint");
            continue;
        }
        let app_port = match service_port.target_port.as_ref() {
            Some(_) => resolve_target_port(service_port.target_port.as_ref(), &workload.ports)
                .filter(|port| *port != 0),
            None => (service_port.port != 0).then_some(service_port.port),
        };
        let Some(app_port) = app_port else {
            continue;
        };

        for address in &workload.addresses {
            let mut tags = crate::service_discovery::mesh::mesh_sidecar_mtls_target_tags(
                service,
                workload,
                protocol,
                service_port.name.as_deref(),
            );
            tags.remove(crate::proxy::hbone_pool::MESH_SPIFFE_ID_TAG);
            tags.insert(
                crate::proxy::mesh_mtls_pool::MESH_TRUST_DOMAIN_TAG.to_string(),
                workload.trust_domain.as_str().to_string(),
            );
            tags.insert(
                crate::modes::mesh::multicluster::MESH_REMOTE_TAG.to_string(),
                crate::modes::mesh::multicluster::MESH_REMOTE_TAG_VALUE.to_string(),
            );
            tags.insert(
                crate::proxy::mesh_mtls_pool::MESH_MTLS_DIAL_HOST_TAG.to_string(),
                gateway.host.clone(),
            );
            tags.insert(
                crate::proxy::mesh_mtls_pool::MESH_MTLS_PORT_TAG.to_string(),
                gateway.port.to_string(),
            );
            tags.insert(
                crate::proxy::mesh_mtls_pool::MESH_MTLS_AUTHORITY_HOST_TAG.to_string(),
                address.clone(),
            );
            tags.insert(
                crate::proxy::mesh_mtls_pool::MESH_EASTWEST_SNI_TAG.to_string(),
                dial_sni.clone(),
            );
            tags.insert(
                crate::proxy::mesh_mtls_pool::MESH_CROSS_CLUSTER_TAG.to_string(),
                "true".to_string(),
            );
            let synthetic_host = format!(
                "mesh-xc-l4-{}|{}|{}|{}|{}",
                gateway.host,
                gateway.port,
                workload.trust_domain.as_str(),
                dial_sni,
                address
            );
            built.push(BuiltTarget {
                target: UpstreamTarget {
                    host: synthetic_host,
                    port: app_port,
                    service_port_policy_key: Some(service_port.port),
                    weight: 1,
                    tags,
                    locality: workload.locality.clone(),
                    path: None,
                },
                dial_endpoint: (gateway.host.clone(), gateway.port),
                trust_domain: workload.trust_domain.as_str().to_string(),
            });
        }
    }

    let mut trust_domains_by_endpoint: std::collections::HashMap<
        (String, u16),
        std::collections::HashSet<String>,
    > = std::collections::HashMap::new();
    for item in &built {
        trust_domains_by_endpoint
            .entry(item.dial_endpoint.clone())
            .or_default()
            .insert(item.trust_domain.clone());
    }
    for item in built {
        if trust_domains_by_endpoint
            .get(&item.dial_endpoint)
            .is_some_and(|domains| domains.len() > 1)
        {
            warn!(
                service = %service.name,
                gateway_host = %item.dial_endpoint.0,
                gateway_port = item.dial_endpoint.1,
                "Skipping ambiguous cross-cluster Sidecar L4 target: one gateway endpoint serves multiple trust domains"
            );
            continue;
        }
        targets.push(item.target);
    }
}

/// Build the SCOPED SYNTHETIC `UpstreamTarget.host` for an AMBIENT cross-cluster
/// HBONE target, keyed by `(east-west gateway dial endpoint, real pod addr)`. It
/// is an OPAQUE identity for every host:port-keyed runtime map (load balancer,
/// passive+active health, circuit breaker, retry-exclusion, adaptive
/// concurrency) so two remote pods that share a pod IP across overlapping CIDRs
/// but are reached through DIFFERENT gateways never collapse to one key. It is
/// NEVER dialed or DNS-resolved (the transport dials `mesh.hbone_dial_host`; the
/// real CONNECT `:authority` rides `mesh.hbone_authority_host`). The `mesh-xc-`
/// prefix guarantees it cannot be mistaken for a real hostname and never starts
/// with `*.` (so `concretize_wildcard_target_for_request` leaves it untouched).
fn cross_cluster_hbone_synthetic_host(
    gateway_host: &str,
    gateway_port: u16,
    pod_addr: &str,
) -> String {
    format!(
        "{}{gateway_host}|{gateway_port}|{pod_addr}",
        crate::proxy::hbone_pool::HBONE_CROSS_CLUSTER_SYNTHETIC_HOST_PREFIX
    )
}

/// Append AMBIENT (HBONE) cross-cluster east-west targets for `service` on
/// `service_port` — the HBONE counterpart of
/// [`append_cross_cluster_mesh_targets`] (which does the Sidecar mesh-mTLS
/// shape). The two differ in SHAPE because the inner protocol does (see the
/// `build_outbound_mesh_targets` call site):
///
/// - Sidecar: inner = mesh-mTLS-HTTP, the dest sidecar routes by `Host` →
///   loopback, so ONE target per `(network, trust_domain)` at the GATEWAY
///   endpoint.
/// - Ambient: inner = HBONE CONNECT, the dest relay
///   (`build_inbound_hbone_relay_proxy`) dials the CONNECT `:authority` under the
///   OPEN-RELAY GUARD (`inbound_hbone_relay_destination_allowed`) — the authority
///   must be loopback OR a slice-declared workload addr+port; a service FQDN is
///   REJECTED. The remote pod IP IS slice-declared on the dest side AND known to
///   the client (merged remote endpoints). So Ambient cross-cluster targets are
///   PER-REMOTE-POD, with the east-west gateway carried as a DIAL OVERRIDE.
///
/// IDENTITY (overlapping-CIDR collision avoidance): `UpstreamTarget.host` is a
/// SCOPED SYNTHETIC identity keyed by `(gateway dial endpoint, real pod addr)`
/// (`cross_cluster_hbone_synthetic_host`), NOT the bare pod addr — two remote
/// pods that share an IP across overlapping CIDRs but are reached through
/// DIFFERENT gateways would otherwise collapse to one `(host, port)` key and
/// cross-contaminate every host:port-keyed runtime map (LB / health / circuit
/// breaker / retry / adaptive concurrency). The REAL pod addr (the inner CONNECT
/// `:authority` the dest relay dials under the open-relay guard) rides
/// `mesh.hbone_authority_host`, which dispatch reads for `app_host`; the
/// synthetic host is never dialed/resolved.
///
/// Each surviving reachable remote workload's gateway is selected per the
/// workload's own `(network, trust_domain)` (the SAME
/// [`select_east_west_gateway_for_network`] +
/// [`east_west_workload_is_reachable`] reuse as the Sidecar path). One target is
/// emitted per pod ADDRESS with:
/// - `host` = the scoped synthetic identity; `port` = resolved app-port;
/// - `mesh.hbone_authority_host` = the real pod addr (inner CONNECT `:authority`);
/// - `mesh.hbone = "true"` (Ambient transport);
/// - `mesh.hbone_dial_host` = `gateway.host` (the network dial host);
/// - `mesh.hbone_port` = `gateway.port` (the DIAL port, e.g. `:15443`);
/// - `mesh.eastwest_sni` = the destination service FQDN (outer-TLS SNI override);
/// - `mesh.trust_domain` = the remote TD (trust-domain-only verification);
/// - `mesh.cross_cluster = "true"`; `mesh.remote = "true"`;
/// - NO `mesh.spiffe_id` (the gateway LB-picks the destination, so no pod pin).
///
/// FAIL-CLOSED collision rule (cross-TD ambiguity on a shared GATEWAY DIAL
/// ENDPOINT): each pod target dials `(gateway.host, gateway.port, sni)` (= the
/// outer TLS endpoint the SNI-passthrough gateway terminates). If a SINGLE dial
/// endpoint serves MULTIPLE trust domains (e.g. a TD-less wildcard gateway
/// fronting pods that span two trust domains), the client cannot present a
/// coherent trust-domain-scoped verification for that one endpoint — so EVERY
/// pod target on that ambiguous dial endpoint is DROPPED (the operator must
/// declare a distinct gateway endpoint per trust domain), mirroring
/// [`append_cross_cluster_mesh_targets`]'s `[R3-3]` rule. Unlike the Sidecar
/// path there is NO same-endpoint COLLAPSE: each pod is a distinct backend
/// identity (the scoped synthetic host above), so same-TD pods sharing a dial
/// endpoint are all legitimately emitted (the gateway routes each by the pinned
/// CONNECT authority carried in `mesh.hbone_authority_host`).
///
/// DESTINATION-SIDE FORWARDING (why the dest east-west gateway forwards to the
/// app port, not `:15008`): the remote cluster's east-west gateway is a SNI
/// passthrough that forwards the opaque outer TLS to the destination workload's
/// APP PORT (`build_east_west_service_targets` resolves the first service port's
/// `targetPort` / container port, NOT a mesh terminator port). The destination
/// pod's INBOUND CAPTURE then redirects that app-port traffic to the mesh
/// terminator — iptables REDIRECT app-port → `:15008` for Ambient (an HBONE
/// CONNECT relayed by `handle_hbone_request` under the open-relay guard),
/// `:15006` for Sidecar. This is the SAME capture-based model same-cluster
/// east-west *inbound* uses, and it is exactly how the merged #1897 Sidecar
/// cross-cluster path works too (its `build_east_west_service_targets` also
/// forwards to the app/target port and relies on the dest capture → `:15006`).
/// So this is a CONSISTENT, pre-existing architecture, not an Ambient-specific
/// gap: NO destination-side change is needed for cross-cluster, and there is no
/// gateway-side analog the Sidecar path lacks. The functional fixture models the
/// captured hop by setting the destination service port to the terminator port
/// (the dest gateway forwards straight to `:15008`); the live two-cluster SPIRE
/// fixture validates the real captured path. See `docs/mesh.md`
/// ("Destination inbound relies on the standard inbound capture").
fn append_cross_cluster_ambient_hbone_targets(
    targets: &mut Vec<UpstreamTarget>,
    runtime: &MeshRuntimeConfig,
    service: &crate::modes::mesh::config::MeshService,
    service_port: &crate::modes::mesh::config::ServicePort,
    protocol: AppProtocol,
    workloads: &[crate::modes::mesh::config::Workload],
    multi_cluster: Option<&crate::modes::mesh::config::MultiClusterConfig>,
) {
    let Some(multi_cluster) = multi_cluster else {
        return;
    };

    let all_remote_workloads =
        matched_remote_service_workloads(service, workloads, Some(multi_cluster));
    append_cross_cluster_ambient_hbone_targets_prematched(
        targets,
        &runtime.cluster_domain,
        service,
        service_port,
        protocol,
        &all_remote_workloads,
        multi_cluster,
    );
}

/// The pre-matched entry point of the Ambient/HBONE cross-cluster shared core
/// (see [`append_cross_cluster_ambient_hbone_targets`], which documents the
/// emitted target shape). `remote_workloads` must already be matched to
/// `service` under the caller's matching semantics and classified remote
/// against the same `multi_cluster`. The mesh-mode materializer calls the
/// ref-based wrapper above; the gateway mesh-SD bridge calls this directly so
/// it can preserve its service-name fallback matching while sharing the same
/// reachability, gateway-selection, and collision rules.
pub(crate) fn append_cross_cluster_ambient_hbone_targets_prematched(
    targets: &mut Vec<UpstreamTarget>,
    cluster_domain: &str,
    service: &crate::modes::mesh::config::MeshService,
    service_port: &crate::modes::mesh::config::ServicePort,
    protocol: AppProtocol,
    remote_workloads: &[&crate::modes::mesh::config::Workload],
    multi_cluster: &crate::modes::mesh::config::MultiClusterConfig,
) {
    // Every supported service port gets per-remote-pod cross-cluster targets.
    // The client SELECTS the gateway by the base FQDN or the exact dialed alias
    // (`east_west_acceptable_snis`) but DIALS the per-port SNI
    // (`cross_cluster_service_sni`); the inner HBONE CONNECT
    // `:authority` already carries the per-port app port (`resolve_app_port`
    // below, which honors `service_port.target_port`). Raw-TCP/UDP ports always
    // get the explicit `p<port>` alias from `cross_cluster_service_sni`.
    if remote_workloads.is_empty() {
        return;
    }

    // [R2-2] REACHABILITY FILTER: keep only remote workloads the destination
    // cluster's east-west materializer could itself back (≥1 address + resolvable
    // targetPort for THIS service port), mirroring `build_east_west_service_targets`
    // — a workload the destination would drop must not produce a dead path here.
    let remote_workloads: Vec<_> = remote_workloads
        .iter()
        .copied()
        .filter(|workload| east_west_workload_is_reachable(service_port, workload))
        .collect();
    if remote_workloads.is_empty() {
        warn!(
            service = %service.name,
            namespace = %service.namespace,
            service_port = service_port.port,
            "Skipping Ambient cross-cluster egress: no reachable remote workload (every remote \
             endpoint lacks an address or has an unresolved targetPort for this port)"
        );
        return;
    }

    // DIAL the per-port SNI alias (`mesh.eastwest_sni`); SELECT a gateway that
    // claims EITHER the base service FQDN OR the exact per-port alias being dialed
    // (codex #2040 Finding C). Both derive from `cross_cluster_service_{base_fqdn,
    // sni}` so client + gateway cannot drift.
    let base_fqdn = cross_cluster_service_base_fqdn(service, cluster_domain);
    let dial_sni = cross_cluster_service_sni(service, service_port, cluster_domain);
    let acceptable_snis = east_west_acceptable_snis(&base_fqdn, &dial_sni);

    // The app (container) port the inner CONNECT `:authority` carries. Same
    // fail-closed targetPort rule as the local pass: a DECLARED `targetPort` must
    // resolve (skip the workload otherwise — never fall back to the service
    // port); an ABSENT one uses the service port.
    let resolve_app_port = |workload: &crate::modes::mesh::config::Workload| -> Option<u16> {
        match service_port.target_port.as_ref() {
            Some(_) => {
                match resolve_target_port(service_port.target_port.as_ref(), &workload.ports) {
                    Some(p) if p != 0 => Some(p),
                    _ => None,
                }
            }
            None if service_port.port != 0 => Some(service_port.port),
            None => None,
        }
    };

    // Build each pod's target into a local list first, tagging it with the
    // selected gateway DIAL ENDPOINT so cross-trust-domain ambiguity on a shared
    // endpoint can fail closed before any target reaches the LB.
    struct BuiltHboneTarget {
        target: UpstreamTarget,
        dial_endpoint: (String, u16),
        trust_domain: String,
    }
    let mut built: Vec<BuiltHboneTarget> = Vec::new();
    for workload in &remote_workloads {
        let Some(gateway) = select_east_west_gateway_for_network(
            multi_cluster,
            workload.network.as_deref(),
            &acceptable_snis,
            &workload.trust_domain,
        ) else {
            warn!(
                service = %service.name,
                namespace = %service.namespace,
                network = workload.network.as_deref().unwrap_or("<none>"),
                trust_domain = %workload.trust_domain.as_str(),
                service_fqdn = %base_fqdn,
                dial_sni = %dial_sni,
                "Skipping Ambient cross-cluster egress for a remote workload: no EastWestGateway on \
                 its network whose sni_hosts claim the destination service FQDN OR the per-port \
                 alias being dialed AND whose trust domain matches (fail closed; never broaden to a \
                 different-network catch-all or a mismatched-trust-domain gateway)"
            );
            continue;
        };
        if gateway.host.is_empty() || gateway.port == 0 {
            warn!(
                service = %service.name,
                namespace = %service.namespace,
                gateway = %gateway.name,
                "Skipping Ambient cross-cluster egress: EastWestGateway has no usable host:port"
            );
            continue;
        }
        let Some(app_port) = resolve_app_port(workload) else {
            // Defensive: the reachability filter already proved the first port
            // resolves, so this is unreachable, but never emit a `:0` authority.
            continue;
        };

        for address in &workload.addresses {
            // Start from the standard Ambient HBONE tag core (destination
            // identity + service metadata), then override for the cross-cluster
            // posture: drop the pinned pod identity, set the remote trust domain,
            // the gateway dial host/port, the SNI override, and the markers.
            let mut tags = crate::service_discovery::mesh::mesh_hbone_target_tags(
                service,
                workload,
                protocol,
                service_port.name.as_deref(),
            );
            // No pod pinning across the SNI-passthrough gateway: remove the
            // pinned SPIFFE id so dispatch uses trust-domain-SCOPED verification.
            tags.remove(crate::proxy::hbone_pool::MESH_SPIFFE_ID_TAG);
            // The trust_domain tag is already the workload's trust domain (set by
            // the tag core), which is what dispatch scopes verification to.
            // Remote provenance for strict local-first locality LB.
            tags.insert(
                crate::modes::mesh::multicluster::MESH_REMOTE_TAG.to_string(),
                crate::modes::mesh::multicluster::MESH_REMOTE_TAG_VALUE.to_string(),
            );
            // The DIAL host is the east-west gateway (≠ target.host = pod IP).
            tags.insert(
                crate::proxy::hbone_pool::HBONE_DIAL_HOST_TAG.to_string(),
                gateway.host.clone(),
            );
            // The DIAL port is the gateway port (e.g. :15443), NOT :15008.
            tags.insert(
                crate::proxy::hbone_pool::HBONE_PORT_TAG.to_string(),
                gateway.port.to_string(),
            );
            // Outer-TLS SNI override = the bare destination service FQDN for a
            // single-HTTP-port service, or the `p<port>.<fqdn>` alias for every
            // port of a multi-port service (multi-port east-west, issue #2010
            // phase 3).
            tags.insert(
                crate::proxy::mesh_mtls_pool::MESH_EASTWEST_SNI_TAG.to_string(),
                dial_sni.clone(),
            );
            tags.insert(
                crate::proxy::mesh_mtls_pool::MESH_CROSS_CLUSTER_TAG.to_string(),
                "true".to_string(),
            );
            // The REAL pod addr is the inner HBONE CONNECT `:authority` HOST the
            // dest relay dials under the open-relay guard. It rides this tag
            // because `target.host` is set to a SCOPED SYNTHETIC identity below.
            tags.insert(
                crate::proxy::hbone_pool::HBONE_AUTHORITY_HOST_TAG.to_string(),
                address.clone(),
            );

            built.push(BuiltHboneTarget {
                target: UpstreamTarget {
                    // IDENTITY = a SCOPED SYNTHETIC host keyed by `(gateway dial
                    // endpoint, real pod addr)`, NOT the bare pod addr. Two REMOTE
                    // pods that share a pod IP across overlapping CIDRs but are
                    // reached through DIFFERENT east-west gateways would otherwise
                    // collapse to one `(host, port)` and cross-contaminate every
                    // host:port-keyed runtime map — load balancer least-conn /
                    // hash ring, passive+active health, circuit breaker
                    // (`circuit_breaker::target_key`), retry-exclusion,
                    // adaptive-concurrency. The synthetic host disambiguates them
                    // while the REAL pod addr (the inner CONNECT `:authority`)
                    // rides `mesh.hbone_authority_host` (read by dispatch for
                    // `app_host`). The transport NEVER dials this synthetic host:
                    // it dials `mesh.hbone_dial_host` / `mesh.hbone_port` (the
                    // gateway), and the only consumer that resolves `target.host`
                    // (the observability `dns_cache.resolve`) just yields `None`.
                    // The HBONE pool key is keyed on the gateway dial host + SNI +
                    // trust domain (already isolated per gateway), so this does not
                    // affect connection reuse. Pin matched by the synthetic-host
                    // unit test; do NOT collapse it back to the pod addr.
                    host: cross_cluster_hbone_synthetic_host(&gateway.host, gateway.port, address),
                    port: app_port,
                    // DR policy stays keyed by the declared SERVICE port.
                    service_port_policy_key: Some(service_port.port),
                    weight: 1,
                    tags,
                    // Remote-tier locality so locality-LB ranks this AFTER locals.
                    locality: workload.locality.clone(),
                    path: None,
                },
                dial_endpoint: (gateway.host.clone(), gateway.port),
                trust_domain: workload.trust_domain.as_str().to_string(),
            });
        }
    }

    // [R3-3] FAIL CLOSED on a cross-trust-domain shared GATEWAY DIAL ENDPOINT:
    // the outer TLS terminates at `(gateway.host, gateway.port)` (the SNI is the
    // one service FQDN), so if MULTIPLE trust domains' pods resolve to the SAME
    // dial endpoint (a TD-less wildcard gateway fronting a network whose pods
    // span trust domains), the client cannot pin a coherent trust domain for that
    // endpoint's outer handshake — DROP every pod target on that ambiguous
    // endpoint. (Same-TD pods sharing an endpoint are fine: each is a distinct
    // pinned CONNECT authority; there is NO same-endpoint collapse here, unlike
    // the per-gateway Sidecar shape.)
    let mut tds_by_dial_endpoint: std::collections::HashMap<
        (String, u16),
        std::collections::HashSet<String>,
    > = std::collections::HashMap::new();
    for entry in &built {
        tds_by_dial_endpoint
            .entry(entry.dial_endpoint.clone())
            .or_default()
            .insert(entry.trust_domain.clone());
    }
    for entry in built {
        if tds_by_dial_endpoint
            .get(&entry.dial_endpoint)
            .map(std::collections::HashSet::len)
            .unwrap_or(0)
            > 1
        {
            warn!(
                service = %service.name,
                namespace = %service.namespace,
                gateway_host = %entry.dial_endpoint.0,
                gateway_port = entry.dial_endpoint.1,
                "Skipping Ambient cross-cluster egress target: multiple trust domains resolve to \
                 the same east-west gateway dial endpoint (fail closed; an SNI-passthrough gateway \
                 terminates one outer TLS identity, so a shared endpoint cannot pin a trust domain \
                 — declare a distinct gateway endpoint per trust domain)"
            );
            continue;
        }
        targets.push(entry.target);
    }
}

/// Whether a REMOTE workload of `service` would yield a materializable east-west
/// backend on the DESTINATION cluster — i.e. whether
/// [`build_east_west_service_targets`] would emit a target for it rather than
/// skip it. MIRRORS that function's per-workload skip conditions so a workload
/// the destination would drop never produces a dead cross-cluster gateway path
/// (codex r2 [R2-2]):
/// - the workload must have ≥1 address (no pod IP ⇒ skipped there); AND
/// - the given `service_port` (multi-port east-west, issue #2010 phase 3 — each
///   HTTP-family port materializes its own gateway proxy on a per-port SNI alias)
///   must resolve to a usable backend port: a DECLARED `target_port` must
///   `resolve_target_port` to a non-zero port (an unresolved named targetPort ⇒
///   skipped there); an ABSENT `target_port` uses the service port.
fn east_west_workload_is_reachable(
    service_port: &crate::modes::mesh::config::ServicePort,
    workload: &crate::modes::mesh::config::Workload,
) -> bool {
    if workload.addresses.is_empty() {
        return false;
    }
    match service_port.target_port.as_ref() {
        Some(_) => matches!(
            resolve_target_port(service_port.target_port.as_ref(), &workload.ports),
            Some(p) if p != 0
        ),
        // Absent targetPort falls back to the service port — always usable.
        None => true,
    }
}

/// The SNIs a client will ACCEPT an east-west gateway for: the base service FQDN
/// plus the per-port alias actually being dialed (`dial_sni`), deduplicated.
/// `dial_sni == base_fqdn` for a single-port service, so the result collapses to
/// a single entry there. A gateway that claims the base FQDN automatically owns
/// the service's per-port aliases (its passthrough materializes them); a gateway
/// that lists ONLY the per-port alias is also acceptable for that port (codex
/// #2040 Finding C). Returned as a small stack `Vec<&str>` borrowing the two
/// inputs — no allocation of the SNI strings themselves.
pub(crate) fn east_west_acceptable_snis<'a>(base_fqdn: &'a str, dial_sni: &'a str) -> Vec<&'a str> {
    if dial_sni == base_fqdn {
        vec![base_fqdn]
    } else {
        vec![base_fqdn, dial_sni]
    }
}

/// Select the [`EastWestGateway`](crate::modes::mesh::config::EastWestGateway)
/// that fronts `network`, claims one of the ACCEPTABLE destination SNIs in its
/// `sni_hosts`, AND matches `expected_trust_domain`.
///
/// The gateway forwards the (opaque) outer TLS purely by ClientHello SNI, so a
/// gateway that does not OWN the destination host would blackhole the request;
/// and a mesh federating MULTIPLE remote trust domains must not route a
/// destination's SNI through a gateway fronting a DIFFERENT domain. A gateway is
/// a CANDIDATE iff ALL hold:
/// 1. **network** — `gateway.network.as_deref() == network` (EXACT); see the
///    catch-all rule below;
/// 2. **SNI** — `gateway.sni_hosts` overlaps ANY of `acceptable_snis` (the base
///    service FQDN OR the per-port alias being dialed, codex #2040 Finding C),
///    using the SAME wildcard-aware
///    [`hosts_overlap`](crate::config::types::hosts_overlap) semantics east-west
///    materialization uses (an EMPTY `sni_hosts` is a wildcard/any-host gateway
///    and matches everything); AND
/// 3. **trust domain** (codex r2 [R2-3]) — `gateway.trust_domain.is_none()`
///    (a TD-less gateway is a wildcard) OR
///    `gateway.trust_domain == Some(expected_trust_domain)`.
///
/// Selection precedence is FAIL-CLOSED — it NEVER broadens on a miss:
/// 1. Among gateways whose `gateway.network == network` (exact), return the
///    first candidate.
/// 2. **Catch-all** (`gateway.network == None`, codex r2 [R2-1]): considered
///    ONLY when there is NO EastWestGateway entry for the requested `network` at
///    all. If the network HAS gateways but none are candidates, return `None`
///    (do NOT fall through to a different-network catch-all). When the catch-all
///    branch applies, the catch-all gateway must ALSO be a candidate (SNI + TD).
/// 3. Else `None`.
///
/// (When `network` is itself `None`, the requested network IS the catch-all:
/// step 1 already matches `gateway.network == None` candidates, and the
/// "network has no gateway" guard for step 2 is never satisfied, so the two
/// steps coincide.)
///
/// Returns `None` (the caller then SKIPS + warns, fail-closed) when no candidate
/// is selected by this precedence.
fn select_east_west_gateway_for_network<'a>(
    multi_cluster: &'a crate::modes::mesh::config::MultiClusterConfig,
    network: Option<&str>,
    acceptable_snis: &[&str],
    expected_trust_domain: &crate::identity::spiffe::TrustDomain,
) -> Option<&'a crate::modes::mesh::config::EastWestGateway> {
    // An EMPTY `sni_hosts` is a wildcard (matches any host); a non-empty list
    // must overlap one of the ACCEPTABLE destination SNIs. A gateway is a
    // candidate if it claims EITHER the base service FQDN (whose ownership
    // automatically extends to the service's per-port aliases) OR the exact
    // per-port alias SNI being dialed (codex #2040 Finding C) — an operator may
    // list just the alias for a single port. `hosts_overlap` already treats an
    // empty side as a catch-all, so passing `gateway.sni_hosts` (possibly empty)
    // against the single-FQDN slice yields exactly this semantics per SNI.
    let is_candidate = |gateway: &crate::modes::mesh::config::EastWestGateway| {
        acceptable_snis.iter().any(|sni| {
            let fqdn = [sni.to_string()];
            crate::config::types::hosts_overlap(&gateway.sni_hosts, &fqdn)
        })
            // [R2-3] trust domain: a TD-less gateway is a wildcard; a TD-bearing
            // one must match the remote workloads' trust domain.
            && gateway
                .trust_domain
                .as_ref()
                .is_none_or(|td| td == expected_trust_domain)
    };

    // Exact network match first — the first gateway on this network that is a
    // candidate (claims the host AND matches the trust domain).
    if let Some(exact) = multi_cluster
        .east_west_gateways
        .iter()
        .find(|gateway| gateway.network.as_deref() == network && is_candidate(gateway))
    {
        return Some(exact);
    }
    // [R2-1] Catch-all (`network: None`) is considered ONLY when the requested
    // network has NO EastWestGateway entry AT ALL. If the network HAS gateways
    // but none are candidates (SNI/TD miss), FAIL CLOSED here — do NOT fall
    // through to a `None`-network catch-all fronting a DIFFERENT network.
    let network_has_gateway = multi_cluster
        .east_west_gateways
        .iter()
        .any(|gateway| gateway.network.as_deref() == network);
    if network_has_gateway {
        return None;
    }
    multi_cluster
        .east_west_gateways
        .iter()
        .find(|gateway| gateway.network.is_none() && is_candidate(gateway))
}

/// Whether an east-west gateway declaration makes cross-cluster routing
/// AUTHORITATIVE for `network` — i.e. the gateway-routed shape must be
/// attempted and mismatches must fail closed rather than bypass the gateway
/// with a direct pod dial. True when EITHER holds:
///
/// 1. For a NAMED network, ANY gateway declared with `gateway.network == network`
///    (exact) is authoritative even when it is NOT a candidate
///    (SNI/trust-domain miss): the operator declared how this network is
///    reached, so a non-routable destination fails closed instead of
///    re-enabling a direct dial. `network == None` is not a named exact network;
///    `network: None` gateways are catch-alls and are authoritative only when
///    the selector accepts them as candidates; or
/// 2. [`select_east_west_gateway_for_network`] selects a gateway — which, when
///    the network has no exact declaration, is an APPLICABLE catch-all
///    (`network: None` AND an SNI/trust-domain candidate). A NON-candidate
///    catch-all is NOT authoritative: it could never route this destination,
///    so it does not suppress the flat-network direct fallback.
///
/// The gateway mesh-SD bridge uses the NEGATION of this as the Ambient
/// direct-pod flat-network fallback valve (issue #2011,
/// `service_discovery::mesh`); keeping the predicate next to the selector
/// guarantees the fallback rule and the selection precedence can never drift.
pub(crate) fn east_west_gateway_governs_network(
    multi_cluster: &crate::modes::mesh::config::MultiClusterConfig,
    network: Option<&str>,
    acceptable_snis: &[&str],
    expected_trust_domain: &crate::identity::spiffe::TrustDomain,
) -> bool {
    let selected_gateway = select_east_west_gateway_for_network(
        multi_cluster,
        network,
        acceptable_snis,
        expected_trust_domain,
    );
    let exact_named_network_declared = network.is_some()
        && multi_cluster
            .east_west_gateways
            .iter()
            .any(|gateway| gateway.network.as_deref() == network);

    selected_gateway.is_some() || exact_named_network_declared
}

/// An HTTP-family `/` proxy on the outbound capture listener whose `HttpPool`
/// dispatch (from `backend_scheme: Http`) lights up the topology's mesh
/// transport for any `mesh.hbone=true` / `mesh.mtls=true` upstream target. No
/// backend host/port of its own — it dispatches through `upstream_id`.
/// `retry: None` (the streamed request body is not replayable).
/// `preserve_host_header` so the destination sees its own service Host /
/// `:authority`, not a rewritten one.
fn mesh_outbound_route_proxy(
    id: &str,
    hosts: Vec<String>,
    namespace: &str,
    upstream_id: &str,
    now: chrono::DateTime<chrono::Utc>,
) -> Proxy {
    Proxy {
        id: id.to_string(),
        name: Some(format!("mesh outbound {id}")),
        namespace: namespace.to_string(),
        hosts,
        listen_path: Some("/".to_string()),
        backend_scheme: Some(BackendScheme::Http),
        dispatch_kind: Default::default(),
        backend_host: String::new(),
        backend_port: 0,
        backend_path: None,
        strip_listen_path: false,
        preserve_host_header: true,
        backend_connect_timeout_ms: 5_000,
        backend_read_timeout_ms: 30_000,
        backend_write_timeout_ms: 30_000,
        backend_tls_client_cert_path: None,
        backend_tls_client_key_path: None,
        backend_tls_verify_server_cert: false,
        backend_tls_server_ca_cert_path: None,
        resolved_tls: BackendTlsConfig::default(),
        dispatch_port_overrides: None,
        dispatch_port_override_fallback: None,
        dns_override: None,
        dns_cache_ttl_seconds: None,
        auth_mode: Default::default(),
        plugins: Vec::<PluginAssociation>::new(),
        pool_idle_timeout_seconds: None,
        pool_enable_http_keep_alive: None,
        pool_enable_http2: None,
        pool_tcp_keepalive_seconds: None,
        pool_http2_keep_alive_interval_seconds: None,
        pool_http2_keep_alive_timeout_seconds: None,
        pool_http2_initial_stream_window_size: None,
        pool_http2_initial_connection_window_size: None,
        pool_http2_adaptive_window: None,
        pool_http2_max_frame_size: None,
        pool_http2_max_concurrent_streams: None,
        pool_http3_connections_per_backend: None,
        h2_upgrade_policy: None,
        pool_max_requests_per_connection: None,
        // Derived-only: projected from DestinationRule port overrides at
        // dispatch time via `resolve_effective_proxy_for_target`; a
        // freshly-materialized mesh proxy starts at `None`.
        pool_http1_max_pending_requests: None,
        upstream_id: Some(upstream_id.to_string()),
        upstream_subset: None,
        api_spec_id: None,
        circuit_breaker: None,
        retry: None,
        response_body_mode: ResponseBodyMode::Stream,
        listen_port: None,
        frontend_tls: false,
        passthrough: false,
        udp_idle_timeout_seconds: 60,
        udp_max_response_amplification_factor: None,
        stream_proxy_protocol: None,
        tcp_idle_timeout_seconds: Some(300),
        websocket_idle_timeout_seconds: None,
        allowed_methods: None,
        allowed_ws_origins: Vec::new(),
        created_at: now,
        updated_at: now,
    }
}

fn mesh_outbound_http_bywl_route_proxy(
    spec: &MeshHttpBywlUpstreamSpec<'_>,
    now: chrono::DateTime<chrono::Utc>,
) -> Proxy {
    let mut proxy = mesh_outbound_route_proxy(
        &spec.proxy_id,
        vec![mesh_outbound_http_bywl_hidden_host(
            &spec.service.namespace,
            &spec.service.name,
            spec.service_port.port,
            spec.canonical_ip,
        )],
        &spec.service.namespace,
        &spec.upstream_id,
        now,
    );
    // Direct Pod-IP HTTP selects its workload strictly by SO_ORIGINAL_DST before
    // Host routing. Preserve the application Host after that selection so the
    // backend does not see a synthetic pod-IP authority.
    proxy.preserve_host_header = true;
    proxy
}

/// The upstream backing a materialized outbound egress proxy: the service's
/// transport-tagged workload targets with passive health and round-robin LB.
/// Mirrors the east-west service upstream. Top-level DR traffic policy applies
/// (the upstream is FQDN-named so DestinationRules match it), and the
/// `portLevelSettings` entry authored on this upstream's owning Service port
/// is stored by `apply_destination_rules` under that declared Service port
/// when the targets carry `service_port_policy_key`. The targets still dial
/// the per-workload resolved `targetPort` (numeric or **named**, which can
/// resolve differently across workloads); dispatch maps each selected target
/// back to its owning Service port before reading the override.
fn mesh_outbound_route_upstream(
    upstream_id: &str,
    namespace: &str,
    service_fqdn: &str,
    targets: Vec<UpstreamTarget>,
    now: chrono::DateTime<chrono::Utc>,
) -> Upstream {
    Upstream {
        id: upstream_id.to_string(),
        // DR-matchable service host (see the materializer call site).
        name: Some(service_fqdn.to_string()),
        namespace: namespace.to_string(),
        targets,
        algorithm: LoadBalancerAlgorithm::RoundRobin,
        hash_on: None,
        hash_on_cookie_config: None,
        health_checks: Some(HealthCheckConfig {
            active: None,
            passive: Some(PassiveHealthCheck::default()),
        }),
        service_discovery: None,
        subsets: None,
        port_overrides: HashMap::new(),
        source_locality: None,
        locality_lb_strict: false,
        locality_lb_setting: None,
        backend_tls_client_cert_path: None,
        backend_tls_client_key_path: None,
        backend_tls_verify_server_cert: true,
        backend_tls_server_ca_cert_path: None,
        backend_tls_sni: None,
        backend_tls_san_allow_list: Vec::new(),
        resolved_subset_tls: HashMap::new(),
        dispatch_port_override_fallback: None,
        api_spec_id: None,
        created_at: now,
        updated_at: now,
    }
}

// ── DestinationRule application ────────────────────────────────────────

/// Return the Service port a mesh-SD upstream will select when discovery runs.
/// This mirrors `MeshServiceDiscoverer::selected_service_port` for apply-time
/// policy projection before the dynamic targets exist.
fn mesh_sd_selected_service_port(upstream: &Upstream, mesh_slice: &MeshSlice) -> Option<u16> {
    let mesh = upstream.service_discovery.as_ref()?.mesh.as_ref()?;
    if let Some(port) = mesh.port {
        return Some(port);
    }

    let namespace = mesh.namespace.as_deref().unwrap_or(&upstream.namespace);
    mesh_slice
        .services
        .iter()
        .find(|svc| svc.name == mesh.service_name && svc.namespace == namespace)
        .and_then(|svc| svc.ports.first())
        .map(|port| port.port)
}

/// Apply DestinationRule traffic policies onto matching upstreams.
///
/// For each DestinationRule, we find upstreams whose targets match the DR
/// host and apply:
/// - `connectionPool.tcp.connectTimeout` onto proxies referencing the upstream
/// - `outlierDetection` onto the upstream's passive health check
/// - `loadBalancer` onto the upstream's algorithm
/// - `subsets` as `SubsetDefinition` entries on the upstream
///
/// Multiple DRs targeting the same upstream are applied in a deterministic
/// order — sorted by `(namespace, name)` — so the last-writer-wins outcome
/// is reproducible across CP restarts and DP subscribers.
/// Synthesize per-route `cors` plugin instances onto materialized sidecar
/// OUTBOUND routes from the slice's VirtualService-derived CORS policies
/// (issue #1973). Istio applies VirtualService policy on the client sidecar,
/// so the policy attaches to the egress routes; application is HOST-LEVEL
/// (materialized routes are host-routed `/`). Policy hosts resolve against
/// each service's FQDN with DestinationRule host semantics
/// (`destination_rule_host_matches`: bare name, `name.namespace`, FQDN).
///
/// Determinism + conflict handling mirror `apply_destination_rules`: policies
/// are sorted by `(namespace, name)` and the FIRST match per service wins
/// (additional matches warn — Istio would merge VS routes; host-level mesh
/// application takes one policy per host). Runs AFTER outbound
/// materialization (the proxy ids must exist for `validate_plugin_references`)
/// and touches only `__mesh-outbound-*` proxies plus its own reserved
/// `__mesh-cors-*` plugin ids — operator plugin configs are never modified.
fn synthesize_mesh_outbound_cors_plugins(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) {
    // Client-SIDECAR scope only (the GA row and docs promise exactly that):
    // Ambient/waypoint topologies also materialize `__mesh-outbound-*` routes,
    // but VS policy application for them is a waypoint concern — do not hand
    // sidecar-style CORS behavior to sidecarless clients.
    if runtime.topology != MeshTopology::Sidecar {
        return;
    }
    if mesh_slice.virtual_service_cors_policies.is_empty() {
        return;
    }
    // Normalize the host MATCH KEY here, not just in `MeshConfig::normalize()`:
    // a slice arriving over the native/xDS carriers never passes config-source
    // normalization on this DP, and `destination_rule_host_matches` lowercases
    // and strips trailing dots but does NOT trim whitespace — a padded carried
    // host would silently match no service and synthesize no plugin.
    let mut sorted_policies: Vec<(String, &config::MeshVirtualServiceCorsPolicy)> = mesh_slice
        .virtual_service_cors_policies
        .iter()
        .map(|policy| (config::normalize_mesh_hostname_like(&policy.host), policy))
        .collect();
    sorted_policies.sort_by(|a, b| (&a.1.namespace, &a.1.name).cmp(&(&b.1.namespace, &b.1.name)));
    let cluster_domain = runtime.cluster_domain.trim_matches('.');

    let mut synthesized: Vec<PluginConfig> = Vec::new();
    for service in &mesh_slice.services {
        let service_fqdn = format!(
            "{}.{}.svc.{}",
            service.name, service.namespace, cluster_domain
        );
        let matching: Vec<&(String, &config::MeshVirtualServiceCorsPolicy)> = sorted_policies
            .iter()
            .filter(|(host, policy)| {
                destination_rule_host_matches(host, &policy.namespace, &service_fqdn)
            })
            .collect();
        let Some((_, policy)) = matching.first() else {
            continue;
        };
        if matching.len() > 1 {
            warn!(
                service = %service_fqdn,
                applied = %format!("{}/{}", policy.namespace, policy.name),
                total_matches = matching.len(),
                "Multiple VirtualService CORS policies target one service; applying the \
                 first by (namespace, name) — host-level mesh CORS takes one policy per host"
            );
        }
        for service_port in service_http_family_ports(service) {
            let proxy_id =
                mesh_outbound_proxy_id(&service.namespace, &service.name, service_port.port);
            let Some(proxy) = config.proxies.iter_mut().find(|proxy| proxy.id == proxy_id) else {
                // Not every declared HTTP port materializes (e.g. an
                // unresolved named targetPort skips its sibling) — nothing to
                // attach CORS to on a route that does not exist.
                continue;
            };
            // Reserved id derived from the materialized route id so it is
            // collision-free by construction and idempotent across prepares.
            let plugin_id = format!(
                "__mesh-cors-{}",
                proxy_id.trim_start_matches(MESH_OUTBOUND_PROXY_ID_PREFIX)
            );
            if proxy
                .plugins
                .iter()
                .any(|association| association.plugin_config_id == plugin_id)
            {
                continue;
            }
            proxy.plugins.push(PluginAssociation {
                plugin_config_id: plugin_id.clone(),
            });
            let now = chrono::Utc::now();
            synthesized.push(PluginConfig {
                id: plugin_id,
                plugin_name: "cors".to_string(),
                namespace: service.namespace.clone(),
                config: config::cors_plugin_config_from_mesh_policy(&policy.cors),
                scope: PluginScope::Proxy,
                proxy_id: Some(proxy_id),
                enabled: true,
                priority_override: None,
                api_spec_id: None,
                created_at: now,
                updated_at: now,
            });
        }
    }
    if !synthesized.is_empty() {
        info!(
            plugins = synthesized.len(),
            "Synthesized VirtualService CORS plugins onto materialized mesh outbound routes"
        );
        config.plugin_configs.extend(synthesized);
    }
}

fn apply_destination_rules(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) -> Result<(), anyhow::Error> {
    let mut sorted_destination_rules: Vec<&MeshDestinationRule> =
        mesh_slice.destination_rules.iter().collect();
    sorted_destination_rules.sort_by(|a, b| (&a.namespace, &a.name).cmp(&(&b.namespace, &b.name)));

    // Owning Service port per materialized per-port outbound upstream
    // (forward-derived from the slice, like `mesh_outbound_service_groups`).
    // A per-port upstream accepts `portLevelSettings` ONLY for its owning
    // Service port: its targets dial the resolved targetPort T, so the
    // generic "entry port is a target port" acceptance below would otherwise
    // let a DR entry authored for a DIFFERENT service port that numerically
    // equals T leak onto this upstream — each sibling upstream must carry
    // exactly its own port's policy.
    // The raw-TCP per-port upstreams (`__mesh-out-tcp-upstream-*`) join the
    // same map: identical owner-port semantics, distinct id space. The Ambient
    // UDP per-port upstreams (`__mesh-out-udp-upstream-*`, F3 §3.3 Stage 4) join
    // too — a `portLevelSettings` entry on a UDP Service port (e.g. `port: 53,
    // targetPort: 5353`) must map to its UDP upstream or its traffic policy is
    // silently dropped (codex r3).
    let multi_cluster = mesh_slice.multi_cluster.as_ref();
    let mut outbound_upstream_owner_port: std::collections::HashMap<String, u16> = mesh_slice
        .services
        .iter()
        .flat_map(|svc| {
            service_http_family_ports(svc)
                .into_iter()
                .map(|sp| {
                    (
                        mesh_outbound_upstream_id(&svc.namespace, &svc.name, sp.port),
                        sp.port,
                    )
                })
                .chain(service_tcp_stream_ports(svc).into_iter().map(|sp| {
                    (
                        mesh_outbound_tcp_upstream_id(&svc.namespace, &svc.name, sp.port),
                        sp.port,
                    )
                }))
                .chain(service_udp_stream_ports(svc).into_iter().map(|sp| {
                    (
                        mesh_outbound_udp_upstream_id(&svc.namespace, &svc.name, sp.port),
                        sp.port,
                    )
                }))
                .collect::<Vec<_>>()
        })
        .collect();
    // Direct-pod-IP / headless raw-TCP per-workload upstreams (F3 §3.4) join the
    // same map under their owning Service stream-family port, so a
    // `portLevelSettings` entry authored on that port fans onto them exactly like
    // the VIP per-port upstreams (same forward-derivation source).
    for spec in
        mesh_outbound_tcp_bywl_upstreams(&mesh_slice.services, &mesh_slice.workloads, multi_cluster)
    {
        outbound_upstream_owner_port.insert(spec.upstream_id, spec.service_port.port);
    }
    for spec in mesh_outbound_http_bywl_upstreams(
        &mesh_slice.services,
        &mesh_slice.workloads,
        multi_cluster,
    ) {
        outbound_upstream_owner_port.insert(spec.upstream_id, spec.service_port.port);
    }

    for dr in sorted_destination_rules {
        let matching_upstream_indices: Vec<usize> = config
            .upstreams
            .iter()
            .enumerate()
            .filter_map(|(idx, upstream)| {
                destination_rule_matches_upstream(dr, upstream).then_some(idx)
            })
            .collect();

        if matching_upstream_indices.is_empty() {
            debug!(
                host = %dr.host,
                rule = %dr.name,
                "DestinationRule has no matching upstream; skipping"
            );
            continue;
        };

        let connect_timeout_ms = dr
            .traffic_policy
            .as_ref()
            .and_then(|tp| tp.connect_timeout_ms);

        for idx in matching_upstream_indices {
            let upstream = &mut config.upstreams[idx];
            if let Some(ref policy) = dr.traffic_policy {
                apply_traffic_policy_to_upstream(upstream, policy, runtime)?;
            }

            let upstream_policy_ports: std::collections::HashSet<u16> = upstream
                .targets
                .iter()
                .map(UpstreamTarget::dispatch_policy_port)
                .collect();
            let has_service_discovery = upstream.service_discovery.is_some();
            let mesh_sd_selected_port = mesh_sd_selected_service_port(upstream, mesh_slice);

            // Top-level `connectionPool.tcp.{maxConnections,tcpKeepalive}` fan
            // out to every port served by this upstream. Per-port
            // `portLevelSettings` may overwrite either field below. We only
            // expand when there is at least one target port; service-discovery
            // upstreams skip the fan-out because their target ports aren't
            // known at apply time (the per-port loop still applies if the
            // operator explicitly listed `portLevelSettings`).
            if let Some(ref tp) = dr.traffic_policy
                && (tp.max_connections.is_some() || tp.tcp_keepalive.is_some())
                && !has_service_discovery
            {
                for port in &upstream_policy_ports {
                    let override_slot = upstream.port_overrides.entry(*port).or_default();
                    if let Some(max_conn) = tp.max_connections {
                        override_slot.max_connections = Some(max_conn);
                    }
                    if let Some(ref keepalive) = tp.tcp_keepalive {
                        override_slot.tcp_keepalive = Some(keepalive.clone());
                    }
                }
            }

            // Top-level `connectionPool.http.*` fans out to every port served
            // by this upstream so a single DR `trafficPolicy.connectionPool`
            // block applies uniformly across the upstream. Per-port
            // `portLevelSettings.connectionPool.http` overrides per-port
            // below. Mirrors the T1-D fan-out for
            // `connectionPool.tcp.{maxConnections,tcpKeepalive}`.
            //
            // Service-discovery upstreams cannot fan out: their target ports
            // resolve at runtime, not at apply time. Instead the top-level
            // overlay is accumulated on `dispatch_port_override_fallback`, which
            // `resolve_dispatch_port_overrides` projects onto the proxy and the
            // HTTP-family dispatch resolvers apply by the LB-selected port (an
            // explicit `portLevelSettings` entry for that port still wins). This
            // does NOT materialize discovery targets (the rejected PR #1602
            // rework) — it only carries the cap into runtime port resolution.
            // The overlay is applied additively (same `apply_*` helper as the
            // fan-out) so a later matching DR layers over an earlier one.
            if let Some(ref tp) = dr.traffic_policy
                && let Some(ref http) = tp.connection_pool_http
            {
                if has_service_discovery {
                    let fallback = upstream
                        .dispatch_port_override_fallback
                        .get_or_insert_default();
                    apply_connection_pool_http_to_port_override(fallback, http);
                } else {
                    for port in &upstream_policy_ports {
                        let override_slot = upstream.port_overrides.entry(*port).or_default();
                        apply_connection_pool_http_to_port_override(override_slot, http);
                    }
                }
            }

            // Second pass: per-port traffic policy overrides land on the
            // upstream's `port_overrides` slot. Pool-level dispatch already
            // keys per destination port, so per-port policy naturally scopes
            // to that port's pool entry. The top-level policy is still applied
            // first so per-port acts as an additive override of the same
            // fields.
            //
            // The upstream-level TLS base (this DR's top-level tls, applied
            // above) is captured owned so the per-port `entry()` mutable borrow
            // below doesn't conflict with the immutable `from_upstream` read.
            let upstream_base_tls = BackendTlsConfig::from_upstream(upstream);
            let upstream_id_for_tls = upstream.id.clone();
            // Captured owned (like `upstream_base_tls`) so the per-port
            // `entry()` mutable borrow below does not conflict with reading the
            // upstream's targets. Gates the ISTIO_MUTUAL CA-backed fail-closed:
            // mesh-transport upstreams source identity from the gateway SVID
            // slot, not the generic per-port client material.
            let upstream_presents_dynamic_svid = upstream_uses_mesh_transport(upstream);
            for (port, port_policy) in &dr.port_level_settings {
                // The `port_overrides` key(s) this Service-port-scoped entry
                // must land on. Targets that carry `service_port_policy_key`
                // dispatch policy by their owning declared Service port, not
                // by the resolved dial port. Static fallback targets on a mesh
                // service-discovery upstream can still dispatch by their dial
                // port, but only the SD upstream's requested Service-port entry
                // may seed those fallback slots. Sibling DR entries must not
                // leak onto this upstream merely because their service port
                // number appears as a fallback target's dial port.
                let store_ports: Vec<u16> = if let Some(owning_port) =
                    outbound_upstream_owner_port.get(&upstream.id)
                {
                    if port != owning_port {
                        debug!(
                            rule = %dr.name,
                            upstream = %upstream.id,
                            port = port,
                            owning_port = owning_port,
                            "DestinationRule portLevelSettings entry belongs to a sibling per-port upstream; skipping here"
                        );
                        continue;
                    }
                    vec![*port]
                } else if upstream_policy_ports.contains(port) {
                    vec![*port]
                } else if has_service_discovery {
                    let mut ports = Vec::with_capacity(if mesh_sd_selected_port == Some(*port) {
                        upstream_policy_ports.len() + 1
                    } else {
                        1
                    });
                    ports.push(*port);
                    if mesh_sd_selected_port == Some(*port) {
                        ports.extend(upstream_policy_ports.iter().copied());
                    }
                    ports.sort_unstable();
                    ports.dedup();
                    ports
                } else {
                    warn!(
                        rule = %dr.name,
                        upstream = %upstream.id,
                        port = port,
                        "DestinationRule portLevelSettings entry references a port not used by any target; skipping"
                    );
                    continue;
                };
                // Resolve per-port backend TLS over the upstream base, mirroring
                // the per-subset TLS overlay. Computed before the `override_slot`
                // mutable borrow. Fail-closed: an unresolvable per-port TLS
                // (e.g. ISTIO_MUTUAL without SVID material) rejects the slice
                // rather than silently downgrading the port's backend posture.
                let resolved_port_tls = if let Some(ref port_tls) = port_policy.tls {
                    let mut slot = upstream_base_tls.clone();
                    apply_traffic_policy_tls_to_backend_config(
                        &mut slot,
                        port_tls,
                        runtime,
                        &format!("{upstream_id_for_tls}/port-{port}"),
                        upstream_presents_dynamic_svid,
                    )
                    .map_err(|e| {
                        anyhow::anyhow!(
                            "DestinationRule portLevelSettings.tls projection failed for upstream={upstream_id_for_tls} port={port}: {e}"
                        )
                    })?;
                    Some(slot)
                } else {
                    None
                };

                let is_owner_entry = outbound_upstream_owner_port.get(&upstream.id) == Some(port);
                // Seed a FRESH fanned slot's passive health from the upstream
                // level — which carries this DR's top-level outlierDetection,
                // applied above — so a PARTIAL per-port outlier override
                // layers over the top-level window/recovery fields instead of
                // over defaults (`passive_health_for_target` prefers a
                // per-port slot outright). Owner-gated entries only, and only
                // when the entry actually carries outlierDetection; a slot an
                // earlier rule already populated keeps its accumulated
                // layering.
                let upstream_passive_seed =
                    if is_owner_entry && port_policy.outlier_detection.is_some() {
                        upstream
                            .health_checks
                            .as_ref()
                            .and_then(|h| h.passive.clone())
                    } else {
                        None
                    };
                for store_port in store_ports {
                    let override_slot = upstream.port_overrides.entry(store_port).or_default();
                    if override_slot.passive_health_check.is_none()
                        && let Some(ref seed) = upstream_passive_seed
                    {
                        override_slot.passive_health_check = Some(seed.clone());
                    }
                    apply_traffic_policy_to_port_override(override_slot, port_policy);
                    if let Some(ref slot) = resolved_port_tls {
                        override_slot.tls = Some(slot.clone());
                    }
                }

                // SELECTION-TIME fields of an owner-gated per-port upstream's
                // owning entry additionally land at the UPSTREAM level: the
                // LB engages a per-port lane only when one dial port covers
                // every target (`initial_dispatch_port_override`), so a named
                // `targetPort` resolving heterogeneously across replicas
                // leaves no full-coverage lane and selection falls back to
                // upstream-level LB/hash/locality (and upstream-level passive
                // thresholds back the per-target slots). This upstream serves
                // exactly one Service port, so its port policy IS the
                // whole-upstream policy. Field semantics mirror the per-port
                // slot helper: LB/outlier layer additively, hash keys are
                // owned by the LB choice (cleared when the entry switches to
                // a non-hash algorithm), and locality is owned by the entry
                // with a fallback to this DR's top-level locality — exactly
                // the per-port LANE's `.or(upstream-level)` fallback at LB
                // build — assigned unconditionally so a later rule's owning
                // entry that omits locality clears a stale earlier projection
                // instead of pinning it.
                if is_owner_entry {
                    if let Some(algorithm) = mesh_lb_to_ferrum(&port_policy.load_balancer) {
                        upstream.algorithm = algorithm;
                        // Unconditional: clears stale hash keys when this
                        // port switches to a non-hash algorithm (mirrors
                        // `apply_traffic_policy_to_port_override`).
                        upstream.hash_on = mesh_hash_on_to_ferrum(&port_policy.load_balancer);
                    }
                    if let Some(ref od) = port_policy.outlier_detection {
                        let passive = upstream
                            .health_checks
                            .get_or_insert_with(HealthCheckConfig::default)
                            .passive
                            .get_or_insert_with(PassiveHealthCheck::default);
                        apply_outlier_detection_to_passive(passive, od);
                    }
                    upstream.locality_lb_setting = port_policy
                        .locality_lb_setting
                        .as_ref()
                        .or_else(|| {
                            dr.traffic_policy
                                .as_ref()
                                .and_then(|tp| tp.locality_lb_setting.as_ref())
                        })
                        .map(into_upstream_locality);
                }
            }

            if !dr.subsets.is_empty() {
                if upstream.subsets.is_some() {
                    debug!(
                        rule = %dr.name,
                        upstream = %upstream.id,
                        "DestinationRule subsets overwriting existing upstream.subsets"
                    );
                }
                let subset_defs: Vec<SubsetDefinition> = dr
                    .subsets
                    .iter()
                    .map(|subset| SubsetDefinition {
                        name: subset.name.clone(),
                        labels: subset.labels.clone(),
                        traffic_policy: subset.traffic_policy.as_ref().map(|sp| {
                            // Resolve the subset's outlierDetection into a
                            // PassiveHealthCheck (ejection thresholds) up front,
                            // the same projection the upstream-level path uses.
                            let passive_health_check = sp.outlier_detection.as_ref().map(|od| {
                                let mut passive = PassiveHealthCheck::default();
                                apply_outlier_detection_to_passive(&mut passive, od);
                                passive
                            });
                            SubsetTrafficPolicy {
                                load_balancer_algorithm: mesh_lb_to_ferrum(&sp.load_balancer),
                                hash_on: mesh_hash_on_to_ferrum(&sp.load_balancer),
                                tls: sp.tls.clone(),
                                connect_timeout_ms: sp.connect_timeout_ms,
                                passive_health_check,
                            }
                        }),
                    })
                    .collect();
                upstream.subsets = Some(subset_defs);
                // Drop any stale per-subset TLS overlays from a previous DR
                // application of this upstream. The next pass below
                // recomputes overlays for the new subset set against the
                // final upstream-level TLS.
                upstream.resolved_subset_tls.clear();
            }

            // Top-level `trafficPolicy.connectTimeout` for a UDP egress upstream
            // (codex r6 P2). The top-level timeout is applied to `config.proxies`
            // below, but a UDP egress upstream (`__mesh-out-udp-upstream-*`) is
            // referenced by NO config proxy — it materializes a synthesized relay
            // proxy in the router table that dials via
            // `hbone_pool::get_datagram_tunnel`, which reads the connect timeout
            // from `dispatch_port_overrides` (projected from `port_overrides`) and
            // otherwise falls back to the relay proxy's hardcoded default. Seed the
            // top-level value onto each materialized target policy port carrying no
            // per-port `portLevelSettings.connectTimeout`, so the UDP relay honors
            // the operator's top-level connectTimeout instead of the 5s default.
            // Per-port entries written above already win (only unset slots are
            // seeded); other lanes are unaffected — raw-TCP relay proxies do not
            // read `dispatch_port_overrides`, and HTTP upstreams reach config
            // proxies. Keyed by the selected target's policy port because
            // `get_datagram_tunnel` receives both the dial app port and the owning
            // Service-port policy key for targetPort-remapped UDP services.
            if let Some(timeout_ms) = connect_timeout_ms
                && upstream.id.starts_with("__mesh-out-udp-upstream-")
            {
                let mut target_policy_ports: Vec<u16> = upstream
                    .targets
                    .iter()
                    .map(UpstreamTarget::dispatch_policy_port)
                    .collect();
                target_policy_ports.sort_unstable();
                target_policy_ports.dedup();
                for port in target_policy_ports {
                    let slot = upstream.port_overrides.entry(port).or_default();
                    if slot.connect_timeout_ms.is_none() {
                        slot.connect_timeout_ms = Some(timeout_ms);
                    }
                }
            }

            // Per-subset `connectionPool.tcp.connectTimeout` overrides the DR
            // top-level connectTimeout for proxies bound to that subset (Istio:
            // a subset trafficPolicy field-overrides the DR top-level for that
            // subset). Captured as owned data so the `upstream` borrow ends
            // before the `config.proxies` loop below.
            // Derive subset connectTimeouts from THIS DR's own subsets, not the
            // accumulated `upstream.subsets` an earlier sorted rule may have
            // populated. Reading the accumulated set would let a stale subset
            // timeout from a previous rule shadow this rule's top-level
            // connectTimeout at the `.or(connect_timeout_ms)` below, breaking
            // deterministic last-writer-wins for a later rule that defines no
            // subsets of its own.
            let subset_connect_timeouts: Vec<(String, u64)> = dr
                .subsets
                .iter()
                .filter_map(|s| {
                    s.traffic_policy
                        .as_ref()
                        .and_then(|tp| tp.connect_timeout_ms)
                        .map(|ms| (s.name.clone(), ms))
                })
                .collect();

            if connect_timeout_ms.is_some() || !subset_connect_timeouts.is_empty() {
                let upstream_id = upstream.id.clone();
                let upstream_namespace = upstream.namespace.clone();
                for proxy in &mut config.proxies {
                    if proxy.upstream_id.as_deref() != Some(upstream_id.as_str())
                        || proxy.namespace != upstream_namespace
                    {
                        continue;
                    }
                    // A subset-bound proxy uses its subset's connectTimeout when
                    // the subset sets one; otherwise the DR top-level applies
                    // (as it does to every proxy referencing this upstream).
                    let effective_ms = proxy
                        .upstream_subset
                        .as_deref()
                        .and_then(|name| {
                            subset_connect_timeouts
                                .iter()
                                .find(|(n, _)| n == name)
                                .map(|(_, ms)| *ms)
                        })
                        .or(connect_timeout_ms);
                    if let Some(timeout_ms) = effective_ms
                        && proxy.backend_connect_timeout_ms != timeout_ms
                    {
                        debug!(
                            proxy = %proxy.id,
                            upstream = %upstream_id,
                            subset = proxy.upstream_subset.as_deref().unwrap_or(""),
                            previous_ms = proxy.backend_connect_timeout_ms,
                            new_ms = timeout_ms,
                            rule = %dr.name,
                            "DestinationRule overriding proxy backend_connect_timeout_ms"
                        );
                        proxy.backend_connect_timeout_ms = timeout_ms;
                    }
                }
            }
        }
    }

    // Final pass: project per-subset `trafficPolicy.tls` overlays onto each
    // upstream's `resolved_subset_tls` map. Runs once after all DRs are
    // applied so subset TLS layers over the FINAL upstream-level TLS rather
    // than whatever value a mid-loop pass would have observed.
    resolve_subset_traffic_policy_tls(config, runtime)?;

    Ok(())
}

/// Compute each upstream's per-subset resolved TLS overlay against the
/// upstream's settled `backend_tls_*` posture. Skips upstreams with no
/// subsets and subsets with no `trafficPolicy.tls`. The result lands on
/// `Upstream.resolved_subset_tls` keyed by subset name; consulted by
/// [`GatewayConfig::resolve_upstream_tls`] for proxies whose
/// `upstream_subset` selects that subset.
///
/// Fail-closed: any subset whose `trafficPolicy.tls` cannot be resolved
/// (e.g., `ISTIO_MUTUAL` requested without SVID material) rejects the entire
/// slice via `Err`, matching [`apply_traffic_policy_tls_to_upstream`]'s
/// upstream-level semantics. Silently degrading to upstream-level TLS would
/// turn an operator-requested mTLS posture into whatever the upstream defaults
/// to (potentially `SIMPLE` with a public CA).
fn resolve_subset_traffic_policy_tls(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
) -> Result<(), anyhow::Error> {
    for upstream in &mut config.upstreams {
        let Some(subsets) = upstream.subsets.as_ref() else {
            // No subsets — make sure any stale map from a previous apply
            // doesn't survive a slice that removed all subsets.
            upstream.resolved_subset_tls.clear();
            continue;
        };
        let upstream_base_tls = BackendTlsConfig::from_upstream(upstream);
        // Mesh-transport gate for the ISTIO_MUTUAL CA-backed fail-closed,
        // computed once per upstream (subsets share the owning upstream's
        // transport). Mesh-transport upstreams source identity from the
        // gateway SVID slot, not the generic per-subset client material.
        let upstream_presents_dynamic_svid = upstream_uses_mesh_transport(upstream);
        let mut resolved_map: HashMap<String, ResolvedSubsetTrafficPolicy> = HashMap::new();
        for subset in subsets {
            let tp = subset.traffic_policy.as_ref();
            // Per-subset TLS overlay, resolved over the upstream-level TLS.
            let resolved_tls = if let Some(subset_tls) = tp.and_then(|tp| tp.tls.as_ref()) {
                let identity = format!("{}/{}", upstream.id, subset.name);
                let mut slot = upstream_base_tls.clone();
                apply_traffic_policy_tls_to_backend_config(
                    &mut slot,
                    subset_tls,
                    runtime,
                    &identity,
                    upstream_presents_dynamic_svid,
                )
                .map_err(|e| {
                        anyhow::anyhow!(
                            "DestinationRule subset trafficPolicy.tls projection failed for upstream={} subset={}: {}",
                            upstream.id,
                            subset.name,
                            e
                        )
                    })?;
                Some(slot)
            } else {
                None
            };
            // Per-subset passive health (ejection thresholds), already resolved
            // from the subset's outlierDetection in apply_destination_rules.
            let passive = tp.and_then(|tp| tp.passive_health_check.clone());
            if let Some(resolved) = ResolvedSubsetTrafficPolicy::new(resolved_tls, passive) {
                resolved_map.insert(subset.name.clone(), resolved);
            }
        }
        upstream.resolved_subset_tls = resolved_map;
    }
    Ok(())
}

/// Project a `MeshTrafficPolicy` onto a per-port `UpstreamPortOverride` slot.
///
/// Per-port `tls` is intentionally not applied here today because backend TLS
/// posture is stored at upstream scope (`backend_tls_*`), not per-port.
fn apply_traffic_policy_to_port_override(
    slot: &mut UpstreamPortOverride,
    policy: &MeshTrafficPolicy,
) {
    if let Some(timeout_ms) = policy.connect_timeout_ms {
        slot.connect_timeout_ms = Some(timeout_ms);
    }
    if let Some(algorithm) = mesh_lb_to_ferrum(&policy.load_balancer) {
        slot.algorithm = Some(algorithm);
        // Unconditional: clears stale hash keys when switching a port to a non-hash algorithm.
        slot.hash_on = mesh_hash_on_to_ferrum(&policy.load_balancer);
    }
    if let Some(ref od) = policy.outlier_detection {
        // A PARTIAL per-port `outlierDetection` (e.g. only `consecutiveErrors`)
        // is overlaid field-by-field by `apply_outlier_detection_to_passive`, so
        // the *base* it layers onto matters. The caller in `apply_destination_rules`
        // seeds `slot.passive_health_check` from the UPSTREAM-level passive (which
        // already carries this DR's TOP-LEVEL `outlierDetection`) before calling
        // here for the owner-gated port, so a partial override correctly layers
        // over the DR's top-level window/recovery fields rather than over engine
        // defaults. The `unwrap_or_default()` base is therefore only reached when
        // there is genuinely no top-level outlier to inherit (no seed) — the
        // intended fallback, not a regression. NOTE: this is a per-field merge,
        // not Istio's portLevelSettings "complete replacement"; that divergence
        // is uniform across the per-port DR knobs and documented in `docs/mesh.md`.
        let mut passive = slot.passive_health_check.clone().unwrap_or_default();
        apply_outlier_detection_to_passive(&mut passive, od);
        slot.passive_health_check = Some(passive);
    }
    // Per-port localityLbSetting projection. A later matching DR entry with no
    // localityLbSetting clears an earlier value, mirroring the upstream-level
    // semantics in `apply_traffic_policy_to_upstream`.
    slot.locality_lb_setting = policy
        .locality_lb_setting
        .as_ref()
        .map(into_upstream_locality);
    // Per-port `connectionPool.tcp.{maxConnections,tcpKeepalive}`. Ferrum's
    // documented port-level connectionPool contract is field-level merge:
    // per-port fields win when set, while omitted fields keep any top-level
    // fan-out value already present on the slot.
    if let Some(max_conn) = policy.max_connections {
        slot.max_connections = Some(max_conn);
    }
    if let Some(ref keepalive) = policy.tcp_keepalive {
        slot.tcp_keepalive = Some(keepalive.clone());
    }
    // Per-port `connectionPool.http.*` follows the same field-level merge
    // contract as the TCP fields above.
    if let Some(ref http) = policy.connection_pool_http {
        apply_connection_pool_http_to_port_override(slot, http);
    }
}

/// Project an HTTP connection-pool overlay onto a per-port slot.
///
/// Each field is overlaid independently — `None` (field absent) leaves the
/// existing slot value untouched so a per-port partial overlay can layer over
/// a top-level fan-out without clearing fields the operator did not respecify.
///
/// **Field-level merge — intentional Ferrum semantics.** Istio treats a matching
/// `portLevelSettings` entry as a COMPLETE REPLACEMENT of the destination-level
/// `connectionPool` for that port; Ferrum instead does a per-field merge
/// (top-level fan-out, then this additive per-port overlay). This is the
/// documented product contract across every applied `connectionPool` knob.
///
/// `h2_upgrade_policy` carries an explicit `H2UpgradePolicy::Default` rather
/// than collapsing Istio's `DEFAULT` to `None`. That distinction matters HERE:
/// a port-level explicit `Some(Default)` SETS the slot to `Default`, which
/// clears an inherited top-level `Upgrade`/`DoNotUpgrade` for that port (the
/// operator explicitly chose probe-driven). An OMITTED port-level value
/// (`None`) leaves the inherited slot untouched. The effective-proxy/dispatch
/// path treats `Default` and `None` identically (probe-driven).
fn apply_connection_pool_http_to_port_override(
    slot: &mut UpstreamPortOverride,
    http: &crate::modes::mesh::config::MeshConnectionPoolHttp,
) {
    // `maxRequestsPerConnection` is intentionally NOT projected. The parser
    // validates and status-reports it as deferred because Ferrum does not have
    // close-after-N-requests behavior for backend pools.
    if let Some(idle_ms) = http.idle_timeout_ms {
        slot.http_idle_timeout_ms = Some(idle_ms);
    }
    if let Some(max_streams) = http.http2_max_requests {
        slot.h2_max_concurrent_streams = Some(max_streams);
    }
    // An explicit `Some(Default)` (port-level `DEFAULT`) overwrites an
    // inherited `Upgrade`/`DoNotUpgrade`; absent (`None`) leaves it untouched.
    if let Some(policy) = http.h2_upgrade_policy {
        slot.h2_upgrade_policy = Some(policy);
    }
    if let Some(max_retries) = http.max_retries {
        slot.max_retries = Some(max_retries);
    }
    if let Some(pending) = http.http1_max_pending_requests {
        slot.http1_max_pending_requests = Some(pending);
    }
}

/// Project a mesh-derived `MeshLocalityLbSetting` onto its Ferrum
/// `UpstreamLocalityLbSetting` counterpart. Used by both the upstream-level
/// and per-port projection paths so they cannot drift apart.
fn into_upstream_locality(
    locality: &MeshLocalityLbSetting,
) -> crate::config::types::UpstreamLocalityLbSetting {
    crate::config::types::UpstreamLocalityLbSetting {
        enabled: locality.enabled,
        distribute: locality
            .distribute
            .iter()
            .map(|entry| crate::config::types::LocalityDistribute {
                from: entry.from.clone(),
                to: entry.to.clone(),
            })
            .collect(),
        failover: locality
            .failover
            .iter()
            .map(|entry| crate::config::types::LocalityFailover {
                from: entry.from.clone(),
                to: entry.to.clone(),
            })
            .collect(),
    }
}

fn destination_rule_matches_upstream(dr: &MeshDestinationRule, upstream: &Upstream) -> bool {
    upstream
        .targets
        .iter()
        .any(|target| destination_rule_host_matches(&dr.host, &dr.namespace, &target.host))
        || upstream
            .name
            .as_deref()
            .is_some_and(|name| destination_rule_host_matches(&dr.host, &dr.namespace, name))
        || destination_rule_host_matches(&dr.host, &dr.namespace, &upstream.id)
}

/// True when EVERY target of this upstream dispatches through an SVID-backed
/// mesh transport (HBONE or Sidecar mTLS), which source the client cert from the
/// shared gateway SVID slot (gateway_svid_bundle) rather than the generic
/// backend_tls_client_cert_path fields. For such upstreams a CA-backed dynamic
/// SVID CAN back ISTIO_MUTUAL, so the generic "can't present a dynamic client
/// cert" fail-closed must NOT apply.
///
/// Uses the same value-aware predicates as runtime dispatch
/// (`target_hbone_enabled` / `target_mesh_mtls_enabled`, which require a
/// boolish-true tag value), and requires ALL targets to qualify: if any target
/// would fall back to the generic backend (a `mesh.hbone=false` tag, or a mixed
/// upstream with a non-mesh target), clearing the generic client material would
/// let that target connect with no client cert instead of failing closed.
fn upstream_uses_mesh_transport(upstream: &Upstream) -> bool {
    // Every materialized static target must use a mesh transport. A single non-mesh
    // static target means generic backend TLS still applies to it, so the CA-backed
    // mesh-transport classification must NOT clear its client cert/key. (Vacuously
    // true for an empty target list — handled per service-discovery case below.)
    let all_static_targets_mesh = upstream.targets.iter().all(|t| {
        crate::proxy::hbone_pool::target_hbone_enabled(t)
            || crate::proxy::mesh_mtls_pool::target_mesh_mtls_enabled(t)
    });
    match upstream.service_discovery.as_ref() {
        // A NON-mesh service-discovery provider (DNS / Kubernetes / Consul) merges
        // DISCOVERED targets at runtime that carry no mesh transport tags, so the
        // upstream can never be uniformly mesh transport regardless of how its
        // static targets are tagged — fail closed so CA-backed ISTIO_MUTUAL does
        // not clear the generic client cert/key a discovered TLS backend needs
        // (Codex: reject non-mesh SD before clearing client mTLS).
        Some(sd) if sd.provider != crate::config::types::SdProvider::Mesh => false,
        // Mesh service discovery resolves its targets at runtime with HBONE /
        // SVID-mTLS tags, so an empty static-target list is mesh transport; any
        // static fallback targets it ALSO carries are merged unchanged and so must
        // themselves be mesh-tagged.
        Some(_) => all_static_targets_mesh,
        // No service discovery: a classic static upstream — at least one target,
        // every one mesh-tagged.
        None => !upstream.targets.is_empty() && all_static_targets_mesh,
    }
}

fn destination_rule_host_matches(rule_host: &str, namespace: &str, candidate: &str) -> bool {
    let rule_host = rule_host.trim_end_matches('.').to_ascii_lowercase();
    let candidate = candidate.trim_end_matches('.').to_ascii_lowercase();
    if candidate == rule_host {
        return true;
    }

    if !rule_host.contains('.') {
        let namespaced = format!("{rule_host}.{namespace}");
        return candidate == namespaced || candidate.starts_with(&format!("{namespaced}.svc."));
    }

    let dot_count = rule_host.bytes().filter(|byte| *byte == b'.').count();
    if dot_count == 1 {
        return candidate.starts_with(&format!("{rule_host}.svc."));
    }
    if rule_host.ends_with(".svc") {
        return candidate.starts_with(&format!("{rule_host}."));
    }

    false
}

/// Apply a `MeshTrafficPolicy` onto a Ferrum `Upstream`.
///
/// When `policy.tls` is `None` the upstream's `backend_tls_*` fields are
/// left untouched and the workload's PeerAuthentication-derived mTLS
/// posture continues to apply. When `policy.tls` is `Some(...)` the DR's
/// TLS settings override the PeerAuthentication defaults via
/// `apply_traffic_policy_tls_to_upstream`.
fn apply_traffic_policy_to_upstream(
    upstream: &mut Upstream,
    policy: &MeshTrafficPolicy,
    runtime: &MeshRuntimeConfig,
) -> Result<(), anyhow::Error> {
    if let Some(algorithm) = mesh_lb_to_ferrum(&policy.load_balancer) {
        upstream.algorithm = algorithm;
    }
    if let Some(hash_on) = mesh_hash_on_to_ferrum(&policy.load_balancer) {
        upstream.hash_on = Some(hash_on);
    }

    // Outlier detection -> passive health check.
    if let Some(ref od) = policy.outlier_detection {
        let passive = upstream
            .health_checks
            .get_or_insert_with(HealthCheckConfig::default)
            .passive
            .get_or_insert_with(PassiveHealthCheck::default);

        apply_outlier_detection_to_passive(passive, od);
    }

    // Backend TLS posture override from DestinationRule.trafficPolicy.tls.
    if let Some(ref tls) = policy.tls {
        apply_traffic_policy_tls_to_upstream(upstream, tls, runtime)?;
    }

    // localityLbSetting projection. The current traffic policy owns this
    // mesh-derived slot, so a later matching DestinationRule with no
    // localityLbSetting clears an earlier value instead of leaving stale
    // distribute/failover state behind.
    upstream.locality_lb_setting = policy
        .locality_lb_setting
        .as_ref()
        .map(into_upstream_locality);

    Ok(())
}

/// Project `MeshTrafficPolicyTls` onto an `Upstream`'s `backend_tls_*`
/// fields. Thin shim over [`apply_traffic_policy_tls_to_backend_config`] that
/// builds a `BackendTlsConfig` view of the upstream's TLS fields, runs the
/// shared overlay, and writes the result back. The DR wins over the
/// PeerAuthentication-derived default for every field it sets.
///
/// See [`apply_traffic_policy_tls_to_backend_config`] for the per-mode mapping
/// (`Disable` / `Simple` / `Mutual` / `IstioMutual`), the
/// `insecure_skip_verify` precedence rules, and SAN/SNI bounding behaviour.
fn apply_traffic_policy_tls_to_upstream(
    upstream: &mut Upstream,
    tls: &MeshTrafficPolicyTls,
    runtime: &MeshRuntimeConfig,
) -> Result<(), anyhow::Error> {
    let mut slot = BackendTlsConfig::from_upstream(upstream);
    let presents_dynamic_svid = upstream_uses_mesh_transport(upstream);
    apply_traffic_policy_tls_to_backend_config(
        &mut slot,
        tls,
        runtime,
        &upstream.id,
        presents_dynamic_svid,
    )?;
    upstream.backend_tls_client_cert_path = slot.client_cert_path;
    upstream.backend_tls_client_key_path = slot.client_key_path;
    upstream.backend_tls_server_ca_cert_path = slot.server_ca_cert_path;
    upstream.backend_tls_verify_server_cert = slot.verify_server_cert;
    upstream.backend_tls_sni = slot.sni;
    upstream.backend_tls_san_allow_list = slot.san_allow_list;
    Ok(())
}

/// Project `MeshTrafficPolicyTls` onto a `BackendTlsConfig` slot.
///
/// Shared overlay used by both the upstream-level apply
/// ([`apply_traffic_policy_tls_to_upstream`]) and the per-subset apply
/// ([`apply_subset_traffic_policy_tls`]), so subset TLS overrides cannot drift
/// from the upstream-level translation. `identity` is used only for log /
/// error context (the upstream id, or `<upstream>/<subset>`).
///
/// Mapping:
/// - `Disable`: clear all client TLS material and stale SNI / SAN allow-list;
///   leave `verify_server_cert` at its current value (TLS may still originate
///   when the proxy's `backend_scheme` is `https`) unless the operator also
///   asked for `insecure_skip_verify`.
/// - `Simple`: enable server-cert verification; populate CA from
///   `ca_certificates`; clear any stale client cert/key.
/// - `Mutual`: enable server-cert verification; populate CA, client cert,
///   and private key from the DR.
/// - `IstioMutual`: enable server-cert verification and project the workload's
///   file-backed X.509-SVID cert/key paths and trust bundle from the mesh
///   runtime onto the slot. When no file SVID paths are configured: a
///   CA-backed runtime (`ca_backend != None`) fails closed for GENERIC backend
///   upstreams (`presents_dynamic_svid == false`) because generic backend TLS
///   cannot present the dynamic SVID material; for mesh-transport upstreams
///   (`presents_dynamic_svid == true`, i.e. HBONE / Sidecar mTLS) it leaves the
///   generic client material cleared and projects only the SVID trust bundle,
///   because those transports source the client identity from the shared
///   gateway SVID slot. With NO CA backend AND no file SVID there is no dynamic
///   SVID source at all, so ISTIO_MUTUAL fails closed for EVERY upstream
///   including mesh transports.
///
/// `insecure_skip_verify=true` always wins: it forces
/// `verify_server_cert=false` regardless of mode.
///
/// SNI (`tls.sni`) and `subject_alt_names` project onto slot fields here. SAN
/// lists are bounded because mesh-projected slots skip admin admission. The
/// SAN-allow-list digest is recomputed at the end so pool keys partition on
/// the current SAN set.
fn apply_traffic_policy_tls_to_backend_config(
    slot: &mut BackendTlsConfig,
    tls: &MeshTrafficPolicyTls,
    runtime: &MeshRuntimeConfig,
    identity: &str,
    presents_dynamic_svid: bool,
) -> Result<(), anyhow::Error> {
    match tls.mode {
        MtlsMode::Disable => {
            slot.client_cert_path = None;
            slot.client_key_path = None;
            slot.server_ca_cert_path = None;
            slot.sni = None;
            slot.san_allow_list.clear();
            // When mTLS is explicitly disabled, leave `verify_server_cert`
            // at its current value (TLS may still originate when the
            // proxy's `backend_scheme` is `https`) unless the operator
            // also asked for skip_verify.
        }
        MtlsMode::Simple => {
            slot.client_cert_path = None;
            slot.client_key_path = None;
            slot.server_ca_cert_path = tls.ca_certificates.clone();
        }
        MtlsMode::Mutual => {
            slot.client_cert_path = tls.client_certificate.clone();
            slot.client_key_path = tls.private_key.clone();
            slot.server_ca_cert_path = tls.ca_certificates.clone();
        }
        MtlsMode::IstioMutual => {
            match (
                runtime.workload_svid_cert_path.clone(),
                runtime.workload_svid_key_path.clone(),
            ) {
                (Some(cert_path), Some(key_path)) => {
                    slot.server_ca_cert_path = runtime.workload_svid_trust_bundle_path.clone();
                    if runtime.workload_svid_trust_bundle_path.is_none() {
                        warn!(
                            identity = %identity,
                            "DestinationRule ISTIO_MUTUAL requested but workload SVID trust bundle path is not configured; clearing any stale CA and falling back to global/default trust"
                        );
                    }
                    slot.client_cert_path = Some(cert_path);
                    slot.client_key_path = Some(key_path);
                }
                _ if runtime.ca_backend != CaBackend::None && !presents_dynamic_svid => {
                    return Err(anyhow::anyhow!(
                        "DestinationRule ISTIO_MUTUAL for '{}' cannot use FERRUM_MESH_CA_BACKEND yet because generic backend TLS cannot present dynamic runtime SVID client certificates; configure FERRUM_GATEWAY_SVID_CERT_PATH/FERRUM_GATEWAY_SVID_KEY_PATH or use MUTUAL with explicit client cert/key paths",
                        identity
                    ));
                }
                _ if runtime.ca_backend != CaBackend::None => {
                    // Mesh transport (HBONE / Sidecar mTLS): client identity
                    // comes from the shared gateway SVID slot
                    // (gateway_svid_bundle), not slot.client_cert_path — the
                    // HBONE/mTLS pools read `self.gateway_svid.load_full()`, not
                    // the generic backend client material. A CA-backed dynamic
                    // SVID therefore DOES back ISTIO_MUTUAL here, so leave the
                    // generic client material cleared and project only the SVID
                    // trust bundle for server verification.
                    slot.client_cert_path = None;
                    slot.client_key_path = None;
                    slot.server_ca_cert_path = runtime.workload_svid_trust_bundle_path.clone();
                }
                _ => {
                    // No file SVID and no CA backend: there is NO dynamic SVID
                    // source at all, so even a mesh-transport upstream has no
                    // identity to present. Fail closed for EVERY upstream.
                    return Err(anyhow::anyhow!(
                        "DestinationRule ISTIO_MUTUAL for '{}' requires FERRUM_GATEWAY_SVID_CERT_PATH/FERRUM_GATEWAY_SVID_KEY_PATH",
                        identity
                    ));
                }
            }
        }
        // PeerAuthentication-side modes are rejected at translate time;
        // an in-memory slice that still carries one is a programming
        // error. Treat as a no-op rather than panic on the cold path.
        MtlsMode::Strict | MtlsMode::Permissive => {
            warn!(
                identity = %identity,
                mode = ?tls.mode,
                "DestinationRule trafficPolicy.tls.mode is a server-side mode and cannot apply to client-side backend TLS; ignoring"
            );
            return Ok(());
        }
    }

    // `verify_server_cert` precedence: explicit `insecureSkipVerify=true`
    // forces false; otherwise SIMPLE/MUTUAL/ISTIO_MUTUAL require verify=true
    // and DISABLE leaves the existing value alone.
    if tls.insecure_skip_verify {
        slot.verify_server_cert = false;
    } else if matches!(
        tls.mode,
        MtlsMode::Simple | MtlsMode::Mutual | MtlsMode::IstioMutual
    ) {
        slot.verify_server_cert = true;
    }

    if tls.mode != MtlsMode::Disable {
        slot.sni = bounded_backend_tls_sni(identity, tls.sni.as_deref());
        slot.san_allow_list = bounded_backend_tls_san_allow_list(identity, &tls.subject_alt_names);
    }

    slot.recompute_san_digest();
    Ok(())
}

fn bounded_backend_tls_sni(identity: &str, sni: Option<&str>) -> Option<String> {
    let sni = sni?;
    match crate::config::types::validate_backend_tls_sni(sni) {
        Ok(()) => Some(sni.to_ascii_lowercase()),
        Err(error) => {
            warn!(
                identity = %identity,
                error = %error,
                "DestinationRule trafficPolicy.tls.sni is invalid for backend TLS; dropping SNI override"
            );
            None
        }
    }
}

fn bounded_backend_tls_san_allow_list(identity: &str, sans: &[String]) -> Vec<String> {
    let mut bounded = Vec::with_capacity(sans.len().min(MAX_BACKEND_TLS_SAN_ALLOW_LIST_ENTRIES));
    if sans.len() > MAX_BACKEND_TLS_SAN_ALLOW_LIST_ENTRIES {
        warn!(
            identity = %identity,
            count = sans.len(),
            max = MAX_BACKEND_TLS_SAN_ALLOW_LIST_ENTRIES,
            "DestinationRule subjectAltNames exceeds backend TLS SAN allow-list limit; dropping extra entries"
        );
    }

    for san in sans.iter().take(MAX_BACKEND_TLS_SAN_ALLOW_LIST_ENTRIES) {
        if san.len() > MAX_BACKEND_TLS_SAN_ALLOW_LIST_ENTRY_LENGTH {
            warn!(
                identity = %identity,
                len = san.len(),
                max = MAX_BACKEND_TLS_SAN_ALLOW_LIST_ENTRY_LENGTH,
                "DestinationRule subjectAltNames entry exceeds backend TLS SAN allow-list entry limit; dropping entry"
            );
            continue;
        }
        if let Err(error) = crate::config::types::validate_backend_tls_san_allow_list_entry(san) {
            warn!(
                identity = %identity,
                error = %error,
                "DestinationRule subjectAltNames entry is invalid for backend TLS SAN allow-list; dropping entry"
            );
            continue;
        }
        let mut san = san.clone();
        crate::config::types::normalize_backend_tls_san_allow_list_entry(&mut san);
        bounded.push(san);
    }

    bounded
}

/// Convert a mesh LB config to a Ferrum `LoadBalancerAlgorithm`.
fn mesh_lb_to_ferrum(lb: &Option<MeshLoadBalancer>) -> Option<LoadBalancerAlgorithm> {
    match lb {
        Some(MeshLoadBalancer::Simple(simple)) => match simple {
            MeshSimpleLb::RoundRobin => Some(LoadBalancerAlgorithm::RoundRobin),
            MeshSimpleLb::LeastRequest => Some(LoadBalancerAlgorithm::LeastConnections),
            MeshSimpleLb::Random => Some(LoadBalancerAlgorithm::Random),
            // Istio PASSTHROUGH = dial the captured original destination. The
            // request path (`select_upstream_target`) dials orig-dst when it
            // matches a pool target and round-robins otherwise.
            MeshSimpleLb::Passthrough => Some(LoadBalancerAlgorithm::Passthrough),
        },
        Some(MeshLoadBalancer::ConsistentHash(_)) => Some(LoadBalancerAlgorithm::ConsistentHashing),
        None => None,
    }
}

fn mesh_hash_on_to_ferrum(lb: &Option<MeshLoadBalancer>) -> Option<String> {
    let Some(MeshLoadBalancer::ConsistentHash(ch)) = lb else {
        return None;
    };
    if let Some(header) = &ch.http_header_name {
        Some(format!("header:{header}"))
    } else if let Some(cookie) = &ch.http_cookie_name {
        Some(format!("cookie:{cookie}"))
    } else if ch.use_source_ip {
        Some("ip".to_string())
    } else {
        None
    }
}

fn apply_outlier_detection_to_passive(passive: &mut PassiveHealthCheck, od: &MeshOutlierDetection) {
    if let Some(consecutive) = od.consecutive_errors {
        passive.unhealthy_threshold = consecutive;
    }
    if let Some(interval) = od.interval_seconds {
        passive.unhealthy_window_seconds = interval;
    }
    if let Some(ejection) = od.base_ejection_seconds {
        passive.healthy_after_seconds = ejection;
    }
    if let Some(max_pct) = od.max_ejection_percent {
        passive.max_ejection_percent = Some(max_pct);
    }
}

// ── Egress gateway proxy materialization ─────────────────────────────────

/// Materialize HTTP-family proxies and upstreams from external `ServiceEntry`
/// resources when the topology is `EgressGateway`.
///
/// Each external `ServiceEntry` port produces one `Upstream` (targets from
/// endpoints or DNS hosts) and one `Proxy` per host (host-only routing, no
/// `listen_path`). The resulting proxies accept mesh-internal mTLS from
/// sidecars and forward to external backends with optional re-encryption.
fn materialize_egress_gateway_proxies(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) {
    if runtime.topology != MeshTopology::EgressGateway {
        return;
    }

    let service_entries = &mesh_slice.service_entries;
    if service_entries.is_empty() {
        debug!("egress gateway has no service entries to materialize");
        return;
    }

    // Stream-family egress proxies bind their own listen_port. Skip ports that
    // collide with the egress gateway's own mTLS-termination listener
    // (`egress_listen_addr`, default 15090). Without this guard a ServiceEntry
    // for, say, `external.io:15090/TCP` would materialize a stream proxy on
    // the same port the gateway is already binding for HTTP-family egress,
    // causing the stream listener bind to fail at runtime (EADDRINUSE) with
    // no actionable signal to the operator.
    let mut mesh_reserved_ports = std::collections::HashSet::new();
    mesh_reserved_ports.insert(runtime.egress_listen_addr.port());

    let (proxies, upstreams) = build_egress_proxies_and_upstreams(
        service_entries,
        &runtime.namespace,
        &mesh_reserved_ports,
        runtime.egress_stream_enabled,
        runtime.egress_stream_allow_plaintext,
    );

    if proxies.is_empty() {
        debug!("no external service entries produced egress proxies");
        return;
    }

    info!(
        egress_proxies = proxies.len(),
        egress_upstreams = upstreams.len(),
        "Materializing egress gateway proxies from external ServiceEntries"
    );

    // Merge upstreams: replace existing by ID or append.
    for upstream in upstreams {
        if let Some(existing) = config
            .upstreams
            .iter_mut()
            .find(|candidate| candidate.id == upstream.id)
        {
            *existing = upstream;
        } else {
            config.upstreams.push(upstream);
        }
    }

    // Merge proxies: replace existing by ID or append.
    for proxy in proxies {
        if let Some(existing) = config
            .proxies
            .iter_mut()
            .find(|candidate| candidate.id == proxy.id)
        {
            *existing = proxy;
        } else {
            config.proxies.push(proxy);
        }
    }
}

/// One-time guard so the "UDP egress materialization deferred" warning fires at
/// most once per process instead of on every slice apply that carries a UDP
/// ServiceEntry. Reset is intentionally not provided — F3 §3.3 stage 1 is inert
/// for UDP and the later datapath stage removes the skip entirely.
static UDP_EGRESS_DEFERRED_WARNED: AtomicBool = AtomicBool::new(false);

/// Build proxy + upstream pairs from external `ServiceEntry` resources.
///
/// UDP ServiceEntry ports (`AppProtocol::Udp`) are classified but NOT
/// materialized in this F3 §3.3 stage (schema-only / inert) — they are skipped
/// with a one-time deferred warning so no premature UDP listener is emitted (no
/// port-only TCP/UDP dedup collision, no unseeded-DTLS deferral). UDP egress
/// materialization arrives in a later stage.
///
/// Only entries with `location == MeshExternal` are materialized. For each
/// qualifying entry, one upstream per port is created (keyed by host + port
/// number). DNS-resolution entries use the ServiceEntry hosts as backend
/// targets; static-resolution entries use the endpoint addresses.
///
/// HTTP-family ports (`http`, `http2`, `grpc`, `tls`) are materialized as
/// host-routed HTTP-family proxies sharing the egress gateway listener
/// (mTLS termination at `egress_listen_addr`, default 15090). Each host
/// admits only one HTTP-family proxy across all ports (host-only routing
/// can't safely disambiguate ports).
///
/// Stream-family ports (`tcp`, `mongo`, `redis`, `mysql`, `postgres`) are
/// materialized as L4 stream proxies bound on the ServiceEntry's own
/// port (e.g., `mongo.external.io:27017/TCP` produces a TCP listener on
/// port 27017). Each `listen_port` admits at most one stream proxy; later
/// SEs requesting the same port are skipped with a warning. The materialized
/// stream proxy and the outbound capture flow share the destination port so
/// sidecars dialing the external host are routed to the egress gateway
/// without rewriting the destination port. ServiceEntry ports that collide
/// with `mesh_reserved_ports` (the egress gateway's own listener port) are
/// skipped with a warning instead of materializing — letting them through
/// would fail at listener bind time with EADDRINUSE.
///
/// Stream egress listeners terminate SVID-mTLS (`frontend_tls: true`, sharing
/// the mesh-inbound `ServerConfig` slot) and run `mesh_authz` at accept — the
/// same authn/z as HTTP egress — unless `egress_stream_allow_plaintext` is set,
/// which restores the legacy plaintext + unauthenticated posture.
fn build_egress_proxies_and_upstreams(
    service_entries: &[ServiceEntry],
    namespace: &str,
    mesh_reserved_ports: &std::collections::HashSet<u16>,
    egress_stream_enabled: bool,
    egress_stream_allow_plaintext: bool,
) -> (Vec<Proxy>, Vec<Upstream>) {
    let mut proxies = Vec::new();
    let mut upstreams = Vec::new();
    // HTTP-family materialization is host-keyed because the egress listener
    // shares one port (15090) with host-based routing.
    let mut materialized_http_hosts = std::collections::HashSet::new();
    // Stream-family materialization is port-keyed because each stream proxy
    // owns its own listen_port. Two SEs trying to bind the same port produce
    // a non-fatal skip (the second one warns).
    let mut materialized_stream_ports = std::collections::HashSet::new();
    let now = chrono::Utc::now();

    for entry in service_entries {
        if !service_entry_exported_to_namespace(entry, namespace) {
            continue;
        }

        if entry.location != ServiceEntryLocation::MeshExternal {
            continue;
        }

        if entry.hosts.is_empty() {
            continue;
        }

        for port_spec in &entry.ports {
            // F3 §3.3 stage 1 is schema-only and INERT for UDP: a `protocol: UDP`
            // ServiceEntry port classifies as `AppProtocol::Udp` (so it is no
            // longer mis-routed as HTTP-family) but must NOT yet materialize an
            // egress listener. Materializing it now would (a) collide with a
            // sibling TCP port on the same number under the port-only stream
            // dedup (e.g. DNS TCP/53 + UDP/53) and (b) build a `frontend_tls`
            // listener that mesh never seeds DTLS material for, deferring it
            // indefinitely. UDP egress materialization (with protocol-aware
            // dedup + DTLS seeding) belongs to a later F3 §3.3 stage; skip it
            // here so Stage 1 stays inert. Warn once per process to flag the
            // deferral without log spam across repeated slice applies.
            if matches!(port_spec.protocol, AppProtocol::Udp) {
                if !UDP_EGRESS_DEFERRED_WARNED.swap(true, std::sync::atomic::Ordering::Relaxed) {
                    warn!(
                        service_entry = %entry.name,
                        namespace = %entry.namespace,
                        port = port_spec.port,
                        "UDP egress materialization deferred to a later F3 §3.3 stage: \
                         UDP ServiceEntry ports are classified but not yet materialized \
                         as egress listeners (no UDP capture/egress datapath in this stage)."
                    );
                }
                continue;
            }

            let Some(backend_scheme) = egress_backend_scheme(port_spec.protocol) else {
                // Defensive: every AppProtocol variant maps to a concrete
                // scheme today (HTTP-family or stream-family). Future
                // protocol additions that haven't been classified land
                // here and get skipped with a warning instead of panicking.
                warn!(
                    service_entry = %entry.name,
                    namespace = %entry.namespace,
                    port = port_spec.port,
                    protocol = ?port_spec.protocol,
                    "Skipping ServiceEntry port for egress gateway: unknown protocol classification"
                );
                continue;
            };

            if egress_is_stream_protocol(port_spec.protocol) {
                if !egress_stream_enabled {
                    warn!(
                        service_entry = %entry.name,
                        namespace = %entry.namespace,
                        port = port_spec.port,
                        protocol = ?port_spec.protocol,
                        "Skipping stream egress ServiceEntry port: stream-family egress is \
                         disabled. Set FERRUM_MESH_EGRESS_STREAM_ENABLED=true to materialize \
                         per-port stream egress listeners (they terminate SVID-mTLS and run \
                         mesh_authz by default)."
                    );
                    continue;
                }
                build_stream_egress_for_entry(
                    entry,
                    port_spec,
                    backend_scheme,
                    namespace,
                    now,
                    mesh_reserved_ports,
                    egress_stream_allow_plaintext,
                    &mut materialized_stream_ports,
                    &mut proxies,
                    &mut upstreams,
                );
            } else {
                build_http_egress_for_entry(
                    entry,
                    port_spec,
                    backend_scheme,
                    namespace,
                    now,
                    &mut materialized_http_hosts,
                    &mut proxies,
                    &mut upstreams,
                );
            }
        }
    }

    (proxies, upstreams)
}

/// HTTP-family egress materialization branch. One proxy per host, host-routed
/// off the shared egress listener (15090). Each host admits only the first
/// port we see for it — host-only routing can't disambiguate ports.
#[allow(clippy::too_many_arguments)]
fn build_http_egress_for_entry(
    entry: &ServiceEntry,
    port_spec: &crate::modes::mesh::config::ServicePort,
    backend_scheme: BackendScheme,
    namespace: &str,
    now: chrono::DateTime<chrono::Utc>,
    materialized_http_hosts: &mut std::collections::HashSet<String>,
    proxies: &mut Vec<Proxy>,
    upstreams: &mut Vec<Upstream>,
) {
    let proxy_hosts: Vec<&String> = entry
        .hosts
        .iter()
        .filter(|host| !materialized_http_hosts.contains(*host))
        .collect();
    if proxy_hosts.is_empty() {
        warn!(
            service_entry = %entry.name,
            namespace = %entry.namespace,
            port = port_spec.port,
            "Skipping egress ServiceEntry port because its hosts were already materialized as HTTP-family"
        );
        return;
    }

    // Honor a numeric ServiceEntry `targetPort` for the backend (the proxy/
    // upstream IDs below stay keyed on the service `port`). A numeric targetPort
    // also overrides the per-endpoint named port map for STATIC endpoints, so
    // pass NO port name in that case — otherwise the static path requires each
    // endpoint to carry a matching `ports[name]` entry and ignores the resolved
    // targetPort. A named/absent targetPort keeps the endpoint port map.
    let (backend_port, backend_port_name) =
        match resolve_target_port(port_spec.target_port.as_ref(), &[]) {
            Some(resolved) => (resolved, None),
            None => (port_spec.port, port_spec.name.clone()),
        };
    for host in proxy_hosts {
        let targets = build_egress_upstream_targets(
            entry,
            host,
            port_spec.port,
            backend_port,
            &backend_port_name,
        );

        if targets.is_empty() {
            debug!(
                service_entry = %entry.name,
                host = %host,
                port = port_spec.port,
                "Skipping egress host with no resolvable targets"
            );
            continue;
        }

        materialized_http_hosts.insert(host.clone());

        let upstream_id =
            mesh_egress_upstream_id(&entry.namespace, &entry.name, host, port_spec.port);

        upstreams.push(build_egress_upstream(&upstream_id, namespace, targets, now));

        let proxy_id = mesh_egress_proxy_id(&entry.namespace, &entry.name, host, port_spec.port);
        let proxy = egress_gateway_proxy(
            &proxy_id,
            host,
            namespace,
            Some(backend_scheme),
            &upstream_id,
            now,
        );
        proxies.push(proxy);
    }
}

/// Stream-family (TCP / UDP) egress materialization branch. One stream proxy
/// per ServiceEntry port, listening on the entry's own port number so that
/// sidecar outbound capture routes traffic to the same destination port the
/// workload was already dialing. The proxy chooses the first host in the
/// entry's `hosts` list as the upstream target identity (DNS resolution
/// flow) or every endpoint address (static resolution flow). Additional
/// hosts on the same entry / port are ignored — a raw L4 listener cannot
/// distinguish hosts (no SNI for plain TCP/UDP), so operators should split
/// multi-host external services into one ServiceEntry per host.
#[allow(clippy::too_many_arguments)]
fn build_stream_egress_for_entry(
    entry: &ServiceEntry,
    port_spec: &crate::modes::mesh::config::ServicePort,
    backend_scheme: BackendScheme,
    namespace: &str,
    now: chrono::DateTime<chrono::Utc>,
    mesh_reserved_ports: &std::collections::HashSet<u16>,
    allow_plaintext: bool,
    materialized_stream_ports: &mut std::collections::HashSet<u16>,
    proxies: &mut Vec<Proxy>,
    upstreams: &mut Vec<Upstream>,
) {
    if port_spec.port == 0 {
        warn!(
            service_entry = %entry.name,
            namespace = %entry.namespace,
            protocol = ?port_spec.protocol,
            "Skipping stream egress ServiceEntry port 0: stream proxy listen_port must be >= 1"
        );
        return;
    }

    if mesh_reserved_ports.contains(&port_spec.port) {
        warn!(
            service_entry = %entry.name,
            namespace = %entry.namespace,
            port = port_spec.port,
            protocol = ?port_spec.protocol,
            "Skipping stream egress ServiceEntry port: collides with a mesh gateway listener port \
             (would fail to bind at runtime). Operators should choose a different ServiceEntry \
             port or relocate the egress gateway listener."
        );
        return;
    }

    if materialized_stream_ports.contains(&port_spec.port) {
        warn!(
            service_entry = %entry.name,
            namespace = %entry.namespace,
            port = port_spec.port,
            protocol = ?port_spec.protocol,
            "Skipping stream egress ServiceEntry port: another ServiceEntry already \
             materialized a stream proxy on this listen_port"
        );
        return;
    }

    // Stream-family proxies route by port, not by host, so we materialize at
    // most one proxy per (entry, port) — using the first host as the upstream
    // target identity (DNS) or all endpoints (Static). Multi-host stream
    // entries are not splittable at the L4 listener boundary.
    let representative_host = match entry.hosts.first() {
        Some(host) => host,
        None => {
            // Guarded above by `entry.hosts.is_empty()`; defensive only.
            return;
        }
    };

    // Honor a numeric ServiceEntry `targetPort` for the backend dial port while
    // the listener, proxy/upstream IDs, and port-dedup stay keyed on the service
    // `port`. Mirrors the HTTP egress branch; without it a TCP ServiceEntry like
    // `number: 5432, targetPort: 15432` would bind 5432 but dial 5432. A numeric
    // targetPort also overrides the per-endpoint named port map for STATIC
    // endpoints, so pass NO port name in that case — otherwise
    // `build_egress_upstream_targets` requires each endpoint to carry a matching
    // `ports[name]` entry and ignores the resolved targetPort.
    let (backend_port, backend_port_name) =
        match resolve_target_port(port_spec.target_port.as_ref(), &[]) {
            Some(resolved) => (resolved, None),
            None => (port_spec.port, port_spec.name.clone()),
        };
    let targets = build_egress_upstream_targets(
        entry,
        representative_host,
        port_spec.port,
        backend_port,
        &backend_port_name,
    );

    if targets.is_empty() {
        debug!(
            service_entry = %entry.name,
            host = %representative_host,
            port = port_spec.port,
            protocol = ?port_spec.protocol,
            "Skipping stream egress port with no resolvable targets"
        );
        return;
    }

    materialized_stream_ports.insert(port_spec.port);

    let upstream_id = mesh_egress_upstream_id(
        &entry.namespace,
        &entry.name,
        representative_host,
        port_spec.port,
    );
    upstreams.push(build_egress_upstream(&upstream_id, namespace, targets, now));

    let proxy_id = mesh_egress_proxy_id(
        &entry.namespace,
        &entry.name,
        representative_host,
        port_spec.port,
    );
    let proxy = stream_egress_gateway_proxy(
        &proxy_id,
        representative_host,
        namespace,
        backend_scheme,
        port_spec.port,
        port_spec.protocol,
        &upstream_id,
        allow_plaintext,
        now,
    );
    proxies.push(proxy);
}

/// Shared upstream constructor used by both HTTP- and stream-family egress
/// materialization. Keeps the proxy/upstream pair fields in sync — any new
/// upstream field added here flows to both materialization paths.
fn build_egress_upstream(
    upstream_id: &str,
    namespace: &str,
    targets: Vec<UpstreamTarget>,
    now: chrono::DateTime<chrono::Utc>,
) -> Upstream {
    Upstream {
        id: upstream_id.to_string(),
        name: Some(upstream_id.to_string()),
        namespace: namespace.to_string(),
        targets,
        algorithm: LoadBalancerAlgorithm::RoundRobin,
        hash_on: None,
        hash_on_cookie_config: None,
        health_checks: egress_health_checks(),
        service_discovery: None,
        subsets: None,
        port_overrides: HashMap::new(),
        source_locality: None,
        locality_lb_strict: false,
        locality_lb_setting: None,
        backend_tls_client_cert_path: None,
        backend_tls_client_key_path: None,
        backend_tls_verify_server_cert: true,
        backend_tls_server_ca_cert_path: None,
        backend_tls_sni: None,
        backend_tls_san_allow_list: Vec::new(),
        resolved_subset_tls: HashMap::new(),
        dispatch_port_override_fallback: None,
        api_spec_id: None,
        created_at: now,
        updated_at: now,
    }
}

fn egress_health_checks() -> Option<HealthCheckConfig> {
    Some(HealthCheckConfig {
        active: None,
        passive: Some(PassiveHealthCheck::default()),
    })
}

/// Build upstream targets from a `ServiceEntry`. When the entry uses static
/// resolution with explicit endpoints, those addresses become targets. When
/// endpoints are empty (DNS or None resolution), each host becomes a target.
fn build_egress_upstream_targets(
    entry: &ServiceEntry,
    host: &str,
    service_port: u16,
    backend_port: u16,
    port_name: &Option<String>,
) -> Vec<UpstreamTarget> {
    if entry.resolution == Resolution::Static && !entry.endpoints.is_empty() {
        entry
            .endpoints
            .iter()
            .filter_map(|ep| {
                // Named endpoint ports must be present on each endpoint. Falling
                // back to the ServiceEntry port would route to an unrelated
                // service when endpoint port maps are partial.
                let target_port = match port_name.as_ref() {
                    Some(name) => ep.ports.get(name).copied(),
                    None => Some(backend_port),
                }?;

                // Copy the ServiceEntry endpoint's operator-authored labels as
                // target tags, but STRIP the reserved `mesh.*` namespace first so a
                // hand-authored `mesh.remote`/`mesh.hbone`/… label cannot forge a
                // mesh provenance/transport marker the data plane owns.
                let mut tags = ep.labels.clone();
                crate::modes::mesh::multicluster::strip_reserved_mesh_tags(&mut tags);
                Some(UpstreamTarget {
                    host: ep.address.clone(),
                    port: target_port,
                    service_port_policy_key: Some(service_port),
                    weight: 1,
                    tags,
                    locality: None,
                    path: None,
                })
            })
            .collect()
    } else {
        // DNS or None resolution: keep each host's proxy pinned to that host so
        // SNI/Host expectations cannot be crossed by load balancing.
        vec![UpstreamTarget {
            host: host.to_string(),
            port: backend_port,
            service_port_policy_key: Some(service_port),
            weight: 1,
            tags: std::collections::HashMap::new(),
            locality: None,
            path: None,
        }]
    }
}

/// Determine the backend scheme from the ServiceEntry port protocol.
///
/// HTTP-family protocols (`Http`, `Https/Tls`, `Http2`, `Grpc`, `Unknown`) map
/// to `Http` / `Https` so the egress gateway terminates inbound mTLS and
/// re-emits HTTP-family traffic to the external backend. Stream-family
/// protocols (`Tcp`, `Udp`, `Mongo`, `Redis`, `Mysql`, `Postgres`) map to
/// `BackendScheme::Tcp` / `BackendScheme::Udp` and are materialized as raw L4
/// stream proxies via [`build_stream_egress_for_entry`]; protocol-aware
/// mediation (e.g., Mongo / Redis wire decode) is intentionally out of scope
/// and tracked separately as T5-C.
///
/// INTENTIONAL divergence from the in-mesh passthrough treatment of `Tls`: an
/// IN-MESH `Tls` service port is opaque-byte passthrough (`service_tcp_stream_ports`
/// — the captured original destination selects the destination service and the
/// app's own TLS is preserved end to end, never terminated by the mesh). At the
/// EGRESS gateway, `Tls` instead maps to `Https` (HTTP-family) because the
/// egress gateway is a terminate-and-re-encrypt boundary: it terminates the
/// in-mesh SVID-mTLS from the sidecar and ORIGINATES a fresh TLS connection to
/// the external backend (`backend_tls_verify_server_cert: true` in
/// `egress_gateway_proxy`). Opaque SNI passthrough to an external host (no
/// re-encryption) is not an egress-gateway capability today; if that is ever
/// needed it would be a distinct stream-family egress mode, not a remap of this
/// scheme. See #1727.
fn egress_backend_scheme(protocol: AppProtocol) -> Option<BackendScheme> {
    match protocol {
        AppProtocol::Tls | AppProtocol::Http2 | AppProtocol::Grpc => Some(BackendScheme::Https),
        AppProtocol::Http | AppProtocol::Unknown => Some(BackendScheme::Http),
        AppProtocol::Udp => Some(BackendScheme::Udp),
        AppProtocol::Tcp
        | AppProtocol::Mongo
        | AppProtocol::Redis
        | AppProtocol::Mysql
        | AppProtocol::Postgres => Some(BackendScheme::Tcp),
    }
}

/// True when the ServiceEntry protocol should materialize a stream-family
/// (TCP / UDP) egress proxy rather than an HTTP-family one. Stream proxies
/// route on `listen_port` rather than `hosts`, so the materializer uses a
/// distinct port-dedup path and binds one listener per ServiceEntry port.
fn egress_is_stream_protocol(protocol: AppProtocol) -> bool {
    matches!(
        protocol,
        AppProtocol::Tcp
            | AppProtocol::Udp
            | AppProtocol::Mongo
            | AppProtocol::Redis
            | AppProtocol::Mysql
            | AppProtocol::Postgres
    )
}

/// Pre-interned protocol label used in `Proxy.name` (and consumed by
/// transaction logs / metrics) so the stream egress materialization stays
/// allocation-free per call. The same `&'static str` convention is used
/// by mesh outbound enforcement (T5-B sibling PR) so observability stays
/// consistent across HTTP / stream egress.
fn egress_app_protocol_label(protocol: AppProtocol) -> &'static str {
    match protocol {
        AppProtocol::Http => "http",
        AppProtocol::Http2 => "http2",
        AppProtocol::Grpc => "grpc",
        AppProtocol::Tls => "tls",
        AppProtocol::Tcp => "tcp",
        AppProtocol::Udp => "udp",
        AppProtocol::Mongo => "mongo",
        AppProtocol::Redis => "redis",
        AppProtocol::Mysql => "mysql",
        AppProtocol::Postgres => "postgres",
        AppProtocol::Unknown => "unknown",
    }
}

/// Construct a single egress gateway proxy. Mirrors `east_west_gateway_proxy`
/// in struct construction style but uses HTTP-family settings (host-only
/// routing, no passthrough; the mesh listener owns frontend mTLS termination.
fn egress_gateway_proxy(
    id: &str,
    host: &str,
    namespace: &str,
    backend_scheme: Option<BackendScheme>,
    upstream_id: &str,
    now: chrono::DateTime<chrono::Utc>,
) -> Proxy {
    Proxy {
        id: id.to_string(),
        name: Some(format!("mesh egress {host}")),
        namespace: namespace.to_string(),
        hosts: vec![host.to_string()],
        listen_path: None,
        backend_scheme,
        dispatch_kind: Default::default(),
        backend_host: String::new(),
        backend_port: 0,
        backend_path: None,
        strip_listen_path: false,
        preserve_host_header: true,
        backend_connect_timeout_ms: 30_000,
        backend_read_timeout_ms: 30_000,
        backend_write_timeout_ms: 30_000,
        backend_tls_client_cert_path: None,
        backend_tls_client_key_path: None,
        backend_tls_verify_server_cert: true,
        backend_tls_server_ca_cert_path: None,
        resolved_tls: BackendTlsConfig::default(),
        dispatch_port_overrides: None,
        dispatch_port_override_fallback: None,
        dns_override: None,
        dns_cache_ttl_seconds: None,
        auth_mode: Default::default(),
        plugins: Vec::<PluginAssociation>::new(),
        pool_idle_timeout_seconds: None,
        pool_enable_http_keep_alive: None,
        pool_enable_http2: None,
        pool_tcp_keepalive_seconds: None,
        pool_http2_keep_alive_interval_seconds: None,
        pool_http2_keep_alive_timeout_seconds: None,
        pool_http2_initial_stream_window_size: None,
        pool_http2_initial_connection_window_size: None,
        pool_http2_adaptive_window: None,
        pool_http2_max_frame_size: None,
        pool_http2_max_concurrent_streams: None,
        pool_http3_connections_per_backend: None,
        h2_upgrade_policy: None,
        pool_max_requests_per_connection: None,
        // Derived-only: projected from DestinationRule port overrides at
        // dispatch time via `resolve_effective_proxy_for_target`; a
        // freshly-materialized mesh proxy starts at `None`.
        pool_http1_max_pending_requests: None,
        upstream_id: Some(upstream_id.to_string()),
        upstream_subset: None,
        api_spec_id: None,
        circuit_breaker: None,
        retry: None,
        response_body_mode: ResponseBodyMode::Stream,
        listen_port: None,
        frontend_tls: false,
        passthrough: false,
        udp_idle_timeout_seconds: 60,
        udp_max_response_amplification_factor: None,
        stream_proxy_protocol: None,
        tcp_idle_timeout_seconds: None,
        websocket_idle_timeout_seconds: None,
        allowed_methods: None,
        allowed_ws_origins: Vec::new(),
        created_at: now,
        updated_at: now,
    }
}

/// Construct a stream-family (TCP / UDP / TCP+TLS / UDP+DTLS) egress gateway
/// proxy. Unlike `egress_gateway_proxy` (HTTP-family, host-routed off the
/// shared 15090 listener), the stream variant routes by `listen_port`, owns
/// its own listener bound to the ServiceEntry's destination port, and has
/// `hosts: []` / `listen_path: None` per the stream-family proxy contract
/// (CLAUDE.md "Proxy hosts/listen_path/listen_port contract").
///
/// The protocol tag is stamped onto `Proxy.name` for observability (transaction
/// logs surface the proxy name); the wire-level dispatch is identical for all
/// stream variants and uses `BackendScheme::Tcp` (TCP-based protocols) per
/// `egress_backend_scheme`. Protocol-aware mediation (Mongo / Redis wire
/// inspection) is tracked separately as T5-C.
#[allow(clippy::too_many_arguments)]
fn stream_egress_gateway_proxy(
    id: &str,
    representative_host: &str,
    namespace: &str,
    backend_scheme: BackendScheme,
    listen_port: u16,
    protocol: AppProtocol,
    upstream_id: &str,
    allow_plaintext: bool,
    now: chrono::DateTime<chrono::Utc>,
) -> Proxy {
    let protocol_label = egress_app_protocol_label(protocol);
    Proxy {
        id: id.to_string(),
        name: Some(format!(
            "mesh egress {protocol_label} {representative_host}:{listen_port}"
        )),
        namespace: namespace.to_string(),
        // Stream-family proxies MUST NOT set `hosts` (route key is
        // `listen_port`). See `validate_stream_proxies()` in
        // `src/config/types.rs`.
        hosts: Vec::new(),
        listen_path: None,
        backend_scheme: Some(backend_scheme),
        dispatch_kind: Default::default(),
        backend_host: String::new(),
        backend_port: 0,
        backend_path: None,
        strip_listen_path: false,
        preserve_host_header: false,
        backend_connect_timeout_ms: 30_000,
        backend_read_timeout_ms: 30_000,
        backend_write_timeout_ms: 30_000,
        backend_tls_client_cert_path: None,
        backend_tls_client_key_path: None,
        backend_tls_verify_server_cert: true,
        backend_tls_server_ca_cert_path: None,
        resolved_tls: BackendTlsConfig::default(),
        dispatch_port_overrides: None,
        dispatch_port_override_fallback: None,
        dns_override: None,
        dns_cache_ttl_seconds: None,
        auth_mode: Default::default(),
        plugins: Vec::<PluginAssociation>::new(),
        pool_idle_timeout_seconds: None,
        pool_enable_http_keep_alive: None,
        pool_enable_http2: None,
        pool_tcp_keepalive_seconds: None,
        pool_http2_keep_alive_interval_seconds: None,
        pool_http2_keep_alive_timeout_seconds: None,
        pool_http2_initial_stream_window_size: None,
        pool_http2_initial_connection_window_size: None,
        pool_http2_adaptive_window: None,
        pool_http2_max_frame_size: None,
        pool_http2_max_concurrent_streams: None,
        pool_http3_connections_per_backend: None,
        h2_upgrade_policy: None,
        pool_max_requests_per_connection: None,
        // Derived-only: projected from DestinationRule port overrides at
        // dispatch time via `resolve_effective_proxy_for_target`; a
        // freshly-materialized mesh proxy starts at `None`.
        pool_http1_max_pending_requests: None,
        upstream_id: Some(upstream_id.to_string()),
        upstream_subset: None,
        api_spec_id: None,
        circuit_breaker: None,
        retry: None,
        response_body_mode: ResponseBodyMode::Stream,
        listen_port: Some(listen_port),
        // Stream egress proxies own their own per-port listener (e.g., 27017
        // for Mongo) and forward to the external backend with
        // `BackendScheme::Tcp`. They are NOT raw SNI passthrough (that's the
        // east-west gateway flow) — passthrough is false so the bytes pass
        // through the regular TCP proxy pipeline (idle timeouts, transaction
        // logging, plugin `on_stream_connect` admission, etc.) rather than
        // `splice(2)` between sockets.
        //
        // By default `frontend_tls: true`: the per-port stream listener
        // terminates SVID-mTLS using the SAME mesh-inbound `ServerConfig`
        // (server identity = gateway SVID leaf+key, peer verifier = SPIFFE
        // against the trust bundle) that backs the egress 15090 HTTP listener
        // — it is shared with the listener manager via
        // `set_frontend_tls_config`/`swap_frontend_tls_config`. The injected
        // `__mesh_spiffe_identity` stream hook then extracts the peer SPIFFE
        // id from the verified client cert and `__mesh_authz` enforces policy
        // at accept, BEFORE the external backend is dialed, so stream egress
        // gets the same authn/z as HTTP egress. Fail-closed by construction:
        // if no mTLS `ServerConfig` is loaded, the stream listener manager
        // DEFERS the bind (never binds plaintext) — mirroring the inbound
        // posture (`enforce_mesh_inbound_fail_closed`).
        //
        // `allow_plaintext` (FERRUM_MESH_EGRESS_STREAM_ALLOW_PLAINTEXT)
        // restores the legacy plaintext + unauthenticated listener for
        // operators who genuinely need it (a loud startup warning is emitted).
        frontend_tls: !allow_plaintext,
        passthrough: false,
        udp_idle_timeout_seconds: 60,
        udp_max_response_amplification_factor: None,
        stream_proxy_protocol: None,
        tcp_idle_timeout_seconds: None,
        websocket_idle_timeout_seconds: None,
        allowed_methods: None,
        allowed_ws_origins: Vec::new(),
        created_at: now,
        updated_at: now,
    }
}

fn mesh_egress_proxy_id(namespace: &str, name: &str, host: &str, port: u16) -> String {
    format!(
        "mesh-egress-{}-{}-{}-{port}",
        sanitize_egress_host_id_part(namespace),
        sanitize_egress_host_id_part(name),
        sanitize_egress_host_id_part(host)
    )
}

fn mesh_egress_upstream_id(namespace: &str, name: &str, host: &str, port: u16) -> String {
    format!(
        "mesh-egress-up-{}-{}-{}-{port}",
        sanitize_egress_host_id_part(namespace),
        sanitize_egress_host_id_part(name),
        sanitize_egress_host_id_part(host)
    )
}

/// INJECTIVE encoder for the namespace / name / host parts of an egress
/// proxy/upstream id. Distinct inputs ALWAYS produce distinct outputs, AND the
/// output never contains the segment delimiter `-`, so the assembled id
/// `mesh-egress-{ns}-{name}-{host}-{port}` is unambiguous: `materialize_*`
/// merges/matches proxies/upstreams by id, so two ServiceEntries that mapped
/// to the same id would silently overwrite one another (and cross-apply each
/// other's targetPort/port policy). K8s DNS-1123 forbids the offending characters in
/// ns/name/host, but the FILE mesh-config path does not validate them.
///
/// Encoding (alphabet `[A-Za-z0-9_]`, no `-`): an ASCII alphanumeric is emitted
/// verbatim; every other character — INCLUDING a literal `_` — becomes a
/// `_`-delimited token. `_` is the sole escape introducer, so it is itself
/// escaped, keeping the map injective:
///   `.`→`_dot_`  `-`→`_dash_`  `/`→`_slash_`  `*`→`_star_`  `_`→`_us_`
///   any other char → `_u<hex>_` (lowercase Unicode scalar, `_`-delimited).
/// No run-collapsing and no trimming (the old token scheme did both, which is
/// exactly what made `-`/`dash` and `a-b`/`a`+`b` collide). The `_`-delimited
/// hex is self-terminating because hex digits are `[0-9a-f]` and the literal-`_`
/// token (`us`) starts with the non-hex letter `s`, so `_us_` and `_u<hex>_`
/// never overlap. An empty input maps to `_empty_` — a token-shaped placeholder
/// no input can produce (`empty` is not a valid token after `_`), so it cannot
/// collide with a literal segment (`any`/`empty`/… all encode to themselves).
fn sanitize_egress_host_id_part(value: &str) -> String {
    if value.is_empty() {
        return "_empty_".to_string();
    }
    let mut out = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '.' => out.push_str("_dot_"),
            '-' => out.push_str("_dash_"),
            '/' => out.push_str("_slash_"),
            '*' => out.push_str("_star_"),
            '_' => out.push_str("_us_"),
            ch if ch.is_ascii_alphanumeric() => out.push(ch),
            ch => {
                out.push_str("_u");
                out.push_str(&format!("{:x}", ch as u32));
                out.push('_');
            }
        }
    }
    out
}

fn node_waypoint_route_upstream_for_authz(upstream_id: &str) -> bool {
    upstream_id.starts_with("istio-vs-upstream-")
        || upstream_id.starts_with("gwapi-route-upstream-")
}

fn push_node_waypoint_authz_cluster_domain(
    domains: &mut Vec<String>,
    seen: &mut HashSet<String>,
    value: &str,
) {
    let domain = value.trim().trim_matches('.').to_ascii_lowercase();
    if !domain.is_empty() && seen.insert(domain.clone()) {
        domains.push(domain);
    }
}

fn node_waypoint_authz_cluster_domains(primary_cluster_domain: &str) -> Vec<String> {
    let mut domains = Vec::new();
    let mut seen = HashSet::new();
    push_node_waypoint_authz_cluster_domain(&mut domains, &mut seen, primary_cluster_domain);
    let k8s_cluster_domain = resolve_ferrum_var("FERRUM_K8S_CLUSTER_DOMAIN")
        .unwrap_or_else(|| dns_proxy::DEFAULT_CLUSTER_DOMAIN.to_string());
    push_node_waypoint_authz_cluster_domain(&mut domains, &mut seen, &k8s_cluster_domain);
    domains
}

fn node_waypoint_assertor_spiffe_ids(mesh_slice: &MeshSlice) -> Vec<String> {
    mesh_slice
        .node_waypoint_assertors
        .iter()
        .map(|spiffe_id| spiffe_id.as_str().to_string())
        .collect()
}

fn mesh_managed_trusted_hbone_assertors(
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) -> Option<Vec<String>> {
    if !runtime.trusted_hbone_assertors.is_empty() {
        return Some(runtime.trusted_hbone_assertors.clone());
    }
    if runtime.node_waypoint_secured_transport_required() {
        return Some(node_waypoint_assertor_spiffe_ids(mesh_slice));
    }
    None
}

fn inject_mesh_global_plugins(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) {
    ensure_global_plugin(
        config,
        MESH_SPIFFE_IDENTITY_PLUGIN_ID,
        "spiffe_identity",
        serde_json::json!({}),
        &runtime.namespace,
    );
    let trust_domain_aliases: Vec<String> = runtime
        .trust_domain_aliases
        .iter()
        .map(|td| td.as_str().to_string())
        .collect();
    let operator_mesh_authz_config = config
        .plugin_configs
        .iter()
        .find(|plugin| {
            plugin.scope == PluginScope::Global
                && plugin.plugin_name == "mesh_authz"
                && plugin.id != MESH_AUTHZ_PLUGIN_ID
        })
        .map(|plugin| plugin.config.clone());
    let operator_mesh_authz_present = operator_mesh_authz_config.is_some();
    let operator_mesh_authz_trusted_assertors = operator_mesh_authz_config
        .as_ref()
        .and_then(|cfg| cfg.get("trusted_hbone_assertors").cloned());
    let mesh_managed_trusted_assertors = mesh_managed_trusted_hbone_assertors(runtime, mesh_slice);
    let mut mesh_authz_config = serde_json::json!({
        "mesh_slice": mesh_slice,
        "cluster_domain": runtime.cluster_domain,
        "trust_domain_aliases": trust_domain_aliases,
        "per_pod_policy_scoping": runtime.topology == MeshTopology::NodeWaypoint,
        "ambient_udp_source_scoping": runtime.topology.uses_ambient_udp_source_scoping(),
    });
    if runtime.topology == MeshTopology::NodeWaypoint {
        mesh_authz_config["cluster_domains"] =
            serde_json::json!(node_waypoint_authz_cluster_domains(&runtime.cluster_domain));
        let route_upstreams: Vec<_> = config
            .upstreams
            .iter()
            .filter(|upstream| node_waypoint_route_upstream_for_authz(&upstream.id))
            .map(|upstream| {
                serde_json::json!({
                    "id": upstream.id.clone(),
                    "namespace": upstream.namespace.clone(),
                    "targets": upstream.targets.iter().map(|target| {
                        let service_port = target.service_port_policy_key.or_else(|| {
                            target
                                .tags
                                .get(UPSTREAM_TARGET_SERVICE_PORT_TAG)
                                .and_then(|value| value.parse::<u16>().ok())
                                .filter(|port| *port != 0)
                        });
                        let mut target_config = serde_json::json!({
                            "host": target.host.clone(),
                            "port": target.port,
                        });
                        if let Some(service_port) = service_port {
                            target_config["service_port"] = serde_json::json!(service_port);
                        }
                        if let Some(namespace) =
                            target.tags.get(UPSTREAM_TARGET_SERVICE_NAMESPACE_TAG)
                        {
                            target_config["service_namespace"] =
                                serde_json::json!(namespace.clone());
                        }
                        if let Some(name) = target.tags.get(UPSTREAM_TARGET_SERVICE_NAME_TAG) {
                            target_config["service_name"] = serde_json::json!(name.clone());
                        }
                        target_config
                    }).collect::<Vec<_>>(),
                })
            })
            .collect();
        mesh_authz_config["node_waypoint_route_upstreams"] = serde_json::json!(route_upstreams);
    }
    // Only thread the mesh-managed assertor list when it is explicit or when
    // an identity-backed NodeWaypoint received the CP-derived exact assertor
    // inventory. A derived empty list intentionally disables baggage rewriting
    // so production NodeWaypoint does not fall back to the bare service-account
    // defaults or to namespace-scoped destination workload metadata.
    if let Some(assertors) = mesh_managed_trusted_assertors.as_ref() {
        mesh_authz_config["trusted_hbone_assertors"] = serde_json::Value::Array(
            assertors
                .iter()
                .map(|raw| serde_json::Value::String(raw.clone()))
                .collect(),
        );
    }
    ensure_global_plugin(
        config,
        MESH_AUTHZ_PLUGIN_ID,
        "mesh_authz",
        mesh_authz_config,
        &runtime.namespace,
    );

    // Outbound registry: inject the `mesh_outbound_registry` plugin when
    // either the slice (CRD path) OR the runtime env var declares
    // REGISTRY_ONLY. Both default to AllowAny (no plugin) so non-mesh
    // and permissive deployments pay zero per-request cost.
    let effective_outbound_policy = mesh_slice
        .outbound_traffic_policy
        .unwrap_or(runtime.outbound_traffic_policy);
    if matches!(
        effective_outbound_policy,
        crate::modes::mesh::config::OutboundTrafficPolicy::RegistryOnly
    ) {
        let registry = mesh_slice.build_known_destinations(&runtime.cluster_domain);
        let outbound_listen_ports = mesh_outbound_registry_listen_ports(runtime);
        if outbound_listen_ports.is_empty() {
            config
                .plugin_configs
                .retain(|p| p.id != MESH_OUTBOUND_REGISTRY_PLUGIN_ID);
        } else {
            let plugin_config = serde_json::json!({
                "registry": registry,
                "outbound_listen_ports": outbound_listen_ports,
                "reject_status": runtime.outbound_registry_reject_status,
                "namespace": runtime.namespace.clone(),
            });
            ensure_global_plugin(
                config,
                MESH_OUTBOUND_REGISTRY_PLUGIN_ID,
                "mesh_outbound_registry",
                plugin_config,
                &runtime.namespace,
            );
        }
    } else {
        // Remove any stale instance (e.g., operator flipped policy back).
        config
            .plugin_configs
            .retain(|p| p.id != MESH_OUTBOUND_REGISTRY_PLUGIN_ID);
    }

    // Merge applicable Telemetry resources (most specific scope wins per section).
    let merged_telemetry = merge_applicable_telemetry(mesh_slice);

    let mut workload_metrics_config = serde_json::json!({
        "node_id": runtime.node_id.clone(),
        "topology": runtime.topology.as_str(),
        "namespace": mesh_slice.namespace.clone(),
        "workload_spiffe_id": mesh_slice.workload_spiffe_id.clone(),
        "labels": mesh_slice.labels.clone(),
        "trust_domain_aliases": trust_domain_aliases,
    });
    // Mirror the EFFECTIVE mesh_authz assertor gate so telemetry source-identity
    // attribution honors HBONE baggage only from the same trusted assertors.
    // If an operator-managed global mesh_authz overrides the mesh-managed
    // instance, copy its `trusted_hbone_assertors` field verbatim (including
    // `[]`); if it omits the field, workload_metrics also omits it so both
    // plugins fall back to their shared defaults. Without an override, thread
    // the runtime/env list exactly as the mesh-managed mesh_authz config does.
    if let Some(value) = operator_mesh_authz_trusted_assertors {
        workload_metrics_config["trusted_hbone_assertors"] = value;
    } else if !operator_mesh_authz_present
        && let Some(assertors) = mesh_managed_trusted_assertors.as_ref()
    {
        workload_metrics_config["trusted_hbone_assertors"] = serde_json::Value::Array(
            assertors
                .iter()
                .map(|raw| serde_json::Value::String(raw.clone()))
                .collect(),
        );
    }
    // Apply ProxyConfig sampling as a baseline. The more granular Telemetry
    // resource below may override on the `sampling_percentage` key.
    if let Some(proxy_cfg) = mesh_slice.resolved_proxy_config()
        && let Some(sampling) = proxy_cfg.tracing_sampling
    {
        workload_metrics_config["sampling_percentage"] = serde_json::json!(sampling);
    }
    // Apply tracing config from Telemetry CRD
    if let Some(tracing) = &merged_telemetry.tracing {
        if let Some(sampling_percentage) = tracing.sampling_percentage {
            workload_metrics_config["sampling_percentage"] = serde_json::json!(sampling_percentage);
        }
        if !tracing.custom_tags.is_empty() {
            workload_metrics_config["custom_tags"] = serde_json::json!(tracing.custom_tags);
        }
        if !tracing.custom_header_tags.is_empty() {
            workload_metrics_config["custom_header_tags"] =
                serde_json::json!(tracing.custom_header_tags);
        }
        if tracing.disable_span_reporting.unwrap_or(false) {
            workload_metrics_config["span_reporting_disabled"] = serde_json::json!(true);
        }
        if !tracing.providers.is_empty() {
            // Keep provider config visible for introspection and propagation even
            // when span_reporting_disabled makes WorkloadMetrics skip exporters.
            workload_metrics_config["tracing_providers"] = serde_json::json!(tracing.providers);
        }
        // GAP-3F: project `Telemetry.tracing[].match.mode` into the plugin's
        // `direction_emit` so a single auto-injected workload_metrics instance
        // can serve both directions. Default (no explicit mode) preserves the
        // pre-GAP-3F SERVER-only emit behaviour.
        if let Some(mode) = tracing.mode {
            workload_metrics_config["direction_emit"] = serde_json::json!({
                "server": mode.emits_server(),
                "client": mode.emits_client(),
            });
        }
    }
    if let Some(metrics) = &merged_telemetry.metrics {
        workload_metrics_config["metrics"] = serde_json::json!(metrics);
    }
    ensure_global_plugin(
        config,
        MESH_WORKLOAD_METRICS_PLUGIN_ID,
        "workload_metrics",
        workload_metrics_config,
        &runtime.namespace,
    );
    inject_mesh_request_auth_plugin(config, runtime, mesh_slice);

    // Build access log config with optional filter from Telemetry CRD.
    // `None` means "access logging is explicitly disabled" — we retain-remove
    // any existing mesh access-log plugin and skip injection, but we MUST NOT
    // short-circuit the rest of inject_mesh_global_plugins (e.g. the bpf_metrics
    // branch below). Earlier versions used `return;` here, which silently
    // skipped bpf_metrics injection/cleanup on NodeWaypoint topology whenever
    // Telemetry CRD disabled access logging.
    //
    // The injected sink is `stdout_logging`: it serializes the same
    // transaction/stream summaries and honors the same `filter` config, and
    // writes through the non-blocking stdout writer rather than the tracing
    // fmt stack. The reserved ID stays `__mesh_access_log` so existing
    // injected plugins are updated in place across upgrades.
    let access_log_config: Option<serde_json::Value> = match &merged_telemetry.access_logging {
        Some(al) if !al.enabled => {
            config
                .plugin_configs
                .retain(|p| p.id != MESH_ACCESS_LOG_PLUGIN_ID);
            None
        }
        Some(al) => Some(match &al.filter {
            Some(filter) => serde_json::json!({ "filter": filter }),
            None => serde_json::json!({}),
        }),
        None => Some(serde_json::json!({})),
    };
    if let Some(cfg) = access_log_config {
        ensure_global_plugin(
            config,
            MESH_ACCESS_LOG_PLUGIN_ID,
            "stdout_logging",
            cfg,
            &runtime.namespace,
        );
    }

    // GAP-SC3: `__mesh_bpf_metrics` exposes BPF SOCK_OPS counters as
    // Prometheus metrics. Auto-inject only on `NodeWaypoint` topology;
    // other topologies don't run the SOCK_OPS BPF program, and emitting
    // always-zero counters from them would mislead operator dashboards.
    // Operators on other topologies can still inject the plugin
    // explicitly; this just controls the default-inject behavior.
    if runtime.topology == MeshTopology::NodeWaypoint {
        ensure_global_plugin(
            config,
            MESH_BPF_METRICS_PLUGIN_ID,
            "__mesh_bpf_metrics",
            serde_json::json!({}),
            &runtime.namespace,
        );
    } else {
        config
            .plugin_configs
            .retain(|p| p.id != MESH_BPF_METRICS_PLUGIN_ID);
    }
}

fn mesh_outbound_registry_listen_ports(runtime: &MeshRuntimeConfig) -> Vec<u16> {
    let mut ports: Vec<u16> = runtime
        .listener_plan()
        .into_iter()
        .filter(|listener| listener.direction == MeshTrafficDirection::Outbound)
        // Exclude the UDP TPROXY capture port (codex r1 P3): the outbound
        // registry enforces HTTP/stream egress that arrived through the TCP
        // `PlaintextCapture` listener, but the UDP capture socket is a
        // separate UDP-only sink. TCP and UDP can coexist on the same numeric
        // port, so including the UDP capture port here would make a regular
        // TCP/HTTP listener on that number be treated as mesh captured egress
        // and rejected against the registry even though it never arrived via
        // the TCP capture listener.
        .filter(|listener| listener.kind != MeshListenerKind::PlaintextUdpCapture)
        .filter_map(|listener| {
            let port = listener.addr.port();
            (port != 0).then_some(port)
        })
        .collect();
    ports.sort_unstable();
    ports.dedup();
    ports
}

/// Refresh the proxy-state mesh outbound enforcement slot from the latest
/// applied slice (T5-B). Called from the slice-apply loop after a slice
/// is accepted by `proxy_state.update_config`. Mirrors the HTTP plugin
/// auto-injection: when the effective policy is `RegistryOnly` AND the
/// runtime owns at least one mesh outbound capture port, the slot is
/// populated with the slice-derived registry; otherwise the slot is
/// cleared so the stream proxies fall through to `Decision::Skip` for
/// every connect.
fn refresh_mesh_outbound_enforcement(
    proxy_state: &ProxyState,
    runtime: &MeshRuntimeConfig,
    slice: &MeshSlice,
) {
    let effective_policy = slice
        .outbound_traffic_policy
        .unwrap_or(runtime.outbound_traffic_policy);
    let next = if matches!(
        effective_policy,
        crate::modes::mesh::config::OutboundTrafficPolicy::RegistryOnly
    ) {
        let ports = mesh_outbound_registry_listen_ports(runtime);
        crate::modes::mesh::outbound_enforcement::MeshOutboundEnforcement::from_slice(
            slice,
            &runtime.cluster_domain,
            runtime.namespace.clone(),
            ports,
            runtime.outbound_registry_reject_status,
        )
        .map(Arc::new)
    } else {
        None
    };
    proxy_state.mesh_outbound_enforcement.store(Arc::new(next));
}

/// Merge applicable `MeshTelemetryResource` entries by scope specificity.
///
/// More specific scopes (WorkloadSelector > Namespace > MeshWide) override
/// less specific ones per config section (tracing, metrics, access_logging
/// independently). Within the same scope level, later resources win.
fn merge_applicable_telemetry(mesh_slice: &MeshSlice) -> MeshTelemetryConfig {
    use crate::modes::mesh::config::scope_applies_to_workload;

    let mut applicable: Vec<(u8, &str, &str, &MeshTelemetryConfig)> = mesh_slice
        .telemetry_resources
        .iter()
        .filter(|t| scope_applies_to_workload(&t.scope, &mesh_slice.namespace, &mesh_slice.labels))
        .map(|t| {
            let specificity = match &t.scope {
                PolicyScope::MeshWide => 0,
                PolicyScope::Namespace { .. } => 1,
                PolicyScope::WorkloadSelector { .. } => 2,
            };
            (
                specificity,
                t.namespace.as_str(),
                t.name.as_str(),
                &t.config,
            )
        })
        .collect();

    // Sort by specificity ascending so more-specific overwrites less-specific.
    // Namespace/name tie-breaks make same-specificity merges deterministic
    // across informer delivery orders.
    applicable.sort_by(|left, right| (left.0, left.1, left.2).cmp(&(right.0, right.1, right.2)));

    let mut merged = MeshTelemetryConfig::default();
    for (_, _, _, config) in &applicable {
        if let Some(tracing) = &config.tracing {
            merge_tracing_config(&mut merged.tracing, tracing);
        }
        if config.metrics.is_some() {
            merged.metrics.clone_from(&config.metrics);
        }
        if config.access_logging.is_some() {
            merged.access_logging.clone_from(&config.access_logging);
        }
    }
    merged
}

fn merge_tracing_config(
    merged: &mut Option<crate::modes::mesh::config::MeshTracingConfig>,
    next: &crate::modes::mesh::config::MeshTracingConfig,
) {
    let current = merged.get_or_insert_with(|| crate::modes::mesh::config::MeshTracingConfig {
        mode: None,
        sampling_percentage: None,
        disable_span_reporting: None,
        custom_tags: HashMap::new(),
        custom_header_tags: HashMap::new(),
        providers: Vec::new(),
    });

    if next.mode.is_some() {
        current.mode = next.mode;
    }
    if next.sampling_percentage.is_some() {
        current.sampling_percentage = next.sampling_percentage;
    }
    if next.disable_span_reporting.is_some() {
        current.disable_span_reporting = next.disable_span_reporting;
    }
    current.custom_tags.extend(next.custom_tags.clone());
    current
        .custom_header_tags
        .extend(next.custom_header_tags.clone());
    if !next.providers.is_empty() {
        current.providers.clone_from(&next.providers);
    }
}

/// Inject a `jwks_auth` global plugin when the mesh slice carries applicable
/// `MeshRequestAuthentication` resources with JWT rules.
///
/// Istio semantics: RequestAuthentication is **permissive** — it declares
/// which JWTs are *valid*, not which are *required*. A request with no JWT
/// passes through. An invalid JWT is rejected. Enforcement (requiring a
/// JWT) comes from AuthorizationPolicy. So the plugin is configured with
/// `anonymous_on_missing_token: true`.
fn inject_mesh_request_auth_plugin(
    config: &mut GatewayConfig,
    runtime: &MeshRuntimeConfig,
    mesh_slice: &MeshSlice,
) {
    use crate::modes::mesh::config::scope_applies_to_workload;

    // FAIL CLOSED on an ambiguous shared-SPIFFE slice. When `labels_ambiguous`
    // is set, `mesh_slice.labels` is only the partial intersection of the
    // divergent candidates sharing this SPIFFE, NOT this workload's
    // authoritative labels, and `request_authentications` carries the
    // candidate-any superset (a JWT RequestAuthentication that matches only ONE
    // candidate rode in). Filtering solely by the partial intersection would
    // silently DROP such a selector-scoped RA, so a forged token for that issuer
    // would pass unvalidated — a fail-OPEN. Since we cannot prove the selector
    // does NOT apply to this workload, INCLUDE candidate-any selector-scoped RAs
    // the intersection cannot resolve so their JWT providers are still installed
    // (Istio RequestAuthentication stays permissive: a request with no token
    // passes; only a forged/invalid token for that issuer is rejected). A
    // non-ambiguous slice (unique SPIFFE / concrete labels / a DP that resolved
    // its authoritative labels) is enforcement-IDENTICAL: only the partial-
    // intersection branch runs. The operator pins
    // `FERRUM_MESH_WORKLOAD_LABELS` / `mesh_slice.labels` to clear the marker and
    // re-filter the superset deterministically.
    let mut included_fail_closed = false;
    let applicable: Vec<&MeshRequestAuthentication> = mesh_slice
        .request_authentications
        .iter()
        .filter(|ra| {
            if scope_applies_to_workload(&ra.scope, &mesh_slice.namespace, &mesh_slice.labels) {
                return true;
            }
            // Unresolvable candidate-only selector RA on an ambiguous slice:
            // include it fail-closed. Only WorkloadSelector scopes are at risk —
            // MeshWide always matched above, and Namespace resolves against the
            // authoritative `mesh_slice.namespace`, not the ambiguous labels. A
            // selector whose NAMESPACE does not match is also authoritatively
            // non-applicable (namespace is never ambiguous), so escalate ONLY on
            // label divergence within this workload's namespace.
            let unresolvable_selector = mesh_slice.labels_ambiguous
                && match &ra.scope {
                    crate::modes::mesh::config::PolicyScope::WorkloadSelector { selector } => {
                        selector
                            .namespace
                            .as_deref()
                            .is_none_or(|ns| ns == mesh_slice.namespace)
                    }
                    _ => false,
                };
            if unresolvable_selector {
                included_fail_closed = true;
            }
            unresolvable_selector
        })
        .collect();

    if included_fail_closed {
        warn!(
            "mesh RequestAuthentication: ambiguous shared-SPIFFE slice carries a candidate-only \
             selector RequestAuthentication the partial label intersection cannot resolve; \
             installing its JWT provider(s) (fail closed) so forged tokens cannot bypass \
             validation. Set FERRUM_MESH_WORKLOAD_LABELS / mesh_slice.labels to pin this \
             workload's identity for deterministic resolution"
        );
    }

    if applicable.is_empty() {
        // No applicable RequestAuthentication — remove any previously injected
        // mesh request auth plugin so it doesn't persist across config updates.
        config
            .plugin_configs
            .retain(|plugin| plugin.id != MESH_REQUEST_AUTH_PLUGIN_ID);
        return;
    }

    let mut providers = Vec::new();
    for ra in &applicable {
        for rule in &ra.jwt_rules {
            if let Some(provider) = build_jwks_provider_config(rule) {
                providers.push(provider);
            }
        }
    }

    if providers.is_empty() {
        config
            .plugin_configs
            .retain(|plugin| plugin.id != MESH_REQUEST_AUTH_PLUGIN_ID);
        return;
    }

    // jwks_auth already passes through requests with no token
    // (ExtractedCredential::Missing -> PluginResult::Continue), which matches
    // Istio's permissive RequestAuthentication semantics. No extra flag needed.
    //
    // `require_exp` defaults to the secure posture (true): tokens that omit
    // `exp` are rejected so they cannot live forever, satisfying the
    // "validate_exp = true" invariant. Some Istio issuers legitimately omit
    // `exp`, so operators can relax this with
    // `FERRUM_MESH_REQUEST_AUTH_REQUIRE_EXP=false`. Expiry *validation* stays
    // on regardless — a present-but-expired `exp` is always rejected.
    let jwks_config = serde_json::json!({
        "providers": providers,
        "require_exp": runtime.request_auth_require_exp,
        "emit_mesh_request_principal_metadata": true,
    });

    ensure_global_plugin(
        config,
        MESH_REQUEST_AUTH_PLUGIN_ID,
        "jwks_auth",
        jwks_config,
        &runtime.namespace,
    );
}

/// Build a single `jwks_auth` provider configuration from a [`MeshJwtRule`].
fn build_jwks_provider_config(rule: &MeshJwtRule) -> Option<serde_json::Value> {
    let mut provider = serde_json::json!({
        "issuer": rule.issuer,
        "forward_original_token": rule.forward_original_token,
    });

    if let Some(uri) = &rule.jwks_uri {
        provider["jwks_uri"] = serde_json::json!(uri);
    } else if let Some(jwks) = &rule.jwks {
        provider["jwks"] = serde_json::json!(jwks);
    } else {
        warn!(
            issuer = %rule.issuer,
            "Skipping MeshRequestAuthentication JWT rule with no jwks_uri or jwks"
        );
        return None;
    }

    if !rule.audiences.is_empty() {
        provider["audiences"] = serde_json::json!(rule.audiences);
    }

    if !rule.from_headers.is_empty() {
        provider["from_headers"] = serde_json::json!(rule.from_headers);
    }

    if !rule.from_params.is_empty() {
        provider["from_params"] = serde_json::json!(rule.from_params);
    }

    Some(provider)
}

fn ensure_global_plugin(
    config: &mut GatewayConfig,
    id: &str,
    plugin_name: &str,
    plugin_config: serde_json::Value,
    namespace: &str,
) {
    let now = chrono::Utc::now();
    let mesh_plugin = PluginConfig {
        id: id.to_string(),
        plugin_name: plugin_name.to_string(),
        namespace: namespace.to_string(),
        config: plugin_config,
        scope: PluginScope::Global,
        proxy_id: None,
        enabled: true,
        priority_override: None,
        api_spec_id: None,
        created_at: now,
        updated_at: now,
    };

    if let Some(existing) = config
        .plugin_configs
        .iter_mut()
        .find(|plugin| plugin.id == id)
    {
        *existing = mesh_plugin;
    } else if config
        .plugin_configs
        .iter()
        .any(|plugin| plugin.scope == PluginScope::Global && plugin.plugin_name == plugin_name)
    {
        // A user-managed global plugin of the same type is an explicit
        // operator override when plugin_configs are already present in the
        // GatewayConfig handed to mesh preparation. Native/xDS MeshSlice feeds
        // do not currently carry operator plugin_configs. Reserved
        // mesh-managed IDs still update above.
    } else {
        config.plugin_configs.push(mesh_plugin);
    }
}

pub async fn run(
    env_config: EnvConfig,
    shutdown_tx: tokio::sync::watch::Sender<bool>,
) -> Result<(), anyhow::Error> {
    let runtime = MeshRuntimeConfig::from_env_config(&env_config)
        .map_err(|e| anyhow::anyhow!("invalid mesh runtime configuration: {e}"))?;
    ensure_runtime_config_protocol_supported(&runtime)?;

    info!(
        node_id = %runtime.node_id,
        namespace = %runtime.namespace,
        topology = runtime.topology.as_str(),
        config_protocol = runtime.config_protocol.as_str(),
        inbound = %runtime.inbound_listen_addr,
        outbound = %runtime.outbound_listen_addr,
        hbone = %runtime.hbone_listen_addr,
        east_west_listen_port = runtime.east_west_listen_port,
        egress = %runtime.egress_listen_addr,
        cp_urls = runtime.cp_urls.len(),
        "Mesh mode starting"
    );

    // Deliberately a warning, not a refusal: the NodeWaypoint eBPF live gate
    // runs the production identity profile on this topology, and the
    // production identity guardrails (dev CA/attestor/no-identity refusals,
    // inbound mTLS fail-closed) all still apply. The warning exists so an
    // operator running an Experimental topology under the production flag has
    // an explicit, greppable signal of the maturity mismatch.
    if runtime.topology == MeshTopology::NodeWaypoint && crate::identity::production_mode() {
        warn!(
            topology = runtime.topology.as_str(),
            "FERRUM_MESH_TOPOLOGY=node_waypoint is an Experimental topology running under \
             FERRUM_MESH_PRODUCTION_MODE=true. Experimental surfaces are excluded from the GA \
             contract (docs/mesh_supported_matrix.md); production identity guardrails still \
             apply."
        );
    }

    // Configure the process-singleton policy-deny recorder before anything can
    // record into it. This is idempotent and a no-op on subsequent calls
    // (e.g., a restart-without-fork test harness) so we never wipe history
    // mid-process.
    crate::modes::mesh::policy_deny_log::configure_global_capacity(
        env_config.mesh_policy_deny_log_capacity,
    );

    let mesh_state = MeshRuntimeState::new();
    let federation_activation = FederationActivation::from_env_config(&env_config);

    let mut background_handles = Vec::new();
    if runtime.config_protocol == MeshConfigProtocol::File {
        // Localized file source: no control plane, so no CP/DP JWT secret and
        // no DP gRPC TLS machinery. The initial load is synchronous and
        // fail-closed — an unreadable or invalid mesh document refuses
        // startup, matching file-mode validation semantics. Subsequent SIGHUP
        // reloads keep the last good slice on error.
        let file_path = runtime.file_config_path.clone().ok_or_else(|| {
            anyhow::anyhow!(
                "FERRUM_MESH_FILE_CONFIG_PATH is required when FERRUM_MESH_CONFIG_PROTOCOL=file"
            )
        })?;
        let initial_slice = config_consumer::file_source::load_mesh_slice_from_file(
            std::path::Path::new(&file_path),
            runtime.mesh_slice_request(),
        )
        .with_context(|| format!("failed to load localized mesh config from '{file_path}'"))?;
        // Fail-closed beyond mesh-field validity: run the full slice→config
        // preparation (plugin injection, materialization, DestinationRule
        // projection — which can reject e.g. unloadable ISTIO_MUTUAL TLS
        // material) before installing the slice. The CP consumers tolerate a
        // rejected initial slice by waiting for the CP to push a fix; the
        // file source has no pusher, so a slice the runtime would reject must
        // refuse startup instead of hanging in the initial-config wait.
        let empty_federation_snapshot = federation::FederationSnapshot::default();
        gateway_config_from_mesh_slice_with_federation(
            &initial_slice,
            &runtime,
            Some(&empty_federation_snapshot),
            None,
            federation_activation,
        )
        .with_context(|| {
            format!("localized mesh config '{file_path}' failed runtime preparation")
        })?;
        let initial_version = initial_slice.version.clone();
        mesh_state.install_slice(initial_slice);
        let handle = tokio::spawn(
            config_consumer::file_source::start_mesh_file_source_with_shutdown(
                file_path.clone(),
                runtime.mesh_slice_request(),
                mesh_state.clone(),
                shutdown_tx.subscribe(),
            ),
        );
        background_handles.push(handle);
        info!(
            node_id = %runtime.node_id,
            namespace = %runtime.namespace,
            file_path = %file_path,
            mesh_slice_version = %initial_version,
            "Mesh mode initialized localized file config source (SIGHUP reloads)"
        );
    } else {
        let jwt_secret = GrpcJwtSecret::with_issuer(
            env_config.cp_dp_grpc_jwt_secret.clone().ok_or_else(|| {
                anyhow::anyhow!("FERRUM_CP_DP_GRPC_JWT_SECRET is required in mesh mode")
            })?,
            env_config.cp_dp_grpc_jwt_issuer.clone(),
        );
        let grpc_tls = build_dp_grpc_tls_config(&env_config, &runtime.cp_urls, "Mesh")?;
        let mesh_grpc_tls_reload_handle =
            crate::modes::grpc_tls_reload::start_dp_grpc_tls_reload_task(
                Arc::new(env_config.clone()),
                Arc::new(runtime.cp_urls.clone()),
                "Mesh",
                Some(shutdown_tx.subscribe()),
            );
        let grpc_tls_reload = mesh_grpc_tls_reload_handle.map(|handle| {
            let reload = DpGrpcTlsReload {
                env_config: Arc::new(env_config.clone()),
                label: "Mesh",
                revision_rx: handle.revision_rx,
            };
            background_handles.push(handle.watcher_handle);
            reload
        });

        if runtime.config_protocol == MeshConfigProtocol::Native {
            let client_config = runtime.native_client_config();
            let request = client_config.subscribe_request(crate::FERRUM_VERSION);
            let cp_urls = runtime.cp_urls.clone();
            let state = mesh_state.clone();
            let shutdown_rx = shutdown_tx.subscribe();
            let handle = tokio::spawn(
                config_consumer::native_client::start_native_mesh_client_with_shutdown(
                    cp_urls,
                    jwt_secret.clone(),
                    client_config,
                    state,
                    shutdown_rx,
                    grpc_tls.clone(),
                    grpc_tls_reload,
                ),
            );
            background_handles.push(handle);
            info!(
                node_id = %request.node_id,
                namespace = %request.namespace,
                cp_urls = runtime.cp_urls.len(),
                has_first_slice = mesh_state.has_first_slice(),
                "Mesh mode initialized native MeshSubscribe consumer"
            );
        } else {
            let xds_config = runtime.xds_client_config();
            let state = mesh_state.clone();
            let shutdown_rx = shutdown_tx.subscribe();
            let handle = tokio::spawn(config_consumer::xds_client::start_xds_client_with_shutdown(
                jwt_secret.clone(),
                xds_config,
                state,
                shutdown_rx,
                grpc_tls.clone(),
                grpc_tls_reload,
            ));
            background_handles.push(handle);
            info!(
                node_id = %runtime.node_id,
                namespace = %runtime.namespace,
                cp_urls = runtime.cp_urls.len(),
                has_first_slice = mesh_state.has_first_slice(),
                "Mesh mode initialized xDS ADS consumer"
            );
        }
    }
    let (bootstrap_config, initial_applied_mesh_slice) = wait_for_initial_mesh_config(
        &mesh_state,
        &runtime,
        federation_activation,
        shutdown_tx.subscribe(),
    )
    .await
    .context("mesh runtime stopped before receiving a valid initial mesh slice")?;
    info!(
        mesh_global_plugins = bootstrap_config.plugin_configs.len(),
        mesh_slice_version = %initial_applied_mesh_slice.version,
        "Mesh global plugin chain prepared from initial mesh slice"
    );

    serve_mesh_runtime(
        env_config,
        runtime,
        bootstrap_config,
        shutdown_tx,
        mesh_state,
        Some(initial_applied_mesh_slice),
        background_handles,
    )
    .await
}

fn ensure_runtime_config_protocol_supported(
    runtime: &MeshRuntimeConfig,
) -> Result<(), anyhow::Error> {
    match runtime.config_protocol {
        MeshConfigProtocol::Native | MeshConfigProtocol::Xds | MeshConfigProtocol::File => Ok(()),
    }
}

async fn serve_mesh_runtime(
    env_config: EnvConfig,
    runtime: MeshRuntimeConfig,
    config: GatewayConfig,
    shutdown_tx: tokio::sync::watch::Sender<bool>,
    mesh_state: MeshRuntimeState,
    initial_applied_mesh_slice: Option<Arc<MeshSlice>>,
    mut mesh_background_handles: Vec<JoinHandle<()>>,
) -> Result<(), anyhow::Error> {
    // Fail closed on malformed UDP capture settings (codex r2 P2 / r3 P2),
    // BEFORE binding the DNS proxy or spawning any mesh background task. The
    // `udp_capture_listener()` helper feeding `listener_plan()` is infallible
    // (read-only predicates call it too), so it can only warn-and-skip a parse
    // error — which would silently drop the capture listener while the Stage-2
    // TPROXY rules still divert UDP to a now-unbound port. Validating here, at
    // the very top of the serving path, makes an operator config error abort
    // mesh startup cleanly instead of leaking a bound DNS socket / spawned tasks
    // (which a later `?` would have left running for in-process retries/tests).
    crate::capture::udp_capture_settings_from_env()
        .map_err(|e| anyhow::anyhow!("Invalid mesh UDP capture settings: {e}"))?;

    let dns_cache = DnsCache::new(DnsConfig {
        global_overrides: env_config.dns_overrides.clone(),
        resolver_addresses: env_config.dns_resolver_address.clone(),
        hosts_file_path: env_config.dns_resolver_hosts_file.clone(),
        dns_order: env_config.dns_order.clone(),
        ttl_override_seconds: env_config.dns_ttl_override,
        min_ttl_seconds: env_config.dns_min_ttl,
        stale_ttl_seconds: env_config.dns_stale_ttl,
        error_ttl_seconds: env_config.dns_error_ttl,
        max_cache_size: env_config.dns_cache_max_size,
        warmup_concurrency: env_config.dns_warmup_concurrency,
        slow_threshold_ms: env_config.dns_slow_threshold_ms,
        refresh_threshold_percent: env_config.dns_refresh_threshold_percent,
        failed_retry_interval_seconds: env_config.dns_failed_retry_interval,
        try_tcp_on_error: env_config.dns_try_tcp_on_error,
        num_concurrent_reqs: env_config.dns_num_concurrent_reqs,
        max_active_requests: env_config.dns_max_active_requests,
        max_concurrent_refreshes: env_config.dns_max_concurrent_refreshes,
        backend_allow_ips: env_config.backend_allow_ips.clone(),
        shard_amount: env_config.pool_shard_amount,
    });

    let mut hostnames: Vec<_> = config
        .proxies
        .iter()
        .map(|proxy| {
            (
                proxy.backend_host.clone(),
                proxy.dns_override.clone(),
                proxy.dns_cache_ttl_seconds,
            )
        })
        .collect();
    for upstream in &config.upstreams {
        for target in &upstream.targets {
            hostnames.push((target.host.clone(), None, None));
        }
    }
    let initial_dns_slice = initial_applied_mesh_slice.as_ref().and_then(|slice| {
        node_waypoint_dns_slice_for_prepared_config(&runtime, slice.as_ref(), &config)
    });

    let tls_policy = TlsPolicy::from_env_config(&env_config)?;
    let crls = tls::load_crls(env_config.tls_crl_file_path.as_deref())?;
    // GAP-3D: on node-waypoint topology, create the SOCK_OPS metrics
    // state up front so plugin construction inside `ProxyState::new`
    // picks it up via PluginHttpClient and the spawned ringbuf consumer
    // updates the same Arc.
    let bpf_metrics_state = if runtime.topology == MeshTopology::NodeWaypoint {
        Some(crate::ebpf::bpf_metrics::BpfMetricsState::new())
    } else {
        None
    };
    let (proxy_state, health_check_handles) = ProxyState::new_with_bpf_metrics(
        config,
        dns_cache.clone(),
        env_config.clone(),
        Some(tls_policy.clone()),
        Some(shutdown_tx.subscribe()),
        bpf_metrics_state.clone(),
    )?;
    let proxy_state = if runtime.topology == MeshTopology::NodeWaypoint {
        info!(
            "Node-waypoint identity resolver enabled; unknown outbound capture socket cookies fail closed"
        );
        let resolver = Arc::new(node_waypoint::NodeWaypointIdentityResolver::new(
            env_config.pool_shard_amount,
        ));
        if let Some(initial_slice) = initial_applied_mesh_slice.as_ref() {
            let snapshot =
                resolver.build_policy_scope_snapshot_from_workloads(&initial_slice.workloads);
            resolver.install_policy_scope_snapshot(snapshot);
        }
        if let Some(handle) = node_waypoint::spawn_cgroup_sweep_task(
            resolver.clone(),
            env_config.mesh_node_waypoint_cgroup_sweep_interval_secs,
            shutdown_tx.subscribe(),
        ) {
            mesh_background_handles.push(handle);
        }
        if let Some(handle) = node_waypoint::spawn_idle_identity_gc_task(
            resolver.clone(),
            env_config.mesh_node_waypoint_idle_gc_interval_secs,
            shutdown_tx.subscribe(),
        ) {
            mesh_background_handles.push(handle);
        }
        // Spawn the SOCK_OPS ringbuf consumer. When the kernel program
        // is not pinned (no node-agent on this host, kernel < 5.7, or
        // build without the ebpf feature), the spawned task logs once
        // and exits — the plugin still emits zero counters.
        if let Some(state) = bpf_metrics_state.as_ref()
            && let Some(handle) = spawn_sock_ops_consumer_task(state.clone(), &shutdown_tx)
        {
            mesh_background_handles.push(handle);
        }
        // Spawn the orig-dst → identity bridge. It reads the pinned
        // FERRUM_ORIG_DST4/6 maps the node-agent populated, mirrors each
        // socket-cookie record into the resolver, and installs the synchronous
        // accept-path fallback. Without a node-agent / eBPF build the spawned
        // task logs loudly and returns; the resolver stays empty and the accept
        // path fails closed.
        //
        // Node-waypoint resolution is now wired end-to-end: the accept-side
        // cookie registrar (GAP-2M) lives in the kernel sock_ops program, and
        // the snapshot installed above seeds BOTH policy scopes AND a
        // workload_spiffe_hash → SPIFFE index, so `resolve_record` lazily
        // enrolls `pod_uid` → identity by hash-join against the eBPF-stamped
        // records (no separate enrollment channel). The path is complete in
        // code and CI-verified at the load/attach level (`ebpf-live`); it stays
        // unexercised on a live multi-pod datapath, where a tuple/byte-order or
        // enrollment miss fails closed (never misattributes).
        mesh_background_handles.push(spawn_orig_dst_bridge_task(resolver.clone(), &shutdown_tx));
        proxy_state.with_node_waypoint_identity_resolver(resolver)
    } else {
        proxy_state
    };
    // Node-waypoint in-netns outbound capture listeners (opt-in). The default
    // outbound listener binds in the HOST netns, which a pod's loopback-rewritten
    // capture (`connect4` → 127.0.0.1:15001, `connect6` → [::1]:15001) can never
    // reach; with this enabled the proxy additionally opens dual-family loopback
    // listeners INSIDE each enrolled pod's network namespace, so captured
    // connections are accepted there and the GAP-2M sock_ops same-netns cookie
    // bridge resolves their source identity. Pods are discovered from the registry
    // the node-agent publishes. Linux-only; the full pod-loopback datapath is
    // verified only on a live multi-pod node (see `src/proxy/netns_capture.rs`).
    if runtime.topology == MeshTopology::NodeWaypoint {
        // The connect hooks rewrite captured pod egress to loopback inside the
        // POD netns, taking only the port from FERRUM_MESH_OUTBOUND_LISTEN_ADDR.
        // So the in-netns manager binds 127.0.0.1:<port> and [::1]:<port> and
        // inherits ONLY the configured port — binding the configured IP verbatim
        // (e.g. a node IP) would listen on an address the pod never dials. The IP
        // part of the configured address governs the HOST outbound listener, not
        // these pod-netns listeners. Port `0` disables the outbound listener entirely
        // (nothing is captured), so skip starting the manager.
        let capture_port = runtime.outbound_listen_addr.port();
        if capture_port == 0 {
            info!(
                "Node-waypoint in-netns capture listeners requested, but the outbound listen \
                 port is 0 (disabled); not starting in-netns capture"
            );
        } else {
            let capture_addr = std::net::SocketAddr::new(
                std::net::IpAddr::V4(std::net::Ipv4Addr::LOCALHOST),
                capture_port,
            );
            if !runtime.outbound_listen_addr.ip().is_loopback()
                && !runtime.outbound_listen_addr.ip().is_unspecified()
            {
                info!(
                    configured = %runtime.outbound_listen_addr,
                    bound_ipv4 = %capture_addr,
                    bound_ipv6 = %std::net::SocketAddr::new(
                        std::net::IpAddr::V6(std::net::Ipv6Addr::LOCALHOST),
                        capture_port,
                    ),
                    "Node-waypoint in-netns capture binds pod loopback with the configured \
                     outbound port; the configured IP applies only to the host listener"
                );
            }
            // One connection semaphore shared across all in-netns listeners,
            // sized from `max_connections` exactly like every other listener path
            // (each `run_accept_loop` builds its own — `max_connections` is a
            // per-listener cap in Ferrum, not a single process-wide one). This
            // bounds captured pod egress with a `max_connections`-sized limiter
            // rather than leaving it unbounded (`None`); it is intentionally a
            // separate cap from the inbound HBONE listener's so a saturated
            // inbound path cannot starve all local-pod egress (and vice versa).
            let conn_semaphore: Option<Arc<tokio::sync::Semaphore>> =
                if env_config.max_connections > 0 {
                    Some(Arc::new(tokio::sync::Semaphore::new(
                        env_config.max_connections,
                    )))
                } else {
                    None
                };
            let source = Arc::new(crate::proxy::netns_capture::DirectoryCaptureSource::new(
                env_config.mesh_node_waypoint_pod_registry_dir.clone(),
            ));
            let backend = crate::proxy::netns_capture::ProxyNetnsBackend::new(
                proxy_state.clone(),
                conn_semaphore,
                Some(MeshTrafficDirection::Outbound),
                shutdown_tx.subscribe(),
            );
            // Listener-readiness markers go in dot-subdirs of the registry dir:
            // `.ready` remains the IPv4-compatible marker, while `.ready4` and
            // `.ready6` expose family-level readiness. Redirect hooks are already
            // attached by the node-agent and fail closed until a listener exists.
            // `DirectoryCaptureSource` skips dotfiles, so these subdirs are
            // invisible to the pod-discovery scan.
            let ready_dir = std::path::Path::new(&env_config.mesh_node_waypoint_pod_registry_dir)
                .join(".ready");
            let manager = crate::proxy::netns_capture::NetnsCaptureManager::new(
                capture_addr,
                source,
                backend,
                std::time::Duration::from_secs(2),
            )
            .with_ready_dir(Some(ready_dir));
            let manager_shutdown = shutdown_tx.subscribe();
            info!(
                registry_dir = %env_config.mesh_node_waypoint_pod_registry_dir,
                capture_ipv4 = %capture_addr,
                capture_ipv6 = %std::net::SocketAddr::new(
                    std::net::IpAddr::V6(std::net::Ipv6Addr::LOCALHOST),
                    capture_port,
                ),
                "Node-waypoint dual-family in-netns outbound capture listeners enabled"
            );
            mesh_background_handles.push(tokio::spawn(async move {
                manager.run(manager_shutdown).await;
            }));
        }
    }

    // Ambient per-pod-netns UDP capture producer (#2013). Ambient's proxy runs
    // OUTSIDE the workload pods' network namespaces, so a host-netns UDP capture
    // listener would receive nothing (the host-netns iptables fallback emits no
    // UDP TPROXY rules). When UDP capture is enabled, start a manager that — for
    // each pod the node-agent enrolls in the registry — installs the UDP TPROXY
    // rules and binds a transparent capture socket INSIDE that pod's netns, then
    // runs the shared capture/egress loop (with a pod-netns reply-socket factory).
    // Sidecar keeps its current-netns `PlaintextUdpCapture` listener; any other
    // topology captures no UDP. Linux-only; a clear warning is emitted elsewhere.
    if runtime.topology == MeshTopology::Ambient {
        // Fail closed on a malformed UDP setting (codex): the operator explicitly
        // enabled UDP capture, so a typo must not silently start the mesh with the
        // producer disabled and pod UDP egress bypassing the mesh.
        let settings = crate::capture::udp_capture_settings_from_env().map_err(|e| {
            anyhow::anyhow!("invalid UDP capture settings for the Ambient UDP producer: {e}")
        })?;
        if settings.udp_capture_enabled {
            if !cfg!(target_os = "linux") {
                warn!(
                    "Ambient UDP capture is enabled but the per-pod-netns producer is Linux-only; \
                     not starting it (UDP egress passes through un-captured)"
                );
            } else {
                // Fail closed on a malformed capture config (codex): an invalid
                // include/exclude CIDR, port list, or FERRUM_MESH_IP6TABLES_ENABLED
                // value must abort startup, not silently disable the datapath.
                let mut capture_config =
                    crate::capture::CaptureConfig::from_env().map_err(|e| {
                        anyhow::anyhow!(
                            "Ambient UDP capture is enabled but the capture config is invalid: {e}"
                        )
                    })?;
                // Producer posture: UDP enabled, POD netns (never host-netns — the
                // producer installs rules INSIDE each pod netns), on the resolved
                // capture port/mark. The include/exclude scope is node-level (from
                // the proxy's `FERRUM_MESH_CAPTURE_*` env); per-pod
                // `includeOutboundPorts` annotation scoping is a documented
                // follow-up (it would ride the registry).
                capture_config.udp_capture_enabled = true;
                capture_config.host_netns = false;
                capture_config.udp_outbound_port = settings.udp_outbound_port;
                capture_config.tproxy_mark = settings.tproxy_mark;
                // The sidecar default excludes (15001/15006/15008/15020) only make
                // sense when a proxy is co-located in the pod netns. Ambient's
                // producer runs inside workload pod netns with no sidecar, so an
                // implicit exclude would let app UDP to those service ports bypass
                // capture/authz. Explicit operator excludes are preserved.
                capture_config.clear_implicit_exclude_ports();
                // NO proxy-UID owner-match self-exclusion. That RETURN exists to
                // skip the co-located SIDECAR's own egress; in Ambient the proxy is
                // OUTSIDE the pod netns, so the only egress in the pod netns is the
                // app's — exactly what we capture. Keeping the default UID (1337)
                // would fail OPEN for a pod app that happened to run as 1337. The
                // anti-loop mark RETURN + `! --dst-type LOCAL` scope still bound the
                // OUTPUT-mark loop without an owner match, and the proxy's own relay
                // egress never traverses the pod netns anyway.
                capture_config.proxy_uid = None;
                // Preflight the in-netns tooling NOW — after the config is built —
                // so it can ALSO require `ip6tables` when IPv6 UDP capture is set to
                // `required` with IPv6 CIDRs (the per-pod script would otherwise
                // FATALLY preflight `ip6tables` and fail every setup forever on an
                // image that lacks it). A distroless runtime image has no
                // `sh`/`ip`/`iptables` at all; fail closed with a clear message
                // instead of retrying forever with nothing captured (codex).
                crate::proxy::netns_udp_capture::preflight_capture_tools(
                    capture_config.udp_ipv6_capture_required(),
                )
                .map_err(|e| anyhow::anyhow!(e))?;
                let source = Arc::new(crate::proxy::netns_capture::DirectoryCaptureSource::new(
                    env_config.mesh_node_waypoint_pod_registry_dir.clone(),
                ));
                let backend = crate::proxy::netns_udp_capture::ProxyNetnsUdpBackend::new(
                    Arc::new(proxy_state.clone()),
                    capture_config,
                    settings.udp_outbound_port,
                    env_config.udp_max_sessions,
                    env_config.udp_cleanup_interval_seconds,
                    env_config.udp_recvmmsg_batch_size,
                    env_config.pool_shard_amount,
                );
                let manager = crate::proxy::netns_udp_capture::NetnsUdpCaptureManager::new(
                    settings.udp_outbound_port,
                    source,
                    backend,
                    std::time::Duration::from_secs(2),
                )
                .with_ready_dir(Some(
                    std::path::Path::new(&env_config.mesh_node_waypoint_pod_registry_dir)
                        .join(".udp-ready"),
                ));
                let manager_shutdown = shutdown_tx.subscribe();
                info!(
                    registry_dir = %env_config.mesh_node_waypoint_pod_registry_dir,
                    capture_port = settings.udp_outbound_port,
                    "Ambient per-pod-netns UDP capture producer enabled"
                );
                mesh_background_handles.push(tokio::spawn(async move {
                    manager.run(manager_shutdown).await;
                }));
            }
        } else if cfg!(target_os = "linux") {
            let source = Arc::new(crate::proxy::netns_capture::DirectoryCaptureSource::new(
                env_config.mesh_node_waypoint_pod_registry_dir.clone(),
            ));
            let backend = crate::proxy::netns_udp_capture::ProxyNetnsUdpCleanupBackend::new(true);
            let manager = crate::proxy::netns_udp_capture::NetnsUdpCleanupManager::new(
                source,
                backend,
                std::time::Duration::from_secs(2),
            )
            .with_ready_dir(Some(
                std::path::Path::new(&env_config.mesh_node_waypoint_pod_registry_dir)
                    .join(".udp-ready"),
            ));
            let manager_shutdown = shutdown_tx.subscribe();
            info!(
                registry_dir = %env_config.mesh_node_waypoint_pod_registry_dir,
                "Ambient UDP capture disabled; stale per-pod-netns UDP cleanup manager enabled"
            );
            mesh_background_handles.push(tokio::spawn(async move {
                manager.run(manager_shutdown).await;
            }));
        }
    }

    if let Some(ref slice) = initial_applied_mesh_slice {
        mesh_state.record_applied_slice(slice);
    }
    let startup_ready = Arc::new(AtomicBool::new(false));
    let serving_degraded = Arc::new(AtomicBool::new(false));
    let serving_listener_failures = Arc::new(crate::startup::ServingListenerFailures::default());
    let MeshAdminListeners {
        handles: admin_handles,
        startup_signals: admin_startup_signals,
    } = start_mesh_admin_listeners(
        &env_config,
        &shutdown_tx,
        proxy_state.clone(),
        mesh_state.clone(),
        MeshServingSignals {
            startup_ready: startup_ready.clone(),
            serving_degraded: serving_degraded.clone(),
            listener_failures: serving_listener_failures.clone(),
        },
        &tls_policy,
        &crls,
    )?;
    mesh_background_handles.extend(admin_handles);
    crate::runtime_metrics::global().configure(
        env_config.status_counts_max_entries,
        env_config.runtime_metrics_pool_tracking_enabled,
        env_config.runtime_metrics_status_tracking_enabled,
        env_config.runtime_metrics_cache_ttl_ms,
    );
    proxy_state
        .stream_listener_manager
        .set_global_shutdown_rx(shutdown_tx.subscribe());

    // Share the node-waypoint identity resolver with the stream listener
    // manager so TCP stream accept loops resolve each connection's source pod
    // identity and stamp the per-pod `PolicyScopeCache`, giving scoped
    // (Namespace/WorkloadSelector) mesh policies the same enforcement on raw
    // TCP streams that the HTTP/HBONE path already gets. Injected here, after
    // `with_node_waypoint_identity_resolver` populated the field on
    // `proxy_state`, and BEFORE `initial_reconcile_stream_listeners()` below so
    // listeners binding on startup observe it. `None` (and thus a no-op) in
    // every non-NodeWaypoint topology. UDP/DTLS listeners deliberately do not
    // consume the resolver — see `StreamListenerManager::set_node_waypoint_identity_resolver`.
    if let Some(resolver) = proxy_state.node_waypoint_identity_resolver.as_ref() {
        proxy_state
            .stream_listener_manager
            .set_node_waypoint_identity_resolver(resolver.clone());
    }

    // Install the initial mesh outbound enforcement slot (T5-B). The
    // slice-apply loop refreshes this on every subsequent accepted slice,
    // but the very first slice was already applied by
    // `prepare_gateway_config_for_native_slice` before `ProxyState::new`
    // existed, so the apply-loop wiring would otherwise miss it.
    if let Some(ref slice) = initial_applied_mesh_slice {
        refresh_mesh_outbound_enforcement(&proxy_state, &runtime, slice);
    }

    // Resolve mTLS mode and start any CA-backed runtime SVID source before pool
    // warmup / backend capability probes. HBONE capability probes require a
    // gateway SVID; if the first refresh runs while the slot is empty, HBONE
    // targets can remain Unknown until the next periodic refresh.
    let inbound_mtls_mode =
        startup_inbound_mtls_mode(initial_applied_mesh_slice.as_deref(), &runtime)?;
    validate_egress_gateway_mtls_config(&runtime, &env_config)?;
    // Loud warning when stream egress is opted out of SVID-mTLS. The default
    // (false) terminates SVID-mTLS + runs mesh_authz on stream egress listeners
    // (parity with HTTP egress); enabling plaintext means any pod that can reach
    // the gateway reaches the external service through it with no SPIFFE authn/z.
    if runtime.topology == MeshTopology::EgressGateway
        && runtime.egress_stream_enabled
        && runtime.egress_stream_allow_plaintext
    {
        warn!(
            "FERRUM_MESH_EGRESS_STREAM_ALLOW_PLAINTEXT=true: stream-family (TCP/UDP) egress \
             listeners are running PLAINTEXT and UNAUTHENTICATED. mesh_authz cannot verify SPIFFE \
             peer identity without mTLS, so any pod that can reach this egress gateway can reach \
             the external ServiceEntry backends through it with no authorization check. Unset \
             FERRUM_MESH_EGRESS_STREAM_ALLOW_PLAINTEXT to terminate SVID-mTLS (parity with HTTP \
             egress); keep it enabled only with compensating network controls."
        );
    }
    let mesh_runtime_trust_overlay_slot = empty_mesh_inbound_trust_overlay_slot();
    let mesh_ca_svid_slot = start_mesh_ca_backend_svid_source(
        &proxy_state,
        &runtime,
        &env_config,
        mesh_runtime_trust_overlay_slot.clone(),
        &mut mesh_background_handles,
        shutdown_tx.subscribe(),
    )
    .await?;
    let mesh_runtime_trust_overlay_slot = (mesh_ca_svid_slot.is_some()
        || gateway_svid_material_configured(&env_config))
    .then_some(mesh_runtime_trust_overlay_slot);

    for host in proxy_state.plugin_cache.collect_warmup_hostnames() {
        hostnames.push((host, None, None));
    }
    dns_cache.warmup(hostnames).await;

    if env_config.pool_warmup_enabled {
        proxy_state.warmup_connection_pools().await;
    }
    proxy_state.start_backend_capability_refresh_task(
        !env_config.pool_warmup_enabled,
        Some(shutdown_tx.subscribe()),
    );
    proxy_state.start_service_discovery(Some(shutdown_tx.subscribe()));

    let dns_handle =
        dns_cache.start_background_refresh_with_shutdown(Some(shutdown_tx.subscribe()));
    let dns_retry_handle = dns_cache.start_failed_retry_task(Some(shutdown_tx.subscribe()));
    let per_ip_cleanup_handle =
        proxy_state.start_per_ip_cleanup_task(Some(shutdown_tx.subscribe()));
    let overload_handle = crate::overload::start_monitor(
        proxy_state.overload.clone(),
        env_config.overload_config(),
        env_config.max_connections,
        env_config.max_requests,
        shutdown_tx.subscribe(),
    );
    let metrics_handle = crate::metrics::start_metrics_monitor(
        proxy_state.request_count.clone(),
        proxy_state.status_counts.clone(),
        proxy_state.windowed_metrics.clone(),
        env_config.status_metrics_window_seconds,
        shutdown_tx.subscribe(),
    );
    let runtime_system_handle = crate::system_metrics::start_sampler(
        Some(proxy_state.clone()),
        env_config.runtime_metrics_system_sample_interval_ms,
        shutdown_tx.subscribe(),
    );
    let runtime_window_handle = crate::runtime_metrics::start_window_rotator(
        env_config.runtime_metrics_window_1m_seconds,
        env_config.runtime_metrics_window_5m_seconds,
        shutdown_tx.subscribe(),
    );
    // Start mesh DNS proxy if enabled
    let dns_proxy_handle = if runtime.dns_enabled {
        let dns_proxy = Arc::new(MeshDnsProxy::new(
            runtime.dns_listen_addr,
            runtime.dns_upstream_addr,
            runtime.dns_ttl_seconds,
            runtime.dns_max_concurrent_queries,
            runtime.dns_response_cache_max_entries,
            runtime.cluster_domain.clone(),
        ));
        // Build initial resolution table from the applied slice
        if let Some(ref slice) = initial_applied_mesh_slice {
            dns_proxy.update_from_slice(initial_dns_slice.as_ref().unwrap_or(slice.as_ref()));
        }
        let dns_sockets = dns_proxy.bind().await.with_context(|| {
            format!(
                "failed to bind mesh DNS proxy at {}",
                runtime.dns_listen_addr
            )
        })?;
        let dns_shutdown = shutdown_tx.subscribe();
        let dns_runner = dns_proxy.clone();
        mesh_background_handles.push(tokio::spawn(async move {
            dns_runner.run_bound(dns_sockets, dns_shutdown).await;
        }));
        info!(
            addr = %runtime.dns_listen_addr,
            upstream = %runtime.dns_upstream_addr,
            ttl = runtime.dns_ttl_seconds,
            max_concurrent_queries = runtime.dns_max_concurrent_queries,
            response_cache_max_entries = runtime.dns_response_cache_max_entries,
            cluster_domain = %runtime.cluster_domain,
            "Mesh DNS proxy started"
        );
        Some(dns_proxy)
    } else {
        None
    };

    // By default inbound mTLS remains a startup-only decision (`inbound_mtls_mode`
    // and `validate_egress_gateway_mtls_config` resolved earlier, before the
    // CA-backend SVID source started). When the opt-in live reload flag is
    // enabled, the mesh accept loops read the authoritative
    // `proxy_state.mesh_inbound_tls_policy` on every accept and slice apply may
    // atomically swap the inbound fallback + per-port ServerConfigs/modes.
    //
    // The inbound server identity resolves from `proxy_state.gateway_svid_bundle`:
    // the CA-backend SVID source (started above) installs its issued SVID there,
    // so the SVID-rotating server identity reads the live leaf and fails closed
    // when the slot is empty.
    let mesh_frontend_identity =
        load_mesh_frontend_server_identity(&env_config, &proxy_state.gateway_svid_bundle)?;
    let inbound_mtls_modes_by_port =
        resolve_inbound_mtls_modes_by_port(initial_applied_mesh_slice.as_deref(), &runtime);
    let inbound_app_port_by_orig_dst_port =
        resolve_inbound_app_ports_by_orig_dst_port(initial_applied_mesh_slice.as_deref());
    let has_inbound_tls_termination_listener = runtime.has_inbound_tls_termination_listener();
    // Snapshot the client CA at startup even when PeerAuthentication live reload
    // is disabled. Per-port configs share the rotating server identity and need
    // the CA bytes supplied explicitly; passing only the configured path would
    // leave STRICT/PERMISSIVE overrides unable to build on the default path.
    // Passthrough-only topologies remain exempt through the listener-aware helper.
    let mut initial_inbound_tls_snapshot = mesh_inbound_tls_reload_snapshot_for_listener(
        &env_config,
        inbound_mtls_mode,
        inbound_mtls_modes_by_port.clone(),
        has_inbound_tls_termination_listener,
    )?;
    initial_inbound_tls_snapshot.app_port_by_orig_dst_port =
        inbound_app_port_by_orig_dst_port.clone();
    // SPIFFE inbound peer-verification slot (gateway SVID local bundle merged
    // with the initial slice's federated bundles). `None` when no gateway SVID
    // material is configured — the listener then keeps operator-CA chain
    // verification. The slot is read live by the verifier and re-published on
    // slice apply so federated trust changes propagate lock-free.
    let federation_activation = FederationActivation::from_env_config(&env_config);
    let initial_federation_snapshot = mesh_state.federation_store().snapshot();
    let mesh_inbound_spiffe_slot = build_mesh_inbound_spiffe_slot_with_federation(
        &env_config,
        initial_applied_mesh_slice.as_deref(),
        Some(&initial_federation_snapshot),
        federation_activation,
        mesh_ca_svid_slot.as_ref(),
    );
    if let Some(slice) = initial_applied_mesh_slice.as_deref() {
        publish_gateway_active_trust_bundles(
            &proxy_state,
            slice,
            Some(&initial_federation_snapshot),
            federation_activation,
        );
        publish_staged_spiffe_bundle(
            &proxy_state,
            stage_gateway_runtime_spiffe_bundle_with_federation(
                &proxy_state,
                mesh_inbound_spiffe_slot.as_ref(),
                mesh_runtime_trust_overlay_slot.as_ref(),
                slice,
                Some(&initial_federation_snapshot),
                federation_activation,
            ),
        );
    }
    if let (Some(inbound_slot), Some(trust_overlay_slot)) = (
        mesh_inbound_spiffe_slot.clone(),
        mesh_runtime_trust_overlay_slot.clone(),
    ) {
        mesh_background_handles.push(start_mesh_inbound_svid_rotation_republisher(
            proxy_state.clone(),
            inbound_slot,
            trust_overlay_slot,
            proxy_state.backend_svid_rotation_tx.subscribe(),
            shutdown_tx.subscribe(),
        ));
    }
    let frontend_tls = load_mesh_frontend_tls(
        &env_config,
        &tls_policy,
        &crls,
        inbound_mtls_mode,
        runtime.topology,
        mesh_frontend_identity.as_deref(),
        initial_inbound_tls_snapshot.client_ca_bundle.as_ref(),
        mesh_inbound_spiffe_slot.as_ref(),
    )?;
    let frontend_tls_by_port = if has_inbound_tls_termination_listener {
        load_mesh_frontend_tls_by_port(
            &env_config,
            &tls_policy,
            &crls,
            &inbound_mtls_modes_by_port,
            runtime.topology,
            mesh_frontend_identity.as_deref(),
            initial_inbound_tls_snapshot.client_ca_bundle.as_ref(),
            mesh_inbound_spiffe_slot.as_ref(),
        )?
    } else {
        HashMap::new()
    };
    // Runtime fail-closed enforcement (issue #1523): #1522's config-time gate
    // only checks that identity material is *named*. Here the inbound listener's
    // actual resolved posture is known, so a production mesh refuses to come up
    // with a plaintext inbound termination listener or a configured-but-
    // unloadable SPIFFE verifier, instead of silently falling open to the
    // PERMISSIVE-plaintext posture (dev allows it with a loud warning). The
    // production flag is read once here and threaded into the live-reload gate
    // so it is fixed for the process lifetime.
    let mesh_production_mode = crate::identity::production_mode();
    let effective_inbound_mtls_mode =
        effective_inbound_mtls_mode_for_topology(inbound_mtls_mode, runtime.topology);
    let effective_inbound_mtls_modes_by_port =
        effective_inbound_mtls_modes_for_topology(&inbound_mtls_modes_by_port, runtime.topology);
    enforce_mesh_inbound_fail_closed(
        &runtime,
        &env_config,
        effective_inbound_mtls_mode,
        frontend_tls.as_ref(),
        mesh_inbound_spiffe_slot.as_ref(),
        mesh_production_mode,
    )?;
    for (&port, tls_config) in &frontend_tls_by_port {
        enforce_mesh_inbound_fail_closed(
            &runtime,
            &env_config,
            effective_inbound_mtls_modes_by_port[&port],
            tls_config.as_ref(),
            mesh_inbound_spiffe_slot.as_ref(),
            mesh_production_mode,
        )
        .with_context(|| format!("invalid inbound mTLS posture for app port {port}"))?;
    }
    if has_inbound_tls_termination_listener {
        crate::plugins::mesh::prometheus_helpers::set_mesh_inbound_plaintext_allowed(
            mesh_inbound_listener_allows_plaintext(runtime.topology, mesh_production_mode)
                && (mesh_inbound_mode_accepts_plaintext(effective_inbound_mtls_mode)
                    || effective_inbound_mtls_modes_by_port
                        .values()
                        .copied()
                        .any(mesh_inbound_mode_accepts_plaintext)
                    || frontend_tls.is_none()
                    || frontend_tls_by_port.values().any(Option::is_none)),
        );
    }
    let any_inbound_tls_configured =
        frontend_tls.is_some() || frontend_tls_by_port.values().any(Option::is_some);
    // Keep the slot populated with startup TLS even when live reload is
    // disabled. The flag controls which listener source is used; without live
    // reload the slot never updates again, so readers must not treat it as the
    // current PeerAuthentication state.
    proxy_state
        .mesh_inbound_tls
        .store(Arc::new(frontend_tls.clone()));
    proxy_state
        .mesh_inbound_tls_policy
        .store(Arc::new(crate::proxy::MeshInboundTlsPolicy {
            default: frontend_tls.clone(),
            by_port: frontend_tls_by_port,
            default_mode: effective_inbound_mtls_mode,
            modes_by_port: effective_inbound_mtls_modes_by_port,
            app_port_by_orig_dst_port: inbound_app_port_by_orig_dst_port,
        }));
    proxy_state.mesh_inbound_spiffe_verifier_active.store(
        mesh_inbound_spiffe_verifier_active(
            has_inbound_tls_termination_listener,
            any_inbound_tls_configured,
            mesh_inbound_spiffe_slot.is_some(),
        ),
        Ordering::Release,
    );
    if let Some(ref tls_config) = frontend_tls {
        proxy_state
            .stream_listener_manager
            .set_frontend_tls_config(Some(tls_config.clone()))
            .await;
    }

    // Spawn the SPIFFE trust-bundle federation poller reconciler before the
    // apply task so the first slice apply observes whatever the poller has
    // already fetched. Unlike the old one-shot spawn, the reconciler watches
    // accepted slice updates: it starts pollers for federation endpoints added
    // after startup, stops pollers for removed clusters, and retires a
    // withdrawn cluster's federation store generation so stale poll results
    // cannot keep being overlaid onto slice applies. Reconcile is intentionally
    // coupled to accepted slices, not merely received slices, so an invalid
    // update rejected by the apply task cannot stop existing pollers or remove
    // cached bundles still used by the live proxy config. No pollers run when
    // `FERRUM_MESH_FEDERATION_POLL_INTERVAL_SECONDS=0` or no remote cluster
    // carries a federation endpoint.
    let federation_poller_config = federation::FederationPollerConfig::from_env_with_max_stale(
        env_config.mesh_federation_poll_interval_seconds,
        env_config.mesh_federation_poll_timeout_seconds,
        env_config.mesh_federation_fail_open,
        env_config.mesh_federation_max_stale_seconds,
    );
    let federation_manager = federation::FederationPollerManager::new(
        federation_poller_config,
        proxy_state.plugin_cache.http_client().clone(),
        mesh_state.federation_store().clone(),
    );
    mesh_background_handles.push(start_federation_poller_reconcile_task(
        mesh_state.clone(),
        federation_manager,
        shutdown_tx.subscribe(),
    ));
    info!("SPIFFE trust-bundle federation poller reconciler running");

    // Spawn cross-cluster endpoint discovery (Tier 3b). A reconciler watches
    // slice + federation updates and keeps one poller per currently eligible
    // `RemoteCluster.control_plane_url`. This is fail-closed on trust: a remote
    // cluster is only dialed while a federated trust bundle for its trust domain
    // exists, and stale endpoints are removed when config or trust withdraws.
    // Guard the entire TLS-build + discovery-config block: when the interval
    // is 0 (the default — discovery is disabled), skip the TLS material clone,
    // the build_dp_grpc_tls_config calls, and the associated log lines entirely.
    // Previously these ran unconditionally, causing cert-file reads and a
    // "MeshRemoteDiscovery gRPC TLS configured" log on every mesh startup even
    // when discovery was never enabled (F4).
    let remote_discovery_config = if env_config.mesh_remote_discovery_poll_interval_seconds != 0 {
        let remote_grpc_secret = env_config.cp_dp_grpc_jwt_secret.clone().map(|secret| {
            crate::grpc::dp_client::GrpcJwtSecret::with_issuer(
                secret,
                env_config.cp_dp_grpc_jwt_issuer.clone(),
            )
        });
        let remote_grpc_tls = multicluster::RemoteDiscoveryTlsConfig {
            tls_urls: build_dp_grpc_tls_config(
                &env_config,
                &["https://remote-control-plane.invalid".to_string()],
                "MeshRemoteDiscovery",
            )?,
            // The scheme is authoritative for plaintext remotes: a `grpc://` /
            // `http://` control_plane_url must NOT get DP gRPC TLS material
            // attached just because TLS env vars are set, or
            // `fetch_remote_slice_endpoints` would attempt a TLS handshake
            // against a plaintext port. (`build_dp_grpc_tls_config(.., &[], ..)`
            // returns `Some(tls)` whenever any TLS env is set, independent of
            // scheme — so force `None` here.) A `grpcs://` / `https://` remote
            // uses `tls_urls` above.
            plain_urls: None,
        };
        multicluster::RemoteDiscoveryConfig::new_with_max_stale(
            env_config.mesh_remote_discovery_poll_interval_seconds,
            env_config.mesh_remote_discovery_poll_timeout_seconds,
            env_config.mesh_remote_discovery_max_stale_seconds,
            remote_grpc_secret,
            runtime.node_id.clone(),
            runtime.namespace.clone(),
            remote_grpc_tls,
        )
    } else {
        None
    };
    if let Some(remote_discovery_config) = remote_discovery_config {
        // F1: warn when discovery is enabled but the local workload locality
        // is absent. Without a source locality the priority-tier load balancer
        // has no source region to prefer, so `target_locality_ranks` stays
        // empty. The behavior in that case depends on FERRUM_MESH_LOCALITY_LB_STRICT:
        // default (fail-open) returns ALL candidates (local + remote) together;
        // strict (fail-closed-to-local) restricts to LOCAL endpoints, widening to
        // remote only when no local endpoint is healthy. The warning text below is
        // branched accordingly so it never tells a strict-mode operator that local
        // and remote are selected together (which would be false). This is not a
        // bug in the LB; it is the expected behavior when no locality is
        // configured. Emit a startup WARN so the posture is visible to an operator
        // who enabled discovery expecting local-first failover.
        if initial_applied_mesh_slice
            .as_deref()
            .is_none_or(|slice| mesh_source_workload_locality(slice).is_none())
        {
            if runtime.locality_lb_strict {
                warn!(
                    poll_interval_seconds = env_config.mesh_remote_discovery_poll_interval_seconds,
                    "Cross-cluster endpoint discovery is enabled \
                     (FERRUM_MESH_REMOTE_DISCOVERY_POLL_INTERVAL_SECONDS > 0) but the local \
                     workload source locality is not set (topology.kubernetes.io/region+zone \
                     labels missing or SPIFFE-matched workload has no locality). \
                     FERRUM_MESH_LOCALITY_LB_STRICT is on, so without a source locality the \
                     load balancer restricts selection to LOCAL endpoints (fail-closed-to-local), \
                     widening to remote endpoints only when no local endpoint is healthy. \
                     Set the workload's topology.kubernetes.io/region+zone labels to enable \
                     full local-first priority-tier failover. \
                     See docs/mesh.md \"Cross-Cluster Endpoint Discovery\" for details."
                );
            } else {
                warn!(
                    poll_interval_seconds = env_config.mesh_remote_discovery_poll_interval_seconds,
                    "Cross-cluster endpoint discovery is enabled \
                     (FERRUM_MESH_REMOTE_DISCOVERY_POLL_INTERVAL_SECONDS > 0) but the local \
                     workload source locality is not set (topology.kubernetes.io/region+zone \
                     labels missing or SPIFFE-matched workload has no locality). \
                     The locality-aware priority-tier load balancer requires a source locality \
                     to prefer local endpoints over remote ones; without it (and with strict \
                     mode off), local and remote endpoints are selected together (fails open, \
                     not local-first). \
                     See docs/mesh.md \"Cross-Cluster Endpoint Discovery\" for the precondition."
                );
            }
        }
        let remote_discovery_credentials = match multicluster::parse_remote_discovery_credentials(
            env_config.mesh_remote_discovery_credentials.as_deref(),
            &env_config.cp_dp_grpc_jwt_issuer,
        ) {
            Ok(map) => std::sync::Arc::new(map),
            Err(err) => {
                // Fail closed: a malformed per-remote credential map must not
                // start discovery with an unknown auth posture. An empty map
                // here still fails closed per-cluster in `start_cluster` for any
                // RemoteCluster that references a (now-absent) credential.
                error!("{err}");
                std::sync::Arc::new(std::collections::HashMap::new())
            }
        };
        let remote_discovery_manager = multicluster::RemoteDiscoveryManager::new(
            Some(remote_discovery_config),
            mesh_state.remote_endpoint_store().clone(),
            multicluster::native_source_factory,
        )
        .with_credentials(remote_discovery_credentials);
        mesh_background_handles.push(start_remote_cluster_discovery_reconcile_task(
            mesh_state.clone(),
            remote_discovery_manager,
            federation_activation,
            shutdown_tx.subscribe(),
        ));
        info!("Cross-cluster endpoint discovery reconciler running");
    }

    let mesh_apply_handle = start_mesh_slice_apply_task(
        mesh_state,
        proxy_state.clone(),
        runtime.clone(),
        initial_applied_mesh_slice,
        MeshInboundTlsReloadState {
            server_identity: mesh_frontend_identity,
            last_snapshot: Some(initial_inbound_tls_snapshot),
            spiffe_bundle_slot: mesh_inbound_spiffe_slot,
            runtime_trust_overlay_slot: mesh_runtime_trust_overlay_slot,
            production: mesh_production_mode,
        },
        shutdown_tx.subscribe(),
        dns_proxy_handle,
    );

    info!(
        listeners = runtime.listener_plan().len(),
        ?inbound_mtls_mode,
        "Mesh listener plan prepared"
    );
    let mut listener_handles = Vec::new();
    // Admin listeners are startup-critical in mesh mode just like traffic
    // listeners. Keeping their bind signals in the same gate ensures a failed
    // admin bind cannot be hidden by the unconditional readiness store below.
    let mut startup_signals = admin_startup_signals;
    let mesh_topology = runtime.topology;
    for listener in runtime.listener_plan() {
        let uses_mesh_inbound_tls = matches!(
            listener.kind,
            MeshListenerKind::MtlsTermination | MeshListenerKind::HboneTermination
        );
        let tls_config = if uses_mesh_inbound_tls {
            None
        } else {
            listener_tls_config_for_mtls_mode(&listener, frontend_tls.clone(), inbound_mtls_mode)
        };
        let listener_has_tls = if uses_mesh_inbound_tls {
            let policy = proxy_state.mesh_inbound_tls_policy.load();
            policy.default.is_some() || policy.by_port.values().any(Option::is_some)
        } else {
            tls_config.is_some()
        };
        if !listener_has_tls
            && matches!(
                listener.kind,
                MeshListenerKind::MtlsTermination | MeshListenerKind::HboneTermination
            )
            && inbound_mtls_mode != config::MtlsMode::Disable
        {
            warn!(
                direction = ?listener.direction,
                addr = %listener.addr,
                "Mesh TLS listener is running without frontend TLS because no mesh/frontend certificate is configured"
            );
        }

        let label = format!("{:?} {:?} mesh listener", listener.direction, listener.kind);
        let state = proxy_state.clone();
        let shutdown = shutdown_tx.subscribe();
        let addr = listener.addr;
        let direction = listener.direction;
        let kind = listener.kind;
        let listener_startup_ready = startup_ready.clone();
        let listener_serving_degraded = serving_degraded.clone();
        let listener_failures = serving_listener_failures.clone();
        let failure_label = label.clone();
        let (started_tx, started_rx) = tokio::sync::oneshot::channel();
        let handle = tokio::spawn(async move {
            info!(
                direction = ?direction,
                kind = ?kind,
                addr = %addr,
                "Starting mesh listener"
            );
            let records_mesh_mtls_metric = matches!(
                kind,
                MeshListenerKind::MtlsTermination | MeshListenerKind::HboneTermination
            );
            let listener_result = if records_mesh_mtls_metric {
                let allows_plaintext = kind == MeshListenerKind::MtlsTermination
                    && mesh_inbound_listener_allows_plaintext(mesh_topology, mesh_production_mode);
                proxy::start_proxy_listener_with_mesh_inbound_tls_and_signal(
                    addr,
                    state,
                    shutdown,
                    Some(direction),
                    allows_plaintext,
                    Some(started_tx),
                )
                .await
            } else if matches!(kind, MeshListenerKind::PlaintextUdpCapture) {
                // UDP TPROXY capture listener (F3 §3.3 Stage 3) — plaintext,
                // distinct from the TCP capture/HTTP path: it binds a transparent
                // UDP socket, recovers per-datagram orig-dst from cmsg, and drops
                // (egress is Stage 4). `tls_config` is always None here.
                proxy::start_mesh_udp_capture_listener_with_signal(
                    addr,
                    state,
                    shutdown,
                    tls_config,
                    Some(direction),
                    Some(started_tx),
                )
                .await
            } else {
                // Outbound capture (plaintext) — non-mTLS mesh listener. Use the
                // generic listener entry but stamp direction by routing through
                // the mesh mTLS variant with `record_mesh_mtls_metric=false`.
                // We accomplish that by constructing the underlying call
                // directly so we can pass `mesh_direction` even though TLS
                // termination is disabled.
                proxy::start_mesh_plaintext_listener_with_signal(
                    addr,
                    state,
                    shutdown,
                    tls_config,
                    Some(direction),
                    Some(started_tx),
                )
                .await
            };
            if let Err(e) = listener_result {
                crate::startup::record_post_start_listener_failure(
                    &listener_startup_ready,
                    &listener_serving_degraded,
                    &listener_failures,
                    &failure_label,
                    addr.port(),
                    &e,
                );
            }
        });
        listener_handles.push(handle);
        startup_signals.push((label, started_rx));
    }

    let startup_result: Result<(), anyhow::Error> = async {
        proxy_state.initial_reconcile_stream_listeners().await?;
        wait_for_start_signals(startup_signals, Duration::from_secs(10)).await?;
        proxy_state
            .stream_listener_manager
            .wait_until_started(Duration::from_secs(10))
            .await?;
        startup_ready.store(true, std::sync::atomic::Ordering::Release);
        info!("Mesh runtime startup complete");
        Ok(())
    }
    .await;
    if let Err(e) = startup_result {
        warn!(
            "Mesh runtime startup failed after spawning tasks: {}; draining before returning",
            e
        );
        let _ = shutdown_tx.send(true);
        let _ =
            await_mesh_listener_handles(listener_handles, shutdown_tx.clone(), "startup failure")
                .await;
        shutdown_and_join_mesh(
            proxy_state,
            MeshBackgroundTasks {
                handles: vec![
                    dns_handle,
                    overload_handle,
                    metrics_handle,
                    runtime_system_handle,
                    runtime_window_handle,
                    mesh_apply_handle,
                ],
                dns_retry_handle,
                per_ip_cleanup_handle,
                health_check_handles,
                mesh_background_handles,
            },
            env_config.shutdown_drain_seconds,
        )
        .await;
        return Err(e);
    }

    let listener_result =
        await_mesh_listener_handles(listener_handles, shutdown_tx.clone(), "shutdown").await;

    shutdown_and_join_mesh(
        proxy_state,
        MeshBackgroundTasks {
            handles: vec![
                dns_handle,
                overload_handle,
                metrics_handle,
                runtime_system_handle,
                runtime_window_handle,
                mesh_apply_handle,
            ],
            dns_retry_handle,
            per_ip_cleanup_handle,
            health_check_handles,
            mesh_background_handles,
        },
        env_config.shutdown_drain_seconds,
    )
    .await;
    info!("Mesh runtime mode shutting down");
    listener_result?;
    Ok(())
}

struct MeshAdminListeners {
    handles: Vec<JoinHandle<()>>,
    startup_signals: Vec<(String, tokio::sync::oneshot::Receiver<()>)>,
}

/// Shared readiness/degradation handles threaded from `serve_mesh_runtime`
/// into the admin listeners so post-startup listener failures flip the same
/// sticky serving state the traffic listeners use.
struct MeshServingSignals {
    startup_ready: Arc<AtomicBool>,
    serving_degraded: Arc<AtomicBool>,
    listener_failures: Arc<crate::startup::ServingListenerFailures>,
}

fn start_mesh_admin_listeners(
    env_config: &EnvConfig,
    shutdown_tx: &tokio::sync::watch::Sender<bool>,
    proxy_state: ProxyState,
    mesh_state: MeshRuntimeState,
    serving_signals: MeshServingSignals,
    tls_policy: &TlsPolicy,
    crls: &tls::CrlList,
) -> Result<MeshAdminListeners, anyhow::Error> {
    let MeshServingSignals {
        startup_ready,
        serving_degraded,
        listener_failures: serving_listener_failures,
    } = serving_signals;
    let admin_allowed_cidrs = Arc::new(
        crate::proxy::client_ip::TrustedProxies::parse_strict(&env_config.admin_allowed_cidrs)
            .map_err(|err| anyhow::anyhow!("Invalid FERRUM_ADMIN_ALLOWED_CIDRS: {err}"))?,
    );
    let metrics_auth = Arc::new(
        crate::admin::MetricsAuthPolicy::from_env(env_config)
            .map_err(|err| anyhow::anyhow!(err))?,
    );
    let jwt_manager = match create_jwt_manager_from_env() {
        Ok(manager) => manager,
        Err(err) => {
            warn!(
                "Admin JWT not configured for mesh mode ({}), admin endpoints will reject operator tokens",
                err
            );
            let random_secret = format!("{}{}", uuid::Uuid::new_v4(), uuid::Uuid::new_v4());
            crate::admin::jwt_auth::JwtManager::new(crate::admin::jwt_auth::JwtConfig {
                secret: random_secret,
                ..Default::default()
            })
        }
    };
    let admin_state = AdminState {
        db: None,
        jwt_manager,
        cached_config: Some(proxy_state.config.clone()),
        proxy_state: Some(proxy_state.clone()),
        mode: "mesh".to_string(),
        read_only: true,
        admin_audit_enabled: env_config.admin_audit_enabled,
        admin_require_namespace_claim: env_config.admin_require_namespace_claim,
        startup_ready: Some(startup_ready.clone()),
        serving_degraded: Some(serving_degraded.clone()),
        serving_listener_failures: Some(serving_listener_failures.clone()),
        db_available: None,
        config_rejected: None,
        admin_restore_max_body_size_mib: env_config.admin_restore_max_body_size_mib,
        admin_spec_max_body_size_mib: env_config.admin_spec_max_body_size_mib,
        reserved_ports: env_config.reserved_gateway_ports(),
        stream_proxy_bind_address: env_config.stream_proxy_bind_address.clone(),
        admin_allowed_cidrs,
        metrics_auth,
        cached_db_health: Arc::new(arc_swap::ArcSwap::new(Arc::new(None))),
        db_health_refresh: Arc::new(tokio::sync::Mutex::new(())),
        dp_registry: None,
        mesh_registry: None,
        cp_connection_state: None,
        admin_http_header_read_timeout_seconds: env_config.http_header_read_timeout_seconds,
        admin_body_read_timeout_seconds: env_config.admin_body_read_timeout_seconds,
        admin_http2_max_concurrent_streams: env_config.admin_http2_max_concurrent_streams,
        mesh_runtime_state: Some(mesh_state),
        admin_tls_handshake_timeout_seconds: env_config.frontend_tls_handshake_timeout_seconds,
        backend_allow_ips: env_config.backend_allow_ips.clone(),
    };

    let mut handles = Vec::new();
    let mut startup_signals = Vec::new();
    let admin_state_for_https = admin_state.clone();
    // Shared admin connection limiter (plaintext + HTTPS listeners share one
    // management-plane cap, independent of the data-plane FERRUM_MAX_CONNECTIONS).
    let admin_conn_limiter = Arc::new(admin::AdminConnLimiter::new(
        env_config.admin_max_connections,
        env_config.admin_max_connections_per_ip,
    ));

    if env_config.admin_http_port != 0 {
        let admin_http_addr = env_config.admin_socket_addr(env_config.admin_http_port);
        let shutdown = shutdown_tx.subscribe();
        let admin_http_limiter = admin_conn_limiter.clone();
        let (started_tx, started_rx) = tokio::sync::oneshot::channel();
        let admin_startup_ready = startup_ready.clone();
        let admin_serving_degraded = serving_degraded.clone();
        let admin_failures = serving_listener_failures.clone();
        handles.push(tokio::spawn(async move {
            info!(
                "Starting mesh admin HTTP listener on {}",
                crate::secrets::report_listener_addr(
                    "FERRUM_ADMIN_BIND_ADDRESS",
                    "FERRUM_ADMIN_HTTP_PORT",
                    &admin_http_addr.to_string()
                )
            );
            if let Err(err) = admin::start_admin_listener_with_tls_and_signal(
                admin_http_addr,
                admin_state,
                shutdown,
                None,
                Some(started_tx),
                admin_http_limiter,
            )
            .await
            {
                crate::startup::record_post_start_listener_failure(
                    &admin_startup_ready,
                    &admin_serving_degraded,
                    &admin_failures,
                    "Mesh admin HTTP listener",
                    admin_http_addr.port(),
                    &err,
                );
            }
        }));
        startup_signals.push(("Mesh admin HTTP listener".to_string(), started_rx));
    } else {
        info!(
            "{} — plaintext mesh admin HTTP listener disabled",
            crate::secrets::report_env_assignment("FERRUM_ADMIN_HTTP_PORT", "0")
        );
    }

    // Admin HTTPS listener (only if TLS is configured and the port is not
    // disabled — port 0 is the repository-wide disable sentinel).
    if env_config.admin_https_port == 0 {
        info!(
            "{} — mesh admin HTTPS listener disabled",
            crate::secrets::report_env_assignment("FERRUM_ADMIN_HTTPS_PORT", "0")
        );
    } else if let (Some(admin_cert_path), Some(admin_key_path)) = (
        &env_config.admin_tls_cert_path,
        &env_config.admin_tls_key_path,
    ) {
        let admin_https_addr = env_config.admin_socket_addr(env_config.admin_https_port);
        let admin_client_ca_bundle = env_config.admin_tls_client_ca_bundle_path.as_deref();
        let admin_tls_config = tls::load_tls_config_with_client_auth_and_ocsp(
            admin_cert_path,
            admin_key_path,
            admin_client_ca_bundle,
            env_config.admin_tls_ocsp_response_source.as_deref(),
            env_config.admin_tls_no_verify,
            tls_policy,
            env_config.tls_cert_expiry_warning_days,
            crls,
        )
        .map_err(|err| anyhow::anyhow!("Invalid mesh admin TLS configuration: {err}"))?;
        let admin_reload_handles = crate::modes::tls_reload::prepare_admin_frontend_tls(
            admin_tls_config.clone(),
            env_config,
            tls_policy,
            crls,
            Some(shutdown_tx.subscribe()),
        );
        if admin_reload_handles.watcher_handle.is_some() {
            info!("Frontend TLS live reload enabled for mesh admin HTTPS");
        }
        let admin_tls_slot = admin_reload_handles.slot.clone();
        let shutdown = shutdown_tx.subscribe();
        let admin_https_limiter = admin_conn_limiter.clone();
        let (started_tx, started_rx) = tokio::sync::oneshot::channel();
        let admin_startup_ready = startup_ready.clone();
        let admin_serving_degraded = serving_degraded.clone();
        let admin_failures = serving_listener_failures.clone();
        handles.push(tokio::spawn(async move {
            info!(
                "Starting mesh admin HTTPS listener on {}",
                crate::secrets::report_listener_addr(
                    "FERRUM_ADMIN_BIND_ADDRESS",
                    "FERRUM_ADMIN_HTTPS_PORT",
                    &admin_https_addr.to_string()
                )
            );
            let result = if let Some(slot) = admin_tls_slot {
                admin::start_admin_listener_with_dynamic_tls_and_signal(
                    admin_https_addr,
                    admin_state_for_https,
                    shutdown,
                    slot,
                    Some(started_tx),
                    admin_https_limiter,
                )
                .await
            } else {
                admin::start_admin_listener_with_tls_and_signal(
                    admin_https_addr,
                    admin_state_for_https,
                    shutdown,
                    Some(admin_tls_config),
                    Some(started_tx),
                    admin_https_limiter,
                )
                .await
            };
            if let Err(err) = result {
                crate::startup::record_post_start_listener_failure(
                    &admin_startup_ready,
                    &admin_serving_degraded,
                    &admin_failures,
                    "Mesh admin HTTPS listener",
                    admin_https_addr.port(),
                    &err,
                );
            }
        }));
        startup_signals.push(("Mesh admin HTTPS listener".to_string(), started_rx));
    } else {
        info!("Mesh admin TLS not configured - HTTPS listener disabled");
    }

    if env_config.admin_http_port == 0 && !env_config.admin_https_listener_enabled() {
        warn!(
            "No mesh admin API listeners are active — {} and admin HTTPS not configured or {}. The admin API is unreachable.",
            crate::secrets::report_env_assignment("FERRUM_ADMIN_HTTP_PORT", "0"),
            crate::secrets::report_env_assignment("FERRUM_ADMIN_HTTPS_PORT", "0")
        );
    }

    Ok(MeshAdminListeners {
        handles,
        startup_signals,
    })
}

/// Resolve the workload-level mTLS fallback for the inbound TLS-terminating
/// listener. App-port overrides are published separately in the per-port
/// table; a mesh transport port must never select one as the listener fallback.
fn resolve_inbound_mtls_mode(
    initial_slice: Option<&MeshSlice>,
    _runtime: &MeshRuntimeConfig,
) -> config::MtlsMode {
    let Some(slice) = initial_slice else {
        return config::MtlsMode::Permissive;
    };
    // Fail-closed variant: on an ambiguous shared-SPIFFE slice whose partial
    // label intersection cannot confirm a candidate-only selector
    // PeerAuthentication, escalate to the most-restrictive candidate mTLS mode
    // rather than silently dropping a selector STRICT and falling back to
    // Permissive (a fail-open). Enforcement-identical to the plain resolver on a
    // non-ambiguous slice.
    slice.resolve_inbound_workload_mtls_mode_fail_closed()
}

/// Return every local app/listener port that can select a PeerAuthentication
/// override for this slice. Carried namespace policies may mention ports served
/// by unrelated workloads, so their raw key union is not a safe listener table.
fn selectable_inbound_peer_auth_ports(
    slice: &MeshSlice,
    runtime: &MeshRuntimeConfig,
) -> std::collections::BTreeSet<u16> {
    let mut ports = std::collections::BTreeSet::new();
    let (services, local_workload_src): (
        &[crate::modes::mesh::config::MeshService],
        &[crate::modes::mesh::config::Workload],
    ) = match slice.local_inbound_workloads.as_deref() {
        Some(workloads) => (slice.local_inbound_services.as_slice(), workloads),
        None => (slice.services.as_slice(), slice.workloads.as_slice()),
    };
    let Some(local_spiffe) = runtime.workload_spiffe_id.as_deref() else {
        return slice
            .local_ingress_listeners
            .iter()
            .filter(|listener| {
                listener.endpoint_is_valid()
                    && !listener.owner_namespace.is_empty()
                    && !listener.owner_service.is_empty()
            })
            .map(|listener| listener.endpoint_port)
            .filter(|port| *port != 0)
            .collect();
    };
    // Keep the policy table's selectable port domain identical to the inbound
    // route materializer. In particular, a cluster-tagged local workload must
    // be matched with the slice-declared local cluster rather than rejected as
    // remote, and the process runtime's SPIFFE identity is authoritative over
    // a stale or differently sourced identity carried in the slice.
    let local_cluster = slice
        .multi_cluster
        .as_ref()
        .and_then(|multi_cluster| multi_cluster.local_cluster.as_deref());
    let local_workloads = crate::modes::mesh::slice::resolve_local_workloads(
        local_workload_src,
        local_spiffe,
        &slice.labels,
        local_cluster,
    );

    for workload in local_workloads {
        ports.extend(
            workload
                .ports
                .iter()
                .map(|port| port.port)
                .filter(|port| *port != 0),
        );
        for service in services.iter().filter(|service| {
            service.name == workload.service_name
                && service.namespace == workload.namespace
                && service
                    .workloads
                    .iter()
                    .any(|candidate| candidate.spiffe_id == workload.spiffe_id)
        }) {
            for service_port in &service.ports {
                if let Some(app_port) = resolve_sidecar_inbound_backend_port(service_port, workload)
                    .filter(|port| *port != 0)
                {
                    ports.insert(app_port);
                }
            }
        }
    }
    for listener in &slice.local_ingress_listeners {
        if listener.endpoint_is_valid()
            && !listener.owner_namespace.is_empty()
            && !listener.owner_service.is_empty()
        {
            ports.insert(listener.endpoint_port);
        }
    }
    ports
}

/// Resolve every locally selectable app-port-specific PeerAuthentication
/// posture before an inbound TLS handshake. The canonical resolver still
/// filters policy scope and preserves the fail-secure same-tier tie-break for
/// each individual port.
fn resolve_inbound_mtls_modes_by_port(
    slice: Option<&MeshSlice>,
    runtime: &MeshRuntimeConfig,
) -> std::collections::BTreeMap<u16, config::MtlsMode> {
    let Some(slice) = slice else {
        return std::collections::BTreeMap::new();
    };
    let carried_override_ports = slice
        .peer_authentications
        .iter()
        .filter(|policy| policy.has_workload_selector())
        .flat_map(|policy| policy.port_overrides.keys().copied())
        .collect::<std::collections::BTreeSet<_>>();
    // A shared-SPIFFE slice with ambiguous labels cannot reliably identify its
    // local workload/service ports. Preserve every carried candidate override
    // in that case so the fail-closed resolver below can apply the most
    // restrictive candidate posture instead of silently dropping enforcement.
    if slice.labels_ambiguous {
        return carried_override_ports
            .into_iter()
            .map(|port| (port, slice.resolve_inbound_mtls_mode_fail_closed(port)))
            .collect();
    }
    let local_ports = selectable_inbound_peer_auth_ports(slice, runtime);
    carried_override_ports
        .into_iter()
        .filter(|port| local_ports.contains(port))
        .map(|port| (port, slice.resolve_inbound_mtls_mode_fail_closed(port)))
        .collect()
}

/// When PeerAuthentication TLS reload is disabled, the startup table is fixed.
/// Reject a slice that makes an overridden app port newly local when that port
/// was filtered out of the fixed table; accepting it would route traffic under
/// the listener fallback instead of the configured override until restart.
fn newly_selectable_inbound_peer_auth_port_requires_reload(
    previous_slice: Option<&MeshSlice>,
    next_slice: &MeshSlice,
    runtime: &MeshRuntimeConfig,
    fixed_default_mode: config::MtlsMode,
    fixed_modes_by_port: &std::collections::BTreeMap<u16, config::MtlsMode>,
) -> Option<(u16, config::MtlsMode)> {
    let previous_slice = previous_slice?;
    let previous_ports = selectable_inbound_peer_auth_ports(previous_slice, runtime);

    let next_modes = effective_inbound_mtls_modes_for_topology(
        &resolve_inbound_mtls_modes_by_port(Some(next_slice), runtime),
        runtime.topology,
    );
    next_modes.into_iter().find(|(port, mode)| {
        !previous_ports.contains(port)
            && !fixed_modes_by_port.contains_key(port)
            && *mode != fixed_default_mode
    })
}

/// EgressGateway's PERMISSIVE policy is deliberately escalated to a required
/// client-certificate listener. Publish that effective posture to the accept
/// loop and post-route gate so they cannot re-enable plaintext from the raw
/// policy mode after TLS construction has tightened it.
fn effective_inbound_mtls_mode_for_topology(
    mode: config::MtlsMode,
    topology: MeshTopology,
) -> config::MtlsMode {
    if topology == MeshTopology::EgressGateway && mode == config::MtlsMode::Permissive {
        config::MtlsMode::Strict
    } else {
        mode
    }
}

fn effective_inbound_mtls_modes_for_topology(
    modes: &std::collections::BTreeMap<u16, config::MtlsMode>,
    topology: MeshTopology,
) -> std::collections::BTreeMap<u16, config::MtlsMode> {
    modes
        .iter()
        .map(|(&port, &mode)| {
            (
                port,
                effective_inbound_mtls_mode_for_topology(mode, topology),
            )
        })
        .collect()
}

fn mesh_inbound_listener_allows_plaintext(topology: MeshTopology, production: bool) -> bool {
    !production
        && matches!(
            topology,
            MeshTopology::Sidecar | MeshTopology::EgressGateway
        )
}

/// Build the pre-handshake port-domain translation for captured Sidecar
/// ingress[] traffic. SO_ORIGINAL_DST carries the declared listener port, while
/// PeerAuthentication.portLevelMtls is keyed by the defaultEndpoint backend app
/// port. Ordinary captured inbound routes already carry the app port and need
/// no alias.
fn resolve_inbound_app_ports_by_orig_dst_port(
    slice: Option<&MeshSlice>,
) -> std::collections::BTreeMap<u16, u16> {
    let Some(slice) = slice else {
        return std::collections::BTreeMap::new();
    };
    let mut aliases = std::collections::BTreeMap::new();
    for listener in &slice.local_ingress_listeners {
        // Match the ingress materializer's carried-value boundary checks. A
        // malformed listener that cannot become a route must not influence the
        // TLS policy table.
        if !listener.endpoint_is_valid()
            || listener.owner_namespace.is_empty()
            || listener.owner_service.is_empty()
        {
            continue;
        }
        // Native Sidecar resolution already deduplicates by listener port and
        // keeps the first entry. Preserve that deterministic behavior for a
        // defensive carried-slice duplicate as well.
        aliases
            .entry(listener.port)
            .or_insert(listener.endpoint_port);
    }
    aliases
}

/// Reject `MtlsMode::Disable` on topologies whose inbound listener is
/// fundamentally mTLS-only:
///
/// - **Ambient / NodeWaypoint**: HBONE is HTTP/2 CONNECT over mTLS — running
///   it plaintext is not a valid HBONE listener.
/// - **EgressGateway**: the egress listener must verify sidecar client
///   certificates (already enforced for env-derived TLS materials by
///   `validate_egress_gateway_mtls_config`; this check covers the
///   policy-derived path).
///
/// Sidecar and EastWestGateway accept any resolved mode (EastWestGateway
/// has no TLS termination so it is structurally a no-op).
fn validate_inbound_mtls_mode_for_topology(
    runtime: &MeshRuntimeConfig,
    mtls_mode: config::MtlsMode,
) -> Result<(), anyhow::Error> {
    if mtls_mode != config::MtlsMode::Disable {
        return Ok(());
    }
    match runtime.topology {
        MeshTopology::Ambient | MeshTopology::NodeWaypoint | MeshTopology::ServiceWaypoint => {
            Err(anyhow::anyhow!(
                "Mesh PeerAuthentication resolved to DISABLE on {} topology, but HBONE \
             (HTTP/2 CONNECT over mTLS) requires mTLS. Use PERMISSIVE or STRICT for this \
             workload, or move it to Sidecar topology if plaintext-only is intended.",
                runtime.topology.as_str()
            ))
        }
        MeshTopology::EgressGateway => Err(anyhow::anyhow!(
            "Mesh PeerAuthentication resolved to DISABLE on EgressGateway topology, but the \
             egress mTLS listener must verify sidecar client certificates. Use PERMISSIVE or \
             STRICT for this workload."
        )),
        MeshTopology::Sidecar | MeshTopology::EastWestGateway => Ok(()),
    }
}

fn startup_inbound_mtls_mode(
    initial_slice: Option<&MeshSlice>,
    runtime: &MeshRuntimeConfig,
) -> Result<config::MtlsMode, anyhow::Error> {
    let resolved = resolve_inbound_mtls_mode(initial_slice, runtime);
    validate_inbound_mtls_mode_for_topology(runtime, resolved)?;
    for (port, mode) in resolve_inbound_mtls_modes_by_port(initial_slice, runtime) {
        validate_inbound_mtls_mode_for_topology(runtime, mode).with_context(|| {
            format!("PeerAuthentication portLevelMtls[{port}] is invalid for this topology")
        })?;
    }
    Ok(resolved)
}

fn live_reload_inbound_mtls_mode(
    slice: &MeshSlice,
    runtime: &MeshRuntimeConfig,
) -> Option<config::MtlsMode> {
    let resolved = resolve_inbound_mtls_mode(Some(slice), runtime);
    if let Err(error) = validate_inbound_mtls_mode_for_topology(runtime, resolved) {
        warn!(
            mesh_slice_version = %slice.version,
            ?resolved,
            topology = ?runtime.topology,
            "Rejecting mesh slice apply because PeerAuthentication mTLS mode is invalid \
             for this topology: {error}; keeping the previous mesh config"
        );
        return None;
    }
    for (port, mode) in resolve_inbound_mtls_modes_by_port(Some(slice), runtime) {
        if let Err(error) = validate_inbound_mtls_mode_for_topology(runtime, mode) {
            warn!(
                mesh_slice_version = %slice.version,
                port,
                ?mode,
                topology = ?runtime.topology,
                "Rejecting mesh slice apply because portLevelMtls is invalid for this topology: {error}; keeping the previous mesh config"
            );
            return None;
        }
    }
    Some(resolved)
}

#[derive(Clone, Eq)]
struct MeshInboundClientCaBundle {
    path: String,
    pem: Arc<[u8]>,
}

impl PartialEq for MeshInboundClientCaBundle {
    fn eq(&self, other: &Self) -> bool {
        self.pem == other.pem
    }
}

impl fmt::Debug for MeshInboundClientCaBundle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("MeshInboundClientCaBundle")
            .field("path", &self.path)
            .field("pem_len", &self.pem.len())
            .finish()
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MeshInboundTlsReloadSnapshot {
    mtls_mode: config::MtlsMode,
    port_modes: std::collections::BTreeMap<u16, config::MtlsMode>,
    app_port_by_orig_dst_port: std::collections::BTreeMap<u16, u16>,
    client_ca_bundle: Option<MeshInboundClientCaBundle>,
}

fn gateway_svid_material_configured(env_config: &EnvConfig) -> bool {
    env_config.gateway_svid_cert_path.is_some()
        || env_config.gateway_svid_key_path.is_some()
        || env_config.gateway_svid_trust_bundle_path.is_some()
}

fn configured_mesh_workload_spiffe_id(
    runtime: &MeshRuntimeConfig,
) -> Result<crate::identity::SpiffeId, anyhow::Error> {
    let raw = runtime.workload_spiffe_id.as_deref().ok_or_else(|| {
        anyhow::anyhow!(
            "FERRUM_MESH_CA_BACKEND requires FERRUM_MESH_WORKLOAD_SPIFFE_ID so the issued \
             runtime SVID matches the local mesh workload identity"
        )
    })?;
    crate::identity::SpiffeId::new(raw.to_string()).map_err(|error| {
        anyhow::anyhow!(
            "FERRUM_MESH_WORKLOAD_SPIFFE_ID must be a valid SPIFFE URI when \
             FERRUM_MESH_CA_BACKEND is enabled: {error}"
        )
    })
}

async fn start_mesh_ca_backend_svid_source(
    proxy_state: &ProxyState,
    runtime: &MeshRuntimeConfig,
    env_config: &EnvConfig,
    trust_overlay_slot: SharedMeshInboundTrustOverlaySlot,
    mesh_background_handles: &mut Vec<JoinHandle<()>>,
    shutdown_rx: tokio::sync::watch::Receiver<bool>,
) -> Result<Option<tls::SharedBundleSlot>, anyhow::Error> {
    let backend = CaBackend::from_str_lossy(&env_config.mesh_ca_backend)
        .map_err(|error| anyhow::anyhow!("Invalid FERRUM_MESH_CA_BACKEND: {error}"))?;
    if backend == CaBackend::None {
        return Ok(None);
    }

    if gateway_svid_material_configured(env_config) {
        warn!(
            backend = %backend,
            "FERRUM_MESH_CA_BACKEND is configured, but file-based FERRUM_GATEWAY_SVID_* \
             material is also configured; using the explicit file SVID material and not \
             starting automatic CA-backed SVID issuance"
        );
        return Ok(None);
    }

    let workload_spiffe_id = configured_mesh_workload_spiffe_id(runtime)?;
    let inbound_slot: tls::SharedBundleSlot = Arc::new(arc_swap::ArcSwap::new(Arc::new(None)));
    match backend {
        CaBackend::SpireAgent => {
            let slot = start_spire_agent_mesh_svid_source(
                proxy_state,
                env_config,
                &workload_spiffe_id,
                inbound_slot,
                trust_overlay_slot,
                mesh_background_handles,
                shutdown_rx,
            )
            .await?;
            Ok(Some(slot))
        }
        CaBackend::Internal => {
            let slot = start_internal_mesh_svid_source(
                proxy_state,
                env_config,
                workload_spiffe_id,
                inbound_slot,
                trust_overlay_slot,
                mesh_background_handles,
                shutdown_rx,
            )
            .await?;
            Ok(Some(slot))
        }
        CaBackend::None => Ok(None),
    }
}

async fn start_spire_agent_mesh_svid_source(
    proxy_state: &ProxyState,
    env_config: &EnvConfig,
    expected_spiffe_id: &crate::identity::SpiffeId,
    inbound_slot: tls::SharedBundleSlot,
    trust_overlay_slot: SharedMeshInboundTrustOverlaySlot,
    mesh_background_handles: &mut Vec<JoinHandle<()>>,
    mut shutdown_rx: tokio::sync::watch::Receiver<bool>,
) -> Result<tls::SharedBundleSlot, anyhow::Error> {
    let handle = crate::identity::workload_api::SvidFetchHandle::from_slot(
        proxy_state.gateway_svid_bundle.clone(),
    )
    .with_revision_tx(proxy_state.backend_svid_rotation_tx.clone())
    .with_installer({
        let state = proxy_state.clone();
        let inbound_slot = inbound_slot.clone();
        let trust_overlay_slot = trust_overlay_slot.clone();
        move |bundle| {
            state.install_gateway_runtime_svid_bundle(bundle);
            publish_runtime_svid_to_inbound_slot(&state, &inbound_slot, &trust_overlay_slot);
        }
    });
    let fetch_config = crate::identity::workload_api::FetchLoopConfig {
        socket_path: env_config.mesh_spire_agent_socket.clone(),
        expected_spiffe_id: Some(expected_spiffe_id.clone()),
        ..Default::default()
    };
    let join =
        crate::identity::workload_api::spawn_fetch_loop_with_handle(fetch_config, handle.clone());

    if tokio::time::timeout(MESH_CA_INITIAL_SVID_TIMEOUT, handle.wait_for_first_svid())
        .await
        .is_err()
    {
        join.abort();
        return Err(anyhow::anyhow!(
            "timed out after {}s waiting for the initial SPIRE Workload API SVID from {}; \
                 refusing to bind mesh listeners without runtime identity",
            MESH_CA_INITIAL_SVID_TIMEOUT.as_secs(),
            env_config.mesh_spire_agent_socket
        ));
    }

    let snapshot = handle.snapshot();
    let bundle = snapshot.as_ref().as_ref().ok_or_else(|| {
        join.abort();
        anyhow::anyhow!("SPIRE Workload API reported initial readiness without an SVID bundle")
    })?;
    if &bundle.spiffe_id != expected_spiffe_id {
        join.abort();
        anyhow::bail!(
            "SPIRE Workload API returned SVID '{}' but FERRUM_MESH_WORKLOAD_SPIFFE_ID is '{}'",
            bundle.spiffe_id,
            expected_spiffe_id
        );
    }

    info!(
        spiffe_id = %bundle.spiffe_id,
        trust_domain = %bundle.trust_domain(),
        "Mesh CA backend loaded runtime SVID from SPIRE Workload API"
    );
    let mut join = join;
    mesh_background_handles.push(tokio::spawn(async move {
        tokio::select! {
            result = &mut join => {
                if let Err(error) = result
                    && !error.is_cancelled()
                {
                    warn!(
                        error = %error,
                        "SPIRE Workload API SVID fetch task exited unexpectedly"
                    );
                }
            }
            _ = wait_for_mesh_shutdown(&mut shutdown_rx) => {
                join.abort();
                match join.await {
                    Ok(()) => {}
                    Err(error) if error.is_cancelled() => {}
                    Err(error) => {
                        warn!(
                            error = %error,
                            "SPIRE Workload API SVID fetch task failed while stopping"
                        );
                    }
                }
            }
        }
    }));
    Ok(inbound_slot)
}

async fn start_internal_mesh_svid_source(
    proxy_state: &ProxyState,
    env_config: &EnvConfig,
    spiffe_id: crate::identity::SpiffeId,
    inbound_slot: tls::SharedBundleSlot,
    trust_overlay_slot: SharedMeshInboundTrustOverlaySlot,
    mesh_background_handles: &mut Vec<JoinHandle<()>>,
    shutdown_rx: tokio::sync::watch::Receiver<bool>,
) -> Result<tls::SharedBundleSlot, anyhow::Error> {
    let root = crate::identity::ca::bootstrap::bootstrap_dev_root(
        crate::identity::ca::bootstrap::BootstrapConfig::new(spiffe_id.trust_domain().clone()),
    )
    .map_err(|error| anyhow::anyhow!("internal mesh CA bootstrap failed: {error}"))?;
    let ca = Arc::new(crate::identity::ca::internal::InternalCa::new(
        crate::identity::ca::internal::InternalCaConfig {
            root_cert_pem: root.root_cert_pem,
            root_key_pem: root.root_key_pem,
            trust_domain: root.trust_domain,
            bundle_refresh_hint_secs: None,
            default_svid_ttl_secs: env_config.mesh_cert_ttl_seconds,
            max_svid_ttl_secs: crate::identity::ca::internal::MAX_SVID_TTL_SECS,
        },
    )?) as crate::identity::ca::SharedCa;

    issue_and_install_mesh_ca_svid(
        proxy_state,
        ca.as_ref(),
        &spiffe_id,
        env_config,
        &inbound_slot,
        &trust_overlay_slot,
        false,
    )
    .await?;
    let state = proxy_state.clone();
    let loop_env = env_config.clone();
    let loop_inbound_slot = inbound_slot.clone();
    let loop_trust_overlay_slot = trust_overlay_slot.clone();
    mesh_background_handles.push(tokio::spawn(async move {
        run_internal_mesh_svid_rotation_loop(
            state,
            ca,
            spiffe_id,
            loop_env,
            loop_inbound_slot,
            loop_trust_overlay_slot,
            shutdown_rx,
        )
        .await;
    }));

    Ok(inbound_slot)
}

async fn run_internal_mesh_svid_rotation_loop(
    proxy_state: ProxyState,
    ca: crate::identity::ca::SharedCa,
    spiffe_id: crate::identity::SpiffeId,
    env_config: EnvConfig,
    inbound_slot: tls::SharedBundleSlot,
    trust_overlay_slot: SharedMeshInboundTrustOverlaySlot,
    mut shutdown_rx: tokio::sync::watch::Receiver<bool>,
) {
    let mut retry_after_failure = None;
    let mut failure_backoff_secs = INTERNAL_MESH_CA_FAILURE_BACKOFF_INITIAL_SECS;
    loop {
        let next_tick = if let Some(delay) = retry_after_failure.take() {
            delay
        } else {
            let snapshot = proxy_state.gateway_svid_bundle.load_full();
            snapshot
                .as_ref()
                .as_ref()
                .map(|bundle| crate::identity::rotation::decide_next_tick(bundle, 0.5))
                .unwrap_or(Duration::from_secs(1))
        };

        tokio::select! {
            _ = tokio::time::sleep(next_tick) => {}
            changed = shutdown_rx.changed() => {
                if changed.is_err() || *shutdown_rx.borrow() {
                    return;
                }
                continue;
            }
        }

        let needs_rotation = {
            let snapshot = proxy_state.gateway_svid_bundle.load_full();
            snapshot
                .as_ref()
                .as_ref()
                .map(|bundle| crate::identity::rotation::is_due_for_rotation(bundle, 0.5))
                .unwrap_or(true)
        };
        if !needs_rotation {
            continue;
        }

        match issue_and_install_mesh_ca_svid(
            &proxy_state,
            ca.as_ref(),
            &spiffe_id,
            &env_config,
            &inbound_slot,
            &trust_overlay_slot,
            true,
        )
        .await
        {
            Ok(()) => {
                failure_backoff_secs = INTERNAL_MESH_CA_FAILURE_BACKOFF_INITIAL_SECS;
            }
            Err(error) => {
                let retry_delay = crate::util::backoff::jittered_backoff(failure_backoff_secs);
                let retry_after_ms = retry_delay.as_millis();
                retry_after_failure = Some(retry_delay);
                failure_backoff_secs = failure_backoff_secs
                    .saturating_mul(2)
                    .min(crate::util::backoff::BACKOFF_MAX_SECS);
                crate::plugins::mesh::prometheus_helpers::increment_mesh_cert_rotation_failure(
                    &spiffe_id, "internal",
                );
                warn!(
                    error = %error,
                    spiffe_id = %spiffe_id,
                    retry_after_ms,
                    "internal mesh CA SVID rotation failed; keeping current identity"
                );
            }
        }
    }
}

async fn issue_and_install_mesh_ca_svid(
    proxy_state: &ProxyState,
    ca: &dyn CertificateAuthority,
    spiffe_id: &crate::identity::SpiffeId,
    env_config: &EnvConfig,
    inbound_slot: &tls::SharedBundleSlot,
    trust_overlay_slot: &SharedMeshInboundTrustOverlaySlot,
    publish_revision: bool,
) -> Result<(), anyhow::Error> {
    let signed = ca
        .issue_svid(crate::identity::ca::IssuanceRequest::Generate {
            spiffe_id: spiffe_id.clone(),
            ttl_secs: env_config.mesh_cert_ttl_seconds,
        })
        .await?;
    let trust_bundle = ca.trust_bundle(spiffe_id.trust_domain()).await?;
    let bundle = crate::identity::SvidBundle {
        spiffe_id: signed.spiffe_id,
        cert_chain_der: signed.cert_chain_der,
        private_key_pkcs8_der: signed.private_key_pkcs8_der,
        trust_bundles: crate::identity::TrustBundleSet::local_only(crate::identity::TrustBundle {
            trust_domain: trust_bundle.trust_domain.clone(),
            x509_authorities: trust_bundle.roots_der,
            jwt_authorities: Vec::new(),
            refresh_hint_seconds: trust_bundle.refresh_hint_secs,
        }),
    };
    let installed_spiffe_id = bundle.spiffe_id.clone();
    proxy_state.install_gateway_runtime_svid_bundle(bundle);
    publish_runtime_svid_to_inbound_slot(proxy_state, inbound_slot, trust_overlay_slot);
    if publish_revision {
        proxy_state
            .backend_svid_rotation_tx
            .send_modify(|revision| *revision = revision.saturating_add(1));
    }
    info!(
        spiffe_id = %installed_spiffe_id,
        svid_revision = *proxy_state.backend_svid_rotation_tx.borrow(),
        "Mesh CA backend installed runtime SVID"
    );
    Ok(())
}

type SharedMeshInboundTrustOverlaySlot =
    Arc<arc_swap::ArcSwap<Option<crate::identity::TrustBundleSet>>>;

fn empty_mesh_inbound_trust_overlay_slot() -> SharedMeshInboundTrustOverlaySlot {
    Arc::new(arc_swap::ArcSwap::new(Arc::new(None)))
}

/// Republish the inbound SPIFFE verifier slot from the CURRENT runtime SVID plus
/// the current accepted trust overlay.
///
/// Both the SVID rotation install path and the slice-apply staged publish call
/// this, so it serializes on `gateway_svid_update_lock` (the same lock
/// `install_gateway_runtime_svid_bundle` holds) and re-reads the latest SVID from
/// `gateway_file_svid_bundle` under that lock rather than trusting a captured
/// snapshot. Without this, a rotation that completes between a slice apply's
/// staging and publish could be clobbered by the older staged SVID, leaving the
/// inbound verifier pinned to stale (possibly near-expiry) cert/key + roots.
fn publish_runtime_svid_to_inbound_slot(
    proxy_state: &ProxyState,
    inbound_slot: &tls::SharedBundleSlot,
    trust_overlay_slot: &SharedMeshInboundTrustOverlaySlot,
) {
    let _guard = proxy_state
        .gateway_svid_update_lock
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let snapshot = proxy_state.gateway_file_svid_bundle.load_full();
    let Some(mut bundle) = snapshot.as_ref().clone() else {
        return;
    };
    let trust_overlay = trust_overlay_slot.load_full();
    match trust_overlay.as_ref() {
        Some(overlay) => merge_trust_overlay_into_svid_bundle(&mut bundle, overlay),
        None => retain_svid_local_trust_only(&mut bundle),
    }
    inbound_slot.store(Arc::new(Some(bundle)));
}

fn start_mesh_inbound_svid_rotation_republisher(
    proxy_state: ProxyState,
    inbound_slot: tls::SharedBundleSlot,
    trust_overlay_slot: SharedMeshInboundTrustOverlaySlot,
    mut revision_rx: tokio::sync::watch::Receiver<u64>,
    mut shutdown_rx: tokio::sync::watch::Receiver<bool>,
) -> JoinHandle<()> {
    tokio::spawn(async move {
        // Snapshot the rotation revision *before* the initial publish, then
        // republish once up front. A file/CA rotation can bump
        // `backend_svid_rotation_tx` after this receiver was subscribed but
        // before this task runs; the initial publish covers that case because
        // `publish_runtime_svid_to_inbound_slot` re-reads `gateway_file_svid_bundle`
        // live under `gateway_svid_update_lock`, so it picks up any already
        // installed bundle.
        //
        // The ordering matters for the narrow window where a rotation lands
        // *between* the baseline read and the publish (or just after it).
        // The loop dedups on the `observed_revision` integer compare below;
        // if the baseline were taken AFTER the publish it could capture a
        // bump whose bundle the publish had NOT yet read, and then
        // `next_revision == observed_revision` would skip the follow-up
        // republish, pinning the inbound verifier to OLD roots until the next
        // rotation or slice apply. Reading the baseline first guarantees any
        // rotation that could change the bundle is either already reflected in
        // the publish or strictly greater than `observed_revision` (forcing a
        // republish). The publish is idempotent, so the occasional redundant
        // republish is harmless.
        let mut observed_revision = *revision_rx.borrow();
        publish_runtime_svid_to_inbound_slot(&proxy_state, &inbound_slot, &trust_overlay_slot);
        loop {
            tokio::select! {
                changed = revision_rx.changed() => {
                    if changed.is_err() {
                        return;
                    }
                }
                changed = shutdown_rx.changed() => {
                    if changed.is_err() || *shutdown_rx.borrow() {
                        return;
                    }
                    continue;
                }
            }
            let next_revision = *revision_rx.borrow();
            if next_revision == observed_revision {
                continue;
            }
            observed_revision = next_revision;
            publish_runtime_svid_to_inbound_slot(&proxy_state, &inbound_slot, &trust_overlay_slot);
            debug!(
                svid_revision = next_revision,
                "Refreshed mesh inbound SPIFFE peer-verifier bundle after gateway SVID rotation"
            );
        }
    })
}

struct MeshInboundTlsReloadState {
    server_identity: Option<Arc<tls::MeshServerIdentity>>,
    last_snapshot: Option<MeshInboundTlsReloadSnapshot>,
    /// Lock-free SVID bundle slot used to build the SPIFFE trust-domain
    /// verifier for inbound peer certs. `None` when no gateway SVID material
    /// is configured (falls back to operator-CA chain verification). When
    /// present, the slot carries the gateway SVID's local trust bundle merged
    /// with the slice's federated bundles; the verifier reads it live, and
    /// slice apply re-publishes it so federated trust-domain changes take
    /// effect without a listener restart (per the lock-free SVID slot model
    /// in `.claude/rules/tls-security.md`).
    spiffe_bundle_slot: Option<tls::SharedBundleSlot>,
    runtime_trust_overlay_slot: Option<SharedMeshInboundTrustOverlaySlot>,
    /// `FERRUM_MESH_PRODUCTION_MODE` captured once at startup. The live-reload
    /// fail-closed gate (issue #1523) consults this instead of re-reading the
    /// environment on every slice apply: the flag is fixed for the process
    /// lifetime, and a per-apply env read would also be racy under the test
    /// harness's env mutation. A production mesh refuses a PeerAuthentication
    /// update that would downgrade the inbound listener to plaintext.
    production: bool,
}

/// Build the optional SPIFFE inbound trust-bundle slot from file-backed SVID
/// material or a CA-backed runtime SVID slot. Runtime-backed slots receive the
/// accepted slice overlay through `stage_gateway_runtime_spiffe_bundle` so SVID
/// rotations can refresh the inbound verifier without waiting for another
/// slice apply.
/// Returns `None` when no gateway SVID material is configured (the inbound
/// listener then keeps the operator client-CA chain verification it has always
/// used). It also returns `None` (logged) when file SVID material *is*
/// configured but fails to load — but the caller does NOT silently degrade to
/// chain-only in that case (issue #1523): at startup a configured-but-unloadable
/// SVID is fatal (see the F2 note in the body, and
/// `enforce_mesh_inbound_fail_closed`), and on live reload the previous trust
/// bundle is retained. See `build_mesh_inbound_spiffe_slot`'s F2 comment for
/// the precise per-caller disposition.
#[cfg(test)]
#[allow(dead_code)]
fn build_mesh_inbound_spiffe_slot(
    env_config: &EnvConfig,
    slice: Option<&MeshSlice>,
    runtime_svid_slot: Option<&tls::SharedBundleSlot>,
) -> Option<tls::SharedBundleSlot> {
    build_mesh_inbound_spiffe_slot_with_federation(
        env_config,
        slice,
        None,
        FederationActivation::disabled(),
        runtime_svid_slot,
    )
}

fn build_mesh_inbound_spiffe_slot_with_federation(
    env_config: &EnvConfig,
    slice: Option<&MeshSlice>,
    federation: Option<&federation::FederationSnapshot>,
    activation: FederationActivation,
    runtime_svid_slot: Option<&tls::SharedBundleSlot>,
) -> Option<tls::SharedBundleSlot> {
    if let Some(slot) = runtime_svid_slot {
        return Some(slot.clone());
    }

    let (cert_path, key_path, trust_bundle_path) = match (
        env_config.gateway_svid_cert_path.as_deref(),
        env_config.gateway_svid_key_path.as_deref(),
        env_config.gateway_svid_trust_bundle_path.as_deref(),
    ) {
        (Some(cert), Some(key), Some(trust)) => (cert, key, trust),
        _ => return None,
    };

    // F2 (accepted coupling, documented): `load_svid_bundle_from_files`
    // validates the gateway SVID *leaf* (notBefore/notAfter, non-CA) as well as
    // the trust-bundle CAs, so an expired/mid-rotation leaf OR a corrupt trust
    // bundle fails the whole load and this returns `None`. The disposition is the
    // CALLER's, and (issue #1523) it is NOT graceful chain-only at startup:
    //   - Startup: a configured-but-unloadable gateway SVID is a hard fault. The
    //     SAME material is loaded and validated by `load_gateway_svid_bundle` in
    //     ProxyState construction (`new_with_bpf_metrics`), which refuses startup
    //     *first*; `enforce_mesh_inbound_fail_closed` is the inbound-local guard
    //     for the identical condition. So a configured SVID that fails to load —
    //     including an expired/mid-rotation leaf — aborts startup; it does not
    //     silently degrade to chain-only.
    //   - Live reload: `stage_mesh_inbound_spiffe_bundle` keeps the PREVIOUS trust
    //     bundle (the running verifier is retained, not dropped to chain-only), so
    //     a transient mid-rotation failure does not drop inbound trust-domain
    //     enforcement.
    // We intentionally do not load only the trust bundle here: the gateway leaf
    // must also be currently valid for the listener to present a usable server
    // identity, so an expired leaf is a real fault, not a reason to half-load.
    let mut bundle = match crate::identity::file_loader::load_svid_bundle_from_files(
        std::path::Path::new(cert_path),
        std::path::Path::new(key_path),
        std::path::Path::new(trust_bundle_path),
        env_config.gateway_spiffe_id.as_deref(),
    ) {
        Ok(bundle) => bundle,
        Err(error) => {
            // Neutral report — the caller decides the disposition: fatal at
            // startup (also independently enforced by `load_gateway_svid_bundle`),
            // previous-bundle-retained on live reload.
            error!(
                %error,
                "Failed to load gateway SVID material for the mesh inbound SPIFFE peer \
                 verifier (startup: fatal; live reload: previous trust bundle retained)"
            );
            return None;
        }
    };

    let effective_trust_bundles =
        slice.and_then(|slice| effective_trust_bundles_for_slice(slice, federation, activation));
    merge_effective_trust_bundles_into_svid_bundle(&mut bundle, effective_trust_bundles.as_ref());

    Some(Arc::new(arc_swap::ArcSwap::new(Arc::new(Some(bundle)))))
}

/// Overlay the effective federated (and any extra local) trust bundles onto the
/// gateway SVID bundle so the inbound SPIFFE verifier accepts peers from the
/// same active trust domains used for outbound mTLS. The SVID's own local
/// bundle is preserved; effective federated entries replace any raw federated
/// entries already present on the SVID bundle.
fn merge_effective_trust_bundles_into_svid_bundle(
    bundle: &mut crate::identity::SvidBundle,
    trust_bundles: Option<&config::TrustBundleSet>,
) {
    retain_svid_local_trust_only(bundle);
    let Some(serialized) = trust_bundles else {
        return;
    };
    let runtime = match serialized.to_runtime() {
        Ok(runtime) => runtime,
        Err(error) => {
            warn!(
                %error,
                "Ignoring malformed slice trust bundles when building mesh inbound \
                 SPIFFE verifier; using gateway SVID local bundle only"
            );
            return;
        }
    };
    merge_trust_overlay_into_svid_bundle(bundle, &runtime);
}

fn retain_svid_local_trust_only(bundle: &mut crate::identity::SvidBundle) {
    bundle.trust_bundles.federated.clear();
}

fn merge_trust_bundle_authorities(
    target: &mut crate::identity::TrustBundle,
    overlay: &crate::identity::TrustBundle,
) {
    for authority in &overlay.x509_authorities {
        if !target
            .x509_authorities
            .iter()
            .any(|existing| existing == authority)
        {
            target.x509_authorities.push(authority.clone());
        }
    }
    for authority in &overlay.jwt_authorities {
        if !target.jwt_authorities.iter().any(|existing| {
            existing.key_id == authority.key_id
                && existing.public_key_pem == authority.public_key_pem
        }) {
            target.jwt_authorities.push(authority.clone());
        }
    }
    if target.refresh_hint_seconds.is_none() {
        target.refresh_hint_seconds = overlay.refresh_hint_seconds;
    }
}

fn merge_trust_overlay_into_svid_bundle(
    bundle: &mut crate::identity::SvidBundle,
    runtime: &crate::identity::TrustBundleSet,
) {
    // The accepted effective trust set is authoritative for inbound federation.
    // Drop raw federated bundles from the SVID source before adding accepted
    // bundles. The local bundle stays anchored to the gateway SVID's own trust
    // domain, but same-domain authorities are additive so a control plane or
    // polled bundle can stage CA-root rotation without replacing the freshly
    // loaded SVID roots.
    retain_svid_local_trust_only(bundle);
    for (trust_domain, federated) in &runtime.federated {
        bundle
            .trust_bundles
            .federated
            .entry(trust_domain.clone())
            .or_insert_with(|| federated.clone());
    }
    if runtime.local.trust_domain == bundle.trust_bundles.local.trust_domain {
        merge_trust_bundle_authorities(&mut bundle.trust_bundles.local, &runtime.local);
        return;
    }
    // If the slice's local bundle is for a different trust domain than the
    // SVID's, treat it as a federated peer trust domain so cross-trust peers
    // still validate.
    bundle
        .trust_bundles
        .federated
        .entry(runtime.local.trust_domain.clone())
        .or_insert_with(|| runtime.local.clone());
}

/// Rebuild the inbound SPIFFE trust-bundle from the gateway SVID material plus
/// the current slice's federated bundles, returning it STAGED (not yet stored
/// into the live slot). The caller publishes it into the live slot only after
/// the candidate proxy config is accepted, so a rejected slice cannot leave new
/// federated trust domains active for inbound handshakes. A rebuild failure
/// returns `None` (logged) and the caller leaves the previous trust bundles in
/// place — this never fails the slice.
#[cfg(test)]
#[allow(dead_code)]
fn stage_mesh_inbound_spiffe_bundle(
    proxy_state: &ProxyState,
    slot: Option<&tls::SharedBundleSlot>,
    runtime_trust_overlay_slot: Option<&SharedMeshInboundTrustOverlaySlot>,
    env_config: &EnvConfig,
    slice: &MeshSlice,
) -> Option<StagedSpiffeBundle> {
    stage_mesh_inbound_spiffe_bundle_with_federation(
        proxy_state,
        slot,
        runtime_trust_overlay_slot,
        env_config,
        slice,
        None,
        FederationActivation::disabled(),
    )
}

#[allow(clippy::too_many_arguments)]
fn stage_mesh_inbound_spiffe_bundle_with_federation(
    proxy_state: &ProxyState,
    slot: Option<&tls::SharedBundleSlot>,
    runtime_trust_overlay_slot: Option<&SharedMeshInboundTrustOverlaySlot>,
    env_config: &EnvConfig,
    slice: &MeshSlice,
    federation: Option<&federation::FederationSnapshot>,
    activation: FederationActivation,
) -> Option<StagedSpiffeBundle> {
    let slot = slot?;
    if runtime_trust_overlay_slot.is_some() {
        return stage_gateway_runtime_spiffe_bundle_with_federation(
            proxy_state,
            Some(slot),
            runtime_trust_overlay_slot,
            slice,
            federation,
            activation,
        );
    }
    if !gateway_svid_material_configured(env_config) {
        return stage_gateway_runtime_spiffe_bundle_with_federation(
            proxy_state,
            Some(slot),
            runtime_trust_overlay_slot,
            slice,
            federation,
            activation,
        );
    }
    match build_mesh_inbound_spiffe_slot_with_federation(
        env_config,
        Some(slice),
        federation,
        activation,
        None,
    ) {
        Some(rebuilt) => Some(StagedSpiffeBundle::DirectSlot {
            slot: slot.clone(),
            bundle: rebuilt.load_full(),
        }),
        None => {
            warn!(
                mesh_slice_version = %slice.version,
                "Unable to rebuild mesh inbound SPIFFE trust-bundle slot from slice; \
                 keeping previous trust bundles"
            );
            None
        }
    }
}

#[cfg(test)]
#[allow(dead_code)]
fn stage_gateway_runtime_spiffe_bundle(
    proxy_state: &ProxyState,
    slot: Option<&tls::SharedBundleSlot>,
    runtime_trust_overlay_slot: Option<&SharedMeshInboundTrustOverlaySlot>,
    slice: &MeshSlice,
) -> Option<StagedSpiffeBundle> {
    stage_gateway_runtime_spiffe_bundle_with_federation(
        proxy_state,
        slot,
        runtime_trust_overlay_slot,
        slice,
        None,
        FederationActivation::disabled(),
    )
}

fn stage_gateway_runtime_spiffe_bundle_with_federation(
    proxy_state: &ProxyState,
    slot: Option<&tls::SharedBundleSlot>,
    runtime_trust_overlay_slot: Option<&SharedMeshInboundTrustOverlaySlot>,
    slice: &MeshSlice,
    federation: Option<&federation::FederationSnapshot>,
    activation: FederationActivation,
) -> Option<StagedSpiffeBundle> {
    let slot = slot?;
    let runtime_trust_overlay_slot = runtime_trust_overlay_slot?;
    let effective_trust_bundles = effective_trust_bundles_for_slice(slice, federation, activation);
    let trust_overlay = match effective_trust_bundles.as_ref() {
        Some(serialized) => match serialized.to_runtime() {
            Ok(runtime) => Some(runtime),
            Err(error) => {
                warn!(
                    %error,
                    mesh_slice_version = %slice.version,
                    "Unable to stage mesh inbound SPIFFE trust overlay from slice; \
                     keeping previous trust bundles"
                );
                return None;
            }
        },
        None => None,
    };

    let snapshot = proxy_state.gateway_file_svid_bundle.load_full();
    if snapshot.as_ref().is_none() {
        warn!(
            mesh_slice_version = %slice.version,
            "Unable to stage mesh inbound SPIFFE trust overlay because no runtime SVID \
             bundle is loaded; keeping previous trust bundles"
        );
        return None;
    }
    Some(StagedSpiffeBundle::RuntimeSlot {
        slot: slot.clone(),
        trust_overlay_slot: runtime_trust_overlay_slot.clone(),
        trust_overlay,
    })
}

/// Build the inbound SPIFFE client-cert verifier for the given mTLS mode and
/// bundle slot. PERMISSIVE uses `peer_required = false` so a peer that offers
/// no cert is still admitted (but an offered cert is trust-domain-validated);
/// STRICT requires + validates a peer cert. Returns `None` when no slot is
/// available or the mode is DISABLE.
///
/// `crls` is threaded into the verifier so inbound mesh peers get end-entity
/// revocation checking, matching the operator-CA mTLS path. An empty CRL list
/// disables revocation checking (the pre-CRL behavior).
fn mesh_inbound_spiffe_verifier(
    slot: Option<&tls::SharedBundleSlot>,
    mtls_mode: config::MtlsMode,
    crls: tls::CrlList,
) -> Option<Arc<dyn rustls::server::danger::ClientCertVerifier>> {
    let slot = slot?;
    match mtls_mode {
        config::MtlsMode::Strict => Some(tls::build_spiffe_client_cert_verifier(
            slot.clone(),
            true,
            crls,
        )),
        config::MtlsMode::Permissive => Some(tls::build_spiffe_client_cert_verifier(
            slot.clone(),
            false,
            crls,
        )),
        // DISABLE has no TLS; client-side DR modes never reach here.
        _ => None,
    }
}

fn mesh_inbound_tls_reload_snapshot(
    env_config: &EnvConfig,
    mtls_mode: config::MtlsMode,
    port_modes: std::collections::BTreeMap<u16, config::MtlsMode>,
) -> Result<MeshInboundTlsReloadSnapshot, anyhow::Error> {
    let any_mode_needs_client_ca = mtls_mode != config::MtlsMode::Disable
        || port_modes
            .values()
            .any(|mode| *mode != config::MtlsMode::Disable);
    let client_ca_bundle = if !any_mode_needs_client_ca {
        None
    } else if let Some(path) = env_config.frontend_tls_client_ca_bundle_path.as_deref() {
        let source = CertSource::parse(path, MaterialKind::CaBundle);
        let material =
            load_material_blocking(&source, MaterialKind::CaBundle).with_context(|| {
                format!(
                    "failed to load mesh frontend client CA bundle at {}",
                    source.redacted_source_id()
                )
            })?;
        let pem: Arc<[u8]> = material.bytes.expose_secret().to_vec().into();
        Some(MeshInboundClientCaBundle {
            path: material.display_source_id,
            pem,
        })
    } else {
        None
    };
    Ok(MeshInboundTlsReloadSnapshot {
        mtls_mode,
        port_modes,
        app_port_by_orig_dst_port: std::collections::BTreeMap::new(),
        client_ca_bundle,
    })
}

fn mesh_inbound_tls_reload_snapshot_for_listener(
    env_config: &EnvConfig,
    mtls_mode: config::MtlsMode,
    port_modes: std::collections::BTreeMap<u16, config::MtlsMode>,
    has_termination_listener: bool,
) -> Result<MeshInboundTlsReloadSnapshot, anyhow::Error> {
    if !has_termination_listener {
        return Ok(MeshInboundTlsReloadSnapshot {
            mtls_mode,
            port_modes,
            app_port_by_orig_dst_port: std::collections::BTreeMap::new(),
            client_ca_bundle: None,
        });
    }
    mesh_inbound_tls_reload_snapshot(env_config, mtls_mode, port_modes)
}

fn load_mesh_frontend_server_identity(
    env_config: &EnvConfig,
    gateway_svid_bundle: &crate::identity::SharedSvidBundle,
) -> Result<Option<Arc<tls::MeshServerIdentity>>, anyhow::Error> {
    // The explicit frontend TLS cert/key is the operator override for the
    // inbound listener's server identity. It stays a STATIC operational input
    // (the operator owns its rotation), per the TLS rotation model.
    if let (Some(cert_path), Some(key_path)) = (
        env_config.frontend_tls_cert_path.as_deref(),
        env_config.frontend_tls_key_path.as_deref(),
    ) {
        return Ok(Some(tls::load_mesh_server_identity(
            cert_path,
            key_path,
            env_config.tls_cert_expiry_warning_days,
        )?));
    }
    // Otherwise fall back to the gateway SVID material as the inbound server
    // identity (issue #1523, gap #3 — "gateway SVID ≠ inbound server identity").
    // Previously a mesh configured with ONLY FERRUM_GATEWAY_SVID_* had a SPIFFE
    // peer *verifier* (built separately by `build_mesh_inbound_spiffe_slot`) but
    // no server *cert*, so `load_mesh_frontend_tls` fell open to `Ok(None)`
    // (plaintext) under the default PERMISSIVE mode. The gateway SVID IS the
    // mesh's workload identity, so it should back the listener's server cert.
    //
    // The identity resolves LIVE from the shared SVID slot — the same slot the
    // gateway SVID file watcher (`run_gateway_svid_file_rotation_loop`) and any
    // future CA-backend rotation loop store into — so a file-based SVID
    // rotation reaches inbound handshakes without a restart (this closes the
    // old "inbound server cert pinned at startup" caveat from issue #1523).
    // Startup still hard-errors when the slot's current material cannot back a
    // server certificate (fail closed): configured-but-broken identity is a
    // real fault, not a dev-plaintext posture ("no identity at all" is gated
    // separately at config time by #1522). `ProxyState` construction loaded
    // and validated the same files into this slot before we got here.
    if let (Some(cert_path), Some(key_path)) = (
        env_config.gateway_svid_cert_path.as_deref(),
        env_config.gateway_svid_key_path.as_deref(),
    ) {
        info!(
            "Mesh inbound listener using gateway SVID material as its TLS server \
             identity (no explicit FERRUM_FRONTEND_TLS_CERT_PATH / KEY_PATH set). \
             The inbound server certificate resolves live from the gateway SVID \
             slot and rotates with it."
        );
        return Ok(Some(tls::svid_rotating_mesh_server_identity(
            cert_path,
            key_path,
            gateway_svid_bundle.clone(),
        )?));
    }
    // No explicit FERRUM_FRONTEND_TLS_* override and no FERRUM_GATEWAY_SVID_*
    // file material, but a CA backend (FERRUM_MESH_CA_BACKEND=spire|internal) is
    // active: the inbound listener's server identity is the CA-issued runtime
    // SVID. `start_mesh_ca_backend_svid_source` (run earlier in startup) installs
    // that SVID into `proxy_state.gateway_svid_bundle` — the same shared slot
    // passed here — and refreshes it on every rotation, so the inbound server
    // certificate resolves LIVE from the slot exactly like the gateway-SVID-file
    // case above. `svid_rotating_mesh_server_identity` validates the slot's
    // current material and FAILS CLOSED at startup if it is empty (a configured
    // CA backend that produced no usable SVID is a real fault, not a
    // dev-plaintext posture). There are no cert/key files, so the descriptor
    // strings record the CA backend rather than a path.
    let ca_backend = crate::identity::ca::CaBackend::from_str_lossy(&env_config.mesh_ca_backend)
        .map_err(|error| anyhow::anyhow!("Invalid FERRUM_MESH_CA_BACKEND: {error}"))?;
    if ca_backend != crate::identity::ca::CaBackend::None {
        let descriptor = format!("FERRUM_MESH_CA_BACKEND={ca_backend}");
        info!(
            ca_backend = %ca_backend,
            "Mesh inbound listener using the CA-backed runtime SVID as its TLS \
             server identity (no explicit FERRUM_FRONTEND_TLS_* or FERRUM_GATEWAY_SVID_* \
             material set). The inbound server certificate resolves live from the \
             gateway SVID slot and rotates with each CA-backed issuance."
        );
        return Ok(Some(tls::svid_rotating_mesh_server_identity(
            &descriptor,
            &descriptor,
            gateway_svid_bundle.clone(),
        )?));
    }
    Ok(None)
}

/// Outcome of resolving a PeerAuthentication mTLS mode into an inbound
/// rustls client-auth posture, given which trust anchors are available.
///
/// Kept separate from [`tls::MeshClientAuth`] so the caller can emit a single
/// loud warning for the one degraded case (PERMISSIVE with no trust anchor at
/// all) without that warning living inside an otherwise-pure decision that
/// tests want to assert on directly.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MeshClientAuthDecision {
    /// A concrete client-auth posture was resolved.
    Resolved(tls::MeshClientAuth),
    /// PERMISSIVE was requested but neither an operator client-CA bundle nor a
    /// gateway SVID trust anchor exists, so a presented peer cert cannot be
    /// verified and no SPIFFE identity can be recorded. Resolves to
    /// [`tls::MeshClientAuth::None`] (no CertificateRequest), and the caller is
    /// expected to warn once.
    PermissiveNoTrustAnchor,
    /// EgressGateway-only fail-closed decision: the egress mTLS listener is a
    /// security boundary that MUST authenticate every client, but PERMISSIVE
    /// resolved with no trust anchor at all (no client-CA bundle, no SVID
    /// material), so it cannot. Optional-no-verify mTLS would admit cert-less
    /// peers straight onto the external backend, so [`load_mesh_frontend_tls`]
    /// turns this into a hard error rather than serving it. In practice
    /// [`validate_egress_gateway_mtls_config`] already requires a peer verifier
    /// for this topology, so this is defense-in-depth for the
    /// reload/non-validated paths.
    EgressGatewayNoTrustAnchor,
}

impl MeshClientAuthDecision {
    /// The rustls client-auth posture this decision maps to.
    fn client_auth(self) -> tls::MeshClientAuth {
        match self {
            MeshClientAuthDecision::Resolved(auth) => auth,
            MeshClientAuthDecision::PermissiveNoTrustAnchor
            | MeshClientAuthDecision::EgressGatewayNoTrustAnchor => tls::MeshClientAuth::None,
        }
    }
}

/// Resolve the inbound rustls client-auth posture for a PeerAuthentication mTLS
/// mode, given whether an operator client-CA bundle and/or a gateway SVID
/// trust-domain verifier are available.
///
/// This is the security-critical decision behind mesh inbound mTLS:
/// - `STRICT` → `Required`: a peer cert is mandatory and verified.
/// - `PERMISSIVE` with **any** trust anchor (SVID verifier preferred, else the
///   operator client-CA bundle) → `Optional`: the listener requests a client
///   cert and verifies it when offered, but cert-less peers are still admitted.
///   This is what lets PERMISSIVE record `peer_spiffe_id` for a peer that
///   presents a valid SVID instead of silently treating it as anonymous.
///   **EgressGateway is the exception**: that topology's TLS listener (the
///   `:15090` HTTP mTLS inbound AND the F6.1 stream-family egress listeners that
///   share the same `ServerConfig`) is a security boundary onto external
///   networks. A cert-less client admitted there reaches the external backend
///   unauthenticated, so PERMISSIVE-with-anchor is escalated to `Required`:
///   every egress client MUST present a verifiable SVID. STRICT, the explicit
///   `FERRUM_MESH_EGRESS_STREAM_ALLOW_PLAINTEXT` opt-out (handled before this
///   resolver, plaintext listener), and PeerAuthentication `DISABLE` (rejected
///   for EgressGateway by [`validate_inbound_mtls_mode_for_topology`]) are the
///   only ways an egress client skips client-cert verification.
/// - `PERMISSIVE` with **no** trust anchor → [`MeshClientAuthDecision::PermissiveNoTrustAnchor`]
///   for non-egress topologies: no CertificateRequest is sent because a
///   presented cert could not be verified anyway. The caller emits a single
///   loud warning. For **EgressGateway** the same input is
///   [`MeshClientAuthDecision::EgressGatewayNoTrustAnchor`]: the security
///   boundary cannot authenticate clients at all, so the caller fails closed
///   (hard error) instead of serving optional-no-verify mTLS.
///   ([`validate_egress_gateway_mtls_config`] already requires a peer verifier
///   for this topology at config time; this is defense-in-depth for the
///   live-reload/non-validated paths.)
/// - `DISABLE` never reaches here (handled by the plaintext-listener early
///   return in [`load_mesh_frontend_tls`]).
/// - `Simple` / `Mutual` / `IstioMutual` are client-side `DestinationRule.tls`
///   modes that must never reach this server-side resolver; they fall back to
///   no client auth so a mistranslation cannot crash a running data plane.
fn resolve_mesh_inbound_client_auth(
    mtls_mode: config::MtlsMode,
    has_client_ca_bundle: bool,
    has_spiffe_verifier: bool,
    topology: MeshTopology,
) -> MeshClientAuthDecision {
    let is_egress_gateway = topology == MeshTopology::EgressGateway;
    match mtls_mode {
        config::MtlsMode::Strict => MeshClientAuthDecision::Resolved(tls::MeshClientAuth::Required),
        config::MtlsMode::Permissive if has_client_ca_bundle || has_spiffe_verifier => {
            // EgressGateway is a security boundary onto external networks: a
            // cert-less client must NOT be admitted to the external backend.
            // Escalate PERMISSIVE-with-anchor from Optional to Required so every
            // egress client presents a verifiable SVID. Non-egress topologies
            // keep the standard PERMISSIVE-optional posture (verify-if-offered,
            // still admit cert-less peers) unchanged.
            if is_egress_gateway {
                MeshClientAuthDecision::Resolved(tls::MeshClientAuth::Required)
            } else {
                MeshClientAuthDecision::Resolved(tls::MeshClientAuth::Optional)
            }
        }
        // EgressGateway with no trust anchor cannot authenticate clients at all;
        // serving optional-no-verify mTLS would admit cert-less peers onto the
        // external backend. Fail closed instead (the caller hard-errors).
        config::MtlsMode::Permissive if is_egress_gateway => {
            MeshClientAuthDecision::EgressGatewayNoTrustAnchor
        }
        config::MtlsMode::Permissive => MeshClientAuthDecision::PermissiveNoTrustAnchor,
        // DISABLE has no TLS and is handled before this resolver runs.
        config::MtlsMode::Disable => MeshClientAuthDecision::Resolved(tls::MeshClientAuth::None),
        // `Simple` / `Mutual` / `IstioMutual` are client-side `DestinationRule`
        // modes; they never apply to a server-side PeerAuthentication listener.
        config::MtlsMode::Simple | config::MtlsMode::Mutual | config::MtlsMode::IstioMutual => {
            MeshClientAuthDecision::Resolved(tls::MeshClientAuth::None)
        }
    }
}

/// Build the mesh frontend TLS configuration respecting the resolved mTLS mode.
///
/// - `Strict` / `Permissive`: Load TLS with the appropriate client-auth mode.
/// - `Disable`: Return `None` (plaintext listener).
///
/// `topology` drives the EgressGateway client-auth escalation (PERMISSIVE +
/// trust anchor → Required; PERMISSIVE + no anchor → fail closed) — see
/// [`resolve_mesh_inbound_client_auth`].
#[allow(clippy::too_many_arguments)]
fn load_mesh_frontend_tls(
    env_config: &EnvConfig,
    tls_policy: &TlsPolicy,
    crls: &[rustls::pki_types::CertificateRevocationListDer<'static>],
    mtls_mode: config::MtlsMode,
    topology: MeshTopology,
    server_identity: Option<&tls::MeshServerIdentity>,
    client_ca_bundle: Option<&MeshInboundClientCaBundle>,
    spiffe_bundle_slot: Option<&tls::SharedBundleSlot>,
) -> Result<Option<Arc<rustls::ServerConfig>>, anyhow::Error> {
    if mtls_mode == config::MtlsMode::Disable {
        info!(
            "Mesh PeerAuthentication mTLS mode is DISABLE; inbound listener will accept plaintext only"
        );
        return Ok(None);
    }

    let Some(server_identity) = server_identity else {
        if mtls_mode == config::MtlsMode::Strict {
            return Err(anyhow::anyhow!(
                "Mesh PeerAuthentication STRICT requires FERRUM_FRONTEND_TLS_CERT_PATH and FERRUM_FRONTEND_TLS_KEY_PATH"
            ));
        }
        return Ok(None);
    };

    // SPIFFE trust-domain verifier (validates peer SANs against local+federated
    // bundles). Present only when gateway SVID material is configured. When
    // present it drives client auth even without an operator client CA bundle,
    // because it carries its own trust anchors from the SVID bundle. The
    // gateway CRLs are threaded in so inbound mesh peers get the same
    // end-entity revocation enforcement the operator-CA path already applies
    // (empty CRLs => no revocation checking, unchanged behavior).
    let spiffe_verifier =
        mesh_inbound_spiffe_verifier(spiffe_bundle_slot, mtls_mode, Arc::new(crls.to_vec()));

    let client_ca_bundle_path = client_ca_bundle
        .map(|bundle| bundle.path.as_str())
        .or(env_config.frontend_tls_client_ca_bundle_path.as_deref());
    let client_auth = match resolve_mesh_inbound_client_auth(
        mtls_mode,
        client_ca_bundle_path.is_some(),
        spiffe_verifier.is_some(),
        topology,
    ) {
        MeshClientAuthDecision::Resolved(auth) => {
            // A client-side `DestinationRule.tls` mode reaching this server-side
            // resolver is a translator bug; surface it loudly. The resolver
            // already maps it to no client auth so a mistranslation cannot crash
            // a running data plane.
            if matches!(
                mtls_mode,
                config::MtlsMode::Simple | config::MtlsMode::Mutual | config::MtlsMode::IstioMutual
            ) {
                warn!(
                    mode = ?mtls_mode,
                    "Mesh PeerAuthentication received a client-side DR.tls mode; \
                     falling back to no client auth (this is a programming error \
                     in the K8s translator if observed)"
                );
            }
            auth
        }
        MeshClientAuthDecision::EgressGatewayNoTrustAnchor => {
            // Fail closed: an EgressGateway is a security boundary onto external
            // networks. PERMISSIVE resolved here with no trust anchor at all, so
            // it cannot authenticate clients; serving optional-no-verify mTLS
            // would admit cert-less peers straight onto the external backend.
            // Refuse to build the listener rather than silently downgrade the
            // egress boundary. (`validate_egress_gateway_mtls_config` already
            // requires a peer verifier at config time; this guards the
            // live-reload/non-validated paths.)
            return Err(anyhow::anyhow!(
                "Mesh PeerAuthentication resolved to PERMISSIVE on EgressGateway topology but no \
                 FERRUM_FRONTEND_TLS_CLIENT_CA_BUNDLE_PATH or gateway SVID material is configured, \
                 so the egress mTLS listener cannot verify sidecar client certificates. The egress \
                 gateway must authenticate every client; configure a client-CA bundle or gateway \
                 SVID material, use STRICT PeerAuthentication, or set \
                 FERRUM_MESH_EGRESS_STREAM_ALLOW_PLAINTEXT=true to explicitly opt the stream egress \
                 listeners into unauthenticated plaintext"
            ));
        }
        decision @ MeshClientAuthDecision::PermissiveNoTrustAnchor => {
            // Loud, single warning: PERMISSIVE with no trust anchor at all means
            // a presented peer cert cannot be verified and no SPIFFE identity
            // can be recorded. We do not silently pretend to do mTLS — we make
            // the missing-anchor degradation explicit.
            warn!(
                "Mesh PeerAuthentication mTLS mode is PERMISSIVE but no \
                 FERRUM_FRONTEND_TLS_CLIENT_CA_BUNDLE_PATH or gateway SVID material is \
                 configured; client certificates will not be requested or verified and \
                 no peer SPIFFE identity will be recorded for inbound connections"
            );
            decision.client_auth()
        }
    };
    // The SPIFFE verifier only applies when we actually request client certs.
    let spiffe_verifier = if matches!(client_auth, tls::MeshClientAuth::None) {
        None
    } else {
        spiffe_verifier
    };
    if spiffe_verifier.is_some() {
        info!(
            ?mtls_mode,
            "Mesh inbound listener verifying peer SPIFFE SAN trust domains against \
             local + federated SVID bundles"
        );
    }

    let client_ca_bundle_ref = client_ca_bundle.map(|bundle| tls::ClientCaBundleRef {
        path: bundle.path.as_str(),
        pem: bundle.pem.as_ref(),
    });
    // `MeshServerIdentity` encapsulates both the operator-static credential and
    // the SVID-rotating credential (CA-backed or gateway-SVID-file); its
    // `server_cert_resolver` presents the live leaf per handshake for the
    // rotating source and fails closed when the shared slot is empty. The same
    // `spiffe_verifier` is wired in below regardless of source, so a CA-backed
    // inbound listener verifies peer SPIFFE SANs exactly like the file path.
    let mut tls_config = if let Some(bundle_ref) = client_ca_bundle_ref {
        tls::load_mesh_tls_config_with_identity_and_client_ca_bytes(
            server_identity,
            Some(bundle_ref),
            client_auth,
            tls_policy,
            env_config.tls_cert_expiry_warning_days,
            crls,
            spiffe_verifier,
        )
    } else {
        tls::load_mesh_tls_config_with_identity(
            server_identity,
            client_ca_bundle_path,
            client_auth,
            tls_policy,
            env_config.tls_cert_expiry_warning_days,
            crls,
            spiffe_verifier,
        )
    }
    .map_err(|e| anyhow::anyhow!("Invalid mesh frontend TLS configuration: {}", e))?;
    tls::enable_early_data(&mut tls_config, tls_policy);
    if env_config.ktls_enabled.could_be_enabled() {
        tls::enable_secret_extraction_for_ktls(&mut tls_config);
    }
    Ok(Some(tls_config))
}

#[allow(clippy::too_many_arguments)]
fn load_mesh_frontend_tls_by_port(
    env_config: &EnvConfig,
    tls_policy: &TlsPolicy,
    crls: &[rustls::pki_types::CertificateRevocationListDer<'static>],
    modes: &std::collections::BTreeMap<u16, config::MtlsMode>,
    topology: MeshTopology,
    server_identity: Option<&tls::MeshServerIdentity>,
    client_ca_bundle: Option<&MeshInboundClientCaBundle>,
    spiffe_bundle_slot: Option<&tls::SharedBundleSlot>,
) -> Result<HashMap<u16, Option<Arc<rustls::ServerConfig>>>, anyhow::Error> {
    // There are only three valid server-side modes. Share one immutable
    // ServerConfig per distinct mode instead of rebuilding certificates and
    // verifiers for every declared app port.
    let mut configs_by_mode: Vec<(config::MtlsMode, Option<Arc<rustls::ServerConfig>>)> =
        Vec::new();
    let mut by_port = HashMap::with_capacity(modes.len());
    for (&port, &mode) in modes {
        let tls_config = if let Some((_, cached)) = configs_by_mode
            .iter()
            .find(|(cached_mode, _)| *cached_mode == mode)
        {
            cached.clone()
        } else {
            let built = load_mesh_frontend_tls(
                env_config,
                tls_policy,
                crls,
                mode,
                topology,
                server_identity,
                client_ca_bundle,
                spiffe_bundle_slot,
            )
            .with_context(|| format!("failed to build inbound TLS config for app port {port}"))?;
            configs_by_mode.push((mode, built.clone()));
            built
        };
        by_port.insert(port, tls_config);
    }
    Ok(by_port)
}

/// Posture decision for a mesh inbound listener that would serve **plaintext**
/// (issue #1523). Pure so the truth table can be unit-tested without touching the
/// environment; the env reads + logging live in [`enforce_mesh_inbound_fail_closed`].
///
/// | trigger (plaintext) | production | result             |
/// |---------------------|------------|--------------------|
/// | false               | *          | `Ok`               |
/// | true                | true       | `Refuse`           |
/// | true                | false      | `AllowWithWarning` |
///
/// The **production** contract is absolute: a production mesh must serve mTLS on
/// its inbound listener, so a plaintext posture is refused. **Dev** allows it
/// with a loud warning — reaching plaintext in dev is always *intentional*: the
/// no-identity *silent default* trap is separately fail-closed at config time by
/// the `FERRUM_MESH_ALLOW_NO_CA` gate (`EnvConfig::validate`), so the only ways to
/// get here in dev are (a) that opt-out already acknowledged, or (b) an explicit
/// `PeerAuthentication` DISABLE. The runtime gate therefore does not re-consult
/// the dev opt-out.
///
/// This governs ONLY the plaintext posture. A *configured-but-unloadable* SVID
/// verifier (the listener serves TLS but its SPIFFE trust-domain verifier failed
/// to load) is a genuine misconfiguration, not an intentional dev posture, so
/// [`enforce_mesh_inbound_fail_closed`] hard-errors that case regardless of
/// `production` — never routing it through this decision.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MeshInboundFailClosed {
    /// Listener enforces mTLS (or there is nothing to enforce); proceed.
    Ok,
    /// Insecure posture tolerated in dev/test; proceed after a loud warning.
    AllowWithWarning,
    /// Refuse — a production mesh must not serve a plaintext inbound listener.
    Refuse,
}

fn decide_mesh_inbound_fail_closed(trigger: bool, production: bool) -> MeshInboundFailClosed {
    if !trigger {
        MeshInboundFailClosed::Ok
    } else if production {
        MeshInboundFailClosed::Refuse
    } else {
        MeshInboundFailClosed::AllowWithWarning
    }
}

fn mesh_inbound_mode_accepts_plaintext(mode: config::MtlsMode) -> bool {
    matches!(
        mode,
        config::MtlsMode::Permissive | config::MtlsMode::Disable
    )
}

/// Fail closed when the *resolved* mesh inbound listener would not actually
/// enforce mTLS (issue #1523 — the runtime complement to #1522's config-time
/// presence check).
///
/// #1522 guarantees that a production mesh *names* file-based gateway SVID
/// material, but that is only a presence check: it cannot see whether the
/// material loads or whether the resolved PeerAuthentication mode would leave
/// the inbound mTLS/HBONE termination listener serving plaintext. This runs at
/// the startup TLS-setup path, where the listener's real posture is known, and
/// closes two distinct escapes — with deliberately different severity:
///
///  - **configured-but-unloadable SVID verifier** (gap #2): the listener serves
///    TLS but gateway SVID material is configured and failed to load, so the
///    SPIFFE peer-trust-domain verifier is absent (an offered peer cert would not
///    be trust-domain validated). The operator named all three
///    `FERRUM_GATEWAY_SVID_*` paths intending verification, so this is a genuine
///    misconfiguration — **fatal regardless of `production`**, mirroring how
///    [`load_mesh_frontend_server_identity`] already hard-errors a broken SVID
///    cert/key. (`ProxyState` construction's `load_gateway_svid_bundle` rejects
///    the same broken material independently; this is the inbound-local guard.)
///  - **would-serve-plaintext**: a termination listener exists but its resolved
///    `ServerConfig` is `None` (DISABLE, or no usable server identity). Refused
///    under `production`; in dev allowed with a loud warning. A usable
///    PERMISSIVE config remains startup-compatible with the historical
///    TLS-only production listener; listener-kind demux controls whether dev
///    Sidecar traffic may additionally arrive as plaintext.
///
/// Topologies without a TLS-terminating inbound listener (EastWestGateway does
/// SNI passthrough — encrypted bytes are forwarded, never terminated) have no
/// plaintext-inbound posture to enforce against and are skipped.
fn enforce_mesh_inbound_fail_closed(
    runtime: &MeshRuntimeConfig,
    env_config: &EnvConfig,
    mtls_mode: config::MtlsMode,
    frontend_tls: Option<&Arc<rustls::ServerConfig>>,
    spiffe_bundle_slot: Option<&tls::SharedBundleSlot>,
    production: bool,
) -> Result<(), anyhow::Error> {
    if !runtime.has_inbound_tls_termination_listener() {
        return Ok(());
    }

    // A configured-but-unloadable SVID verifier on a TLS-serving listener is a
    // genuine fault, not an intentional posture, so it is fatal regardless of
    // `production` (consistent with the hard error a broken SVID cert/key already
    // gets in `load_mesh_frontend_server_identity`). "Configured" is exact: blank
    // FERRUM_GATEWAY_SVID_* values were normalized to `None` at parse (#1522), so
    // all-three-`Some` means material was named; `build_mesh_inbound_spiffe_slot`
    // returning `None` for named material then means the load failed (it logs the
    // underlying error first). This is gated on `frontend_tls.is_some()` so a
    // resolved-plaintext listener (DISABLE — the verifier is unused) falls to the
    // plaintext branch below instead.
    let gateway_svid_configured = env_config.gateway_svid_cert_path.is_some()
        && env_config.gateway_svid_key_path.is_some()
        && env_config.gateway_svid_trust_bundle_path.is_some();
    if frontend_tls.is_some() && gateway_svid_configured && spiffe_bundle_slot.is_none() {
        return Err(anyhow::anyhow!(
            "gateway SVID material is configured (FERRUM_GATEWAY_SVID_*) but failed to load on \
             {} topology, so the mesh inbound listener would serve TLS WITHOUT SPIFFE \
             peer-trust-domain verification (an offered peer certificate would not be \
             trust-domain validated). Fix the SVID cert/key/trust-bundle material, or unset it \
             to fall back to operator client-CA verification.",
            runtime.topology.as_str()
        ));
    }

    // Otherwise the only remaining escape is a listener with no usable TLS
    // config. PERMISSIVE with a valid config historically starts in production
    // and remains TLS-only there; do not turn its optional client certificate
    // posture into a new startup failure.
    let reason: &str = if mtls_mode == config::MtlsMode::Disable {
        "PeerAuthentication resolved to DISABLE, so the inbound mTLS/HBONE termination \
         listener would accept unauthenticated plaintext"
    } else if mtls_mode == config::MtlsMode::Permissive {
        "PeerAuthentication resolved to PERMISSIVE, so the inbound mTLS/HBONE termination \
         listener would accept unauthenticated plaintext alongside TLS"
    } else {
        "the inbound mTLS/HBONE termination listener resolved to no usable TLS server identity \
         (set FERRUM_GATEWAY_SVID_CERT_PATH / KEY_PATH / TRUST_BUNDLE_PATH, or \
         FERRUM_FRONTEND_TLS_CERT_PATH / KEY_PATH), so it would accept unauthenticated plaintext"
    };
    match decide_mesh_inbound_fail_closed(frontend_tls.is_none(), production) {
        MeshInboundFailClosed::Ok => {
            crate::plugins::mesh::prometheus_helpers::set_mesh_inbound_plaintext_allowed(false);
            Ok(())
        }
        MeshInboundFailClosed::AllowWithWarning => {
            // Coarse posture gauge only — the reason detail stays in the
            // `warn!` below (security detail goes to logs, not /metrics).
            crate::plugins::mesh::prometheus_helpers::set_mesh_inbound_plaintext_allowed(true);
            warn!(
                topology = runtime.topology.as_str(),
                ?mtls_mode,
                "{reason}. The mesh inbound listener is coming up WITHOUT enforced mTLS and may \
                 accept unauthenticated plaintext traffic. Dev/test only — configure gateway \
                 SVID material and set FERRUM_MESH_PRODUCTION_MODE=true for production."
            );
            Ok(())
        }
        // Refuse only happens under production mode (see decide_*).
        MeshInboundFailClosed::Refuse => Err(anyhow::anyhow!(
            "FERRUM_MESH_PRODUCTION_MODE=true but {reason} on {} topology. Refusing to start: a \
             production mesh must serve mTLS on its inbound listener.",
            runtime.topology.as_str()
        )),
    }
}

fn validate_egress_gateway_mtls_config(
    runtime: &MeshRuntimeConfig,
    env_config: &EnvConfig,
) -> Result<(), anyhow::Error> {
    if runtime.topology != MeshTopology::EgressGateway {
        return Ok(());
    }

    let has_explicit_frontend_identity =
        env_config.frontend_tls_cert_path.is_some() && env_config.frontend_tls_key_path.is_some();
    let has_file_svid_identity = env_config.gateway_svid_cert_path.is_some()
        && env_config.gateway_svid_key_path.is_some()
        && env_config.gateway_svid_trust_bundle_path.is_some();
    let has_ca_backed_svid_identity = runtime.ca_backend != CaBackend::None;
    let has_svid_backed_identity = has_file_svid_identity || has_ca_backed_svid_identity;

    if !has_explicit_frontend_identity && !has_svid_backed_identity {
        return Err(anyhow::anyhow!(
            "FERRUM_MESH_TOPOLOGY=egress_gateway requires a TLS server identity for the egress mTLS listener: set FERRUM_FRONTEND_TLS_CERT_PATH and FERRUM_FRONTEND_TLS_KEY_PATH, configure FERRUM_GATEWAY_SVID_CERT_PATH / FERRUM_GATEWAY_SVID_KEY_PATH / FERRUM_GATEWAY_SVID_TRUST_BUNDLE_PATH, or configure FERRUM_MESH_CA_BACKEND with FERRUM_MESH_WORKLOAD_SPIFFE_ID"
        ));
    }

    if env_config.tls_no_verify {
        return Err(anyhow::anyhow!(
            "FERRUM_MESH_TOPOLOGY=egress_gateway cannot be used with FERRUM_TLS_NO_VERIFY=true because the egress mTLS listener must verify sidecar client certificates"
        ));
    }

    if env_config.frontend_tls_client_ca_bundle_path.is_none() && !has_svid_backed_identity {
        return Err(anyhow::anyhow!(
            "FERRUM_MESH_TOPOLOGY=egress_gateway requires a peer verifier for the egress mTLS listener: set FERRUM_FRONTEND_TLS_CLIENT_CA_BUNDLE_PATH, configure FERRUM_GATEWAY_SVID_CERT_PATH / FERRUM_GATEWAY_SVID_KEY_PATH / FERRUM_GATEWAY_SVID_TRUST_BUNDLE_PATH, or configure FERRUM_MESH_CA_BACKEND with FERRUM_MESH_WORKLOAD_SPIFFE_ID"
        ));
    }

    Ok(())
}

fn listener_tls_config(
    listener: &MeshListener,
    frontend_tls: Option<Arc<rustls::ServerConfig>>,
) -> Option<Arc<rustls::ServerConfig>> {
    match listener.kind {
        // Both plaintext listeners (TCP outbound capture and the UDP TPROXY
        // capture listener) terminate no TLS.
        MeshListenerKind::PlaintextCapture | MeshListenerKind::PlaintextUdpCapture => None,
        MeshListenerKind::MtlsTermination | MeshListenerKind::HboneTermination => frontend_tls,
    }
}

/// Resolve the per-listener TLS config, respecting PeerAuthentication mTLS mode.
///
/// - `Disable` mode: all listeners run plaintext (no TLS config).
/// - `Strict` / `Permissive`: mTLS/HBONE listeners get the frontend TLS config;
///   plaintext-capture listeners stay plaintext.
fn listener_tls_config_for_mtls_mode(
    listener: &MeshListener,
    frontend_tls: Option<Arc<rustls::ServerConfig>>,
    mtls_mode: config::MtlsMode,
) -> Option<Arc<rustls::ServerConfig>> {
    if mtls_mode == config::MtlsMode::Disable {
        return None;
    }
    listener_tls_config(listener, frontend_tls)
}

fn mesh_inbound_spiffe_verifier_active(
    has_termination_listener: bool,
    tls_configured: bool,
    spiffe_bundle_slot_configured: bool,
) -> bool {
    has_termination_listener && tls_configured && spiffe_bundle_slot_configured
}

enum MeshInboundTlsReloadPlan {
    /// No listener TLS-config change is needed (mode + client CA bundle are
    /// unchanged), but the SPIFFE federated trust-bundle may still need
    /// publishing because the snapshot does not capture the slice's federated
    /// trust domains. The staged bundle is published only after the proxy
    /// config is accepted.
    Unchanged {
        staged_spiffe: Option<StagedSpiffeBundle>,
    },
    Swap {
        snapshot: MeshInboundTlsReloadSnapshot,
        tls_config: Option<Arc<rustls::ServerConfig>>,
        tls_by_port: HashMap<u16, Option<Arc<rustls::ServerConfig>>>,
        /// SPIFFE inbound trust-bundle staged during reload planning but NOT yet
        /// stored into the live slot. It is published into the live slot only
        /// when the proxy config is accepted (alongside the TLS swap), so a
        /// rejected slice never leaves new federated trust domains live for
        /// inbound handshakes. `None` when there is no SPIFFE slot (no gateway
        /// SVID material) or the rebuild failed (the live slot is left intact).
        staged_spiffe: Option<StagedSpiffeBundle>,
    },
}

/// A staged inbound SPIFFE trust update. Staging keeps the live verifier
/// reading the previous trust bundles until the candidate proxy config is
/// accepted.
enum StagedSpiffeBundle {
    /// File-backed SVID path: replace the dedicated inbound verifier slot.
    DirectSlot {
        slot: tls::SharedBundleSlot,
        bundle: Arc<Option<crate::identity::SvidBundle>>,
    },
    /// Runtime-backed SVID path: update the dedicated inbound verifier slot
    /// from the latest raw SVID plus the accepted slice trust overlay. The
    /// SVID itself is intentionally not captured at staging time because a
    /// file/CA rotation can complete while the candidate slice is still being
    /// planned.
    RuntimeSlot {
        slot: tls::SharedBundleSlot,
        trust_overlay_slot: SharedMeshInboundTrustOverlaySlot,
        trust_overlay: Option<crate::identity::TrustBundleSet>,
    },
}

#[allow(clippy::too_many_arguments)]
#[cfg(test)]
#[allow(dead_code)]
fn plan_mesh_inbound_tls_reload(
    proxy_state: &ProxyState,
    runtime: &MeshRuntimeConfig,
    slice: &MeshSlice,
    mtls_mode: config::MtlsMode,
    server_identity: Option<&tls::MeshServerIdentity>,
    last_snapshot: Option<&MeshInboundTlsReloadSnapshot>,
    spiffe_bundle_slot: Option<&tls::SharedBundleSlot>,
    runtime_trust_overlay_slot: Option<&SharedMeshInboundTrustOverlaySlot>,
    production: bool,
    // Precomputed once by the apply task (topology is process-fixed) so the reload
    // path does not re-derive `runtime.listener_plan()` on every slice apply.
    has_termination_listener: bool,
) -> Option<MeshInboundTlsReloadPlan> {
    plan_mesh_inbound_tls_reload_with_federation(
        proxy_state,
        runtime,
        slice,
        None,
        FederationActivation::disabled(),
        mtls_mode,
        server_identity,
        last_snapshot,
        spiffe_bundle_slot,
        runtime_trust_overlay_slot,
        production,
        has_termination_listener,
    )
}

#[allow(clippy::too_many_arguments)]
fn plan_mesh_inbound_tls_reload_with_federation(
    proxy_state: &ProxyState,
    runtime: &MeshRuntimeConfig,
    slice: &MeshSlice,
    federation: Option<&federation::FederationSnapshot>,
    activation: FederationActivation,
    mtls_mode: config::MtlsMode,
    server_identity: Option<&tls::MeshServerIdentity>,
    last_snapshot: Option<&MeshInboundTlsReloadSnapshot>,
    spiffe_bundle_slot: Option<&tls::SharedBundleSlot>,
    runtime_trust_overlay_slot: Option<&SharedMeshInboundTrustOverlaySlot>,
    production: bool,
    // Precomputed once by the apply task (topology is process-fixed) so the reload
    // path does not re-derive `runtime.listener_plan()` on every slice apply.
    has_termination_listener: bool,
) -> Option<MeshInboundTlsReloadPlan> {
    let port_modes = resolve_inbound_mtls_modes_by_port(Some(slice), runtime);
    let mut next_snapshot = match mesh_inbound_tls_reload_snapshot_for_listener(
        &proxy_state.env_config,
        mtls_mode,
        port_modes,
        has_termination_listener,
    ) {
        Ok(snapshot) => snapshot,
        Err(error) => {
            warn!(
                mesh_slice_version = %slice.version,
                ?mtls_mode,
                "Unable to inspect mesh inbound TLS reload inputs: {error}; rejecting the entire mesh slice and keeping the last good config in its entirety (no authz/policy/ServiceEntry/endpoint update from this slice is applied) until the inbound TLS inputs are readable again"
            );
            return None;
        }
    };
    next_snapshot.app_port_by_orig_dst_port =
        resolve_inbound_app_ports_by_orig_dst_port(Some(slice));
    // Rebuild the SPIFFE inbound trust-bundle from the new slice's federated
    // bundles, but STAGE it rather than storing it into the live slot here.
    // Storing during planning would let a slice that is later rejected leave
    // its federated trust domains active for new inbound handshakes (a rejected
    // update could trust new peer domains or drop existing ones with no backing
    // mesh config). The staged bundle is published into the live slot only after
    // the candidate proxy config is accepted. The verifier reads the slot live,
    // so this still propagates federated trust-domain changes lock-free even
    // when the operator client CA bundle and mTLS mode are otherwise unchanged.
    // Only the accepted slice trust overlay is recomputed; the SVID cert/key
    // and local roots stay anchored to the current file or CA runtime source.
    let staged_spiffe = stage_mesh_inbound_spiffe_bundle_with_federation(
        proxy_state,
        spiffe_bundle_slot,
        runtime_trust_overlay_slot,
        &proxy_state.env_config,
        slice,
        federation,
        activation,
    );
    if last_snapshot == Some(&next_snapshot) {
        return Some(MeshInboundTlsReloadPlan::Unchanged { staged_spiffe });
    }
    let Some(tls_policy) = proxy_state.tls_policy.as_deref() else {
        error!(
            mesh_slice_version = %slice.version,
            ?mtls_mode,
            "Mesh PeerAuthentication live reload requested but TLS policy is unavailable; this is a programming error. Applying proxy config only; the inbound TLS slot remains at its previous value until restart and will be re-evaluated on later slice applies."
        );
        return Some(MeshInboundTlsReloadPlan::Unchanged { staged_spiffe });
    };
    match load_mesh_frontend_tls(
        &proxy_state.env_config,
        tls_policy,
        &proxy_state.crls,
        mtls_mode,
        runtime.topology,
        server_identity,
        next_snapshot.client_ca_bundle.as_ref(),
        spiffe_bundle_slot,
    ) {
        Ok(tls_config) => {
            let tls_by_port = match if has_termination_listener {
                load_mesh_frontend_tls_by_port(
                    &proxy_state.env_config,
                    tls_policy,
                    &proxy_state.crls,
                    &next_snapshot.port_modes,
                    runtime.topology,
                    server_identity,
                    next_snapshot.client_ca_bundle.as_ref(),
                    spiffe_bundle_slot,
                )
            } else {
                Ok(HashMap::new())
            } {
                Ok(configs) => configs,
                Err(error) => {
                    warn!(
                        mesh_slice_version = %slice.version,
                        "Failed to rebuild per-app-port mesh inbound TLS configs: {error}; rejecting the entire mesh slice and keeping the last good config"
                    );
                    return None;
                }
            };
            // Runtime fail-closed for PeerAuthentication LIVE RELOAD (issue
            // #1523): the startup gate (`enforce_mesh_inbound_fail_closed`) only
            // sees the initial slice. A later accepted update that resolves the
            // inbound termination listener to a plaintext-capable posture —
            // PERMISSIVE admits plaintext beside TLS, while DISABLE makes
            // `load_mesh_frontend_tls` return `None`, which
            // `apply_mesh_inbound_tls_reload` would store, clearing the inbound +
            // shared-stream TLS slots — would silently downgrade a running
            // production sidecar. Reject the slice instead (return `None` → the
            // apply task keeps the last-good mTLS config in its entirety;
            // fail-closed by retention, never crashing a live data plane). Same
            // posture as startup: refused under production; dev allows it with a
            // warning (an explicit plaintext-capable mode is intentional).
            // Topologies without a TLS-terminating inbound listener (EastWestGateway
            // SNI passthrough) are exempt (`has_termination_listener` is false).
            let effective_mode =
                effective_inbound_mtls_mode_for_topology(mtls_mode, runtime.topology);
            let effective_port_modes = effective_inbound_mtls_modes_for_topology(
                &next_snapshot.port_modes,
                runtime.topology,
            );
            let accepts_plaintext = tls_config.is_none()
                || tls_by_port.values().any(Option::is_none)
                || (mesh_inbound_listener_allows_plaintext(runtime.topology, production)
                    && (mesh_inbound_mode_accepts_plaintext(effective_mode)
                        || effective_port_modes
                            .values()
                            .copied()
                            .any(mesh_inbound_mode_accepts_plaintext)));
            if has_termination_listener && accepts_plaintext {
                match decide_mesh_inbound_fail_closed(true, production) {
                    MeshInboundFailClosed::Refuse => {
                        warn!(
                            mesh_slice_version = %slice.version,
                            ?mtls_mode,
                            topology = runtime.topology.as_str(),
                            "Rejecting mesh slice: this PeerAuthentication update resolves the \
                             inbound mTLS/HBONE termination listener to a plaintext-capable \
                             posture, which a production mesh must not serve. Keeping the last-good \
                             mTLS config in its entirety (no authz/policy/ServiceEntry/endpoint \
                             update from this slice is applied)."
                        );
                        // Drop the staged SPIFFE bundle: the slice is rejected, so
                        // the live slot keeps its previous trust bundles.
                        return None;
                    }
                    MeshInboundFailClosed::AllowWithWarning => {
                        // Warn here at the decision site, but do NOT touch the
                        // coarse posture gauge yet: this is still plan time, and
                        // `proxy_state.update_config()` may reject the candidate
                        // slice. The gauge is written only on the accepted-apply
                        // path in `apply_mesh_inbound_tls_reload`, derived from
                        // the swapped `tls_config`.
                        warn!(
                            mesh_slice_version = %slice.version,
                            ?mtls_mode,
                            topology = runtime.topology.as_str(),
                            "Applying a PeerAuthentication update that downgrades the inbound \
                             listener to plaintext. The mesh inbound listener will accept \
                             unauthenticated plaintext traffic. Dev/test only."
                        );
                    }
                    MeshInboundFailClosed::Ok => {}
                }
            }
            Some(MeshInboundTlsReloadPlan::Swap {
                snapshot: next_snapshot,
                tls_config,
                tls_by_port,
                staged_spiffe,
            })
        }
        Err(error) => {
            warn!(
                mesh_slice_version = %slice.version,
                ?mtls_mode,
                "Failed to rebuild mesh inbound TLS config from PeerAuthentication update: {error}; rejecting the entire mesh slice and keeping the last good config in its entirety (no authz/policy/ServiceEntry/endpoint update from this slice is applied) until the inbound TLS rebuild succeeds"
            );
            // Drop the staged SPIFFE bundle: the slice is being rejected, so the
            // live slot must keep its previous trust bundles.
            None
        }
    }
}

/// Reload-invariant context for [`apply_mesh_inbound_tls_reload`], bundled so
/// the per-slice call passes one value alongside the slice-specific plan.
struct MeshInboundTlsReloadCtx {
    has_termination_listener: bool,
    spiffe_bundle_slot_configured: bool,
    topology: MeshTopology,
    production: bool,
}

async fn apply_mesh_inbound_tls_reload(
    proxy_state: &ProxyState,
    slice: &MeshSlice,
    mtls_mode: config::MtlsMode,
    plan: MeshInboundTlsReloadPlan,
    last_snapshot: &mut Option<MeshInboundTlsReloadSnapshot>,
    ctx: MeshInboundTlsReloadCtx,
) {
    let MeshInboundTlsReloadCtx {
        has_termination_listener,
        spiffe_bundle_slot_configured,
        topology,
        production,
    } = ctx;
    match plan {
        MeshInboundTlsReloadPlan::Unchanged { staged_spiffe } => {
            // Listener TLS config is unchanged, but a federated trust-domain
            // change may still need publishing. Now that the proxy config was
            // accepted, store the staged SPIFFE bundle into the live slot.
            publish_staged_spiffe_bundle(proxy_state, staged_spiffe);
            let policy = proxy_state.mesh_inbound_tls_policy.load();
            let tls_configured =
                policy.default.is_some() || policy.by_port.values().any(Option::is_some);
            proxy_state.mesh_inbound_spiffe_verifier_active.store(
                mesh_inbound_spiffe_verifier_active(
                    has_termination_listener,
                    tls_configured,
                    spiffe_bundle_slot_configured,
                ),
                Ordering::Release,
            );
        }
        MeshInboundTlsReloadPlan::Swap {
            snapshot,
            tls_config,
            tls_by_port,
            staged_spiffe,
        } => {
            let effective_mode = effective_inbound_mtls_mode_for_topology(mtls_mode, topology);
            let effective_port_modes =
                effective_inbound_mtls_modes_for_topology(&snapshot.port_modes, topology);
            let plaintext_allowed = mesh_inbound_listener_allows_plaintext(topology, production)
                && (mesh_inbound_mode_accepts_plaintext(effective_mode)
                    || effective_port_modes
                        .values()
                        .copied()
                        .any(mesh_inbound_mode_accepts_plaintext)
                    || tls_config.is_none()
                    || tls_by_port.values().any(Option::is_none));
            let any_tls_configured =
                tls_config.is_some() || tls_by_port.values().any(Option::is_some);
            // Publish the staged SPIFFE trust-bundle into the live slot first,
            // then swap the listener TLS config. Both happen only post-accept so
            // a rejected slice never alters inbound trust. The verifier reads
            // the slot live; the new TLS config's verifier will observe the new
            // bundle on its next handshake.
            publish_staged_spiffe_bundle(proxy_state, staged_spiffe);
            proxy_state
                .mesh_inbound_tls
                .store(Arc::new(tls_config.clone()));
            proxy_state.mesh_inbound_tls_policy.store(Arc::new(
                crate::proxy::MeshInboundTlsPolicy {
                    default: tls_config.clone(),
                    by_port: tls_by_port,
                    default_mode: effective_inbound_mtls_mode_for_topology(mtls_mode, topology),
                    modes_by_port: effective_inbound_mtls_modes_for_topology(
                        &snapshot.port_modes,
                        topology,
                    ),
                    app_port_by_orig_dst_port: snapshot.app_port_by_orig_dst_port.clone(),
                },
            ));
            proxy_state.mesh_inbound_spiffe_verifier_active.store(
                mesh_inbound_spiffe_verifier_active(
                    has_termination_listener,
                    any_tls_configured,
                    spiffe_bundle_slot_configured,
                ),
                Ordering::Release,
            );
            // Coarse posture gauge, written only here on the accepted-apply
            // path so a candidate slice that `update_config()` rejects leaves
            // the gauge at its pre-reload value (fail-closed by retention,
            // matching the rest of this reload contract). Derived from the
            // swapped config rather than carried on the plan: a Swap that
            // clears the termination listener's ServerConfig is exactly the
            // dev plaintext posture (production planning rejects that swap as
            // a whole-slice `None`, which never reaches this function), and a
            // Swap that restores one heals it. Topologies without a
            // TLS-terminating inbound listener (EastWestGateway SNI
            // passthrough) never move the gauge.
            if has_termination_listener {
                crate::plugins::mesh::prometheus_helpers::set_mesh_inbound_plaintext_allowed(
                    plaintext_allowed,
                );
            }
            // Extend the live carve-out to mesh-shared TCP+TLS stream
            // listeners: swap the shared `rustls::ServerConfig` slot that
            // every TCP+TLS accept loop snapshots per accept. Existing
            // sessions keep the `ServerConfig` they handshake with until
            // they end; new accepts use the swapped config on the next
            // handshake. Skips when the slot is empty (PeerAuth resolved
            // to `Disable`).
            proxy_state
                .stream_listener_manager
                .swap_frontend_tls_config(tls_config);
            // And the same for UDP+DTLS: rebuild a `FrontendDtlsConfig`
            // from the current env-config inputs and have every active
            // `DtlsServer` swap atomically. Existing DTLS sessions keep
            // the crypto material they handshake with; new sessions pick
            // up the swap on the next ClientHello.
            //
            // The DTLS rebuild reuses operator-supplied cert/key/client-CA
            // paths because PeerAuth live reload, per the operating
            // invariant, never rotates cert/key paths — those remain
            // static restart-required inputs. What changes here is the
            // *mode* (Permissive ↔ Strict) and whether the client CA bundle
            // is required for mTLS verification.
            //
            // Skip the DTLS rebuild entirely on `Disable`: TCP+TLS goes to
            // plaintext via the cleared slot above, but DTLS cannot speak
            // plaintext (it is encryption by definition). On topologies
            // where `Disable` is allowed (Sidecar / EastWestGateway), an
            // operator with UDP+DTLS listeners is expected to remove
            // them from the proxy config rather than rely on a PeerAuth
            // flip; the existing DtlsServer keeps its startup material
            // so in-flight sessions and any pre-existing handshake
            // contract remain intact until the listener is reconciled
            // away.
            if mtls_mode != config::MtlsMode::Disable {
                let env = &proxy_state.env_config;
                let crls = proxy_state.crls.clone();
                let dtls_cert_key = env
                    .frontend_tls_cert_path
                    .as_deref()
                    .zip(env.frontend_tls_key_path.as_deref())
                    .map(|(c, k)| (c.to_string(), k.to_string()));
                let dtls_client_ca = env.frontend_tls_client_ca_bundle_path.clone();
                if let Some((cert_path, key_path)) = dtls_cert_key {
                    let swapped = proxy_state
                        .stream_listener_manager
                        .swap_active_dtls_frontend_configs(|| {
                            crate::dtls::build_frontend_dtls_config(
                                &cert_path,
                                &key_path,
                                dtls_client_ca.as_deref(),
                                &crls,
                            )
                        })
                        .await;
                    if swapped > 0 {
                        info!(
                            mesh_slice_version = %slice.version,
                            ?mtls_mode,
                            dtls_listeners = swapped,
                            "Mesh inbound PeerAuthentication DTLS configs reloaded"
                        );
                    }
                }
            }
            *last_snapshot = Some(snapshot);
            info!(
                mesh_slice_version = %slice.version,
                ?mtls_mode,
                "Mesh inbound PeerAuthentication TLS config reloaded"
            );
        }
    }
}

fn publish_mesh_inbound_app_port_aliases(proxy_state: &ProxyState, slice: &MeshSlice) {
    let aliases = resolve_inbound_app_ports_by_orig_dst_port(Some(slice));
    let current = proxy_state.mesh_inbound_tls_policy.load_full();
    if current.app_port_by_orig_dst_port == aliases {
        return;
    }
    proxy_state
        .mesh_inbound_tls_policy
        .store(Arc::new(crate::proxy::MeshInboundTlsPolicy {
            default: current.default.clone(),
            by_port: current.by_port.clone(),
            default_mode: current.default_mode,
            modes_by_port: current.modes_by_port.clone(),
            app_port_by_orig_dst_port: aliases,
        }));
}

/// Reconcile the SPIFFE federation pollers against the latest accepted mesh
/// slice. Destructive actions (stopping pollers / removing bundles) must not run
/// from a merely received slice because the apply task may reject that slice and
/// keep serving the previous accepted proxy config.
fn start_federation_poller_reconcile_task(
    mesh_state: MeshRuntimeState,
    mut manager: federation::FederationPollerManager,
    mut shutdown_rx: tokio::sync::watch::Receiver<bool>,
) -> JoinHandle<()> {
    tokio::spawn(async move {
        let mut updates = mesh_state.subscribe_applied();
        loop {
            if *shutdown_rx.borrow() {
                manager.shutdown();
                return;
            }

            let snapshot = mesh_state.applied_snapshot();
            let multi_cluster = snapshot
                .as_ref()
                .as_ref()
                .and_then(|slice| slice.multi_cluster.as_ref());
            manager.reconcile(multi_cluster);

            tokio::select! {
                changed = updates.changed() => {
                    if changed.is_err() {
                        manager.shutdown();
                        return;
                    }
                }
                _ = wait_for_mesh_shutdown(&mut shutdown_rx) => {
                    manager.shutdown();
                    return;
                }
            }
        }
    })
}

/// Reconcile remote-cluster endpoint-discovery pollers against the latest
/// **accepted** mesh slice. Like the federation poller reconciler above, the
/// multicluster config and trust bundles are read from the *applied* slice
/// (`applied_snapshot` / `subscribe_applied`), never the merely *received* one:
/// the apply task may REJECT a received slice and keep serving the previous
/// accepted proxy config, so a rejected slice that diverges (e.g. a changed
/// `network` or `control_plane_url` for the same cluster name + trust domain)
/// must never start a poller or populate the `RemoteEndpointStore`. Sourcing
/// discovery from the accepted slice keeps `GET /mesh/remote-clusters`'s
/// `discovered` view free of any cluster the proxy did not accept (the
/// admin-side name+trust-domain filter is then belt-and-suspenders) and means
/// the store only ever holds endpoints from the proxy-applied multicluster
/// config.
fn start_remote_cluster_discovery_reconcile_task(
    mesh_state: MeshRuntimeState,
    mut manager: multicluster::RemoteDiscoveryManager,
    federation_activation: FederationActivation,
    mut shutdown_rx: tokio::sync::watch::Receiver<bool>,
) -> JoinHandle<()> {
    tokio::spawn(async move {
        let mut updates = mesh_state.subscribe_applied();
        let mut federation_updates = mesh_state.federation_store().subscribe();
        loop {
            if *shutdown_rx.borrow() {
                manager.shutdown();
                return;
            }

            let snapshot = mesh_state.applied_snapshot();
            let slice = snapshot.as_ref().as_ref();
            let federation_snapshot = mesh_state.federation_store().snapshot();
            let effective_trust_bundles = slice.and_then(|slice| {
                effective_trust_bundles_for_slice(
                    slice,
                    Some(&federation_snapshot),
                    federation_activation,
                )
            });
            let empty_federation_snapshot = federation::FederationSnapshot::default();
            let trust_domains = multicluster::trust_domains_from_bundles(
                effective_trust_bundles.as_ref(),
                &empty_federation_snapshot,
            );
            manager.reconcile(
                slice.and_then(|slice| slice.multi_cluster.as_ref()),
                trust_domains,
            );

            tokio::select! {
                changed = updates.changed() => {
                    if changed.is_err() {
                        manager.shutdown();
                        return;
                    }
                }
                changed = federation_updates.changed() => {
                    if changed.is_err() {
                        manager.shutdown();
                        return;
                    }
                }
                _ = wait_for_mesh_shutdown(&mut shutdown_rx) => {
                    manager.shutdown();
                    return;
                },
            }
        }
    })
}

/// Publish a staged inbound SPIFFE trust-bundle into its live slot. Called only
/// after the candidate proxy config is accepted, so the live verifier never
/// trusts (or stops trusting) peer domains for a slice the runtime rejected.
/// The verifier holds an `Arc` to this slot and observes the new bundle on its
/// next handshake.
fn publish_staged_spiffe_bundle(proxy_state: &ProxyState, staged: Option<StagedSpiffeBundle>) {
    match staged {
        Some(StagedSpiffeBundle::DirectSlot { slot, bundle }) => {
            slot.store(bundle);
        }
        Some(StagedSpiffeBundle::RuntimeSlot {
            slot,
            trust_overlay_slot,
            trust_overlay,
        }) => {
            // Publish the accepted trust overlay, then republish the inbound slot
            // from the LATEST runtime SVID under the rotation lock (a CA rotation
            // may have landed since this slice was staged). `publish_runtime_svid_to_inbound_slot`
            // re-reads `gateway_file_svid_bundle` itself, so a rotation cannot be
            // clobbered by a stale staged snapshot.
            trust_overlay_slot.store(Arc::new(trust_overlay));
            publish_runtime_svid_to_inbound_slot(proxy_state, &slot, &trust_overlay_slot);
        }
        None => {}
    }
}

fn publish_gateway_active_trust_bundles(
    proxy_state: &ProxyState,
    slice: &MeshSlice,
    federation: Option<&federation::FederationSnapshot>,
    activation: FederationActivation,
) {
    let Some(serialized) = effective_trust_bundles_for_slice(slice, federation, activation) else {
        proxy_state.clear_gateway_trust_bundles();
        return;
    };
    match serialized.to_runtime() {
        Ok(runtime) => proxy_state.update_gateway_trust_bundles(runtime),
        Err(error) => {
            warn!(
                %error,
                mesh_slice_version = %slice.version,
                "Unable to publish accepted mesh federation trust to gateway SVID slot; \
                 keeping previous outbound trust bundles"
            );
        }
    }
}

/// Build a proxy [`GatewayConfig`] from `base_slice` overlaid with the current
/// federation + remote-endpoint snapshots and apply it to the live proxy
/// runtime, running the same TLS / node-waypoint / DNS / outbound-enforcement
/// side-effects the apply loop performs. Factored out of
/// [`start_mesh_slice_apply_task`] so the loop can apply a generation against
/// EITHER the freshly-received slice OR the last-accepted slice.
///
/// The last-accepted re-apply is the fix for the codex F7.2 round-4 finding that
/// an accepted remote-cluster (or federation) update was consumed but never
/// reflected while the *received* slice was invalid: the discovery poller is
/// keyed to the accepted slice, so it can legitimately publish endpoint changes
/// for the last-accepted generation while the CP's newest received slice is one
/// the proxy rejects. Re-applying the overlay against `base_slice =
/// last_applied_slice` lets that scale-up/down reach the live proxy without
/// waiting for a fresh valid slice — fail-closed by retention if even the
/// last-accepted base no longer builds.
///
/// `base_slice` is also the candidate for the remote-endpoint membership filter
/// in [`gateway_config_from_mesh_slice`]: a remote cluster absent from (or with
/// a diverged identity vs) `base_slice.multi_cluster` contributes no endpoints
/// to this generation, so cluster removal / control-plane identity changes are
/// fail-closed within the SAME generation rather than leaking one generation
/// until the discovery reconciler evicts the store entry.
#[allow(clippy::too_many_arguments)]
async fn apply_mesh_slice_generation(
    mesh_state: &MeshRuntimeState,
    proxy_state: &ProxyState,
    runtime: &MeshRuntimeConfig,
    base_slice: &MeshSlice,
    federation_snapshot: &federation::FederationSnapshot,
    remote_snapshot: &multicluster::RemoteEndpointSnapshot,
    live_reload_enabled: bool,
    inbound_tls_reload: &mut MeshInboundTlsReloadState,
    has_termination_listener: bool,
    last_applied_slice: &mut Option<Arc<MeshSlice>>,
    dns_proxy: &Option<Arc<MeshDnsProxy>>,
) -> bool {
    if has_termination_listener && !live_reload_enabled {
        let fixed_policy = proxy_state.mesh_inbound_tls_policy.load();
        if let Some((port, mode)) = newly_selectable_inbound_peer_auth_port_requires_reload(
            last_applied_slice.as_deref(),
            base_slice,
            runtime,
            fixed_policy.default_mode,
            &fixed_policy.modes_by_port,
        ) {
            warn!(
                mesh_slice_version = %base_slice.version,
                app_port = port,
                required_mode = ?mode,
                "Rejecting mesh slice because it makes an overridden inbound app port newly selectable while PeerAuthentication TLS live reload is disabled; restart with the new port present or enable FERRUM_MESH_PEER_AUTH_LIVE_RELOAD_ENABLED"
            );
            return false;
        }
    }

    let federation_activation = FederationActivation::from_env_config(&proxy_state.env_config);
    let live_reload = if live_reload_enabled {
        live_reload_inbound_mtls_mode(base_slice, runtime).and_then(|mtls_mode| {
            plan_mesh_inbound_tls_reload_with_federation(
                proxy_state,
                runtime,
                base_slice,
                Some(federation_snapshot),
                federation_activation,
                mtls_mode,
                inbound_tls_reload.server_identity.as_deref(),
                inbound_tls_reload.last_snapshot.as_ref(),
                inbound_tls_reload.spiffe_bundle_slot.as_ref(),
                inbound_tls_reload.runtime_trust_overlay_slot.as_ref(),
                inbound_tls_reload.production,
                has_termination_listener,
            )
            .map(|plan| (mtls_mode, plan))
        })
    } else {
        None
    };
    if live_reload_enabled && live_reload.is_none() {
        warn!(
            mesh_slice_version = %base_slice.version,
            "Rejected mesh slice before proxy config apply because inbound mTLS live reload preparation failed"
        );
        return false;
    }
    let staged_inbound_spiffe = if live_reload_enabled {
        None
    } else {
        stage_mesh_inbound_spiffe_bundle_with_federation(
            proxy_state,
            inbound_tls_reload.spiffe_bundle_slot.as_ref(),
            inbound_tls_reload.runtime_trust_overlay_slot.as_ref(),
            &proxy_state.env_config,
            base_slice,
            Some(federation_snapshot),
            federation_activation,
        )
    };
    match gateway_config_from_mesh_slice_with_federation(
        base_slice,
        runtime,
        Some(federation_snapshot),
        Some(remote_snapshot),
        federation_activation,
    ) {
        Ok(mut config) => {
            let previous_config = proxy_state.config.load_full();
            // Materialized mesh upstreams are rebuilt with fresh per-apply
            // timestamps every slice apply (the materializers stamp `Utc::now()`
            // and `project_mesh_source_locality` re-bumps when it stamps the
            // source locality onto the freshly materialized `source_locality =
            // None`). Reconcile each candidate upstream's timestamps against the
            // previously-accepted config so an upstream whose CONTENT is unchanged
            // keeps its prior `updated_at`: otherwise `ConfigDelta` would flag
            // every mesh upstream as modified on every apply and rebuild its
            // `LoadBalancer` — resetting round-robin/EWMA/hash-ring/passive-health
            // state on unrelated mesh-only updates (federation/trust overlays, a
            // different service's remote scale event). A genuinely changed
            // upstream keeps its fresh timestamp and still rebuilds exactly that
            // one LB. Must run BEFORE `update_config` computes the delta.
            reconcile_mesh_upstream_timestamps(&mut config, &previous_config);
            reconcile_fault_plugin_generations(&mut config, &previous_config);
            // GAP-2M.4: build node-waypoint per-pod policy scopes before
            // config apply, but publish them only after update_config accepts
            // the candidate. Pre-swapping scopes can pair old policies with a
            // rejected slice's workload metadata indefinitely; staging keeps
            // rejection side-effect free while making the post-accept swap a
            // cheap ArcSwap publish.
            let staged_policy_scopes = if runtime.topology == MeshTopology::NodeWaypoint {
                proxy_state
                    .node_waypoint_identity_resolver
                    .as_ref()
                    .map(|resolver| {
                        (
                            Arc::clone(resolver),
                            resolver
                                .build_policy_scope_snapshot_from_workloads(&base_slice.workloads),
                        )
                    })
            } else {
                None
            };
            // The TLS reload plan (listener config + staged SPIFFE inbound
            // trust-bundle) is built before config apply, but both are
            // published only after proxy config acceptance inside
            // `apply_mesh_inbound_tls_reload`. This avoids pre-swapping TLS or
            // mutating inbound trust domains for a proxy config the runtime
            // rejects, at the cost of a tiny accept window where listeners may
            // still see the previous TLS config and the previous trust bundle.
            // On a Permissive-to-Strict escalation, an accepted connection in
            // that window can enter the new plugin chain without a peer
            // principal; mesh authz still fails closed for identity-required
            // policy until the slot swaps.
            let dns_slice = dns_proxy.as_ref().and_then(|_| {
                node_waypoint_dns_slice_for_prepared_config(runtime, base_slice, &config)
            });
            let outcome = proxy_state.update_config(config);
            let applied = outcome.applied();
            let accepted = outcome.accepted();
            // Publish the node-waypoint resolver snapshot the instant the proxy
            // config is accepted — before recording the apply result or
            // reloading TLS — so the window where the new config is live but the
            // resolver still holds the previous generation is the minimum
            // possible. Config and resolver are independent ArcSwaps that cannot
            // swap atomically, and staging-until-accept keeps a rejected slice
            // side-effect-free, which precludes pre-swapping the resolver before
            // update_config. So config swaps first and the resolver swaps here,
            // one statement later: within that bounded window the OLD generation
            // still answers, so a workload the new slice removed keeps resolving
            // its old scope (served briefly — NOT failed closed in-window), and
            // a newly added one is not yet enrolled. This is the accepted,
            // self-correcting apply-gap residual: it closes the instant the
            // store below runs, and because the HTTP/HBONE path re-queries the
            // scope per request it picks up the new generation on the next
            // request (the stream path captures at accept). The fail-closed
            // authz gate is enforced against whichever generation is live — it
            // is not an in-window guarantee.
            if accepted && let Some((resolver, snapshot)) = staged_policy_scopes {
                resolver.install_policy_scope_snapshot(snapshot);
            }
            record_mesh_slice_apply_result(mesh_state, last_applied_slice, base_slice, accepted);
            if accepted {
                publish_gateway_active_trust_bundles(
                    proxy_state,
                    base_slice,
                    Some(federation_snapshot),
                    federation_activation,
                );
                // Sidecar ingress routes remain live-reloadable even when
                // PeerAuthentication TLS rebuilding is disabled. Publish the
                // listener-port -> backend-app-port demux table for every
                // accepted slice so pre-handshake policy selection follows the
                // same ingress generation as routing.
                publish_mesh_inbound_app_port_aliases(proxy_state, base_slice);
                match live_reload {
                    Some((mtls_mode, plan)) => {
                        apply_mesh_inbound_tls_reload(
                            proxy_state,
                            base_slice,
                            mtls_mode,
                            plan,
                            &mut inbound_tls_reload.last_snapshot,
                            MeshInboundTlsReloadCtx {
                                has_termination_listener,
                                spiffe_bundle_slot_configured: inbound_tls_reload
                                    .spiffe_bundle_slot
                                    .is_some(),
                                topology: runtime.topology,
                                production: inbound_tls_reload.production,
                            },
                        )
                        .await;
                    }
                    None => publish_staged_spiffe_bundle(proxy_state, staged_inbound_spiffe),
                }
            }
            if accepted && let Some(dns_proxy) = dns_proxy {
                dns_proxy.update_from_slice(dns_slice.as_ref().unwrap_or(base_slice));
            }
            if accepted {
                refresh_mesh_outbound_enforcement(proxy_state, runtime, base_slice);
            }
            if applied {
                info!(
                    mesh_slice_version = %base_slice.version,
                    "Applied mesh slice to proxy runtime"
                );
            } else if accepted {
                debug!(
                    mesh_slice_version = %base_slice.version,
                    "Accepted mesh slice with no proxy runtime delta"
                );
            } else {
                warn!(
                    mesh_slice_version = %base_slice.version,
                    "Rejected mesh slice proxy config; leaving last applied slice and DNS table unchanged"
                );
            }
            accepted
        }
        Err(e) => {
            warn!(
                mesh_slice_version = %base_slice.version,
                error = %e,
                "Ignoring invalid mesh slice update"
            );
            false
        }
    }
}

fn start_mesh_slice_apply_task(
    mesh_state: MeshRuntimeState,
    proxy_state: ProxyState,
    runtime: MeshRuntimeConfig,
    initial_applied_mesh_slice: Option<Arc<MeshSlice>>,
    mut inbound_tls_reload: MeshInboundTlsReloadState,
    mut shutdown_rx: tokio::sync::watch::Receiver<bool>,
    dns_proxy: Option<Arc<MeshDnsProxy>>,
) -> JoinHandle<()> {
    tokio::spawn(async move {
        // Topology is process-fixed, so whether this data plane has an inbound
        // TLS-terminating listener never changes — compute it once here rather
        // than re-deriving the listener plan on every slice apply.
        let has_termination_listener = runtime.has_inbound_tls_termination_listener();
        let mut updates = mesh_state.subscribe();
        let mut federation_updates = mesh_state.federation_store().subscribe();
        let mut remote_endpoint_updates = mesh_state.remote_endpoint_store().subscribe();
        let mut last_applied_slice = initial_applied_mesh_slice;
        let mut last_applied_federation_revision = *federation_updates.borrow();
        let mut last_applied_remote_revision = *remote_endpoint_updates.borrow();
        loop {
            if *shutdown_rx.borrow() {
                return;
            }

            let snapshot = mesh_state.snapshot();
            let current_federation_revision = *federation_updates.borrow();
            let current_remote_revision = *remote_endpoint_updates.borrow();
            // The apply loop re-runs on slice OR federation OR remote-endpoint
            // changes. Without these checks, a no-op slice (CP did not push
            // anything new) would skip applying a freshly polled federation
            // bundle or a remote cluster's scaled endpoint set: the
            // `content_eq` short-circuit only catches the slice, not the
            // bundles / remote endpoints we overlay on top.
            let federation_changed =
                current_federation_revision != last_applied_federation_revision;
            let remote_changed = current_remote_revision != last_applied_remote_revision;
            if let Some(slice) = snapshot.as_ref().as_ref() {
                let slice_unchanged =
                    mesh_slice_matches_last_applied(last_applied_slice.as_deref(), slice);
                if slice_unchanged && !federation_changed && !remote_changed {
                    record_mesh_slice_apply_result(
                        &mesh_state,
                        &mut last_applied_slice,
                        slice,
                        true,
                    );
                    debug!(
                        mesh_slice_version = %slice.version,
                        "Skipping no-op mesh slice update"
                    );
                } else {
                    let live_reload_enabled =
                        proxy_state.env_config.mesh_peer_auth_live_reload_enabled;
                    let federation_snapshot = mesh_state.federation_store().snapshot();
                    let remote_snapshot = mesh_state.remote_endpoint_store().snapshot();
                    // Snapshot the last-accepted slice BEFORE the primary attempt
                    // mutates `last_applied_slice`, so a rejected received slice
                    // can fall back to re-applying the overlay against the slice
                    // the proxy is actually serving (codex F7.2 round-4).
                    let last_accepted_base = last_applied_slice.clone();
                    let received_accepted = apply_mesh_slice_generation(
                        &mesh_state,
                        &proxy_state,
                        &runtime,
                        slice,
                        &federation_snapshot,
                        &remote_snapshot,
                        live_reload_enabled,
                        &mut inbound_tls_reload,
                        has_termination_listener,
                        &mut last_applied_slice,
                        &dns_proxy,
                    )
                    .await;
                    // Finding 3 (accepted-remote/federation update vs rejected
                    // received slice): the discovery + federation pollers are
                    // keyed to the ACCEPTED slice, so they can publish overlay
                    // changes (a remote-cluster scale-up/down, a fresh trust
                    // bundle) for the last-accepted generation while the CP's
                    // newest RECEIVED slice is one the proxy rejects. The primary
                    // attempt above rebuilt from that rejected received slice, so
                    // without this the overlay change is consumed (its revision
                    // marker advances below) but never reaches the live proxy
                    // until another valid slice arrives. When the received slice
                    // did not apply AND an overlay revision changed, re-apply the
                    // overlay against the last-accepted slice so the change is
                    // reflected. Fail-closed by retention: if even the
                    // last-accepted base no longer builds, the previous live
                    // config is kept. Skipped when the received slice IS the
                    // last-accepted one (no distinct base to fall back to) — that
                    // case is already covered by the primary attempt.
                    if !received_accepted
                        && (federation_changed || remote_changed)
                        && let Some(base) = last_accepted_base
                        && !mesh_slice_matches_last_applied(Some(base.as_ref()), slice)
                    {
                        debug!(
                            rejected_slice_version = %slice.version,
                            last_accepted_slice_version = %base.version,
                            "Received mesh slice rejected; re-applying federation/remote overlay against last-accepted slice"
                        );
                        apply_mesh_slice_generation(
                            &mesh_state,
                            &proxy_state,
                            &runtime,
                            base.as_ref(),
                            &federation_snapshot,
                            &remote_snapshot,
                            live_reload_enabled,
                            &mut inbound_tls_reload,
                            has_termination_listener,
                            &mut last_applied_slice,
                            &dns_proxy,
                        )
                        .await;
                    }
                }
                // Federation / remote-endpoint revisions are consumed after
                // every apply attempt, whether successful or not. A rejected
                // apply still advances the markers so a transient invalid slice
                // doesn't pin the apply loop in a re-apply spin on every poll.
                // (Finding 3's re-apply against the last-accepted slice has
                // already reflected any accepted overlay change before we
                // advance, so the change is not lost by this consume.)
                last_applied_federation_revision = current_federation_revision;
                last_applied_remote_revision = current_remote_revision;
            }

            tokio::select! {
                changed = updates.changed() => {
                    if changed.is_err() {
                        return;
                    }
                }
                changed = federation_updates.changed() => {
                    if changed.is_err() {
                        return;
                    }
                }
                changed = remote_endpoint_updates.changed() => {
                    if changed.is_err() {
                        return;
                    }
                }
                _ = wait_for_mesh_shutdown(&mut shutdown_rx) => return,
            }
        }
    })
}

fn mesh_slice_matches_last_applied(
    last_applied_slice: Option<&MeshSlice>,
    slice: &MeshSlice,
) -> bool {
    last_applied_slice.is_some_and(|applied| applied.content_eq(slice))
}

fn record_mesh_slice_apply_result(
    mesh_state: &MeshRuntimeState,
    last_applied_slice: &mut Option<Arc<MeshSlice>>,
    slice: &MeshSlice,
    applied: bool,
) {
    if applied {
        mesh_state.record_applied_slice(slice);
        *last_applied_slice = Some(Arc::new(slice.clone()));
    }
}

struct MeshBackgroundTasks {
    handles: Vec<JoinHandle<()>>,
    dns_retry_handle: Option<JoinHandle<()>>,
    per_ip_cleanup_handle: Option<JoinHandle<()>>,
    health_check_handles: Vec<JoinHandle<()>>,
    mesh_background_handles: Vec<JoinHandle<()>>,
}

async fn await_mesh_listener_handles(
    listener_handles: Vec<JoinHandle<()>>,
    shutdown_tx: tokio::sync::watch::Sender<bool>,
    reason: &str,
) -> Result<(), tokio::task::JoinError> {
    if listener_handles.is_empty() {
        let mut wait_shutdown = shutdown_tx.subscribe();
        while !*wait_shutdown.borrow() {
            if wait_shutdown.changed().await.is_err() {
                break;
            }
        }
        info!(
            reason,
            "Mesh runtime observed shutdown with no active listeners"
        );
        Ok(())
    } else {
        let shutdown_on_panic = move || {
            let _ = shutdown_tx.send(true);
        };
        crate::modes::file::await_listener_handles(listener_handles, shutdown_on_panic).await
    }
}

async fn shutdown_and_join_mesh(
    proxy_state: ProxyState,
    mut tasks: MeshBackgroundTasks,
    drain_seconds: u64,
) {
    proxy_state.stream_listener_manager.shutdown_all().await;
    crate::overload::begin_drain(&proxy_state.overload);
    if drain_seconds > 0 {
        crate::overload::wait_for_drain(&proxy_state.overload, Duration::from_secs(drain_seconds))
            .await;
    }

    if let Some(handle) = tasks.dns_retry_handle {
        tasks.handles.push(handle);
    }
    if let Some(handle) = tasks.per_ip_cleanup_handle {
        tasks.handles.push(handle);
    }
    tasks
        .health_check_handles
        .extend(proxy_state.health_checker.take_active_check_handles());
    tasks.handles.extend(tasks.health_check_handles);
    tasks.handles.extend(tasks.mesh_background_handles);

    crate::modes::file::join_background_handles(tasks.handles, Duration::from_secs(5)).await;
    crate::observability_delivery::shutdown(Duration::from_millis(
        proxy_state.env_config.log_shutdown_drain_timeout_ms,
    ))
    .await;
    crate::plugins::api_chargeback_sink::finalize_all_snapshot_generations().await;
    crate::plugins::kafka_logging::finalize_all_generations().await;
}

fn parse_socket_addr(key: &str, raw: &str) -> Result<SocketAddr, String> {
    raw.parse::<SocketAddr>()
        .map_err(|e| format!("{key} must be a socket address (got '{raw}'): {e}"))
}

/// Parse `FERRUM_MESH_WORKLOAD_LABELS` (`k1=v1,k2=v2`). Empty / `None` returns
/// an empty map. Whitespace around keys/values is trimmed; empty entries are
/// skipped (so a trailing `,` is harmless). Duplicate keys are rejected so the
/// operator catches a typo immediately.
fn parse_workload_labels(
    raw: Option<&str>,
) -> Result<std::collections::HashMap<String, String>, String> {
    let mut labels = std::collections::HashMap::new();
    let Some(raw) = raw else {
        return Ok(labels);
    };
    for entry in raw.split(',') {
        let entry = entry.trim();
        if entry.is_empty() {
            continue;
        }
        // `entry` and `key` are trimmed segments of the variable, so each is a
        // transformed rendering the textual pass cannot admit when short.
        let (key, value) = entry.split_once('=').ok_or_else(|| {
            format!(
                "FERRUM_MESH_WORKLOAD_LABELS entry {} must be in 'key=value' form",
                crate::secrets::quoted_env_value("FERRUM_MESH_WORKLOAD_LABELS", entry)
            )
        })?;
        let key = key.trim();
        let value = value.trim();
        if key.is_empty() {
            return Err(format!(
                "FERRUM_MESH_WORKLOAD_LABELS entry {} has an empty key",
                crate::secrets::quoted_env_value("FERRUM_MESH_WORKLOAD_LABELS", entry)
            ));
        }
        if labels.insert(key.to_string(), value.to_string()).is_some() {
            return Err(format!(
                "FERRUM_MESH_WORKLOAD_LABELS contains duplicate key {}",
                crate::secrets::quoted_env_value("FERRUM_MESH_WORKLOAD_LABELS", key)
            ));
        }
    }
    Ok(labels)
}

fn parse_port(key: &str, raw: &str) -> Result<u16, String> {
    let port = raw
        .parse::<u16>()
        .map_err(|e| format!("{key} must be a TCP port (got '{raw}'): {e}"))?;
    if port == 0 {
        Err(format!("{key} must be between 1 and 65535 (got 0)"))
    } else {
        Ok(port)
    }
}

fn parse_duration_seconds(key: &str, raw: &str) -> Result<u64, String> {
    raw.parse::<u64>()
        .map_err(|e| format!("{key} must be a duration in seconds (got '{raw}'): {e}"))
}

/// Spawn the SOCK_OPS ringbuf consumer for `__mesh_bpf_metrics`.
///
/// On Linux + `ebpf` feature builds, opens the pinned ringbuf from the
/// node-agent and drives a `tokio::select!` poll loop that updates the
/// shared `BpfMetricsState`. On every other build target this is a no-op
/// — the plugin still emits zero counters via the empty `BpfMetricsState`.
fn spawn_sock_ops_consumer_task(
    state: std::sync::Arc<crate::ebpf::bpf_metrics::BpfMetricsState>,
    shutdown_tx: &tokio::sync::watch::Sender<bool>,
) -> Option<tokio::task::JoinHandle<()>> {
    #[cfg(all(feature = "ebpf", target_os = "linux"))]
    {
        let consumer = crate::ebpf::event_consumer::SockOpsConsumer::new(state);
        let shutdown_rx = shutdown_tx.subscribe();
        Some(tokio::spawn(async move {
            if let Err(err) =
                crate::ebpf::event_consumer::production::run_pinned_consumer(consumer, shutdown_rx)
                    .await
            {
                tracing::warn!(error = %err, "SOCK_OPS ringbuf consumer task exited with error");
            }
        }))
    }
    #[cfg(not(all(feature = "ebpf", target_os = "linux")))]
    {
        // Reference the args so the no-op branch compiles cleanly.
        let _ = state;
        let _ = shutdown_tx;
        tracing::debug!(
            "SOCK_OPS ringbuf consumer skipped (build without ebpf feature or non-Linux target)"
        );
        None
    }
}

/// Spawn the node-waypoint orig-dst → identity bridge (GAP-1b). Always returns
/// a handle: on non-eBPF / non-Linux builds the task logs once that no capture
/// runs and returns, so the resolver stays empty and the accept path fails
/// closed. The bridge owns the startup-race retry and node-agent-restart
/// re-open logic in `crate::ebpf::orig_dst_bridge`.
fn spawn_orig_dst_bridge_task(
    resolver: std::sync::Arc<crate::modes::mesh::node_waypoint::NodeWaypointIdentityResolver>,
    shutdown_tx: &tokio::sync::watch::Sender<bool>,
) -> tokio::task::JoinHandle<()> {
    let shutdown_rx = shutdown_tx.subscribe();
    tokio::spawn(async move {
        if let Err(err) =
            crate::ebpf::orig_dst_bridge::run_orig_dst_bridge(resolver, shutdown_rx).await
        {
            tracing::warn!(error = %err, "Node-waypoint orig-dst bridge task exited with error");
        }
    })
}

