    #[test]
    fn sidecar_inbound_proxies_use_workload_port_and_own_service_only() {
        // The local workload backs service "reviews" with a TCP *container* port
        // 9090 (the app/target port); the Service declares the port as HTTP on 80.
        // A different service "ratings" merely shares the SPIFFE id. The inbound
        // route must (a) key on the workload's OWN service ("reviews", not
        // "ratings"), (b) be routable from the SERVICE port's HTTP protocol
        // despite the workload port being TCP, and (c) target the workload's app
        // port 9090 (not the service port 80).
        let spiffe = "spiffe://cluster.local/ns/default/sa/reviews";
        let runtime = MeshRuntimeConfig {
            workload_spiffe_id: Some(spiffe.to_string()),
            ..test_mesh_runtime_config()
        };
        let mut local = workload("reviews", "reviews");
        local.ports = vec![WorkloadPort {
            port: 9090,
            protocol: AppProtocol::Tcp,
            name: Some("http".to_string()),
        }];
        let http_service = |name: &str| MeshService {
            cluster_ips: Vec::new(),
            name: name.to_string(),
            namespace: "default".to_string(),
            ports: vec![ServicePort {
                port: 80,
                protocol: AppProtocol::Http,
                name: Some("http".to_string()),
                target_port: None,
            }],
            workloads: vec![crate::modes::mesh::config::WorkloadRef {
                spiffe_id: SpiffeId::new(spiffe).unwrap(),
            }],
            protocol_overrides: HashMap::new(),
        };
        let slice = MeshSlice {
            node_id: "node-a".to_string(),
            namespace: "default".to_string(),
            version: "test".to_string(),
            workloads: vec![local],
            services: vec![http_service("reviews"), http_service("ratings")],
            ..MeshSlice::default()
        };

        let config =
            gateway_config_from_mesh_slice(&slice, &runtime, None, None).expect("slice → config");

        let inbound: Vec<&str> = config
            .proxies
            .iter()
            .filter(|p| p.id.starts_with("__mesh-inbound-"))
            .map(|p| p.id.as_str())
            .collect();
        assert_eq!(
            inbound,
            vec!["__mesh-inbound-default-reviews-80"],
            "exactly one inbound route, for the local workload's OWN service (not 'ratings')"
        );
        let route = config
            .proxies
            .iter()
            .find(|p| p.id == "__mesh-inbound-default-reviews-80")
            .expect("reviews route");
        assert_eq!(
            route.backend_port, 9090,
            "inbound route must target the workload's app port, not the service port"
        );
        assert!(
            route
                .hosts
                .iter()
                .any(|h| h == "reviews.default.svc.cluster.local")
        );
    }

    /// Build an HTTP `MeshService` named `name` on `port`, backed by `spiffe`.
    fn http_mesh_service(name: &str, port: u16, spiffe: &str) -> MeshService {
        MeshService {
            cluster_ips: Vec::new(),
            name: name.to_string(),
            namespace: "default".to_string(),
            ports: vec![ServicePort {
                port,
                protocol: AppProtocol::Http,
                name: Some("http".to_string()),
                target_port: None,
            }],
            workloads: vec![crate::modes::mesh::config::WorkloadRef {
                spiffe_id: SpiffeId::new(spiffe).unwrap(),
            }],
            protocol_overrides: HashMap::new(),
        }
    }

    // ── East-west target tag hygiene (reserved mesh.* namespace) ──────────

    /// codex r3 Finding C: `build_east_west_service_targets` copies the
    /// workload's operator-authored `selector.labels` into `UpstreamTarget.tags`.
    /// A workload labelled with the RESERVED provenance key `mesh.remote: "true"`
    /// must NOT leak that label onto the target — otherwise strict locality LB
    /// (whose `target_is_local` keys on this exact tag) would treat a
    /// genuinely-LOCAL east-west endpoint as remote and exclude it. Only the
    /// discoverer (from un-spoofable provenance) may stamp `mesh.remote`.
    #[test]
    fn east_west_targets_strip_reserved_mesh_labels() {
        let spiffe = "spiffe://cluster.local/ns/default/sa/reviews";
        let mut wl = workload_with_address("reviews", "reviews", "10.0.0.1");
        // Operator/workload labels INCLUDING a forged reserved provenance marker
        // and a forged transport marker, alongside a legitimate operator label.
        wl.selector
            .labels
            .insert("version".to_string(), "v2".to_string());
        wl.selector.labels.insert(
            crate::modes::mesh::multicluster::MESH_REMOTE_TAG.to_string(),
            crate::modes::mesh::multicluster::MESH_REMOTE_TAG_VALUE.to_string(),
        );
        wl.selector
            .labels
            .insert("mesh.hbone".to_string(), "true".to_string());

        let service = http_mesh_service("reviews", 8080, spiffe);
        let targets = build_east_west_service_targets(
            &service,
            &service.ports[0],
            std::slice::from_ref(&wl),
            None,
        );
        assert_eq!(targets.len(), 1, "one address → one target");
        let tags = &targets[0].tags;
        // The legitimate operator labels survive.
        assert_eq!(tags.get("app").map(String::as_str), Some("reviews"));
        assert_eq!(tags.get("version").map(String::as_str), Some("v2"));
        // The forged reserved markers are stripped, so the LB's `target_is_local`
        // (which keys on the exact `mesh.remote=true` tag) sees no remote marker
        // and treats this genuinely-local endpoint as LOCAL.
        assert!(
            !tags.contains_key(crate::modes::mesh::multicluster::MESH_REMOTE_TAG),
            "forged mesh.remote label must be stripped from the east-west target"
        );
        assert!(
            !tags.contains_key("mesh.hbone"),
            "forged mesh.hbone transport label must be stripped too"
        );
    }

    // ── Ambient outbound (egress) HBONE materialization ───────────────────

    /// A workload with a pod address so the outbound materializer can build HBONE
    /// targets (the bare `workload()` helper has no addresses).
    fn workload_with_address(name: &str, app: &str, address: &str) -> Workload {
        let mut wl = workload(name, app);
        wl.addresses = vec![address.to_string()];
        wl
    }

