    #[test]
    fn mesh_outbound_tcp_bywl_upstreams_materialize_for_direct_pod_ip() {
        // F3 §3.4: a HEADLESS (VIP-less) service backed by a workload with a pod
        // IP materializes a SINGLE-TARGET per-workload raw-TCP egress upstream
        // dialing the resolved targetPort, identity-pinned, tagged for the
        // topology transport — so a direct pod-IP dial is routable even though
        // the VIP table has nothing. NO route proxy (raw streams carry no Host).
        let spiffe = "spiffe://cluster.local/ns/default/sa/redis";
        for (runtime, want_tag, other_tag) in [
            (ambient_runtime(), "mesh.hbone", "mesh.mtls"),
            (test_mesh_runtime_config(), "mesh.mtls", "mesh.hbone"),
        ] {
            let mut headless = http_mesh_service("redis", 6379, spiffe);
            headless.ports[0].protocol = AppProtocol::Redis;
            headless.ports[0].target_port = Some(ServiceTargetPort::Number(6380));
            // No cluster_ips — headless.
            let mut wl = workload_with_address("redis", "redis", "10.0.0.7");
            // The workload must advertise the container port for a numeric
            // targetPort fallback path; numeric resolves regardless, but keep it
            // realistic.
            wl.ports = vec![WorkloadPort {
                port: 6380,
                protocol: AppProtocol::Redis,
                name: Some("redis".to_string()),
            }];
            let slice = MeshSlice {
                namespace: "default".to_string(),
                workloads: vec![wl],
                services: vec![headless],
                ..MeshSlice::default()
            };
            let mut config = GatewayConfig::default();
            materialize_mesh_outbound_tcp_upstreams(&mut config, &runtime, &slice);
            assert!(
                config.proxies.is_empty(),
                "raw-TCP egress materializes upstreams only, never route proxies ({:?})",
                runtime.topology
            );
            let bywl_id = mesh_outbound_tcp_bywl_upstream_id(
                "default",
                "redis",
                6379,
                "10.0.0.7".parse().unwrap(),
            );
            let upstream = config
                .upstreams
                .iter()
                .find(|u| u.id == bywl_id)
                .unwrap_or_else(|| {
                    panic!("per-workload raw-TCP upstream for {:?}", runtime.topology)
                });
            assert_eq!(
                upstream.name.as_deref(),
                Some("redis.default.svc.cluster.local"),
                "FQDN-named so DestinationRules match"
            );
            assert_eq!(upstream.targets.len(), 1, "single-target per workload IP");
            let target = &upstream.targets[0];
            assert_eq!(
                target.host, "10.0.0.7",
                "dials the workload pod IP, not a VIP"
            );
            assert_eq!(target.port, 6380, "dials the resolved targetPort");
            assert_eq!(
                target.service_port_policy_key,
                Some(6379),
                "per-workload raw-TCP target keeps the declared Service port for DestinationRule policy"
            );
            assert_eq!(
                target.tags.get(want_tag).map(String::as_str),
                Some("true"),
                "per-workload target rides the {want_tag} transport ({:?})",
                runtime.topology
            );
            assert!(
                !target.tags.contains_key(other_tag),
                "a target carries exactly one transport tag ({:?})",
                runtime.topology
            );
            assert_eq!(
                target.tags.get("mesh.spiffe_id").map(String::as_str),
                Some(spiffe),
                "destination identity stays pinned"
            );
            // A direct pod-IP dial already carries the app port in its orig-dst,
            // so NO `:authority` rewrite tag is stamped (that is a VIP-multi-port
            // concern only).
            assert!(
                !target
                    .tags
                    .contains_key(crate::proxy::mesh_mtls_pool::MESH_MTLS_AUTHORITY_PORT_TAG),
                "direct pod-IP dials never rewrite the authority ({:?})",
                runtime.topology
            );
        }
    }

    #[test]
    fn mesh_outbound_tcp_bywl_upstreams_skip_when_no_addresses() {
        // A VIP-less service whose workload has no pod address yet (or only
        // DNS-name addresses) materializes nothing on either path — there is no
        // IP to key the by-workload index by.
        let spiffe = "spiffe://cluster.local/ns/default/sa/redis";
        for runtime in [ambient_runtime(), test_mesh_runtime_config()] {
            let mut headless = http_mesh_service("redis", 6379, spiffe);
            headless.ports[0].protocol = AppProtocol::Redis;
            // Workload declared but NO addresses (pod IP unassigned) ...
            let no_addr = workload("redis", "redis");
            // ... and a second workload with only a DNS-name address (skipped).
            let mut dns_only = workload_with_address("redis2", "redis", "redis-0.redis.default");
            dns_only.spiffe_id =
                SpiffeId::new("spiffe://cluster.local/ns/default/sa/redis").unwrap();
            let slice = MeshSlice {
                namespace: "default".to_string(),
                workloads: vec![no_addr, dns_only],
                services: vec![headless],
                ..MeshSlice::default()
            };
            let mut config = GatewayConfig::default();
            materialize_mesh_outbound_tcp_upstreams(&mut config, &runtime, &slice);
            assert!(
                !config
                    .upstreams
                    .iter()
                    .any(|u| u.id.starts_with("__mesh-out-tcp-bywl-upstream-")),
                "no IP workload address ⇒ no by-workload upstream ({:?})",
                runtime.topology
            );
        }
    }

    #[test]
    fn mesh_outbound_tcp_upstream_receives_port_level_dr() {
        // DestinationRule portLevelSettings authored on the TCP SERVICE port
        // stay under the targets' owning service-policy port while the target
        // still dials its resolved workload port.
        let spiffe = "spiffe://cluster.local/ns/default/sa/redis";
        let mut svc = http_mesh_service("redis", 6379, spiffe);
        svc.ports[0].protocol = AppProtocol::Redis;
        svc.ports[0].target_port = Some(ServiceTargetPort::Number(6380));
        svc.cluster_ips = vec!["10.96.0.1".to_string()];
        let slice = MeshSlice {
            namespace: "default".to_string(),
            workloads: vec![workload_with_address("redis", "redis", "10.0.0.7")],
            services: vec![svc],
            destination_rules: vec![MeshDestinationRule {
                name: "redis".to_string(),
                namespace: "default".to_string(),
                host: "redis.default.svc.cluster.local".to_string(),
                traffic_policy: None,
                port_level_settings: HashMap::from([(
                    6379u16,
                    MeshTrafficPolicy {
                        connect_timeout_ms: Some(4321),
                        ..MeshTrafficPolicy::default()
                    },
                )]),
                subsets: Vec::new(),
            }],
            ..MeshSlice::default()
        };
        let mut config = GatewayConfig::default();
        materialize_mesh_outbound_tcp_upstreams(&mut config, &ambient_runtime(), &slice);
        apply_destination_rules(&mut config, &ambient_runtime(), &slice)
            .expect("destination rules apply");
        let upstream = config
            .upstreams
            .iter()
            .find(|u| u.id == "__mesh-out-tcp-upstream-default-redis-6379")
            .expect("raw-TCP upstream");
        assert_eq!(
            upstream
                .port_overrides
                .get(&6379)
                .and_then(|slot| slot.connect_timeout_ms),
            Some(4321),
            "TCP-port portLevelSettings must land on the service policy port"
        );
        assert!(
            !upstream.port_overrides.contains_key(&6380),
            "per-port policy must not be keyed by the resolved dial port"
        );
    }

    #[test]
    fn mesh_outbound_udp_materializes_sidecar_mtls_upstream() {
        // Sidecar UDP egress (#1808) materializes a per-port upstream whose
        // targets carry the `mesh.mtls` transport tag + the pinned destination
        // identity (`mesh.spiffe_id`), under the DISTINCT `__mesh-out-udp-upstream-*`
        // id space — the Sidecar counterpart of the Ambient HBONE UDP materializer.
        // The egress datapath's transport branch then picks the mesh-mTLS datagram
        // tunnel from that tag.
        let spiffe = "spiffe://cluster.local/ns/default/sa/dns";
        let mut svc = http_mesh_service("dns", 53, spiffe);
        svc.ports[0].protocol = AppProtocol::Udp;
        svc.cluster_ips = vec!["10.96.0.10".to_string()];
        let slice = MeshSlice {
            namespace: "default".to_string(),
            workloads: vec![workload_with_address("dns", "dns", "10.0.0.9")],
            services: vec![svc],
            ..MeshSlice::default()
        };
        // `test_mesh_runtime_config()` is the Sidecar topology.
        let runtime = test_mesh_runtime_config();
        assert_eq!(runtime.topology, MeshTopology::Sidecar);
        let mut config = GatewayConfig::default();
        materialize_mesh_outbound_udp_upstreams(&mut config, &runtime, &slice);

        let upstream = config
            .upstreams
            .iter()
            .find(|u| u.id == "__mesh-out-udp-upstream-default-dns-53")
            .expect("Sidecar UDP upstream materialized under the distinct UDP id space");
        let target = upstream
            .targets
            .first()
            .expect("Sidecar UDP upstream has a target");
        assert!(
            crate::proxy::mesh_mtls_pool::target_mesh_mtls_enabled(target),
            "Sidecar UDP target must carry the mesh.mtls transport tag"
        );
        assert!(
            !crate::proxy::hbone_pool::target_hbone_enabled(target),
            "Sidecar UDP target must NOT carry the mesh.hbone tag (mutually exclusive)"
        );
        assert_eq!(
            crate::proxy::mesh_mtls_pool::target_mesh_mtls_expected_peer(target)
                .expect("Sidecar UDP target carries a pinned identity")
                .as_str(),
            spiffe,
            "Sidecar UDP target must pin the destination workload identity"
        );
    }

    #[test]
    fn mesh_outbound_udp_not_materialized_for_non_relay_topology() {
        // Only the two captured-and-relayed topologies (Ambient HBONE, Sidecar
        // mesh-mTLS) materialize UDP egress; EastWestGateway (no UDP relay)
        // materializes nothing (#1808 keeps the `_ => return` arm for the rest).
        let spiffe = "spiffe://cluster.local/ns/default/sa/dns";
        let mut svc = http_mesh_service("dns", 53, spiffe);
        svc.ports[0].protocol = AppProtocol::Udp;
        svc.cluster_ips = vec!["10.96.0.10".to_string()];
        let slice = MeshSlice {
            namespace: "default".to_string(),
            workloads: vec![workload_with_address("dns", "dns", "10.0.0.9")],
            services: vec![svc],
            ..MeshSlice::default()
        };
        let runtime = MeshRuntimeConfig {
            topology: MeshTopology::EastWestGateway,
            ..test_mesh_runtime_config()
        };
        let mut config = GatewayConfig::default();
        materialize_mesh_outbound_udp_upstreams(&mut config, &runtime, &slice);
        assert!(
            !config
                .upstreams
                .iter()
                .any(|u| u.id == "__mesh-out-udp-upstream-default-dns-53"),
            "a topology with no UDP relay must materialize no UDP egress upstream"
        );
    }

