    /// Codex F7.2 round-4 / Finding 3: an accepted remote-cluster scale-up must
    /// reach the live proxy even while the CP's most-recent *received* slice is
    /// one the proxy REJECTS. The discovery poller is keyed to the ACCEPTED
    /// slice, so it legitimately publishes endpoint changes for the last-accepted
    /// generation while a newer received slice is invalid; the apply loop must
    /// re-apply the remote overlay against the last-accepted slice instead of
    /// rebuilding from (and advancing past) the rejected received snapshot.
    #[tokio::test(flavor = "current_thread")]
    async fn mesh_runtime_apply_task_applies_remote_scaleup_while_received_slice_rejected() {
        let runtime = test_mesh_runtime_config();
        let mesh_state = MeshRuntimeState::new();
        let proxy_state = make_test_proxy_state(GatewayConfig::default());
        let (shutdown_tx, shutdown_rx) = tokio::sync::watch::channel(false);
        let apply_task = start_mesh_slice_apply_task(
            mesh_state.clone(),
            proxy_state.clone(),
            runtime,
            None,
            MeshInboundTlsReloadState {
                server_identity: None,
                last_snapshot: None,
                spiffe_bundle_slot: None,
                runtime_trust_overlay_slot: None,
                production: false,
            },
            shutdown_rx,
            None,
        );

        let multi_cluster = MultiClusterConfig {
            remote_clusters: vec![RemoteCluster {
                name: "west".to_string(),
                trust_domain: TrustDomain::new("remote.local").unwrap(),
                network: Some("net2".to_string()),
                control_plane_url: Some("https://cp.remote.example:15010".to_string()),
                federation_endpoint: None,
                discovery_credential_ref: None,
            }],
            ..MultiClusterConfig::default()
        };
        // A valid, ACCEPTED slice declaring the remote cluster + a local
        // workload/service. The label lets us wait for acceptance.
        let good_slice = MeshSlice {
            version: "good-v1".to_string(),
            labels: [("app".to_string(), "reviews".to_string())].into(),
            workloads: vec![workload_with_address("local", "reviews", "10.1.0.1")],
            services: vec![MeshService {
                cluster_ips: Vec::new(),
                name: "reviews".to_string(),
                namespace: "default".to_string(),
                ports: vec![ServicePort {
                    port: 8080,
                    protocol: AppProtocol::Http,
                    name: Some("http".to_string()),
                    target_port: None,
                }],
                workloads: vec![WorkloadRef {
                    spiffe_id: SpiffeId::new(
                        "spiffe://cluster.local/ns/default/sa/local".to_string(),
                    )
                    .unwrap(),
                }],
                protocol_overrides: HashMap::new(),
            }],
            multi_cluster: Some(multi_cluster),
            ..MeshSlice::default()
        };
        mesh_state.install_slice(good_slice);
        wait_for_mesh_authz_label(&proxy_state, "app", "reviews").await;

        // Helper: build a remote endpoint entry for `west` with the given remote
        // workload addresses.
        let remote_entry = |addrs: &[&str]| {
            let workloads = addrs
                .iter()
                .enumerate()
                .map(|(i, addr)| {
                    let mut w = workload_with_address(&format!("remote{i}"), "reviews", addr);
                    w.spiffe_id =
                        SpiffeId::new(format!("spiffe://remote.local/ns/default/sa/remote{i}"))
                            .unwrap();
                    w.trust_domain = TrustDomain::new("remote.local").unwrap();
                    w
                })
                .collect();
            multicluster::RemoteClusterEntry::new(
                "west".to_string(),
                TrustDomain::new("remote.local").unwrap(),
                Some("net2".to_string()),
                // Must match the accepted slice's declared (normalized)
                // control_plane_url so the full-poll-identity merge filter
                // admits these endpoints.
                Some("https://cp.remote.example:15010".to_string()),
                None,
                multicluster::RemoteClusterEndpoints {
                    workloads,
                    services: Vec::new(),
                },
                1,
            )
        };

        // First successful poll: the remote cluster contributes one endpoint.
        // The apply loop re-applies the (still-accepted) good slice with the
        // remote overlay, so the live config gains 10.2.0.1.
        mesh_state
            .remote_endpoint_store()
            .install_for_test(remote_entry(&["10.2.0.1"]));
        wait_for_mesh_workload_address(&proxy_state, "10.2.0.1").await;

        // Now the CP pushes an INVALID slice (a MeshPolicy with an empty
        // principal matcher fails `MeshConfig::validate`, so
        // `gateway_config_from_mesh_slice` returns Err → the slice is rejected).
        let bad_slice = MeshSlice {
            version: "bad-v2".to_string(),
            labels: [("app".to_string(), "rejected".to_string())].into(),
            mesh_policies: vec![MeshPolicy {
                name: "broken".to_string(),
                namespace: "default".to_string(),
                scope: PolicyScope::MeshWide,
                rules: vec![MeshRule {
                    from: vec![PrincipalMatch::default()],
                    action: PolicyAction::Allow,
                    ..MeshRule::default()
                }],
            }],
            ..MeshSlice::default()
        };
        mesh_state.install_slice(bad_slice);

        // While the rejected slice is the current received slice, the remote
        // cluster scales UP to two endpoints. The poller is keyed to the
        // last-accepted slice, so this is legitimate. The apply loop must
        // re-apply the overlay against the last-accepted (good) slice, so the
        // live config gains 10.2.0.2 even though the received slice is invalid.
        mesh_state
            .remote_endpoint_store()
            .install_for_test(remote_entry(&["10.2.0.1", "10.2.0.2"]));
        wait_for_mesh_workload_address(&proxy_state, "10.2.0.2").await;

        // The live config still carries the ACCEPTED slice's label, not the
        // rejected slice's — the rejected slice never became live.
        assert_eq!(
            mesh_authz_label(&proxy_state, "app").as_deref(),
            Some("reviews"),
            "rejected slice must not become the live config; only its remote overlay re-applies onto the accepted slice"
        );

        let _ = shutdown_tx.send(true);
        tokio::time::timeout(Duration::from_secs(2), apply_task)
            .await
            .expect("apply task should stop")
            .expect("apply task should join");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn mesh_runtime_apply_task_live_reloads_peer_auth_tls_slot() {
        let mut runtime = test_mesh_runtime_config();
        runtime.inbound_listen_addr = "127.0.0.1:15006".parse().unwrap();
        let env = EnvConfig {
            mesh_peer_auth_live_reload_enabled: true,
            frontend_tls_cert_path: Some("tests/certs/server.crt".to_string()),
            frontend_tls_key_path: Some("tests/certs/server.key".to_string()),
            frontend_tls_client_ca_bundle_path: Some("tests/certs/server.crt".to_string()),
            pool_warmup_enabled: false,
            shutdown_drain_seconds: 0,
            ..EnvConfig::default()
        };
        let proxy_state = make_test_proxy_state_with_env(GatewayConfig::default(), env.clone());
        let mesh_frontend_identity =
            load_mesh_frontend_server_identity(&env, &test_svid_slot_from_env(&env))
                .expect("mesh frontend identity");
        let initial_snapshot = mesh_inbound_tls_reload_snapshot(
            &env,
            config::MtlsMode::Disable,
            std::collections::BTreeMap::new(),
        )
        .expect("initial snapshot");
        let mesh_state = MeshRuntimeState::new();
        let (shutdown_tx, shutdown_rx) = tokio::sync::watch::channel(false);
        let apply_task = start_mesh_slice_apply_task(
            mesh_state.clone(),
            proxy_state.clone(),
            runtime,
            None,
            MeshInboundTlsReloadState {
                server_identity: mesh_frontend_identity,
                last_snapshot: Some(initial_snapshot),
                spiffe_bundle_slot: None,
                runtime_trust_overlay_slot: None,
                production: false,
            },
            shutdown_rx,
            None,
        );

        mesh_state.install_slice(MeshSlice {
            version: "strict".to_string(),
            ..slice_with_peer_auths(vec![peer_auth_with_workload_mode(config::MtlsMode::Strict)])
        });
        wait_for_mesh_inbound_tls(&proxy_state, true).await;
        let strict_tls_slot = proxy_state.mesh_inbound_tls.load_full();

        mesh_state.install_slice(MeshSlice {
            version: "strict-label-only".to_string(),
            labels: [("app".to_string(), "same-peer-auth".to_string())].into(),
            ..slice_with_peer_auths(vec![peer_auth_with_workload_mode(config::MtlsMode::Strict)])
        });
        wait_for_mesh_authz_label(&proxy_state, "app", "same-peer-auth").await;
        let unchanged_tls_slot = proxy_state.mesh_inbound_tls.load_full();
        assert!(
            Arc::ptr_eq(&strict_tls_slot, &unchanged_tls_slot),
            "unchanged PeerAuthentication inputs should not rebuild the TLS slot"
        );

        mesh_state.install_slice(MeshSlice {
            version: "disable".to_string(),
            ..slice_with_peer_auths(vec![peer_auth_with_workload_mode(
                config::MtlsMode::Disable,
            )])
        });
        wait_for_mesh_inbound_tls(&proxy_state, false).await;

        let _ = shutdown_tx.send(true);
        tokio::time::timeout(Duration::from_secs(2), apply_task)
            .await
            .expect("apply task should stop")
            .expect("apply task should join");
    }

    /// T3-A: apply_mesh_inbound_tls_reload must also publish the swapped
    /// TLS config into the stream-listener slot so mesh-shared TCP+TLS
    /// listeners see the new `ServerConfig` on the next accept. Existing
    /// HBONE/HTTP-frontend slot behavior is preserved (covered by the
    /// neighbouring `mesh_runtime_apply_task_live_reloads_peer_auth_tls_slot`).
    #[tokio::test(flavor = "current_thread")]
    async fn mesh_runtime_apply_task_propagates_peer_auth_swap_to_stream_listener_slot() {
        let mut runtime = test_mesh_runtime_config();
        runtime.inbound_listen_addr = "127.0.0.1:15006".parse().unwrap();
        let env = EnvConfig {
            mesh_peer_auth_live_reload_enabled: true,
            frontend_tls_cert_path: Some("tests/certs/server.crt".to_string()),
            frontend_tls_key_path: Some("tests/certs/server.key".to_string()),
            frontend_tls_client_ca_bundle_path: Some("tests/certs/server.crt".to_string()),
            pool_warmup_enabled: false,
            shutdown_drain_seconds: 0,
            ..EnvConfig::default()
        };
        let proxy_state = make_test_proxy_state_with_env(GatewayConfig::default(), env.clone());
        let mesh_frontend_identity =
            load_mesh_frontend_server_identity(&env, &test_svid_slot_from_env(&env))
                .expect("mesh frontend identity");
        let initial_snapshot = mesh_inbound_tls_reload_snapshot(
            &env,
            config::MtlsMode::Disable,
            std::collections::BTreeMap::new(),
        )
        .expect("initial snapshot");
        let mesh_state = MeshRuntimeState::new();
        let (shutdown_tx, shutdown_rx) = tokio::sync::watch::channel(false);
        let apply_task = start_mesh_slice_apply_task(
            mesh_state.clone(),
            proxy_state.clone(),
            runtime,
            None,
            MeshInboundTlsReloadState {
                server_identity: mesh_frontend_identity,
                last_snapshot: Some(initial_snapshot),
                spiffe_bundle_slot: None,
                runtime_trust_overlay_slot: None,
                production: false,
            },
            shutdown_rx,
            None,
        );

        // Baseline: stream listener slot starts empty (no startup TLS publish
        // by this test harness).
        assert!(
            proxy_state
                .stream_listener_manager
                .snapshot_frontend_tls_config()
                .is_none(),
            "stream listener slot starts empty before any slice apply"
        );

        // Apply a Strict slice; the apply task must publish the new
        // ServerConfig into BOTH the HBONE slot AND the stream-listener slot.
        mesh_state.install_slice(MeshSlice {
            version: "strict-stream".to_string(),
            ..slice_with_peer_auths(vec![peer_auth_with_workload_mode(config::MtlsMode::Strict)])
        });
        wait_for_mesh_inbound_tls(&proxy_state, true).await;

        let hbone_slot = proxy_state.mesh_inbound_tls.load_full();
        let hbone_slot_ref = hbone_slot
            .as_ref()
            .as_ref()
            .expect("HBONE slot populated by Strict apply");

        // Poll briefly for the stream-listener slot publish (the apply path
        // populates both slots in the same await, but the slot read here can
        // race the publishing store on the read side).
        let stream_slot = tokio::time::timeout(Duration::from_secs(1), async {
            loop {
                if let Some(cfg) = proxy_state
                    .stream_listener_manager
                    .snapshot_frontend_tls_config()
                {
                    return cfg;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("stream listener slot should be populated by apply task");

        assert!(
            Arc::ptr_eq(hbone_slot_ref, &stream_slot),
            "apply_mesh_inbound_tls_reload must publish the same ServerConfig Arc \
             into both the HBONE and the stream-listener slots"
        );

        // Disable PeerAuth: both slots must clear.
        mesh_state.install_slice(MeshSlice {
            version: "disable-stream".to_string(),
            ..slice_with_peer_auths(vec![peer_auth_with_workload_mode(
                config::MtlsMode::Disable,
            )])
        });
        wait_for_mesh_inbound_tls(&proxy_state, false).await;

        tokio::time::timeout(Duration::from_secs(1), async {
            while proxy_state
                .stream_listener_manager
                .snapshot_frontend_tls_config()
                .is_some()
            {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("stream-listener slot should clear when PeerAuth flips to Disable");

        let _ = shutdown_tx.send(true);
        tokio::time::timeout(Duration::from_secs(2), apply_task)
            .await
            .expect("apply task should stop")
            .expect("apply task should join");
    }

