    /// [R5-4] A Sidecar client whose remote endpoints are NOT embedded in the
    /// slice but discovered via the `remote_clusters` poller (a
    /// `RemoteEndpointSnapshot`) must still materialize a cross-cluster east-west
    /// target — the merged remote workloads have to reach materialization through
    /// the slice it reads, not only the local-only original slice.
    #[test]
    fn federation_merge_materializes_cross_cluster_target_from_polled_remote_endpoints() {
        let remote_td = TrustDomain::new("cluster-b.local").unwrap();
        // Local svc-b workload (embedded in the slice).
        let local = Workload {
            addresses: vec!["10.0.0.1".to_string()],
            ..workload("svc-b", "svc-b")
        };
        // Remote svc-b workload — discovered by the poller, NOT present in the slice.
        let remote = Workload {
            spiffe_id: SpiffeId::new("spiffe://cluster-b.local/ns/default/sa/svc-b").unwrap(),
            trust_domain: remote_td.clone(),
            network: Some("net-b".to_string()),
            cluster: Some("cluster-b".to_string()),
            addresses: vec!["10.244.5.5".to_string()],
            locality: Some("remote-cluster-b/net-b".to_string()),
            remote_provenance: true,
            ..workload("svc-b", "svc-b")
        };
        let svc_local = MeshService {
            cluster_ips: Vec::new(),
            name: "svc-b".to_string(),
            namespace: "default".to_string(),
            ports: vec![ServicePort {
                port: 8080,
                protocol: AppProtocol::Http,
                name: Some("http".to_string()),
                target_port: None,
            }],
            workloads: vec![WorkloadRef {
                spiffe_id: local.spiffe_id.clone(),
            }],
            protocol_overrides: HashMap::new(),
        };
        // The remote cluster's view of svc-b (refs the remote workload).
        let svc_remote = MeshService {
            workloads: vec![WorkloadRef {
                spiffe_id: remote.spiffe_id.clone(),
            }],
            ..svc_local.clone()
        };

        let east_cluster = RemoteCluster {
            name: "east".to_string(),
            trust_domain: remote_td.clone(),
            network: Some("net-b".to_string()),
            control_plane_url: Some("https://cp-east.remote.example:15010".to_string()),
            federation_endpoint: None,
            discovery_credential_ref: None,
        };
        let slice = MeshSlice {
            version: "xc-federation".to_string(),
            workloads: vec![local],
            services: vec![svc_local],
            multi_cluster: Some(MultiClusterConfig {
                remote_clusters: vec![east_cluster],
                east_west_gateways: vec![EastWestGateway {
                    name: "ew-net-b".to_string(),
                    namespace: "default".to_string(),
                    host: "10.9.9.9".to_string(),
                    port: 15443,
                    sni_hosts: vec!["svc-b.default.svc.cluster.local".to_string()],
                    trust_domain: Some(remote_td.clone()),
                    network: Some("net-b".to_string()),
                }],
                ..MultiClusterConfig::default()
            }),
            ..MeshSlice::default()
        };

        // The poller snapshot (admitted by the slice's declared `east` cluster).
        let mut clusters = HashMap::new();
        clusters.insert(
            "east".to_string(),
            multicluster::RemoteClusterEntry::new(
                "east".to_string(),
                remote_td,
                Some("net-b".to_string()),
                Some("https://cp-east.remote.example:15010".to_string()),
                None,
                multicluster::RemoteClusterEndpoints {
                    workloads: vec![remote],
                    services: vec![svc_remote],
                },
                1,
            ),
        );
        let snapshot = multicluster::RemoteEndpointSnapshot { clusters };

        let mut runtime = test_mesh_runtime_config();
        runtime.workload_spiffe_id =
            Some("spiffe://cluster.local/ns/default/sa/client".to_string());
        let activation = FederationActivation {
            fail_open: false,
            poll_enabled: true,
        };

        let cross_cluster_to_gateway = |config: &GatewayConfig| {
            config.upstreams.iter().any(|upstream| {
                upstream.targets.iter().any(|target| {
                    target
                        .tags
                        .get(crate::proxy::mesh_mtls_pool::MESH_CROSS_CLUSTER_TAG)
                        .map(String::as_str)
                        == Some("true")
                        && target.host == "10.9.9.9"
                })
            })
        };

        // WITH the snapshot: the poller-discovered remote endpoint materializes a
        // cross-cluster target addressed at the east-west gateway.
        let with_snapshot = gateway_config_from_mesh_slice_with_federation(
            &slice,
            &runtime,
            Some(&federation::FederationSnapshot::default()),
            Some(&snapshot),
            activation,
        )
        .expect("prepared with snapshot");
        assert!(
            cross_cluster_to_gateway(&with_snapshot),
            "poller-discovered remote endpoints must materialize a cross-cluster east-west target"
        );

        // WITHOUT the snapshot: no remote workload is known, so no cross-cluster target.
        let without_snapshot = gateway_config_from_mesh_slice_with_federation(
            &slice,
            &runtime,
            Some(&federation::FederationSnapshot::default()),
            None,
            activation,
        )
        .expect("prepared without snapshot");
        assert!(
            !cross_cluster_to_gateway(&without_snapshot),
            "with no remote-endpoint snapshot there is no remote workload to route cross-cluster"
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn publish_gateway_active_trust_bundles_updates_outbound_svid_slot() {
        use crate::identity::{SvidBundle, TrustBundle, TrustBundleSet};
        use base64::Engine;

        let state = make_test_proxy_state(GatewayConfig::default());
        let local_td = TrustDomain::new("local.test").unwrap();
        let remote_td = TrustDomain::new("remote.test").unwrap();
        let id = SpiffeId::from_parts(&local_td, "ns/foo/sa/bar").unwrap();
        state.install_gateway_runtime_svid_bundle(SvidBundle {
            spiffe_id: id,
            cert_chain_der: vec![vec![1, 2, 3]],
            private_key_pkcs8_der: Vec::new().into(),
            trust_bundles: TrustBundleSet::local_only(TrustBundle {
                trust_domain: local_td.clone(),
                x509_authorities: vec![vec![1]],
                jwt_authorities: Vec::new(),
                refresh_hint_seconds: None,
            }),
        });

        let engine = base64::engine::general_purpose::STANDARD;
        let slice = MeshSlice {
            version: "outbound-trust".to_string(),
            trust_bundles: Some(config::TrustBundleSet {
                local: config::TrustBundle {
                    trust_domain: local_td,
                    x509_authorities: vec![engine.encode(b"slice-local")],
                    jwt_authorities: Vec::new(),
                    refresh_hint_seconds: None,
                },
                federated: vec![config::TrustBundle {
                    trust_domain: remote_td.clone(),
                    x509_authorities: vec![engine.encode(b"cp-bootstrap")],
                    jwt_authorities: Vec::new(),
                    refresh_hint_seconds: None,
                }],
            }),
            multi_cluster: Some(MultiClusterConfig {
                remote_clusters: vec![RemoteCluster {
                    name: "remote".to_string(),
                    trust_domain: remote_td.clone(),
                    network: None,
                    control_plane_url: None,
                    federation_endpoint: Some("https://remote/.well-known/spiffe".to_string()),
                    discovery_credential_ref: None,
                }],
                ..MultiClusterConfig::default()
            }),
            ..MeshSlice::default()
        };
        let activation = FederationActivation {
            fail_open: false,
            poll_enabled: true,
        };

        publish_gateway_active_trust_bundles(
            &state,
            &slice,
            Some(&federation::FederationSnapshot::default()),
            activation,
        );
        let active = state.gateway_svid_bundle.load_full();
        let bundle = active.as_ref().as_ref().expect("gateway SVID bundle");
        assert!(
            !bundle.trust_bundles.federated.contains_key(&remote_td),
            "fail-closed bootstrap root must not become outbound active trust before a poll succeeds"
        );

        let mut polled = federation::FederationSnapshot::default();
        polled.bundles.insert(
            remote_td.clone(),
            federation::FederatedBundle {
                bundle: config::TrustBundle {
                    trust_domain: remote_td.clone(),
                    x509_authorities: vec![engine.encode(b"polled-root")],
                    jwt_authorities: Vec::new(),
                    refresh_hint_seconds: None,
                },
                fetched_at_unix_seconds: 1,
                endpoint: "https://remote/.well-known/spiffe".to_string(),
                cluster_name: "remote".to_string(),
            },
        );
        publish_gateway_active_trust_bundles(&state, &slice, Some(&polled), activation);

        let active = state.gateway_svid_bundle.load_full();
        let bundle = active.as_ref().as_ref().expect("gateway SVID bundle");
        let remote = bundle
            .trust_bundles
            .federated
            .get(&remote_td)
            .expect("polled remote trust is active");
        assert_eq!(remote.x509_authorities, vec![b"polled-root".to_vec()]);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn mesh_runtime_apply_task_republishes_inbound_spiffe_without_peer_auth_live_reload() {
        use crate::identity::{SvidBundle, TrustBundle, TrustBundleSet};
        use base64::Engine;

        let runtime = test_mesh_runtime_config();
        let mesh_state = MeshRuntimeState::new();
        let proxy_state = make_test_proxy_state(GatewayConfig::default());
        let inbound_slot: tls::SharedBundleSlot = Arc::new(arc_swap::ArcSwap::new(Arc::new(None)));
        let overlay_slot = empty_mesh_inbound_trust_overlay_slot();
        let local_td = TrustDomain::new("local.runtime").unwrap();
        let remote_td = TrustDomain::new("partner.runtime").unwrap();
        let id = SpiffeId::from_parts(&local_td, "ns/foo/sa/bar").unwrap();
        proxy_state.install_gateway_runtime_svid_bundle(SvidBundle {
            spiffe_id: id,
            cert_chain_der: vec![vec![1, 2, 3]],
            private_key_pkcs8_der: Vec::new().into(),
            trust_bundles: TrustBundleSet::local_only(TrustBundle {
                trust_domain: local_td.clone(),
                x509_authorities: vec![vec![1]],
                jwt_authorities: Vec::new(),
                refresh_hint_seconds: None,
            }),
        });

        let (shutdown_tx, shutdown_rx) = tokio::sync::watch::channel(false);
        let apply_task = start_mesh_slice_apply_task(
            mesh_state.clone(),
            proxy_state.clone(),
            runtime,
            None,
            MeshInboundTlsReloadState {
                server_identity: None,
                last_snapshot: None,
                spiffe_bundle_slot: Some(inbound_slot.clone()),
                runtime_trust_overlay_slot: Some(overlay_slot),
                production: false,
            },
            shutdown_rx,
            None,
        );

        let engine = base64::engine::general_purpose::STANDARD;
        mesh_state.install_slice(MeshSlice {
            version: "accepted-trust".to_string(),
            labels: [("trust".to_string(), "published".to_string())].into(),
            trust_bundles: Some(config::TrustBundleSet {
                local: config::TrustBundle {
                    trust_domain: local_td,
                    x509_authorities: vec![engine.encode(b"slice-local")],
                    jwt_authorities: Vec::new(),
                    refresh_hint_seconds: None,
                },
                federated: vec![config::TrustBundle {
                    trust_domain: remote_td.clone(),
                    x509_authorities: vec![engine.encode(b"partner-root")],
                    jwt_authorities: Vec::new(),
                    refresh_hint_seconds: None,
                }],
            }),
            ..MeshSlice::default()
        });
        wait_for_mesh_authz_label(&proxy_state, "trust", "published").await;
        tokio::time::timeout(Duration::from_secs(1), async {
            loop {
                let active = inbound_slot.load_full();
                if active
                    .as_ref()
                    .as_ref()
                    .is_some_and(|bundle| bundle.trust_bundles.federated.contains_key(&remote_td))
                {
                    return;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("accepted slice should republish inbound SPIFFE trust without PeerAuth reload");

        let active = inbound_slot.load_full();
        let bundle = active.as_ref().as_ref().expect("inbound SVID bundle");
        let remote = bundle
            .trust_bundles
            .federated
            .get(&remote_td)
            .expect("federated trust published");
        assert_eq!(remote.x509_authorities, vec![b"partner-root".to_vec()]);

        let _ = shutdown_tx.send(true);
        tokio::time::timeout(Duration::from_secs(2), apply_task)
            .await
            .expect("apply task should stop")
            .expect("apply task should join");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn runtime_spiffe_overlay_preserves_fresh_ca_roots_on_rotation() {
        use crate::identity::{SvidBundle, TrustBundle, TrustBundleSet};
        use base64::Engine;

        let state = make_test_proxy_state(GatewayConfig::default());
        let inbound_slot: tls::SharedBundleSlot = Arc::new(arc_swap::ArcSwap::new(Arc::new(None)));
        let overlay_slot = empty_mesh_inbound_trust_overlay_slot();
        let td = TrustDomain::new("td.runtime").unwrap();
        let stale_td = TrustDomain::new("stale.runtime").unwrap();
        let id = SpiffeId::from_parts(&td, "ns/foo/sa/bar").unwrap();

        let svid_bundle = |local_roots: Vec<Vec<u8>>| SvidBundle {
            spiffe_id: id.clone(),
            cert_chain_der: vec![vec![1, 2, 3]],
            private_key_pkcs8_der: Vec::new().into(),
            trust_bundles: TrustBundleSet {
                local: TrustBundle {
                    trust_domain: td.clone(),
                    x509_authorities: local_roots,
                    jwt_authorities: Vec::new(),
                    refresh_hint_seconds: None,
                },
                federated: HashMap::from([(
                    stale_td.clone(),
                    TrustBundle {
                        trust_domain: stale_td.clone(),
                        x509_authorities: vec![vec![42]],
                        jwt_authorities: Vec::new(),
                        refresh_hint_seconds: None,
                    },
                )]),
            },
        };

        state.install_gateway_runtime_svid_bundle(svid_bundle(vec![vec![1]]));
        let engine = base64::engine::general_purpose::STANDARD;
        let slice = MeshSlice {
            version: "trust-overlay".to_string(),
            trust_bundles: Some(config::TrustBundleSet {
                local: config::TrustBundle {
                    trust_domain: td.clone(),
                    x509_authorities: vec![engine.encode(b"slice-extra-local-root")],
                    jwt_authorities: Vec::new(),
                    refresh_hint_seconds: None,
                },
                federated: vec![config::TrustBundle {
                    trust_domain: TrustDomain::new("partner.runtime").unwrap(),
                    x509_authorities: vec![engine.encode(b"partner-root")],
                    jwt_authorities: Vec::new(),
                    refresh_hint_seconds: Some(300),
                }],
            }),
            ..MeshSlice::default()
        };

        let staged = stage_gateway_runtime_spiffe_bundle(
            &state,
            Some(&inbound_slot),
            Some(&overlay_slot),
            &slice,
        );

        state.install_gateway_runtime_svid_bundle(svid_bundle(vec![vec![9]]));
        publish_runtime_svid_to_inbound_slot(&state, &inbound_slot, &overlay_slot);
        publish_staged_spiffe_bundle(&state, staged);

        let active = inbound_slot.load_full();
        let bundle = active.as_ref().as_ref().expect("inbound bundle");
        assert_eq!(
            bundle.trust_bundles.local.x509_authorities,
            vec![vec![9], b"slice-extra-local-root".to_vec()],
            "runtime CA local roots must keep the rotated SVID root and add accepted slice roots"
        );
        assert!(
            bundle
                .trust_bundles
                .federated
                .contains_key(&TrustDomain::new("partner.runtime").unwrap()),
            "accepted slice federation should remain overlaid after rotation"
        );
        assert!(
            !bundle.trust_bundles.federated.contains_key(&stale_td),
            "raw SPIRE federated roots must not remain in the inbound verifier"
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn inbound_svid_rotation_republisher_refreshes_file_backed_verifier_roots() {
        use crate::identity::{SvidBundle, TrustBundle, TrustBundleSet};
        use base64::Engine;

        let state = make_test_proxy_state(GatewayConfig::default());
        let inbound_slot: tls::SharedBundleSlot = Arc::new(arc_swap::ArcSwap::new(Arc::new(None)));
        let overlay_slot = empty_mesh_inbound_trust_overlay_slot();
        let td = TrustDomain::new("td.file-rotation").unwrap();
        let id = SpiffeId::from_parts(&td, "ns/foo/sa/bar").unwrap();

        let svid_bundle = |local_roots: Vec<Vec<u8>>| SvidBundle {
            spiffe_id: id.clone(),
            cert_chain_der: vec![vec![1, 2, 3]],
            private_key_pkcs8_der: Vec::new().into(),
            trust_bundles: TrustBundleSet::local_only(TrustBundle {
                trust_domain: td.clone(),
                x509_authorities: local_roots,
                jwt_authorities: Vec::new(),
                refresh_hint_seconds: None,
            }),
        };

        state.install_gateway_runtime_svid_bundle(svid_bundle(vec![vec![1]]));
        let engine = base64::engine::general_purpose::STANDARD;
        let slice = MeshSlice {
            version: "file-rotation-overlay".to_string(),
            trust_bundles: Some(config::TrustBundleSet {
                local: config::TrustBundle {
                    trust_domain: td.clone(),
                    x509_authorities: Vec::new(),
                    jwt_authorities: Vec::new(),
                    refresh_hint_seconds: None,
                },
                federated: vec![config::TrustBundle {
                    trust_domain: TrustDomain::new("partner.file-rotation").unwrap(),
                    x509_authorities: vec![engine.encode(b"partner-root")],
                    jwt_authorities: Vec::new(),
                    refresh_hint_seconds: Some(300),
                }],
            }),
            ..MeshSlice::default()
        };
        let staged = stage_gateway_runtime_spiffe_bundle(
            &state,
            Some(&inbound_slot),
            Some(&overlay_slot),
            &slice,
        );
        publish_staged_spiffe_bundle(&state, staged);

        let (revision_tx, revision_rx) = tokio::sync::watch::channel(0u64);
        let (shutdown_tx, shutdown_rx) = tokio::sync::watch::channel(false);
        let republisher = start_mesh_inbound_svid_rotation_republisher(
            state.clone(),
            inbound_slot.clone(),
            overlay_slot.clone(),
            revision_rx,
            shutdown_rx,
        );
        tokio::task::yield_now().await;

        state.install_gateway_runtime_svid_bundle(svid_bundle(vec![vec![9]]));
        revision_tx.send_replace(1);

        tokio::time::timeout(Duration::from_secs(1), async {
            loop {
                let active = inbound_slot.load_full();
                if active.as_ref().as_ref().is_some_and(|bundle| {
                    bundle.trust_bundles.local.x509_authorities == vec![vec![9]]
                }) {
                    return;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("rotation republisher refreshed inbound verifier roots");

        let active = inbound_slot.load_full();
        let bundle = active.as_ref().as_ref().expect("inbound bundle");
        assert!(
            bundle
                .trust_bundles
                .federated
                .contains_key(&TrustDomain::new("partner.file-rotation").unwrap()),
            "accepted federated overlay must survive file-backed SVID republish"
        );

        let _ = shutdown_tx.send(true);
        tokio::time::timeout(Duration::from_secs(1), republisher)
            .await
            .expect("republisher observed shutdown")
            .expect("republisher task joined");
    }

    // Regression for the file-SVID rotation republish race (#1707 / #1728 P3):
    // a rotation can install the new gateway bundle and bump
    // `backend_svid_rotation_tx` after the republisher subscribed but before its
    // task first runs. The initial publish must read the freshly installed
    // bundle, and the baseline revision must be captured *before* that publish so
    // a later interleaving cannot be deduped away. We model the pre-run rotation
    // deterministically on a single-threaded executor: install the new bundle and
    // bump the revision while the spawned task is still parked, then drive it. A
    // correct republisher pins the verifier to the NEW roots without waiting for a
    // second rotation; the pre-fix order (publish-then-baseline) could leave it on
    // the old roots.
    #[tokio::test(flavor = "current_thread")]
    async fn inbound_svid_rotation_republisher_picks_up_pre_run_rotation() {
        use crate::identity::{SvidBundle, TrustBundle, TrustBundleSet};

        let state = make_test_proxy_state(GatewayConfig::default());
        let inbound_slot: tls::SharedBundleSlot = Arc::new(arc_swap::ArcSwap::new(Arc::new(None)));
        let overlay_slot = empty_mesh_inbound_trust_overlay_slot();
        let td = TrustDomain::new("td.pre-run-rotation").unwrap();
        let id = SpiffeId::from_parts(&td, "ns/foo/sa/bar").unwrap();

        let svid_bundle = |local_roots: Vec<Vec<u8>>| SvidBundle {
            spiffe_id: id.clone(),
            cert_chain_der: vec![vec![1, 2, 3]],
            private_key_pkcs8_der: Vec::new().into(),
            trust_bundles: TrustBundleSet::local_only(TrustBundle {
                trust_domain: td.clone(),
                x509_authorities: local_roots,
                jwt_authorities: Vec::new(),
                refresh_hint_seconds: None,
            }),
        };

        // Old roots in place when the republisher subscribes.
        state.install_gateway_runtime_svid_bundle(svid_bundle(vec![vec![1]]));
        let (revision_tx, revision_rx) = tokio::sync::watch::channel(0u64);
        let (shutdown_tx, shutdown_rx) = tokio::sync::watch::channel(false);
        let republisher = start_mesh_inbound_svid_rotation_republisher(
            state.clone(),
            inbound_slot.clone(),
            overlay_slot.clone(),
            revision_rx,
            shutdown_rx,
        );

        // Rotation lands while the spawned task is still parked (no yield yet):
        // new bundle installed AND the revision bumped before the task runs.
        state.install_gateway_runtime_svid_bundle(svid_bundle(vec![vec![9]]));
        revision_tx.send_replace(1);

        tokio::time::timeout(Duration::from_secs(1), async {
            loop {
                let active = inbound_slot.load_full();
                if active.as_ref().as_ref().is_some_and(|bundle| {
                    bundle.trust_bundles.local.x509_authorities == vec![vec![9]]
                }) {
                    return;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("republisher must pin the inbound verifier to the new roots");

        let _ = shutdown_tx.send(true);
        tokio::time::timeout(Duration::from_secs(1), republisher)
            .await
            .expect("republisher observed shutdown")
            .expect("republisher task joined");
    }

    #[test]
    fn mesh_runtime_request_auth_require_exp_defaults_secure() {
        // Secure default: the auto-injected mesh request-auth plugin requires
        // the JWT `exp` claim so `exp`-less tokens cannot live forever. This
        // honors the "validate_exp = true" invariant.
        let runtime = test_mesh_runtime_config();
        assert!(
            runtime.request_auth_require_exp,
            "test runtime should carry the secure default"
        );
        let prepared =
            prepare_gateway_config_for_mesh(request_auth_config_for_require_exp(), &runtime)
                .expect("mesh config");
        let jwks = prepared
            .plugin_configs
            .iter()
            .find(|plugin| plugin.id == MESH_REQUEST_AUTH_PLUGIN_ID)
            .expect("jwks_auth plugin");

        assert_eq!(
            jwks.config.get("require_exp").and_then(|v| v.as_bool()),
            Some(true),
            "mesh request auth must default require_exp=true (secure)"
        );
    }

    #[test]
    fn mesh_runtime_request_auth_require_exp_can_be_relaxed() {
        // Operators with Istio issuers that omit `exp` can opt out via
        // FERRUM_MESH_REQUEST_AUTH_REQUIRE_EXP=false.
        let mut runtime = test_mesh_runtime_config();
        runtime.request_auth_require_exp = false;
        let prepared =
            prepare_gateway_config_for_mesh(request_auth_config_for_require_exp(), &runtime)
                .expect("mesh config");
        let jwks = prepared
            .plugin_configs
            .iter()
            .find(|plugin| plugin.id == MESH_REQUEST_AUTH_PLUGIN_ID)
            .expect("jwks_auth plugin");

        assert_eq!(
            jwks.config.get("require_exp").and_then(|v| v.as_bool()),
            Some(false),
            "FERRUM_MESH_REQUEST_AUTH_REQUIRE_EXP=false must relax require_exp"
        );
    }

