    #[test]
    fn egress_materializes_l4_service_entry_ports_as_stream_proxies() {
        // Pre-T5-A this entry was skipped (L4 protocols had no materialization
        // path). T5-A added stream-family materialization: an L4 SE now
        // produces a `tcp` stream proxy bound on the SE's own port.
        let service_entries = vec![ServiceEntry {
            name: "mysql".to_string(),
            namespace: "default".to_string(),
            hosts: vec!["db.external.com".to_string()],
            endpoints: Vec::new(),
            resolution: Resolution::Dns,
            location: ServiceEntryLocation::MeshExternal,
            ports: vec![ServicePort {
                port: 3306,
                protocol: AppProtocol::Mysql,
                name: Some("mysql".to_string()),
                target_port: None,
            }],
            export_to: Vec::new(),
            workload_selector: None,
        }];

        let (proxies, upstreams) = build_egress_proxies_and_upstreams(
            &service_entries,
            "default",
            &std::collections::HashSet::new(),
            true,
            false,
        );
        assert_eq!(proxies.len(), 1);
        assert_eq!(upstreams.len(), 1);

        let proxy = &proxies[0];
        assert!(proxy.hosts.is_empty(), "stream proxy must have no hosts");
        assert!(proxy.listen_path.is_none());
        assert_eq!(proxy.listen_port, Some(3306));
        assert_eq!(proxy.backend_scheme, Some(BackendScheme::Tcp));
        assert!(!proxy.passthrough);
        // Stream egress terminates SVID-mTLS by default (parity with HTTP egress).
        assert!(proxy.frontend_tls);
        assert_eq!(
            proxy.name.as_deref(),
            Some("mesh egress mysql db.external.com:3306")
        );

        let upstream = &upstreams[0];
        assert_eq!(upstream.targets.len(), 1);
        assert_eq!(upstream.targets[0].host, "db.external.com");
        assert_eq!(upstream.targets[0].port, 3306);
    }

    #[test]
    fn egress_does_not_materialize_udp_service_entry_in_stage_1() {
        // F3 §3.3 stage 1 is INERT for UDP: a `protocol: UDP` ServiceEntry port
        // is classified `AppProtocol::Udp` but must NOT materialize an egress
        // listener yet (no premature UDP listener → no port-only TCP/UDP dedup
        // collision, no unseeded-DTLS deferral). UDP egress arrives in a later
        // stage. Even with stream egress ENABLED, a UDP-only ServiceEntry yields
        // zero proxies and zero upstreams.
        let service_entries = vec![ServiceEntry {
            name: "dns".to_string(),
            namespace: "default".to_string(),
            hosts: vec!["dns.external.com".to_string()],
            endpoints: Vec::new(),
            resolution: Resolution::Dns,
            location: ServiceEntryLocation::MeshExternal,
            ports: vec![ServicePort {
                port: 53,
                protocol: AppProtocol::Udp,
                name: Some("dns".to_string()),
                target_port: None,
            }],
            export_to: Vec::new(),
            workload_selector: None,
        }];

        let (proxies, upstreams) = build_egress_proxies_and_upstreams(
            &service_entries,
            "default",
            &std::collections::HashSet::new(),
            true,  // egress_stream_enabled
            false, // egress_stream_allow_plaintext
        );

        assert!(
            proxies.is_empty(),
            "UDP ServiceEntry must materialize NO egress proxy in stage 1 (inert), got {proxies:?}"
        );
        assert!(
            upstreams.is_empty(),
            "UDP ServiceEntry must materialize NO egress upstream in stage 1 (inert)"
        );
    }

    #[test]
    fn egress_materializes_tcp_but_not_udp_for_dual_protocol_service() {
        // A DNS-like service exposing BOTH TCP/53 and UDP/53: the TCP/53 stream
        // listener still materializes, while UDP/53 is skipped (deferred). This
        // pins that the inert UDP skip does NOT also drop the coexisting TCP port
        // and that no UDP listener is emitted on the same number (the port-only
        // dedup collision codex flagged never arises because UDP never enters
        // the stream materializer).
        let service_entries = vec![ServiceEntry {
            name: "dns".to_string(),
            namespace: "default".to_string(),
            hosts: vec!["dns.external.com".to_string()],
            endpoints: Vec::new(),
            resolution: Resolution::Dns,
            location: ServiceEntryLocation::MeshExternal,
            ports: vec![
                ServicePort {
                    port: 53,
                    protocol: AppProtocol::Tcp,
                    name: Some("dns-tcp".to_string()),
                    target_port: None,
                },
                ServicePort {
                    port: 53,
                    protocol: AppProtocol::Udp,
                    name: Some("dns-udp".to_string()),
                    target_port: None,
                },
            ],
            export_to: Vec::new(),
            workload_selector: None,
        }];

        let (proxies, upstreams) = build_egress_proxies_and_upstreams(
            &service_entries,
            "default",
            &std::collections::HashSet::new(),
            true,
            false,
        );

        // Exactly one stream proxy (the TCP/53 listener); the UDP/53 port is
        // skipped, so it neither adds a second listener nor collides with TCP.
        assert_eq!(
            proxies.len(),
            1,
            "only the TCP/53 stream listener must materialize (UDP/53 deferred)"
        );
        assert_eq!(proxies[0].listen_port, Some(53));
        assert_eq!(proxies[0].backend_scheme, Some(BackendScheme::Tcp));
        assert_eq!(upstreams.len(), 1);
        assert_eq!(upstreams[0].targets[0].port, 53);
    }

    #[test]
    fn egress_sanitizes_wildcard_host_ids_but_preserves_route_host() {
        let service_entries = vec![test_external_service_entry(
            "wildcard-api",
            vec!["*.api.external.com".to_string()],
            443,
            AppProtocol::Tls,
        )];

        let (proxies, upstreams) = build_egress_proxies_and_upstreams(
            &service_entries,
            "default",
            &std::collections::HashSet::new(),
            true,
            false,
        );

        assert_eq!(proxies.len(), 1);
        // The injective id encoder maps each non-alnum char to a `_`-delimited
        // token (`-`→`_dash_`, `.`→`_dot_`, `*`→`_star_`) — no `-` in any
        // segment, so the `-` segment delimiters stay unambiguous. The service
        // `name` ("wildcard-api") encodes to `wildcard_dash_api`; the host
        // `*.api.external.com` encodes to `_star__dot_api_dot_external_dot_com`.
        assert_eq!(
            proxies[0].id,
            "mesh-egress-default-wildcard_dash_api-_star__dot_api_dot_external_dot_com-443"
        );
        assert_eq!(proxies[0].hosts, vec!["*.api.external.com"]);
        assert_eq!(
            upstreams[0].id,
            "mesh-egress-up-default-wildcard_dash_api-_star__dot_api_dot_external_dot_com-443"
        );
    }

    #[test]
    fn egress_host_id_sanitization_preserves_distinct_valid_hostnames() {
        assert_ne!(
            sanitize_egress_host_id_part("a.b.com"),
            sanitize_egress_host_id_part("a-b.com")
        );
        assert_eq!(
            sanitize_egress_host_id_part("*.api.external.com"),
            "_star__dot_api_dot_external_dot_com"
        );
    }

    #[test]
    fn egress_ids_do_not_collide_across_dash_ambiguous_namespace_name_pairs() {
        // Regression for #1727 (+ codex round 1): the egress id encoder must be
        // INJECTIVE over (namespace, name, host) and must keep the `-` segment
        // delimiter unambiguous. The original `sanitize_egress_id_part`
        // collapsed non-alnum runs to a single `-`; the first attempted fix
        // tokenized chars but wrapped tokens in `-` and trimmed, which still
        // collided (`"-"` and `"dash"`, or `(a-dash, c)` vs `(a, dash-c)`).
        // Materialize merges/matches proxies + upstreams by id, so a collision
        // silently overwrites one entry and can cross-apply its targetPort/port
        // policy. The file mesh-config path does not validate these characters,
        // so all of these are reachable.
        let host = "ext.example.com";
        let port = 443;

        // 1. `-` straddling the namespace/name boundary.
        let a = mesh_egress_proxy_id("a-b", "c", host, port);
        let b = mesh_egress_proxy_id("a", "b-c", host, port);
        assert_ne!(a, b, "egress proxy ids must not collide: {a} == {b}");
        let ua = mesh_egress_upstream_id("a-b", "c", host, port);
        let ub = mesh_egress_upstream_id("a", "b-c", host, port);
        assert_ne!(ua, ub, "egress upstream ids must not collide: {ua} == {ub}");

        // 2. A literal `-` vs the literal token text it used to render as.
        assert_ne!(
            mesh_egress_proxy_id("ns", "-", host, port),
            mesh_egress_proxy_id("ns", "dash", host, port),
            "a literal '-' name must not collide with the literal name 'dash'"
        );

        // 3. The codex counterexample: a token-word straddling the boundary.
        assert_ne!(
            mesh_egress_proxy_id("a-dash", "c", host, port),
            mesh_egress_proxy_id("a", "dash-c", host, port),
            "token-word boundary ambiguity must not collide"
        );

        // 4. `.` vs `-` in a segment, and a `.`-bearing host vs its token text.
        assert_ne!(
            mesh_egress_proxy_id("a.b", "c", host, port),
            a,
            "`.`- and `-`-separated segments must differ"
        );
        assert_ne!(
            mesh_egress_upstream_id("ns", "name", "a.b", port),
            mesh_egress_upstream_id("ns", "name", "a-dot-b", port),
            "a '.'-bearing host must not collide with its token text"
        );

        // 5. Every produced segment is free of the `-` delimiter, so the
        //    assembled id's `-` boundaries are unambiguous by construction.
        for part in ["a-b", "a.b/c*d", "-", "_", "δ", "x_dash_y"] {
            assert!(
                !sanitize_egress_host_id_part(part).contains('-'),
                "encoded segment for {part:?} must not contain the '-' delimiter"
            );
        }

        // 6. The empty-segment placeholder cannot collide with a literal segment
        //    (the old `any` placeholder collided with a literal `any` name).
        assert_ne!(
            sanitize_egress_host_id_part(""),
            sanitize_egress_host_id_part("any"),
            "empty placeholder must not collide with a literal 'any'"
        );
        assert_ne!(
            sanitize_egress_host_id_part(""),
            sanitize_egress_host_id_part("empty"),
            "empty placeholder must not collide with a literal 'empty'"
        );
    }

    #[test]
    fn egress_creates_one_host_only_proxy_per_host() {
        let service_entries = vec![ServiceEntry {
            name: "multi-host".to_string(),
            namespace: "default".to_string(),
            hosts: vec!["api.example.com".to_string(), "cdn.example.com".to_string()],
            endpoints: Vec::new(),
            resolution: Resolution::Dns,
            location: ServiceEntryLocation::MeshExternal,
            ports: vec![
                ServicePort {
                    port: 80,
                    protocol: AppProtocol::Http,
                    name: Some("http".to_string()),
                    target_port: None,
                },
                ServicePort {
                    port: 443,
                    protocol: AppProtocol::Tls,
                    name: Some("https".to_string()),
                    target_port: None,
                },
            ],
            export_to: Vec::new(),
            workload_selector: None,
        }];

        let (proxies, upstreams) = build_egress_proxies_and_upstreams(
            &service_entries,
            "default",
            &std::collections::HashSet::new(),
            true,
            false,
        );

        // Host-only HTTP proxies cannot safely distinguish multiple ports for
        // the same host, so only the first materialized port owns each host.
        assert_eq!(proxies.len(), 2);
        assert_eq!(upstreams.len(), 2);

        assert!(
            proxies
                .iter()
                .any(|p| p.id == "mesh-egress-default-multi_dash_host-api_dot_example_dot_com-80")
        );
        assert!(
            proxies
                .iter()
                .any(|p| p.id == "mesh-egress-default-multi_dash_host-cdn_dot_example_dot_com-80")
        );

        let http_proxy = proxies
            .iter()
            .find(|p| p.id == "mesh-egress-default-multi_dash_host-api_dot_example_dot_com-80")
            .unwrap();
        assert_eq!(http_proxy.backend_scheme, Some(BackendScheme::Http));
    }

